class Solution:
    def minAnagramLength(self, s: str) -> int:
        # Create a frequency dictionary to count occurrences of each character
        char_count = {}
        for char in s:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

        # Calculate the total number of characters in the string
        total_chars = len(s)

        # Find the maximum frequency of any character
        max_freq = max(char_count.values())

        # The minimum length of the anagram is the maximum frequency plus one
        return max_freq + 1

class Solution:
    def maxBottlesDrunk(self, numBottles: int, numExchange: int) -> int:
        total_drunk = numBottles
        empty_bottles = numBottles

        while empty_bottles >= numExchange:
            new_full_bottles = empty_bottles // numExchange
            total_drunk += new_full_bottles
            empty_bottles = empty_bottles % numExchange + new_full_bottles
            numExchange += 1

        return total_drunk

class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [[float('inf')] * 4 for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(1, 4):
                dp[i][j] = dp[i - 1][j] + 1
                if nums[i - 1] >= j:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j - 1])

        return min(dp[n])

