class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def check(node, min_val, max_val):
            if not node:
                return True
            if node.val <= min_val or node.val >= max_val:
                return False
            return check(node.left, min_val, node.val) and check(node.right, node.val, max_val)

        return check(root, float('-inf'), float('inf'))

class Solution:
    def canAliceWin(self, nums: List[int]) -> bool:
        single_digit_sum = sum(num for num in nums if 1 <= num <= 9)
        double_digit_sum = sum(num for num in nums if 10 <= num <= 99)

        return single_digit_sum + double_digit_sum > sum(nums) - (single_digit_sum + double_digit_sum)

class Solution:
    def minInsertions(self, s: str) -> int:
        # Initialize the count of unmatched opening parentheses
        open_count = 0

        # Iterate through each character in the string
        for char in s:
            # If the character is an opening parenthesis, increment the open count
            if char == '(':
                open_count += 1
            # If the character is a closing parenthesis, decrement the open count
            elif char == ')':
                # If there are no unmatched opening parentheses, return the current open count
                if open_count == 0:
                    return open_count
                # Otherwise, decrement the open count and update the result
                open_count -= 1
                open_count += 1

        # Return the total number of unmatched opening parentheses
        return open_count

class Solution:
    def maximumSwap(self, num: int) -> int:
        # Convert the number to a list of its digits
        digits = list(map(int, str(num)))

        # Find the first occurrence of the largest digit
        max_digit_index = digits.index(max(digits))

        # Find the second occurrence of the largest digit
        second_max_digit_index = -1

        # Check both occurrences to find the second largest digit
        for i in range(len(digits)):
            if i != max_digit_index:
                if digits[i] > digits[max_digit_index]:
                    second_max_digit_index = i

        # If no second largest digit is found, return the original number
        if second_max_digit_index == -1:
            return num

        # Swap the largest digit with the second largest digit
        digits[max_digit_index], digits[second_max_digit_index] = digits[second_max_digit_index], digits[max_digit_index]

        # Convert the list of digits back to a string and convert it back to an integer
        return int(''.join(map(str, digits)))

