class Solution:
    def pushDominoes(self, dominoes: str) -> str:
        n = len(dominoes)
        result = ['.'] * n

        # First pass: process left to right
        force = 0
        for i in range(n):
            if dominoes[i] == 'R':
                force = n
            elif dominoes[i] == 'L':
                force = 0
            else:
                force = max(force - 1, 0)
            if force > 0:
                result[i] = 'R'
                force -= 1

        # Second pass: process right to left
        force = 0
        for i in range(n-1, -1, -1):
            if dominoes[i] == 'L':
                force = n
            elif dominoes[i] == 'R':
                force = 0
            else:
                force = max(force - 1, 0)
            if force > 0:
                if result[i] == '.':
                    result[i] = 'L'
                force -= 1

        return ''.join(result)

class Solution:
    def robotWithString(self, s: str) -> str:
        min_right = [s[-1]] * len(s)
        for i in range(len(s)-2, -1, -1):
            min_right[i] = min(min_right[i+1], s[i])

        stack = []
        result = []
        j = 0
        for i, char in enumerate(s):
            stack.append(char)
            while stack and stack[-1] <= min_right[j]:
                result.append(stack.pop())
                if j < len(s) - 1:
                    j += 1

        return ''.join(result)

class Solution:
    def numIslands2(self, m: int, n: int, positions: List[List[int]]) -> List[int]:
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY
                count[rootY] += count[rootX]

        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        parent = {}
        count = {}
        result = []

        for x, y in positions:
            if (x, y) not in parent:
                parent[(x, y)] = (x, y)
                count[(x, y)] = 1
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if (nx, ny) in parent:
                        union((x, y), (nx, ny))

            result.append(count[(x, y)])

        return result

class Solution:
    def pyramidTransition(self, bottom: str, allowed: List[str]) -> bool:
        allowed_map = {}
        for triplet in allowed:
            if triplet[:2] not in allowed_map:
                allowed_map[triplet[:2]] = set()
            allowed_map[triplet[:2]].add(triplet[2])

        def backtrack(current_row):
            if len(current_row) == 1:
                return True
            if len(current_row) == 2:
                return current_row[0] + current_row[1] in allowed_map

            for i in range(len(current_row) - 1):
                left, right = current_row[i], current_row[i + 1]
                if left + right not in allowed_map:
                    return False
                next_blocks = allowed_map[left + right]
                for next_block in next_blocks:
                    if backtrack(current_row[:i] + next_block + current_row[i + 2:]):
                        return True
            return False

        return backtrack(bottom)

class Solution:
    def subsequenceSumOr(self, nums: List[int]) -> int:
        # Initialize the result variable to 0
        result = 0

        # Iterate through each number in the array
        for num in nums:
            # Update the result variable with the bitwise OR of the current number and the result
            result |= num

        # Return the final result
        return result

