class Solution:
    def decrypt(self, code: List[int], k: int) -> List[int]:
        res = [0] * len(code)
        for i in range(len(code)):
            if k > 0:
                start = max(0, i + 1)
                end = min(i + k, len(code))
                res[i] = sum(code[start:end])
            elif k < 0:
                start = max(0, i + k)
                end = min(i + len(code), len(code)) - 1
                res[i] = sum(code[end:start:-1])
            else:
                res[i] = 0
        return res

class Solution:
    def countNumbersWithUniqueDigits(self, n: int) -> int:
        if n == 0:
            return 1

        # Initialize the result for different lengths of numbers
        result = [0] * (n + 1)
        result[0] = 1  # There's 1 number with 0 digits: 0

        # Calculate the number of unique digit numbers for each length from 1 to n
        for i in range(1, n + 1):
            if i == 1:
                result[i] = 9  # The first digit can be anything from 1 to 9, and the rest can be anything from 0 to 9
            else:
                # For longer numbers, the first digit can be anything from 1 to 9 (9 choices), 
                # and the subsequent digits can be anything from 0 to 9 except for the ones already used
                result[i] = 9 * 9 * (10 - i + 1)

        # Sum up the results for all lengths from 1 to n
        return sum(result)

