class Solution:
    def minimumWhiteTiles(self, floor: str, numCarpets: int, carpetLen: int) -> int:
        n = len(floor)
        dp = [[0] * (numCarpets + 1) for _ in range(n + 1)]

        # Initialize the base case
        for i in range(n):
            if floor[i] == '1':
                dp[i][1] = 1

        # Fill the DP table
        for i in range(1, n + 1):
            for j in range(1, numCarpets + 1):
                if floor[i - 1] == '1':
                    dp[i][j] = dp[i - 1][j]
                else:
                    dp[i][j] = min(dp[i - 1][j], dp[max(i - carpetLen, 0)][j - 1])

        return dp[n][numCarpets]

class Solution:
    def minFlips(self, target: str) -> int:
        # Initialize the count of flips
        flips = 0

        # Iterate through each bit in the target string
        for i in range(len(target)):
            # Check if the current bit is '1'
            if target[i] == '1':
                # If it's the first bit or the previous bit is '0', increment flips
                if i == 0 or target[i-1] == '0':
                    flips += 1
                else:
                    # Otherwise, decrement flips
                    flips -= 1

        return flips

