class Solution:
    def getMinSwaps(self, num: str, k: int) -> int:
        n = len(num)
        # Create a dictionary to count occurrences of each digit
        digit_count = {}
        for digit in num:
            if digit in digit_count:
                digit_count[digit] += 1
            else:
                digit_count[digit] = 1

        # Find the maximum frequency of any digit
        max_freq = max(digit_count.values())

        # Calculate the minimum number of swaps needed
        swaps = k // max_freq
        remainder = k % max_freq

        # If there's a remainder, swap the last digit with the digit with the remainder
        if remainder > 0:
            swaps += 1

        return swaps

