class Solution:
    def countRoutes(self, locations: List[int], start: int, finish: int, fuel: int) -> int:
        MOD = 10**9 + 7

        @lru_cache(None)
        def dp(city, remaining_fuel):
            if remaining_fuel < 0:
                return 0
            count = 1 if city == finish else 0
            for next_city in range(len(locations)):
                if next_city != city:
                    cost = abs(locations[next_city] - locations[city])
                    if remaining_fuel >= cost:
                        count += dp(next_city, remaining_fuel - cost)
                        count %= MOD
            return count

        return dp(start, fuel) % MOD

class Solution:
    def solveEquation(self, equation: str) -> str:
        def parse_expression(expr):
            x_coeff = 0
            const = 0
            parts = expr.split('+')
            for part in parts:
                if '-' in part:
                    sub_parts = part.split('-')
                    const -= int(sub_parts[0]) if sub_parts[0] else 0
                    for sub_part in sub_parts[1:]:
                        if sub_part:
                            const += int(sub_part)
                else:
                    if 'x' in part:
                        coeff = 1 if 'x' == part else int(part[:-1])
                        x_coeff += coeff
                    else:
                        const += int(part)
            return x_coeff, const

        left_expr, right_expr = equation.split('=')
        left_x_coeff, left_const = parse_expression(left_expr)
        right_x_coeff, right_const = parse_expression(right_expr)

        total_x_coeff = left_x_coeff - right_x_coeff
        total_const = right_const - left_const

        if total_x_coeff == 0:
            if total_const == 0:
                return "Infinite solutions"
            else:
                return "No solution"
        else:
            x_value = total_const // total_x_coeff
            return f"x={x_value}"

class Solution:
    def largestUniqueNumber(self, nums: List[int]) -> int:
        # Create a dictionary to count occurrences of each number
        count_dict = {}

        # Count occurrences of each number in the array
        for num in nums:
            if num in count_dict:
                count_dict[num] += 1
            else:
                count_dict[num] = 1

        # Find the maximum number that occurs only once
        max_unique = -1
        for num in nums:
            if count_dict[num] == 1:
                if num > max_unique:
                    max_unique = num

        return max_unique

