class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        sa = s.find(a)
        sb = s.find(b)
        res = []
        while sa != -1 and sb != -1:
            if abs(sa-sb) <= k:
                res.append(sa)
            sa = s.find(a, sa+1)
            sb = s.find(b, sb+1)
        return res

class Solution:
    def makePrefSumNonNegative(self, nums: List[int]) -> int:
        n = len(nums)
        total_sum = sum(nums)
        current_sum = 0
        operations = 0

        for num in nums:
            current_sum += num
            if current_sum < 0:
                operations += 1
                current_sum = total_sum - current_sum

        return operations

