class Solution:
    def largestBSTSubtree(self, root: Optional[TreeNode]) -> int:
        if not root: return 0

        # Helper function to check if a subtree is a valid BST
        def isValidBST(node, min_val, max_val):
            if not node: return True
            if node.val <= min_val or node.val >= max_val: return False
            return isValidBST(node.left, min_val, node.val) and isValidBST(node.right, node.val, max_val)

        # Helper function to calculate the size of the largest BST in the subtree rooted at 'node'
        def getLargestBSTSize(node):
            if not node: return 0
            if isValidBST(node, float('-inf'), float('inf')):
                return 1 + getLargestBSTSize(node.left) + getLargestBSTSize(node.right)
            else:
                return max(getLargestBSTSize(node.left), getLargestBSTSize(node.right))

        return getLargestBSTSize(root)

class Solution:
    def maxNumberOfBalloons(self, text: str) -> int:
        count = {'b': 0, 'a': 0, 'l': 0, 'o': 0, 'n': 0}
        for c in text:
            if c in count:
                count[c] += 1
        return min(count['b'], count['a'], count['l'], count['o'], count['n'])

class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        n = len(arr)
        ans = [''] * n

        for i in range(n):
            # Iterate through each character in the current string
            for j in range(i + 1, n):
                # Check if the current substring is shorter than any previous one
                if len(arr[j]) < len(ans[i]):
                    # Update the answer if the current substring is shorter
                    ans[i] = arr[j]

        return ans

