import math

class Solution:
    def minAreaFreeRect(self, points: List[List[int]]) -> float:
        def distance(p1, p2):
            return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

        def dot_product(p1, p2):
            return p1[0] * p2[0] + p1[1] * p2[1]

        def vector(p1, p2):
            return (p2[0] - p1[0], p2[1] - p1[1])

        n = len(points)
        min_area = float('inf')
        seen = set()

        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    p1, p2, p3 = points[i], points[j], points[k]
                    v1 = vector(p1, p2)
                    v2 = vector(p1, p3)

                    if dot_product(v1, v2) != 0:
                        continue

                    p4 = (p2[0] + p3[0] - p1[0], p2[1] + p3[1] - p1[1])
                    if p4 in seen:
                        side1 = distance(p1, p2)
                        side2 = distance(p1, p3)
                        area = side1 * side2
                        min_area = min(min_area, area)

                    seen.add(tuple(p1))
                    seen.add(tuple(p2))
                    seen.add(tuple(p3))

        return min_area if min_area != float('inf') else 0

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def getDirections(self, root: Optional[TreeNode], startValue: int, destValue: int) -> str:
        # Helper function to find the LCA of two nodes
        def lca(node, p, q):
            if not node:
                return None
            if node.val == p or node.val == q:
                return node

            left_lca = lca(node.left, p, q)
            right_lca = lca(node.right, p, q)

            if left_lca and right_lca:
                return node
            return left_lca if left_lca else right_lca

        # Find the LCA of startValue and destValue
        lca_node = lca(root, startValue, destValue)

        # Get the path from startValue to LCA
        start_path = []
        def dfs(node, target):
            if not node:
                return False
            if node.val == target:
                return True
            if dfs(node.left, target):
                start_path.append('L')
                return True
            if dfs(node.right, target):
                start_path.append('R')
                return True
            return False
        dfs(lca_node, startValue)
        start_path.reverse()

        # Get the path from LCA to destValue
        dest_path = []
        def dfs(node, target):
            if not node:
                return False
            if node.val == target:
                return True
            if dfs(node.left, target):
                dest_path.append('L')
                return True
            if dfs(node.right, target):
                dest_path.append('R')
                return True
            return False
        dfs(lca_node, destValue)

        # Combine the paths
        return 'U' * len(start_path) + ''.join(dest_path)

class Solution:
    def getRow(self, rowIndex: int) -> List[int]:
        # Initialize the first row of Pascal's triangle
        if rowIndex == 0:
            return [1]

        # Initialize the result list with the first row
        result = [1]

        # Fill the result list with the values from Pascal's triangle
        for i in range(1, rowIndex + 1):
            # The value at the current position is the sum of the two values above it
            result.append(result[i - 1] + result[i - 2])

        return result

class Solution:
    def nextClosestTime(self, time: str) -> str:
        # Extract the current hour and minute
        hour, minute = map(int, time.split(':'))

        # Get all unique digits from the time
        digits = set(time.replace(':', ''))

        # Generate all possible next minute values
        for i in range(60):
            next_minute = f"{i:02d}"
            if all(digit in digits for digit in next_minute):
                return f"{hour:02d}:{next_minute}"

        # If no valid next minute is found, find the next hour
        for i in range(hour + 1, 24):
            next_hour = f"{i:02d}"
            if all(digit in digits for digit in next_hour):
                return f"{next_hour}:00"

        # If no valid hour is found, return the first valid time of the next day
        return f"{digits[0]:02d}:{digits[0]:02d}"

class Solution:
    def checkPalindromeFormation(self, a: str, b: str) -> bool:
        def is_palindrome(s: str) -> bool:
            return s == s[::-1]

        def can_form_palindrome(a: str, b: str) -> bool:
            i, j = 0, len(a) - 1
            while i < j and a[i] == b[j]:
                i += 1
                j -= 1
            return is_palindrome(a[i:j+1]) or is_palindrome(b[i:j+1])

        return can_form_palindrome(a, b) or can_form_palindrome(b, a)

class Solution:
    def minimumSeconds(self, land: List[List[str]]) -> int:
        n, m = len(land), len(land[0])
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        queue = deque([(0, 0, 0)])  # (x, y, time)
        visited = set()
        while queue:
            x, y, time = queue.popleft()
            if land[x][y] == 'D':
                return time
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, time + 1))
        return -1

