class Solution:
    def minWastedSpace(self, packages: List[int], boxes: List[List[int]]) -> int:
        MOD = 10**9 + 7
        packages.sort()
        max_package = max(packages)
        total_size = sum(packages)
        min_waste = float('inf')

        for box_sizes in boxes:
            if max_package > max(box_sizes):
                continue

            box_sizes.sort()
            prev_index = -1
            current_waste = 0

            for box_size in box_sizes:
                index = bisect.bisect_right(packages, box_size, prev_index + 1)
                if index > prev_index:
                    current_waste += (index - prev_index) * box_size
                prev_index = index

            if prev_index == len(packages):
                min_waste = min(min_waste, current_waste - total_size)

        return min_waste % MOD if min_waste != float('inf') else -1

from typing import List

class Solution:
    def slowestKey(self, releaseTimes: List[int], keysPressed: str) -> str:
        max_duration = 0
        result_key = ""

        for i in range(len(releaseTimes)):
            if i == 0:
                current_duration = releaseTimes[i]
            else:
                current_duration = releaseTimes[i] - releaseTimes[i-1]

            if current_duration > max_duration or (current_duration == max_duration and keysPressed[i] > result_key):
                max_duration = current_duration
                result_key = keysPressed[i]

        return result_key

