class Solution:
    def maxValueOfCoins(self, piles: List[List[int]], k: int) -> int:
        res = 0

        for i in range(len(piles)):
            piles[i].sort(reverse=True)

            # If there are more coins than pile size, take all coins from the pile
            if len(piles[i]) < k:
                res += sum(piles[i])
            else:
                # Otherwise, take k coins from the pile
                res += sum(piles[i][:k])

        return res

class Solution:
    def vowelStrings(self, words: List[str], left: int, right: int) -> int:
        return sum(1 for word in words if word[0] in "aeiou" and word[-1] in "aeiou")

class Solution:
    def possibleToStamp(self, grid: List[List[int]], stampHeight: int, stampWidth: int) -> bool:
        rows, cols = len(grid), len(grid[0])
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 0:
                    for k in range(i, i + stampHeight):
                        for l in range(j, j + stampWidth):
                            if grid[k][l] == 1:
                                return False
                    grid[i][j] = 1
        return True

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        n = len(word)
        dp = [0] * n
        for i in range(n):
            for j in range(i + 1, min(i + 6, n + 1)):
                if word[i:j] in forbidden:
                    break
            else:
                dp[i] = j - i

        return max(dp)

class Solution:
    def getDirections(self, root: Optional[TreeNode], startValue: int, destValue: int) -> str:
        # Helper function to find the shortest path between two nodes
        def dfs(node, path, start, dest):
            if not node:
                return
            if node.val == start:
                path.append('L')
            elif node.val == dest:
                path.append('R')
            else:
                path.append('U')
            dfs(node.left, path, start, dest)
            dfs(node.right, path, start, dest)
            path.pop()

        # Initialize the path for the start node
        path = ['U']
        dfs(root, path, startValue, destValue)

        # Reverse the path to match the correct order
        path.reverse()
        return ''.join(path)

class Solution:
    def maximumSwap(self, num: int) -> int:
        num_str = list(str(num))
        last_index = {int(digit): i for i, digit in enumerate(num_str)}

        for i, digit in enumerate(num_str):
            for d in range(9, int(digit), -1):
                if last_index.get(d, None) > i:
                    num_str[i], num_str[last_index[d]] = num_str[last_index[d]], num_str[i]
                    return int(''.join(num_str))

        return num

class Solution:
    def smallestStringWithSwaps(self, s: str, pairs: List[List[int]]) -> str:
        n = len(s)
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY

        # Union all connected components
        for u, v in pairs:
            union(u, v)

        # Group characters by their root
        groups = collections.defaultdict(list)
        for i, char in enumerate(s):
            root = find(i)
            groups[root].append((char, i))

        # Sort characters within each group and reconstruct the string
        result = list(s)
        for _, chars in groups.items():
            chars.sort()
            for char, i in chars:
                result[i] = char

        return ''.join(result)

class Solution:
    def getSmallestString(self, s: str) -> str:
        # Convert the string to a list of characters
        chars = list(s)

        # Iterate through the list and swap adjacent characters with the same parity
        for i in range(0, len(chars) - 1):
            if chars[i].isalpha() and (chars[i + 1].isalpha() or chars[i + 1].isdigit()):
                # Swap the characters
                chars[i], chars[i + 1] = chars[i + 1], chars[i]

        # Join the list back into a string
        return ''.join(chars)

class Solution:
    def subarraysWithMoreZerosThanOnes(self, nums: List[int]) -> int:
        count = 0
        for i in range(len(nums)):
            one_count = 0
            zero_count = 0
            for j in range(i, len(nums)):
                if nums[j] == 1:
                    one_count += 1
                else:
                    zero_count += 1
                if one_count > zero_count:
                    count += j - i + 1
        return count % (10**9 + 7)

class Solution:
    def tictactoe(self, moves: List[List[int]]) -> str:
        # Check if there are any moves left
        if len(moves) < 9:
            return "Pending"

        # Check if A has won
        for i in range(3):
            if moves[i][0] == moves[i][1] == moves[i][2]:
                return "A"

        # Check if B has won
        for i in range(3):
            if moves[i][0] == moves[i][1] == moves[i][2]:
                return "B"

        # Check if the game is a draw
        if all(moves[i][0] != "" for i in range(3)):
            return "Draw"

        # If no one has won and there are still moves left, return "Pending"
        return "Pending"

from collections import defaultdict

class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        max_sum = 0
        current_sum = 0
        count_map = defaultdict(int)
        start = 0

        for end in range(len(nums)):
            current_sum += nums[end]

            if end - start + 1 == k:
                if len(count_map) == k:
                    max_sum = max(max_sum, current_sum)

                count_map[nums[start]] -= 1
                if count_map[nums[start]] == 0:
                    del count_map[nums[start]]

                start += 1

            if count_map[nums[end]] == 0:
                count_map[nums[end]] += 1

        return max_sum

