import heapq

class Solution:
    def findShortestWay(self, maze: List[List[int]], ball: List[int], hole: List[int]) -> str:
        m, n = len(maze), len(maze[0])
        directions = {'u': (-1, 0), 'd': (1, 0), 'l': (0, -1), 'r': (0, 1)}

        # Priority queue for BFS with priority on distance and path
        pq = [(0, "", ball[0], ball[1])]
        visited = set()

        while pq:
            dist, path, x, y = heapq.heappop(pq)

            # If we reach the hole, return the path
            if [x, y] == hole:
                return path

            # If already visited this state, skip
            if (x, y) in visited:
                continue
            visited.add((x, y))

            for d, (dx, dy) in directions.items():
                ndist, nx, ny, npath = dist, x, y, path + d

                # Roll the ball until it hits a wall or the hole
                while 0 <= nx + dx < m and 0 <= ny + dy < n and maze[nx + dx][ny + dy] == 0:
                    nx += dx
                    ny += dy
                    ndist += 1

                    # If the ball falls into the hole during the roll
                    if [nx, ny] == hole:
                        return npath

                # If this new state has not been visited, add to the priority queue
                if (nx, ny) not in visited:
                    heapq.heappush(pq, (ndist, npath, nx, ny))

        return "impossible"

class Solution:
    def fixedRatio(self, s: str, num1: int, num2: int) -> int:
        count = 0
        balance = 0
        prefix_count = {0: 1}

        for char in s:
            if char == '0':
                balance += num1
            else:
                balance -= num2

            if balance in prefix_count:
                count += prefix_count[balance]
            else:
                prefix_count[balance] = 0

            prefix_count[balance] += 1

        return count

class Solution:
    def getResults(self, queries: List[List[int]]) -> List[bool]:
        obstacles = set()
        results = []
        for query in queries:
            if query[0] == 1:
                obstacles.add(query[1])
            else:
                x, sz = query[1], query[2]
                left = 0
                while left <= x - sz + 1:
                    if left not in obstacles and (left + sz - 1) not in obstacles:
                        results.append(True)
                        break
                    left += 1
                else:
                    results.append(False)
        return results

class Solution:
    def canEat(self, candiesCount: List[int], queries: List[List[int]]) -> List[bool]:
        n = len(candiesCount)
        ans = []
        for i, q in enumerate(queries):
            favoriteType = q[0]
            favoriteDay = q[1]
            dailyCap = q[2]

            # Calculate the total candies needed to eat the current type of candy
            total_candies_needed = favoriteDay + 1

            # Check if we can eat the current type of candy within the daily cap
            if total_candies_needed > sum(candiesCount[:favoriteType+1]):
                ans.append(False)
            else:
                ans.append(True)

        return ans

class Solution:
    def simplifyPath(self, path: str) -> str:
        stack = []
        for c in path:
            if c == '/':
                if stack and stack[-1] != '.':
                    stack.pop()
            elif c == '.':
                if stack and stack[-1] == '.':
                    stack.pop()
                else:
                    stack.append(c)
            else:
                stack.append(c)
        return '/' + '/'.join(stack)

class Solution:
    def splitWordsBySeparator(self, words: List[str], separator: str) -> List[str]:
        # Split the words using the specified separator
        return [word for word in words if word]

class Solution:
    def findIndices(self, nums: List[int], indexDifference: int, valueDifference: int) -> List[int]:
        min_index, max_index = 0, 0

        for i in range(indexDifference, len(nums)):
            if nums[i] - nums[min_index] >= valueDifference:
                return [min_index, i]
            elif nums[max_index] - nums[i] >= valueDifference:
                return [max_index, i]

            if nums[i] < nums[min_index]:
                min_index = i
            elif nums[i] > nums[max_index]:
                max_index = i

        return [-1, -1]

class Solution:
    def findDerangement(self, n: int) -> int:
        # Initialize the result
        res = 1

        # Calculate the number of derangements using the mathematical formula
        for i in range(1, n + 1):
            res = (res * (i - 1)) % (10**9 + 7)

        return res

class Solution:
    def productQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        powers = []
        while n > 0:
            k = int(math.log2(n))
            powers.append(2 ** k)
            n -= 2 ** k

        powers.reverse()
        m = len(powers)

        ans = []
        for l, r in queries:
            p = 1
            for i in range(l, r + 1):
                p = (p * powers[i]) % (10**9 + 7)
            ans.append(p)

        return ans

class Solution:
    def colorTheGrid(self, m: int, n: int) -> int:
        MOD = 1_000_000_007

        # Define the adjacency matrix for the grid
        adj = [
            [1, 1, 1],
            [1, 0, 1],
            [1, 1, 0]
        ]

        # Initialize the dp array
        dp = [[0] * 3 for _ in range(n)]

        # Base case: There's one way to color the first row
        for i in range(3):
            dp[0][i] = 1

        # Fill the dp table using dynamic programming
        for i in range(1, n):
            for j in range(3):
                for k in range(3):
                    if j != k:
                        dp[i][j] = (dp[i][j] + dp[i-1][k]) % MOD

        # Calculate the total number of ways to color the grid
        result = sum(dp[-1]) % MOD

        return result

class Solution:
    def maxSumRangeQuery(self, nums: List[int], requests: List[List[int]]) -> int:
        from collections import defaultdict

        n = len(nums)
        freq = [0] * (n + 1)

        for start, end in requests:
            freq[start] += 1
            freq[end + 1] -= 1

        for i in range(1, n):
            freq[i] += freq[i - 1]

        freq.pop()
        freq.sort(reverse=True)
        nums.sort(reverse=True)

        max_sum = 0
        MOD = 10**9 + 7

        for f, num in zip(freq, nums):
            if f == 0:
                break
            max_sum = (max_sum + f * num) % MOD

        return max_sum

import heapq

def manhattan_distance(worker, bike):
    return abs(worker[0] - bike[0]) + abs(worker[1] - bike[1])

class Solution:
    def assignBikes(self, workers: List[List[int]], bikes: List[List[int]]) -> List[int]:
        # Create a list of tuples containing worker index, bike index, and Manhattan distance
        heap = []
        for i, worker in enumerate(workers):
            for j, bike in enumerate(bikes):
                dist = manhattan_distance(worker, bike)
                heapq.heappush(heap, (dist, i, j))

        result = [-1] * len(workers)
        visited_bikes = set()

        while heap:
            dist, worker_index, bike_index = heapq.heappop(heap)
            if bike_index not in visited_bikes:
                result[worker_index] = bike_index
                visited_bikes.add(bike_index)
                for i, bike in enumerate(bikes):
                    if i not in visited_bikes:
                        new_dist = manhattan_distance(workers[worker_index], bike)
                        if new_dist < dist:
                            heapq.heappush(heap, (new_dist, worker_index, i))

        return result

class Solution:
    def detectCapitalUse(self, word: str) -> bool:
