from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(pizza), len(pizza[0])

        # Precompute the number of apples in the submatrix (i, j) to (m-1, n-1)
        apples = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                apples[i][j] = apples[i + 1][j] + apples[i][j + 1] - apples[i + 1][j + 1] + (pizza[i][j] == 'A')

        # dp[cuts][i][j] means the number of ways to cut the submatrix (i, j) to (m-1, n-1) with cuts cuts
        dp = [[[0] * (n + 1) for _ in range(m + 1)] for _ in range(k)]
        dp[0][0][0] = 1

        for cuts in range(1, k):
            for i in range(m):
                for j in range(n):
                    # Try to make a horizontal cut
                    for ii in range(i + 1, m):
                        if apples[i][j] - apples[ii][j] > 0 and apples[ii][j] > 0:
                            dp[cuts][ii][j] += dp[cuts - 1][i][j]
                            dp[cuts][ii][j] %= MOD
                    # Try to make a vertical cut
                    for jj in range(j + 1, n):
                        if apples[i][j] - apples[i][jj] > 0 and apples[i][jj] > 0:
                            dp[cuts][i][jj] += dp[cuts - 1][i][j]
                            dp[cuts][i][jj] %= MOD

        return dp[k - 1][0][0]

class Solution:
    def beautifulPartitions(self, s: str, k: int, minLength: int) -> int:
        MOD = 10**9 + 7

        @lru_cache(None)
        def dp(i, l):
            if i == len(s):
                return 1

            ans = 0
            for j in range(l, min(minLength, len(s) - i + 1)):
                if s[i] == '2' or s[i] == '3' or s[i] == '5' or s[i] == '7':
                    continue
                ans = (ans + dp(i + 1, j)) % MOD

            return ans

        return dp(0, minLength)

