class Solution:
    def largestSumAfterKNegations(self, nums: List[int], k: int) -> int:
        nums.sort()
        for i in range(k):
            if nums[i] < 0:
                nums[i] *= -1
            else:
                break
        return sum(nums)

class Solution:
    def minSteps(self, s: str, t: str) -> int:
        # Count the frequency of each character in both strings
        count_s = Counter(s)
        count_t = Counter(t)

        # Calculate the minimum number of steps needed to make t an anagram of s
        steps = 0
        for char in count_s:
            if char in count_t:
                steps += abs(count_s[char] - count_t[char])
            else:
                steps += count_s[char]

        return steps

class Solution:
    def minAddToMakeValid(self, s: str) -> int:
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                if balance > 0:
                    balance -= 1
                else:
                    return 1
        return balance

class Solution:
    def maxSumOfThreeSubarrays(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        window_sums = [sum(nums[i:i+k]) for i in range(n-k+1)]

        left_best = [0] * n
        best = 0
        for i in range(k-1, n):
            if window_sums[i-k+1] > window_sums[best]:
                best = i-k+1
            left_best[i] = best

        right_best = [0] * n
        best = n-k
        for i in range(n-k-1, -1, -1):
            if window_sums[i] >= window_sums[best]:
                best = i
            right_best[i] = best

        max_sum = 0
        result = [0, 0, 0]
        for j in range(k, n-2*k+1):
            i = left_best[j-k]
            l = right_best[j+k]
            current_sum = window_sums[i] + window_sums[j] + window_sums[l]
            if current_sum > max_sum:
                max_sum = current_sum
                result = [i, j, l]

        return result

class Solution:
    def flipgame(self, fronts: List[int], backs: List[int]) -> int:
        # Find numbers that appear on both sides of the card
        same = set(fronts) & set(backs)

        # Initialize the minimum good integer to a large number
        min_good = float('inf')

        # Iterate through each card
        for i in range(len(fronts)):
            # Check if the current card is not in the set of numbers appearing on both sides
            if fronts[i] not in same and backs[i] not in same:
                # Update the minimum good integer if the current card's value is smaller
                min_good = min(min_good, fronts[i])
                min_good = min(min_good, backs[i])

        # If no good integer is found, return 0
        if min_good == float('inf'):
            return 0
        else:
            return min_good

class Solution:
    def reverseWords(self, s: str) -> str:
        return ' '.join(word[::-1] for word in s.split(' '))

class Solution:
    def reverse(self, x: int) -> int:
        # Handle negative numbers by converting them to positive
        if x < 0:
            x = -x

        # Reverse the digits of the number
        reversed_x = int(str(x)[::-1])

        # Check if the reversed number is within the 32-bit integer range
        if reversed_x > 2**31 - 1 or reversed_x < -2**31:
            return 0

        return reversed_x

class Solution:
    def smallestCommonElement(self, mat: List[List[int]]) -> int:
        # Initialize variables to keep track of common elements
        common_elements = set()

        # Iterate through each row in the matrix
        for row in mat:
            # Check if the current row has all elements present in the common_elements set
            if all(element in common_elements for element in row):
                # If common_elements contains all elements from the current row, return the first element
                return next(iter(common_elements))

        # If no common elements are found, return -1
        return -1

class Solution:
    def isWinner(self, player1: List[int], player2: List[int]) -> int:
        def calculate_score(player):
            score = 0
            n = len(player)
            for i in range(n):
                if player[i] == 10:
                    score += 2 * player[i]
                    if i > 0:
                        score += player[i-1]
                    if i > 1:
                        score += player[i-2]
                else:
                    score += player[i]
            return score

        score1 = calculate_score(player1)
        score2 = calculate_score(player2)

        if score1 > score2:
            return 1
        elif score2 > score1:
            return 2
        else:
            return 0

class Solution:
    def sumOfThree(self, num: int) -> List[int]:
        if num % 3 != 0:
            return []

        # Calculate the three consecutive integers
        first = num - 2
        second = first + 1
        third = first + 2

        return [first, second, third]

class Solution:
    def rangeBitwiseAnd(self, left: int, right: int) -> int:
        # Use bitwise AND operator to find the bitwise AND of all numbers in the range
        return left & right

from collections import defaultdict, deque
from typing import List

class Solution:
    def sequenceReconstruction(self, nums: List[int], sequences: List[List[int]]) -> bool:
        n = len(nums)
        graph = defaultdict(list)
        indegree = [0] * (n + 1)

        # Build the graph and compute in-degrees
        for seq in sequences:
            for i in range(len(seq)):
                if i > 0:
                    graph[seq[i - 1]].append(seq[i])
                    indegree[seq[i]] += 1

        # Initialize the queue with nodes having zero in-degree
        queue = deque([i for i in range(1, n + 1) if indegree[i] == 0])

        # If there's more than one node with zero in-degree, return False
        if len(queue) != 1:
            return False

        reconstructed = []

        while queue:
            if len(queue) > 1:
                return False

            node = queue.popleft()
            reconstructed.append(node)

            for neighbor in graph[node]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    queue.append(neighbor)

        return reconstructed == nums

