class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int], k: int) -> int:
        if sum(nums1) != sum(nums2): return -1

        diff = 0
        for x,y in zip(nums1, nums2):
            diff += abs(x-y)

        if diff % k != 0: return -1

        return diff // k

class Solution:
    def maxBoxesInWarehouse(self, boxes: List[int], warehouse: List[int]) -> int:
        # Sort the boxes in ascending order
        boxes.sort()

        # Calculate the minimum height from the left to each position in the warehouse
        min_left = warehouse[:]
        for i in range(1, len(warehouse)):
            min_left[i] = min(min_left[i], min_left[i-1])

        # Calculate the minimum height from the right to each position in the warehouse
        min_right = warehouse[:]
        for i in range(len(warehouse) - 2, -1, -1):
            min_right[i] = min(min_right[i], min_right[i+1])

        # Use two pointers to find the maximum number of boxes that can be placed
        left, right = 0, len(warehouse) - 1
        count = 0

        while left <= right:
            if boxes[count] <= min_left[left]:
                left += 1
            elif boxes[count] <= min_right[right]:
                right -= 1
            else:
                break
            count += 1

        return count

class Solution:
    def soupServings(self, n: int) -> float:
        if n >= 5000:
            return 1

        memo = {}

        def dfs(a, b):
            if (a, b) in memo:
                return memo[(a, b)]

            if a <= 0 and b > 0:
                return 1
            if a > 0 and b <= 0:
                return 0
            if a <= 0 and b <= 0:
                return 0.5

            memo[(a, b)] = 0.25 * (dfs(a - 4, b) + dfs(a - 3, b - 1) + dfs(a - 2, b - 2) + dfs(a - 1, b - 3))

            return memo[(a, b)]

        return dfs(n, n)

