class Solution:
    def distinctAverages(self, nums: List[int]) -> int:
        res = set()
        while len(nums) > 0:
            min_val = min(nums)
            max_val = max(nums)
            res.add((min_val+max_val)/2)
            nums.remove(min_val)
            nums.remove(max_val)
        return len(res)

