import math

class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        def is_prime(n):
            if n < 2:
                return False
            for i in range(2, int(math.sqrt(n)) + 1):
                if n % i == 0:
                    return False
            return True

        max_diff = 0
        primes = []

        for num in nums:
            if is_prime(num):
                primes.append(num)

        for i in range(len(primes)):
            for j in range(i+1, len(primes)):
                max_diff = max(max_diff, abs(primes[j] - primes[i]))

        return max_diff

class Solution:
    def shortestWay(self, source: str, target: str) -> int:
        count = 1
        i = 0
        for c in target:
            found = False
            for j in range(i, len(source)):
                if source[j] == c:
                    i = j + 1
                    found = True
                    break
            if not found:
                count += 1
                i = 0
                j = next((k for k, x in enumerate(source) if x == c), None)
                if j is None:
                    return -1
                i = j + 1
        return count

class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        total_sum = sum(nums[:k])
        max_sum = total_sum

        for i in range(k, len(nums)):
            total_sum += nums[i] - nums[i-k]
            if total_sum > max_sum:
                max_sum = total_sum

        return max_sum / k

class Solution:
    def checkIfCanBreak(self, s1: str, s2: str) -> bool:
        # Count the frequency of each character in both strings
        count1 = Counter(s1)
        count2 = Counter(s2)

        # Check if the characters in s1 can be broken by characters in s2
        for char in count1:
            if char in count2 and count2[char] > count1[char]:
                return False

        # Check if the characters in s2 can be broken by characters in s1
        for char in count2:
            if char in count1 and count1[char] > count2[char]:
                return False

        return True

