class Solution:
    def countHighestScoreNodes(self, parents: List[int]) -> int:
        from collections import defaultdict

        # Build the tree using adjacency list
        tree = defaultdict(list)
        for child, parent in enumerate(parents):
            if parent != -1:
                tree[parent].append(child)

        # Dictionary to store the size of each subtree
        subtree_size = {}

        def dfs(node):
            if node not in tree:
                subtree_size[node] = 1
                return 1
            total = 1
            for child in tree[node]:
                total += dfs(child)
            subtree_size[node] = total
            return total

        # Calculate the size of each subtree
        dfs(0)

        n = len(parents)
        max_score = 0
        count_max_score = 0

        for node in range(n):
            score = 1
            remaining_nodes = n - 1 - subtree_size.get(node, 0)
            if remaining_nodes > 0:
                score *= remaining_nodes
            for child in tree[node]:
                score *= subtree_size[child]

            if score > max_score:
                max_score = score
                count_max_score = 1
            elif score == max_score:
                count_max_score += 1

        return count_max_score

class Solution:
    def isAdditiveNumber(self, num: str) -> bool:
        n = len(num)
        if n < 3:
            return False

        # Iterate through the string from the second character
        for i in range(1, n - 1):
            # Try to split the string into two parts at the current position
            part1 = num[:i]
            part2 = num[i:]

            # Check if both parts are valid numbers
            if part1.isdigit() and part2.isdigit():
                # Try to convert the first part to an integer and add the second part
                try:
                    a = int(part1)
                    b = int(part2)
                    c = a + b
                    if c == int(num):
                        return True
                except ValueError:
                    continue

        return False

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        # Fill the table
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if word1[i - 1] == word2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + 1

        return dp[m][n]

class Solution:
    def sumGame(self, num: str) -> bool:
        n = len(num)
        mid = n // 2

        left_sum = 0
        left_question_marks = 0
        right_sum = 0
        right_question_marks = 0

        for i in range(mid):
            if num[i] == '?':
                left_question_marks += 1
            else:
                left_sum += int(num[i])

        for i in range(mid, n):
            if num[i] == '?':
                right_question_marks += 1
            else:
                right_sum += int(num[i])

        # Calculate the difference in sums and question marks
        diff_sum = left_sum - right_sum
        diff_questions = right_question_marks - left_question_marks

        # If the number of question marks is odd, Alice can always win
        if (left_question_marks + right_question_marks) % 2 != 0:
            return True

        # If the difference in question marks is not enough to balance the sum difference, Alice wins
        if diff_questions % 2 != 0:
            return True

        # Calculate the required adjustment to balance the sums
        required_adjustment = diff_sum + (diff_questions // 2) * 9

        # If the required adjustment is not zero, Alice wins
        return required_adjustment != 0

class Solution:
    def new21Game(self, n: int, k: int, maxPts: int) -> float:
        if k == 0 or n >= k + maxPts - 1:
            return 1.0

        dp = [0.0] * (n + 1)
        dp[0] = 1.0
        windowSum = 1.0
        result = 0.0

        for i in range(1, n + 1):
            dp[i] = windowSum / maxPts
            if i < k:
                windowSum += dp[i]
            if i - maxPts >= 0:
                windowSum -= dp[i - maxPts]
            if i >= k:
                result += dp[i]

        return result

