class Solution:
    def countPairs(self, deliciousness: List[int]) -> int:
        MOD = 10**9 + 7
        max_power_of_two = 2**21
        power_of_twos = [1 << i for i in range(22)]
        count = Counter(deliciousness)
        result = 0

        for num in count:
            for power in power_of_twos:
                complement = power - num
                if complement < 0:
                    continue
                if complement == num:
                    result += (count[num] * (count[num] - 1)) // 2
                else:
                    result += count[num] * count[complement]

        return result % MOD

