class Solution:
    def latestTimeCatchTheBus(self, buses: List[int], passengers: List[int], capacity: int) -> int:
        buses.sort()
        passengers.sort()

        last_passenger = -1
        p_index = 0

        for bus_time in buses:
            taken = 0
            while p_index < len(passengers) and passengers[p_index] <= bus_time and taken < capacity:
                if passengers[p_index] != last_passenger:
                    last_passenger = passengers[p_index]
                p_index += 1
                taken += 1

            if taken < capacity and last_passenger < bus_time:
                return bus_time

        while last_passenger == passengers[-1]:
            last_passenger -= 1

        return last_passenger

class Solution:
    def romanToInt(self, s: str) -> int:
        roman_map = {
            'I': 1,
            'V': 5,
            'X': 10,
            'L': 50,
            'C': 100,
            'D': 500,
            'M': 1000
        }

        total = 0
        i = 0

        while i < len(s):
            if i + 1 < len(s) and roman_map[s[i]] < roman_map[s[i + 1]]:
                total += roman_map[s[i + 1]] - roman_map[s[i]]
                i += 2
            else:
                total += roman_map[s[i]]
                i += 1

        return total

