class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        if not nums or k == 0:
            return []

        deque_max = deque()
        result = []

        for i in range(len(nums)):
            # Remove elements from the front of the deque that are out of the current window
            while deque_max and nums[deque_max[0]] < nums[i]:
                deque_max.popleft()

            # Add the current element's index to the deque
            deque_max.append(i)

            # If the current window size is greater than or equal to k, add the maximum value in the deque to the result
            if i >= k - 1:
                result.append(nums[deque_max[0]])

                # Remove the index of the oldest element in the deque if it is outside the current window
                if deque_max[0] == i - k + 1:
                    deque_max.popleft()

        return result

class Solution:
    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        # check if s3 is empty
        if not s3:
            return True

        # initialize dp array with False values
        dp = [[False] * (len(s2) + 1) for _ in range(len(s1) + 1)]

        # base case: if s1 is empty, s3 can be formed from s2
        dp[0][0] = True

        # fill the dp table
        for i in range(1, len(s1) + 1):
            dp[i][0] = dp[i-1][0]

        for j in range(1, len(s2) + 1):
            dp[0][j] = dp[0][j-1]

        for i in range(1, len(s1) + 1):
            for j in range(1, len(s2) + 1):
                # if characters match, check the next cell in dp
                if s1[i-1] == s3[i+j-1] and dp[i-1][j]:
                    dp[i][j] = True
                elif s2[j-1] == s3[i+j-1] and dp[i][j-1]:
                    dp[i][j] = True

        return dp[-1][-1]

