class Solution:
    def findBottomLeftValue(self, root: Optional[TreeNode]) -> int:
        if not root:
            return None

        queue = deque([root])
        while queue:
            size = len(queue)
            leftmost_value = queue[0].val

            for _ in range(size):
                node = queue.popleft()

                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

        return leftmost_value

class Solution:
    def reachNumber(self, target: int) -> int:
        if target < 0:
            target *= -1

        # Calculate the minimum number of steps required
        step = 0
        while True:
            step += 1
            if target <= step * (step + 1) // 2:
                break

        # Adjust the number of steps based on the parity of target
        if target % 2 == 0:
            return step
        else:
            if step % 2 == 0:
                return step + 1
            else:
                return step + 2

