class Solution:
    def kIncreasing(self, arr: List[int], k: int) -> int:
        n = len(arr)
        ans = 0

        for i in range(k):
            subseq = []
            for j in range(i, n, k):
                if not subseq or arr[j] >= subseq[-1]:
                    subseq.append(arr[j])
                else:
                    idx = bisect_right(subseq, arr[j])
                    subseq[idx] = arr[j]
            ans += len(subseq) - len(list(groupby(subseq)))

        return ans

class Solution:
    def findWinners(self, matches: List[List[int]]) -> List[List[int]]:
        # Create dictionaries to count matches for each player
        winner_to_matches = {}
        loser_to_matches = {}

        # Populate the dictionaries with matches
        for winner, loser in matches:
            if winner in winner_to_matches:
                winner_to_matches[winner].append(loser)
            else:
                winner_to_matches[winner] = [loser]

            if loser in loser_to_matches:
                loser_to_matches[loser].append(winner)
            else:
                loser_to_matches[loser] = [winner]

        # Collect players who have not lost any matches
        winners_without_matches = []
        for winner, matches in winner_to_matches.items():
            if len(matches) == 0:
                winners_without_matches.append(winner)

        # Collect players who have lost exactly one match
        losers_with_one_match = []
        for loser, matches in loser_to_matches.items():
            if len(matches) == 1:
                losers_with_one_match.append(loser)

        return [winners_without_matches, losers_with_one_match]

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def checkEqualTree(self, root: Optional[TreeNode]) -> bool:
        def sum_tree(node):
            if not node:
                return 0
            return node.val + sum_tree(node.left) + sum_tree(node.right)

        total_sum = sum_tree(root)

        def can_partition(node):
            if not node:
                return 0

            left_sum = sum_tree(node.left)
            right_sum = sum_tree(node.right)

            if node.left and left_sum == total_sum - left_sum:
                return True
            if node.right and right_sum == total_sum - right_sum:
                return True

            return can_partition(node.left) or can_partition(node.right)

        return can_partition(root)

class Solution:
    def getFood(self, grid: List[List[str]]) -> int:
        m, n = len(grid), len(grid[0])
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        def bfs(x, y):
            queue = collections.deque([(x, y)])
            visited = set()
            steps = 0

            while queue:
                for _ in range(len(queue)):
                    x, y = queue.popleft()
                    if grid[x][y] == '*':
                        return steps
                    if (x, y) not in visited:
                        visited.add((x, y))
                        for dx, dy in directions:
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != 'X':
                                queue.append((nx, ny))
            return -1

        return bfs(0, 0)

class Solution:
    def maxProduct(self, s: str) -> int:
        def is_palindrome(sub):
            return sub == sub[::-1]

        n = len(s)
        max_product = 0

        for mask in range(1, 1 << n):
            subseq1 = []
            subseq2 = []
            for j in range(n):
                if mask & (1 << j):
                    subseq1.append(s[j])
                else:
                    subseq2.append(s[j])

            if is_palindrome(subseq1) and is_palindrome(subseq2):
                max_product = max(max_product, len(subseq1) * len(subseq2))

        return max_product

from typing import List

class Solution:
    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        from collections import defaultdict

        # Build the graph
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        total_sum = sum(nums)
        max_val = max(nums)

        # Check if we can split the tree into k components
        def can_split(k):
            if total_sum % k != 0:
                return False

            target = total_sum // k

            def dfs(node, parent):
                component_sum = nums[node]
                for neighbor in graph[node]:
                    if neighbor != parent:
                        neighbor_sum = dfs(neighbor, node)
                        if neighbor_sum == -1:
                            return -1
                        component_sum += neighbor_sum

                if component_sum > target:
                    return -1
                elif component_sum == target:
                    return 0
                else:
                    return component_sum

            return dfs(0, -1) == 0

        # Try to split the tree into k components, starting from the largest possible k
        for k in range(total_sum // max_val, 0, -1):
            if can_split(k):
                return k - 1

        return 0

class Solution:
    def numberOfWays(self, s: str) -> int:
        count_0, count_1, result = 0, 0, 0

        for char in s:
            if char == '0':
                count_0 += 1
            else:
                count_1 += 1

            # If there are more than one '1', it's not possible to have three consecutive '1's
            if count_1 > 1:
                continue

            # Calculate the number of ways to choose 2 buildings from the remaining '0's
            result += count_0 * (count_0 - 1) // 2

        return result

class Solution:
    def largestEvenSum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix_sums = [0] * (n + 1)
        for i in range(1, n + 1):
            prefix_sums[i] = prefix_sums[i - 1] + nums[i - 1]

        max_even_sum = -1
        for i in range(n - k + 1):
            if prefix_sums[i + k - 1] % 2 == 0:
                max_even_sum = max(max_even_sum, prefix_sums[i + k - 1])

        return max_even_sum

