import math

class Solution:
    def areConnected(self, n: int, threshold: int, queries: List[List[int]]) -> List[bool]:
        graph = defaultdict(set)
        for i in range(threshold + 1, n + 1):
            for j in range(i * 2, n + 1, i):
                graph[i].add(j)
                graph[j].add(i)

        visited = set()
        def dfs(node):
            if node in visited:
                return False
            visited.add(node)
            for neighbor in graph[node]:
                if not dfs(neighbor):
                    return False
            return True

        return [dfs(x) and dfs(y) for x, y in queries]

from typing import List

class Solution:
    def minSumSquareDiff(self, nums1: List[int], nums2: List[int], k1: int, k2: int) -> int:
        n = len(nums1)
        diff = [abs(nums1[i] - nums2[i]) for i in range(n)]
        total_k = k1 + k2

        # Sort the differences in descending order
        diff.sort(reverse=True)

        # If the total number of operations is greater than or equal to the sum of all differences
        if total_k >= sum(diff):
            return 0

        # Reduce the largest differences first
        for i in range(n):
            if total_k == 0:
                break
            if i > 0 and diff[i] == diff[i - 1]:
                continue
            reduce_amount = min(diff[i], total_k)
            diff[i] -= reduce_amount
            total_k -= reduce_amount

        # Calculate the sum of squares of the remaining differences
        return sum(x * x for x in diff)

