class Solution:
    def minRemoveToMakeValid(self, s: str) -> str:
        stack = []
        res = []

        for i, char in enumerate(s):
            if char == '(':
                stack.append(i)
            elif char == ')':
                if stack:
                    stack.pop()
                else:
                    res.append(i)

        for i in range(len(s)):
            if i in stack or i in res:
                continue
            res.append(s[i])

        return ''.join(res)

