class Solution:
    def findSmallestInteger(self, nums: List[int], value: int) -> int:
        remainders = defaultdict(int)
        for num in nums:
            remainders[num % value] += 1
        min_count = min(remainders.values())
        return min_count * value + next(i for i in range(value) if remainders[i] == min_count)

