class Solution:
    def largestMagicSquare(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate prefix sums for rows and columns
        row_prefixes = [[0] * (n + 1) for _ in range(m + 1)]
        col_prefixes = [[0] * (m + 1) for _ in range(n + 1)]

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                row_prefixes[i][j] = grid[i - 1][j - 1] + row_prefixes[i - 1][j]
                col_prefixes[i][j] = grid[i - 1][j - 1] + col_prefixes[i][j - 1]

        max_size = 1

        # Check each possible size from 1 to min(m, n)
        for size in range(1, min(m, n) + 1):
            for i in range(m - size + 1):
                for j in range(n - size + 1):
                    # Calculate the sum of the current submatrix
                    total_sum = row_prefixes[i + size][j + size] - row_prefixes[i][j + size] - row_prefixes[i + size][j] + row_prefixes[i][j]

                    # Check if the sum is consistent across all rows, columns, and diagonals
                    valid = True
                    for k in range(size):
                        if total_sum != row_prefixes[i + k + 1][j + size] - row_prefixes[i + k][j + size] - row_prefixes[i + k + 1][j] + row_prefixes[i + k][j]:
                            valid = False
                            break
                        if total_sum != col_prefixes[i + size][j + k + 1] - col_prefixes[i + size][j + k] - col_prefixes[i + size][j + 1] + col_prefixes[i + size][j]:
                            valid = False
                            break

                    # Check the main diagonal
                    if total_sum != row_prefixes[i + size][j + size] - row_prefixes[i][j + size] - row_prefixes[i + size][j] + row_prefixes[i][j]:
                        valid = False

                    # Check the anti-diagonal
                    if total_sum != row_prefixes[i + size][j] - row_prefixes[i + size][j - 1] - row_prefixes[i][j + size] + row_prefixes[i][j]:
                        valid = False

                    if valid:
                        max_size = max(max_size, size)

        return max_size

class Solution:
    def distMoney(self, money: int, children: int) -> int:
        if money < children:
            return -1

        # First give each child 1 dollar
        money -= children

        # Distribute the remaining money to as many children as possible with 8 dollars
        count = min(money // 7, children - 1)
        money %= 7

        # If the last child gets 4 dollars, redistribute 3 dollars to the previous child
        if count == children - 1 and money == 3:
            count -= 1

        # If the last child gets 7 dollars, redistribute 1 dollar to the previous child
        if count == children - 1 and money == 7:
            count -= 1

        return count

