                if words[i] + words[j] == words[i][::-1] and words[i] != words[j]:
                    res.append([i, j])
        return res

from collections import defaultdict

class Solution:
    def leadsToDestination(self, n: int, edges: List[List[int]], source: int, destination: int) -> bool:
        # Create adjacency list representation of the graph
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)

        # Check if the destination can be reached from the source
        return self.dfs(graph, source, destination, set())

    def dfs(self, graph, current, target, visited):
        # If the current node has been visited before, it means there's a cycle
        if current in visited:
            return False

        # Mark the current node as visited
        visited.add(current)

        # If the current node is the target, return True
        if current == target:
            return True

        # Recur for each neighbor of the current node
        for neighbor in graph[current]:
            if not self.dfs(graph, neighbor, target, visited):
                return False

        # Unmark the current node after exploring its neighbors
        visited.remove(current)
        return True

