class Solution:
    def maximumLengthOfRanges(self, nums: List[int]) -> List[int]:
        n = len(nums)
        left = [-1] * n
        right = [n] * n

        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] < nums[i]:
                right[stack.pop()] = i
            if stack:
                left[i] = stack[-1]
            stack.append(i)

        ans = [0] * n
        for i in range(n):
            ans[i] = right[i] - left[i] - 1

        return ans

class Solution:
    def countPoints(self, rings: str) -> int:
        # Create a dictionary to store the count of each color
        color_count = {}

        # Iterate over the rings string
        for i in range(0, len(rings), 2):
            color = rings[i]
            rod = rings[i+1]

            # Increment the count for the current color
            if color in color_count:
                color_count[color] += 1
            else:
                color_count[color] = 1

        # Count the rods that have all three colors
        count = sum(1 for color, count in color_count.items() if count == 3)

        return count

class Solution:
    def isDecomposable(self, s: str) -> bool:
        count = 0
        i = 0
        while i < len(s):
            if s[i] == '0':
                return False
            j = i + 1
            while j < len(s) and s[j] == s[i]:
                j += 1
            if (j - i) % 3 != 0:
                return False
            count += (j - i) // 3
            i = j
        return count == 1

class Solution:
    def countSubarrays(self, nums: List[int], minK: int, maxK: int) -> int:
        ans = left = right = 0
        for i, num in enumerate(nums):
            if num < minK or num > maxK:
                left = right = i + 1
            else:
                ans += right - left + 1
            right = i + 1
        return ans

class Solution:
    def countSubMultisets(self, nums: List[int], l: int, r: int) -> int:
        MOD = 10**9 + 7
        dp = [[0] * (r+1) for _ in range(len(nums)+1)]
        dp[0][0] = 1

        for i in range(1, len(nums)+1):
            for j in range(r+1):
                dp[i][j] = (dp[i-1][j] + dp[i][j-nums[i-1]]) % MOD

        return dp[-1][-1]

class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:
        # create adjacency list
        adjList = [[] for _ in range(n)]
        for i in range(n):
            if manager[i] != -1:
                adjList[manager[i]].append(i)

        # perform DFS starting from the head node
        stack = [(headID, 0)]  # (node, time)
        totalTime = 0
        while stack:
            node, time = stack.pop()
            totalTime += time

            for neighbor in adjList[node]:
                stack.append((neighbor, time + informTime[neighbor]))

        return totalTime

class Solution:
    def connectTwoGroups(self, cost: List[List[int]]) -> int:
        m, n = len(cost), len(cost[0])
        dp = [[float('inf')] * (1 << n) for _ in range(m + 1)]
        dp[0][0] = 0

        for i in range(1, m + 1):
            min_col_cost = min(cost[i-1])
            for state in range(1 << n):
                dp[i][state] = min(dp[i][state], dp[i-1][state] + min_col_cost)
                for j in range(n):
                    if (state >> j) & 1:
                        dp[i][state] = min(dp[i][state], dp[i-1][state ^ (1 << j)] + cost[i-1][j])

        return dp[m][(1 << n) - 1]

class Solution:
    def numberOfWays(self, corridor: str) -> int:
        mod = 10**9 + 7

        # Count the total number of seats
        num_seats = corridor.count('S')

        # Check if there are enough seats for divisions
        if num_seats % 2 != 0 or num_seats < 4:
            return 0

        # Initialize variables
        result = 1
        count_plants = 0
        start_divider = False

        for char in corridor:
            if char == 'S':
                if start_divider:
                    # Multiply result by the number of ways to place dividers between two groups of seats
                    result = (result * (count_plants + 1)) % mod
                    count_plants = 0
                start_divider = True
            else:
                count_plants += 1

        return result

