class Solution:
    def numberOfPairs(self, points: List[List[int]]) -> int:
        n = len(points)
        ans = 0

        # Sort points based on x-coordinate and then by y-coordinate
        points.sort(key=lambda x: (x[0], x[1]))

        # Iterate over each point as the upper left corner of the fence
        for i in range(n):
            x1, y1 = points[i]
            # Iterate over each point as the lower right corner of the fence
            for j in range(i + 1, n):
                x2, y2 = points[j]

                # Check if the current pair forms a valid fence
                if x1 <= x2 and y1 >= y2:
                    ans += 1

        return ans

class Solution:
    def minOperations(self, initial: str, target: str) -> int:
        if initial == target:
            return 0

        if len(initial) > len(target):
            initial, target = target, initial

        # Find the longest common prefix
        i = 0
        while i < len(initial) and i < len(target) and initial[i] == target[i]:
            i += 1

        # Calculate the cost for removing the remaining characters from initial
        removal_cost_initial = len(initial) - i

        # Calculate the cost for adding characters to target
        addition_cost_target = len(target) - i

        # The total cost is the sum of removals and additions
        return removal_cost_initial + addition_cost_target

class Solution:
    def amountPainted(self, paint: List[List[int]]) -> List[int]:
        n = len(paint)
        worklog = [0] * n

        for i in range(n):
            for j in range(i + 1, n):
                if paint[i][1] >= paint[j][0]:
                    worklog[i] += paint[j][1] - paint[i][0] + 1

        return worklog

