class Solution:
    def countCompleteComponents(self, n: int, edges: List[List[int]]) -> int:
        adj_list = [[] for _ in range(n)]
        for u, v in edges:
            adj_list[u].append(v)
            adj_list[v].append(u)

        visited = set()
        def dfs(node):
            visited.add(node)
            for neighbor in adj_list[node]:
                if neighbor not in visited:
                    dfs(neighbor)

        count = 0
        for i in range(n):
            if i not in visited:
                dfs(i)
                if len(adj_list[i]) * (len(adj_list[i]) - 1) // 2 == len(visited):
                    count += 1

        return count

class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        min_left = float('inf')
        min_right = float('inf')
        res = float('inf')

        for i in range(1, len(nums)-1):
            if nums[i] > min_left:
                min_right = min(min_right, nums[-1])
                res = min(res, nums[i] + min_left + min_right)
            elif nums[i] < min_left:
                min_left = nums[i]

        return res if res != float('inf') else -1

class Solution:
    def kMirror(self, k: int, n: int) -> int:
        if k == 1:
            return 1

        def is_k_mirror(num):
            num_str = str(num)
            reversed_num_str = num_str[::-1]
            return num_str == reversed_num_str

        count = 0
        result = 0
        current = 1

        while count < n:
            if is_k_mirror(current):
                result += current
                count += 1
            current += 1

        return result

class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        if n > m:
            n, m = m, n

        dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]

        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if i == j:
                    dp[i][j] = 1
                else:
                    for k in range(1, min(i, j) + 1):
                        dp[i][j] = min(dp[i][j], dp[i - k][j] + dp[k][j])
                        dp[i][j] = min(dp[i][j], dp[i][j - k] + dp[i][k])

        return dp[n][m]

