class Solution:
    def minOperations(self, s1: str, s2: str, x: int) -> int:
        n = len(s1)
        dp = [[float('inf')] * 2 for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            diff = int(s1[i - 1]) ^ int(s2[i - 1])
            dp[i][0] = dp[i - 1][diff]
            dp[i][1] = dp[i - 1][1 - diff] + 1
            if i > 1:
                dp[i][0] = min(dp[i][0], dp[i - 2][0] + x)
                dp[i][1] = min(dp[i][1], dp[i - 2][1] + x)

        return dp[n][0] if dp[n][0] != float('inf') else -1

class Solution:
    def isAdditiveNumber(self, num: str) -> bool:
        n = len(num)

        def isValid(i, j, k):
            # Check if the first number has leading zeros
            if i > 0 and num[i] == '0':
                return False

            # Check if the second number has leading zeros
            if j > 0 and num[j] == '0':
                return False

            # Check if the sum of the first two numbers is equal to the third number
            s = str(int(num[i:j]) + int(num[j:k]))
            if s != num[k:k+len(s)]:
                return False

            return True

        # Try all possible pairs of indices for the first two numbers
        for i in range(1, n):
            for j in range(i+1, n):
                if isValid(0, i, j):
                    # Try all possible indices for the third number
                    for k in range(j+1, n):
                        if isValid(i, j, k):
                            return True

        return False

class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Calculate the number of valid rotations
        rotations = 0
        for i in range(n):
            if s == t:
                rotations += 1
            s = s[1:] + s[0]

        # If no rotation matches t, return 0
        if rotations == 0:
            return 0

        # If k is 1, we can only perform one rotation
        if k == 1:
            return rotations

        # Calculate the number of ways to perform k rotations
        total_ways = pow(rotations, k, MOD)

        return total_ways

