class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:
        INF = float('inf')

        # dp[i][j][k] means the minimum cost to paint houses[0:i+1] with j neighborhoods ending with color k+1
        dp = [[[INF] * n for _ in range(target + 1)] for _ in range(m)]

        for i in range(m):
            for j in range(1, target + 1):
                for k in range(n):
                    if houses[i] != 0 and houses[i] - 1 != k:
                        continue
                    if i == 0:
                        if houses[i] == 0:
                            dp[i][j][k] = cost[i][k]
                        else:
                            dp[i][j][k] = 0
                        continue

                    if houses[i] == 0:
                        dp[i][j][k] = min(dp[i][j][k], dp[i-1][j][k] + cost[i][k])

                    for kk in range(n):
                        if kk == k:
                            dp[i][j][k] = min(dp[i][j][k], dp[i-1][j][kk] + (0 if houses[i] != 0 else cost[i][k]))
                        else:
                            dp[i][j][k] = min(dp[i][j][k], dp[i-1][j-1][kk] + (0 if houses[i] != 0 else cost[i][k]))

        result = INF
        for k in range(n):
            result = min(result, dp[m-1][target][k])

        return result if result != INF else -1

class Solution:
    def minimizeStringValue(self, s: str) -> str:
        count = [0] * 26
        for c in s:
            if c != '?':
                count[ord(c) - ord('a')] += 1

        res = []
        for c in s:
            if c == '?':
                min_index = min(range(26), key=lambda i: (count[i], chr(ord('a') + i)))
                res.append(chr(ord('a') + min_index))
                count[min_index] += 1
            else:
                res.append(c)

        return ''.join(res)

