class Solution:
    def minimumTotalCost(self, nums1: List[int], nums2: List[int]) -> int:
        # Count occurrences of each element in both lists
        count1 = Counter(nums1)
        count2 = Counter(nums2)

        # Find elements that need swapping
        swap_elements = []
        for num in range(1, len(nums1) + 1):
            if count1[num] > count2[num]:
                swap_elements.append(num)
            elif count1[num] < count2[num]:
                swap_elements.append(num)

        # Sort the swap elements based on their frequency
        swap_elements.sort(key=lambda x: count1[x])

        # Calculate the total cost
        total_cost = 0
        for i in range(len(swap_elements)):
            total_cost += i

        # Check if it's possible to make all elements equal
        if len(swap_elements) % 2 == 0:
            return total_cost // 2
        else:
            return -1

from typing import List

class Solution:
    def minimumDiameterAfterMerge(self, edges1: List[List[int]], edges2: List[List[int]]) -> int:
        def bfs(graph, start):
            queue = [(start, 0)]
            visited = set()
            visited.add(start)
            max_distance = 0
            farthest_node = start

            while queue:
                node, distance = queue.pop(0)
                if distance > max_distance:
                    max_distance = distance
                    farthest_node = node

                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append((neighbor, distance + 1))

            return farthest_node, max_distance

        def get_diameter(graph):
            node, _ = bfs(graph, 0)
            _, diameter = bfs(graph, node)
            return diameter

        def build_graph(edges):
            graph = {}
            for u, v in edges:
                if u not in graph:
                    graph[u] = []
                if v not in graph:
                    graph[v] = []
                graph[u].append(v)
                graph[v].append(u)
            return graph

        graph1 = build_graph(edges1)
        graph2 = build_graph(edges2)

        diameter1 = get_diameter(graph1)
        diameter2 = get_diameter(graph2)

        max_diameter = max(diameter1, diameter2)

        for u in graph1:
            for v in graph2:
                # Calculate the new diameter if we connect u from graph1 to v from graph2
                # The new diameter is the sum of the longest paths from u to a leaf in graph1
                # and from v to a leaf in graph2, minus the overlap of the connection point
                farthest_u, dist_u = bfs(graph1, u)
                farthest_v, dist_v = bfs(graph2, v)
                new_diameter = dist_u + dist_v + 1
                max_diameter = max(max_diameter, new_diameter)

        return max_diameter

class Solution:
    def findGameWinner(self, n: int) -> bool:
