class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0

        queue = deque([root])
        depth = 0

        while queue:
            size = len(queue)
            depth += 1

            for _ in range(size):
                node = queue.popleft()

                if not node.left and not node.right:
                    return depth

                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

        return depth

class Solution:
    def minimumCoins(self, prices: List[int]) -> int:
        n = len(prices)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(1, i + 1):
                if prices[j - 1] <= prices[i - 1]:
                    dp[i] = min(dp[i], dp[j - 1] + prices[i - 1])

        return dp[n]

class Solution:
    def waysToPartition(self, nums: List[int], k: int) -> int:
        n = len(nums)
        left, right = 0, n - 1

        while left < right:
            pivot = (left + right) // 2

            # Check if the sum of elements from the left to pivot equals the sum of elements from the right to pivot
            if sum(nums[:pivot]) == sum(nums[pivot + 1:]):
                return 1
            elif sum(nums[:pivot]) > sum(nums[pivot + 1:]):
                right = pivot - 1
            else:
                left = pivot + 1

        return 0

