import functools

class Solution:
    def minDistance(self, houses: List[int], k: int) -> int:
        houses.sort()

        @functools.lru_cache(None)
        def cost(i, j):
            mid = (i + j) // 2
            return sum(abs(houses[m] - houses[mid]) for m in range(i, j + 1))

        @functools.lru_cache(None)
        def dp(n, k):
            if n == 0:
                return 0
            if k == 0:
                return float('inf')
            res = float('inf')
            for i in range(n - 1, -1, -1):
                res = min(res, dp(i, k - 1) + cost(i + 1, n))
            return res

        return dp(len(houses) - 1, k)

class Solution:
    def waysToReachTarget(self, target: int, types: List[List[int]]) -> int:
        MOD = 10**9 + 7

        # dp[i][j] represents the number of ways to reach target i using at most j types
        dp = [[0] * (target + 1) for _ in range(len(types))]

        # Base case: no types used, only one way to reach 0 points
        dp[0][0] = 1

        # Fill the dp table
        for i in range(1, len(types)):
            for j in range(1, target + 1):
                if types[i - 1][0] <= j:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - types[i - 1][0]]) % MOD

        return dp[-1][-1]

class Solution:
