        return 0

class Solution:
    def wordPattern(self, pattern: str, s: str) -> bool:
        # Dictionary to store the mapping of each character to a word
        char_to_word = {}
        # Dictionary to store the word to its corresponding character
        word_to_char = {}

        # Split the string into words
        words = s.split()

        # Iterate through each character in the pattern
        for i, char in enumerate(pattern):
            # Check if the character is already mapped to a word
            if char in word_to_char:
                # If it is, check if the word matches the current character
                if word_to_char[char] != words[i]:
                    return False
            else:
                # If it's not, map the character to a new word
                word_to_char[char] = words[i]
                # Map the word to its corresponding character
                char_to_word[words[i]] = char

        # If all characters are mapped correctly, return True
        return True

class Solution:
    def countMatches(self, items: List[List[str]], ruleKey: str, ruleValue: str) -> int:
        # Create a mapping from ruleKey to the corresponding index in the item list
        key_index_map = {"type": 0, "color": 1, "name": 2}

        # Get the index corresponding to the ruleKey
        index = key_index_map[ruleKey]

        # Count the number of items that match the ruleValue at the determined index
        count = sum(1 for item in items if item[index] == ruleValue)

        return count

class Solution:
    def totalHammingDistance(self, nums: List[int]) -> int:
        # Initialize the result variable
        result = 0

        # Iterate over each pair of numbers in the list
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                # Calculate the Hamming distance between the current pair of numbers
                distance = bin(nums[i]^nums[j]).count('1')
                # Add the distance to the result
                result += distance

        return result

class Solution:
    def mostPoints(self, questions: List[List[int]]) -> int:
        n = len(questions)
        dp = [0] * n

        # Initialize the DP array
        for i in range(n):
            dp[i] = questions[i][0]

            # Try to solve the previous questions
            for j in range(i - questions[i][1]):
                dp[i] = max(dp[i], dp[j] + questions[i][0])

        return dp[n - 1]

