class Solution:
    def findAllPeople(self, n: int, meetings: List[List[int]], firstPerson: int) -> List[int]:
        graph = [[] for _ in range(n)]
        for x, y, t in meetings:
            graph[x].append((y, t))
            graph[y].append((x, t))

        q = deque([firstPerson])
        seen = set()
        while q:
            node = q.popleft()
            seen.add(node)
            for nei, time in graph[node]:
                if nei not in seen and time >= 0:
                    q.append(nei)
        return list(seen)

