class Solution:
    def maxNumOfSubstrings(self, s: str) -> List[str]:
        last = {c: i for i, c in enumerate(s)}
        intervals = []
        for i, c in enumerate(s):
            start = i
            end = last[c]
            while start < end:
                end = max(end, last[s[start]])
                start += 1
            intervals.append((start, end))

        intervals.sort(key=lambda x: (x[1], -x[0]))
        merged = []
        for interval in intervals:
            if not merged or interval[0] > merged[-1][1]:
                merged.append(interval)
            else:
                merged[-1] = (merged[-1][0], max(merged[-1][1], interval[1]))

        return [s[start:end+1] for start, end in merged]

class Solution:
    def matrixRankTransform(self, matrix: List[List[int]]) -> List[List[int]]:
        n, m = len(matrix), len(matrix[0])
        rank = [[0] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if matrix[i][j] == matrix[i][0]:
                    rank[i][j] = 1
                elif matrix[i][j] == matrix[0][j]:
                    rank[i][j] = 2
                else:
                    rank[i][j] = 3
        for i in range(n):
            for j in range(m):
                for k in range(n):
                    for l in range(m):
                        if matrix[k][l] > matrix[i][j] and matrix[k][l] != matrix[i][0]:
                            rank[i][j] = min(rank[i][j], rank[k][l] + 1)
        return matrix

class Solution:
    def removeDigit(self, number: str, digit: str) -> str:
        # Find the last occurrence of the digit
        last_index = number.rfind(digit)

        # If the digit is not the last character
        if last_index != len(number) - 1:
            # Return the substring before the last occurrence of the digit
            return number[:last_index] + number[last_index+1:]
        else:
            # Remove the last occurrence of the digit
            return number[:-1]

