class Solution:
    def minRefuelStops(self, target: int, startFuel: int, stations: List[List[int]]) -> int:
        if startFuel >= target:
            return 0

        # Initialize variables
        total_fuel = startFuel
        refuel_stops = 0

        for position, fuel in stations:
            # Check if the current position can be reached with the available fuel
            if total_fuel + fuel >= target:
                return refuel_stops + 1

            # Refuel if the current position is not reachable with the available fuel
            if total_fuel + fuel < target:
                total_fuel += fuel
                refuel_stops += 1

        # If no refueling stops are needed, return -1
        return -1

from collections import Counter

class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        count = Counter()
        count[''] = 1
        result = 0

        for i in range(len(s)):
            vowel_count = sum(1 for char in s[:i+1] if char.lower() in 'aeiou')
            consonant_count = i + 1 - vowel_count

            if (vowel_count * consonant_count) % k == 0:
                result += count[str(vowel_count)]

            count[str(vowel_count)] += 1

        return result

class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            else:
                b, a = stack.pop(), stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a // b)
        return stack[0]

