class Solution:
    def betterCompression(self, compressed: str) -> str:
        # Split the compressed string into pairs of character and frequency
        pairs = [compressed[i:i+2] for i in range(0, len(compressed), 2)]

        # Sort the pairs based on the character in alphabetical order
        pairs.sort(key=lambda x: x[0])

        # Count occurrences of each character
        char_count = {}
        for char, freq in pairs:
            if char in char_count:
                char_count[char] += int(freq)
            else:
                char_count[char] = int(freq)

        # Construct the better compression string
        result = ""
        for char, count in char_count.items():
            result += char + str(count)

        return result

