class Solution:
    def longestSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        dp = [0] * n
        dp[0] = 1 if s[0] == '0' else 0

        for i in range(1, n):
            if s[i] == '0':
                dp[i] = max(dp[i], dp[i - 1])
            else:
                dp[i] = max(dp[i], dp[i - 1] + 1)

        return dp[-1]

