class Solution:
    def stoneGameV(self, stoneValue: List[int]) -> int:
        n = len(stoneValue)
        dp = [[0] * (n - 1) for _ in range(n)]
        dp[0][0] = stoneValue[0]

        for i in range(1, n):
            for j in range(i):
                if j == 0:
                    dp[i][j] = max(dp[i - 1][j], dp[i - 1][j + 1] + stoneValue[i])
                elif j == i - 1:
                    dp[i][j] = max(dp[i - 1][j], stoneValue[i])
                else:
                    dp[i][j] = max(dp[i - 1][j], stoneValue[i] + dp[i - 1][j + 1])

        return dp[n - 1][0]

