class Solution:
    def cheapestJump(self, coins: List[int], maxJump: int) -> List[int]:
        n = len(coins)
        if coins[n-1] == -1:
            return []

        # Initialize cost and path arrays
        cost = [float('inf')] * n
        path = [-1] * n
        cost[0] = coins[0]

        for i in range(n):
            if coins[i] == -1:
                continue
            for j in range(1, maxJump + 1):
                if i + j < n and coins[i + j] != -1:
                    new_cost = cost[i] + coins[i + j]
                    if new_cost < cost[i + j]:
                        cost[i + j] = new_cost
                        path[i + j] = i

        # Reconstruct the path
        result = []
        current = n - 1
        while current >= 0:
            result.append(current + 1)
            if path[current] == -1:
                break
            current = path[current]

        if result[-1] != 1:
            return []

        return result[::-1]

