class Solution:
    def maximalNetworkRank(self, n: int, roads: List[List[int]]) -> int:
        # Create a dictionary to store the adjacency list for each city
        adj_list = {i: set() for i in range(n)}

        # Populate the adjacency list with the given roads
        for a, b in roads:
            adj_list[a].add(b)
            adj_list[b].add(a)

        max_rank = 0

        # Check all pairs of cities
        for i in range(n):
            for j in range(i + 1, n):
                # Calculate the network rank of cities i and j
                rank = len(adj_list[i]) + len(adj_list[j])
                # If cities i and j are directly connected, subtract 1
                if j in adj_list[i]:
                    rank -= 1
                # Update the maximum network rank found
                max_rank = max(max_rank, rank)

        return max_rank

class Solution:
    def stoneGameVIII(self, stones: List[int]) -> int:
        n = len(stones)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + stones[i]

        dp = [0] * n
        dp[-1] = prefix_sum[-1]

        for i in range(n - 2, -1, -1):
            dp[i] = max(dp[i + 1], prefix_sum[n] - prefix_sum[i + 1] - dp[i + 1])

        return dp[0]

