import heapq

class Solution:
    def leftmostBuildingQueries(self, heights: List[int], queries: List[List[int]]) -> List[int]:
        n = len(heights)
        max_heap = []
        result = [-1] * len(queries)
        query_map = [[] for _ in range(n)]

        # Map each building to the queries that involve it
        for qi, (ai, bi) in enumerate(queries):
            if ai > bi:
                ai, bi = bi, ai
            if ai == bi or heights[bi] > heights[ai]:
                result[qi] = bi
            else:
                query_map[bi].append((heights[ai], qi))

        # Process buildings from right to left
        for i in range(n - 1, -1, -1):
            # Push current building into the heap
            heapq.heappush(max_heap, (-heights[i], i))

            # Process all queries that involve the current building
            for h, qi in query_map[i]:
                while max_heap and -max_heap[0][0] <= h:
                    heapq.heappop(max_heap)
                if max_heap:
                    result[qi] = max_heap[0][1]

        return result

class Solution:
    def canChange(self, start: str, target: str) -> bool:
        # Initialize pointers for both strings
        i, j = 0, 0

        # Iterate through both strings
        while i < len(start) and j < len(target):
            # If the current characters at the pointers match, move both pointers forward
            if start[i] == target[j]:
                i += 1
                j += 1
            else:
                # If the current character at the pointer is '_', check if the next character in the target matches
                if target[j] == '_':
                    # Move the pointer forward if it matches
                    j += 1
                else:
                    # If the current character at the pointer is 'L', check if the previous character in the start matches
                    if start[i] == '_':
                        # Move the pointer forward if it matches
                        i += 1
                    else:
                        # If the current character at the pointer is 'R', check if the next character in the target matches
                        if target[j] == '_':
                            # Move the pointer forward if it matches
                            j += 1
                        else:
                            # If none of the above conditions are met, return False
                            return False

        # If all characters match, return True
        return True

