class Solution:
    def soupServings(self, n: int) -> float:
        if n < 4000:
            return self.dfs(n, n)
        else:
            return 0.5

    @lru_cache(None)
    def dfs(self, x, y):
        if x == 0 and y == 0:
            return 0.5
        elif x == 0:
            return 1.0
        elif y == 0:
            return 0.0

        return 0.25 * (self.dfs(x - 100, y) + self.dfs(x - 75, y - 25) + self.dfs(x - 50, y - 50) + self.dfs(x - 25, y - 75))

