        n = len(nums)
        if n == 1:
            return 0

        left = 0
        right = 1
        max_length = 0

        while right < n:
            if nums[left] > nums[right]:
                max_length = max(max_length, right - left + 1)
            else:
                left = right
            right += 1

        return max_length

