class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        n = len(nums)

        # Function to count the number of set bits in a number
        def count_set_bits(x):
            return bin(x).count('1')

        # Check if the array is already sorted
        if nums == sorted(nums):
            return True

        # Try to sort the array using the allowed operations
        for i in range(n):
            for j in range(i + 1, n):
                if nums[j] < nums[i] and count_set_bits(nums[j]) == count_set_bits(nums[i]):
                    # Swap nums[i] and nums[j]
                    nums[i], nums[j] = nums[j], nums[i]
                    # Check if the array is sorted after the swap
                    if nums == sorted(nums):
                        return True
                    # If not, swap back to restore the original array
                    nums[i], nums[j] = nums[j], nums[i]

        return False

class Solution:
    def goodDaysToRobBank(self, security: List[int], time: int) -> List[int]:
        n = len(security)
        if n < 2 * time + 1:
            return []

        # Initialize two arrays to store the number of increasing and decreasing days
        inc = [0] * n
        dec = [0] * n

        # Calculate the number of increasing days
        for i in range(1, n):
            if security[i] >= security[i - 1]:
                inc[i] = inc[i - 1] + 1

        # Calculate the number of decreasing days
        for i in range(n - 2, -1, -1):
            if security[i] <= security[i + 1]:
                dec[i] = dec[i + 1] + 1

        # Find the days that are good to rob the bank
        good_days = []
        for i in range(time, n - time):
            if inc[i] >= time and dec[i] >= time:
                good_days.append(i)

        return good_days

from collections import deque
class Solution:
    def minimumOperations(self, nums: List[int], start: int, goal: int) -> int:
        if start == goal:
            return 0

        queue = deque([start])
        visited = {start}
        level = 0

        while queue:
            size = len(queue)

            for _ in range(size):
                current = queue.popleft()

                if current == goal:
                    return level

                for num in nums:
                    next_value = current + num
                    if 0 <= next_value <= 1000 and next_value not in visited:
                        visited.add(next_value)
                        queue.append(next_value)

                    next_value = current - num
                    if 0 <= next_value <= 1000 and next_value not in visited:
                        visited.add(next_value)
                        queue.append(next_value)

                    next_value = current ^ num
                    if 0 <= next_value <= 1000 and next_value not in visited:
                        visited.add(next_value)
                        queue.append(next_value)

            level += 1

        return -1

class Solution:
    def countWays(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        count = 0

        # Check if the first student can be selected
        if nums[0] > 0:
            count += 1

        # Check if the last student can be selected
        if nums[-1] < n - 1:
            count += 1

        # Check for the middle students
        for i in range(1, n - 1):
            if nums[i] > i and nums[i] < n - i - 1:
                count += 2

        return count

class Solution:
    def findTilt(self, root: Optional[TreeNode]) -> int:
        self.tilt = 0
        def dfs(node):
            if not node:
                return 0
            left = dfs(node.left)
            right = dfs(node.right)
            self.tilt += abs(left - right)
            return left + right + node.val

        dfs(root)
        return self.tilt

