class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        prefix_sum = defaultdict(int)
        max_sum = float('-inf')
        current_sum = 0

        for num in nums:
            current_sum += num
            if abs(num) < k:
                max_sum = max(max_sum, current_sum)
            else:
                # Find the previous index where the difference was less than k
                prev_index = prefix_sum[num - k]
                if prev_index != -1:
                    max_sum = max(max_sum, current_sum - prefix_sum[prev_index])

            prefix_sum[num] = max(prefix_sum[num], current_sum)

        return max_sum if max_sum != float('-inf') else 0

