        result = [[0] * n for _ in range(n)]

        # Iterate through each query
        for i, j, k, l in queries:
            # Update the values in the specified submatrix
            for m in range(i, k + 1):
                for n in range(j, l + 1):
                    result[m][n] += 1

        return result

