class Solution:
    def wordsAbbreviation(self, words: List[str]) -> List[str]:
        self.dic = collections.defaultdict(list)
        for i, w in enumerate(words):
            self.dic[len(w)].append((w,i))

        ans = []
        for key, val in self.dic.items():
            val.sort()
            ans.append(self.helper(val))

        return ans


    def helper(self, val):
        if len(val) == 1:
            return val[0][0]

        res = [val[0][0]]
        cnt = 0

        for i in range(1,len(val)):
            if val[i][0] != val[i-1][0]+1:
                res.append(str(cnt+1)+val[i][0])
                cnt = 0
            else:
                cnt += 1

        if cnt > 0:
            res.append(str(cnt+1)+val[-1][0])

        return ''.join(res)

class Solution:
    def maxIceCream(self, costs: List[int], coins: int) -> int:
        # Count the frequency of each cost
        count = {}
        for cost in costs:
            if cost in count:
                count[cost] += 1
            else:
                count[cost] = 1

        # Sort the costs in descending order
        sorted_costs = sorted(count.items(), key=lambda x: x[1], reverse=True)

        # Initialize the number of ice cream bars bought
        num_bars = 0

        # Iterate through the sorted costs
        for cost, freq in sorted_costs:
            # Check if the boy has enough coins to buy the current cost
            if coins >= cost:
                # If yes, subtract the cost from the coins and add to the number of bars
                coins -= cost
                num_bars += freq
            else:
                break

        return num_bars

from heapq import heappush, heappop

class Solution:
    def trapRainWater(self, heightMap: List[List[int]]) -> int:
        if not heightMap or not heightMap[0]:
            return 0

        rows, cols = len(heightMap), len(heightMap[0])
        visited = set()
        max_heights = [[float('-inf')] * cols for _ in range(rows)]
        water_trapped = 0

        # Initialize the heap with boundary cells
        min_heap = []
        for i in range(rows):
            for j in range(cols):
                if i == 0 or j == 0 or i == rows - 1 or j == cols - 1:
                    heappush(min_heap, (heightMap[i][j], i, j))
                    visited.add((i, j))
                    max_heights[i][j] = heightMap[i][j]

        # Directions for moving up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while min_heap:
            current_height, x, y = heappop(min_heap)

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and (nx, ny) not in visited:
                    visited.add((nx, ny))

                    # Update the maximum height seen so far
                    max_heights[nx][ny] = max(max_heights[nx][ny], current_height)

                    # Calculate the trapped water if possible
                    if heightMap[nx][ny] < max_heights[nx][ny]:
                        water_trapped += max_heights[nx][ny] - heightMap[nx][ny]

                    # Add the new cell to the heap
                    heappush(min_heap, (max_heights[nx][ny], nx, ny))

        return water_trapped

from typing import List

class Solution:
    def minimumFinishTime(self, tires: List[List[int]], changeTime: int, numLaps: int) -> int:
        # Calculate the minimum time to complete a sequence of consecutive laps using the same tire
        min_time_per_sequence = [float('inf')] * (numLaps + 1)
        for f, r in tires:
            total_time = 0
            for i in range(1, numLaps + 1):
                total_time += f * (r ** (i - 1))
                if total_time > (i - 1) * changeTime + min(tires)[0]:
                    break
                min_time_per_sequence[i] = min(min_time_per_sequence[i], total_time)

        # Use dynamic programming to find the minimum time to complete numLaps
        dp = [float('inf')] * (numLaps + 1)
        dp[0] = 0
        for i in range(1, numLaps + 1):
            for j in range(1, i + 1):
                dp[i] = min(dp[i], dp[i - j] + min_time_per_sequence[j] + changeTime)

        return dp[numLaps] - changeTime

class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        if d == 1:
            return max(jobDifficulty)

        n = len(jobDifficulty)
        dp = [[float('inf')] * (n+1) for _ in range(d+1)]
        dp[1][jobDifficulty[0]] = jobDifficulty[0]

        for i in range(2, d+1):
            for j in range(n):
                for k in range(j, n):
                    dp[i][j] = min(dp[i][j], dp[i-1][k]+jobDifficulty[j])

        return dp[d][n-1] if dp[d][n-1] != float('inf') else -1

