class Solution:
    def verticalOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []

        # Initialize a dictionary to store nodes by their row and column indices
        row_dict = {}
        queue = [(root, 0)]

        # Perform a level-order traversal of the tree
        while queue:
            node, row = queue.pop(0)
            # If the node has not been added to the dictionary, add it with the current row index
            if row not in row_dict:
                row_dict[row] = []
            # Add the node's value to the corresponding row list in the dictionary
            row_dict[row].append(node.val)

            # Add the left child to the queue with the next row index
            if node.left:
                queue.append((node.left, row + 1))

            # Add the right child to the queue with the next row index
            if node.right:
                queue.append((node.right, row + 1))

        # Convert the dictionary values to a list of lists
        return list(row_dict.values())

class Solution:
    def minSteps(self, s: str, t: str) -> int:
        count_s = [0] * 26
        count_t = [0] * 26

        for char in s:
            count_s[ord(char) - ord('a')] += 1

        for char in t:
            count_t[ord(char) - ord('a')] += 1

        steps = 0
        for i in range(26):
            if count_s[i] > count_t[i]:
                steps += count_s[i] - count_t[i]

        return steps // 2

class Solution:
    def ambiguousCoordinates(self, s: str) -> List[str]:
        def valid(s):
            if len(s) > 1 and s[0] == '0':
                return False
            if '.' in s:
                left, right = s.split('.')
                if int(left) == 0 and len(right) > 1:
                    return False
                if len(right) > 1 and right[-1] == '0':
                    return False
                return True
            return True

        res = []
        n = len(s)
        for i in range(1, n-1):
            left = s[:i]
            right = s[i:]
            if valid(left) and valid(right):
                if len(left) == 1:
                    res.append(f"({left}, {right})")
                else:
                    for j in range(1, len(left)):
                        res.append(f"({left[:j]}, {left[j:]})")
        return res

class Solution:
    def closestPrimes(self, left: int, right: int) -> List[int]:
        def is_prime(n):
            if n <= 1:
                return False
            if n <= 3:
                return True
            if n % 2 == 0 or n % 3 == 0:
                return False
            i = 5
            while i * i <= n:
                if n % i == 0 or n % (i + 2) == 0:
                    return False
                i += 6
            return True

        min_gap = float('inf')
        closest_pair = [-1, -1]

        for num in range(left, right + 1):
            if is_prime(num):
                if closest_pair[0] != -1:
                    gap = num - closest_pair[1]
                    if gap < min_gap:
                        min_gap = gap
                        closest_pair = [closest_pair[1], num]
                else:
                    closest_pair = [num, num]

        return closest_pair

class Solution:
    def smallestString(self, s: str) -> str:
        res = ""
        for i in range(len(s)):
            if s[i] != "a":
                res += chr(ord(s[i]) - 1)
            else:
                res += s[i]
        return res

class Solution:
    def minimumReplacement(self, nums: List[int]) -> int:
        n = len(nums)
        for i in range(n):
            j = i + 1
            while j < n and nums[j] <= nums[i] + nums[j - 1]:
                j += 1
            if j == n:
                return n - i
            nums[i], nums[j] = nums[j], nums[i]
        return 0

class Solution:
    def restoreString(self, s: str, indices: List[int]) -> str:
        result = list(s)
        for i, index in enumerate(indices):
            result[index] = s[i]
        return ''.join(result)

class Solution:
    def findMin(self, nums: List[int]) -> int:
        left, right = 0, len(nums) - 1

        while left < right:
            mid = (left + right) // 2

            if nums[mid] > nums[right]:
                # If the middle element is greater than the rightmost element,
                # the minimum element is in the right half
                left = mid + 1
            else:
                # If the middle element is less than or equal to the rightmost element,
                # the minimum element is in the left half
                right = mid

        # The final value of left will be the minimum element
        return nums[left]

class Solution:
    def partitionDisjoint(self, nums: List[int]) -> int:
        n = len(nums)
        max_left = [nums[0]] * n
        min_right = [nums[-1]] * n

        for i in range(1, n):
            max_left[i] = max(max_left[i-1], nums[i])

        for i in range(n-2, -1, -1):
            min_right[i] = min(min_right[i+1], nums[i])

        for i in range(1, n):
            if max_left[i-1] <= min_right[i]:
                return i

from collections import Counter

class Solution:
    def reductionOperations(self, nums: List[int]) -> int:
        counter = Counter(nums)
        total_operations = 0
        prev_count = 0

        for num, count in sorted(counter.items(), reverse=True):
            total_operations += prev_count * count
            prev_count += count

        return total_operations

class Solution:
    def digitCount(self, num: str) -> bool:
        return all(num.count(str(i)) == int(i) for i in range(len(num)))

from typing import List

class Solution:
    def wordCount(self, startWords: List[str], targetWords: List[str]) -> int:
        start_sets = set()

        for word in startWords:
            start_sets.add(frozenset(word))

        count = 0

        for word in targetWords:
            target_set = set(word)
            for char in word:
                if frozenset(target_set - {char}) in start_sets:
                    count += 1
                    break

        return count

class Solution:
    def kidsWithCandies(self, candies: List[int], extraCandies: int) -> List[bool]:
        return [candy >= extraCandies for candy in candies]

class Solution:
    def maxHeightOfTriangle(self, red: int, blue: int) -> int:
        return max(red + blue - min(red, blue), 1)

from typing import List

class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        def check(mid: float) -> bool:
            min_sum = 0
            current_sum = 0
            for i in range(k):
                current_sum += nums[i] - mid
            if current_sum >= 0:
                return True

            for i in range(k, len(nums)):
                current_sum += nums[i] - mid
                min_sum += nums[i - k] - mid
                if min_sum < 0:
                    current_sum -= min_sum
                    min_sum = 0
                if current_sum >= 0:
                    return True
            return False

        left, right = min(nums), max(nums)
        while right - left > 1e-5:
            mid = (left + right) / 2
            if check(mid):
                left = mid
            else:
                right = mid
        return left

