import collections

class Solution:
    def findShortestCycle(self, n: int, edges: List[List[int]]) -> int:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def bfs(start):
            queue = collections.deque([(start, -1)])
            dist = [-1] * n
            dist[start] = 0
            while queue:
                node, parent = queue.popleft()
                for neighbor in graph[node]:
                    if dist[neighbor] == -1:
                        dist[neighbor] = dist[node] + 1
                        queue.append((neighbor, node))
                    elif neighbor != parent:
                        return dist[node] + dist[neighbor] + 1
            return float('inf')

        min_cycle = float('inf')
        for i in range(n):
            cycle_length = bfs(i)
            min_cycle = min(min_cycle, cycle_length)

        return min_cycle if min_cycle != float('inf') else -1

class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        if not image or not image[0]:
            return 0

        m, n = len(image), len(image[0])
        left, right, top, bottom = x, x, y, y

        # Find the first occurrence of the black pixel
        while left >= 0 and image[left][y] == '1':
            left -= 1

        # Find the last occurrence of the black pixel
        while right < m and image[right][y] == '1':
            right += 1

        # Find the first occurrence of the black pixel in the left direction
        while top >= 0 and image[x][top] == '1':
            top -= 1

        # Find the last occurrence of the black pixel in the right direction
        while bottom < n and image[x][bottom] == '1':
            bottom += 1

        # Calculate the area of the smallest rectangle
        return (right - left + 1) * (bottom - top + 1)

