class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        # Initialize the result counter
        count = 0

        # Ensure x is less than or equal to y
        while x > y:
            # If x is divisible by 11, divide it by 11
            if x % 11 == 0:
                x //= 11
            # If x is divisible by 5, divide it by 5
            elif x % 5 == 0:
                x //= 5
            # Otherwise, decrement x by 1
            else:
                x -= 1
            # Increment the result counter
            count += 1

        # Return the total number of operations
        return count + abs(x - y)

from typing import List
import heapq

class Solution:
    def findAnswer(self, n: int, edges: List[List[int]]) -> List[bool]:
        # Build the graph
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        # Dijkstra's algorithm to find the shortest path from 0 to all nodes
        distances = [float('inf')] * n
        distances[0] = 0
        pq = [(0, 0)]
        while pq:
            dist, u = heapq.heappop(pq)
            if dist > distances[u]:
                continue
            for v, weight in graph[u]:
                if dist + weight < distances[v]:
                    distances[v] = dist + weight
                    heapq.heappush(pq, (distances[v], v))

        # Check if each edge is part of at least one shortest path
        answer = [False] * len(edges)
        for i, (u, v, w) in enumerate(edges):
            if distances[u] + w == distances[v] or distances[v] + w == distances[u]:
                answer[i] = True

        return answer

class Solution:
    def maximumTop(self, nums: List[int], k: int) -> int:
        n = len(nums)

        if k == 0:
            return nums[0] if nums else -1

        if k == 1:
            return nums[1] if n > 1 else -1

        if k >= n:
            return max(nums[:-1])

        return max(nums[0], nums[k])

class Solution:
    def minSessions(self, tasks: List[int], sessionTime: int) -> int:
        from itertools import combinations

        def can_finish_with_k_sessions(k):
            # Try to distribute tasks into k sessions
            sessions = [0] * k
            for task in sorted(tasks, reverse=True):
                placed = False
                for i in range(k):
                    if sessions[i] + task <= sessionTime:
                        sessions[i] += task
                        placed = True
                        break
                if not placed:
                    return False
            return True

        left, right = 1, len(tasks)
        while left < right:
            mid = (left + right) // 2
            if can_finish_with_k_sessions(mid):
                right = mid
            else:
                left = mid + 1
        return left

from collections import defaultdict

class Solution:
    def placedCoins(self, edges: List[List[int]], cost: List[int]) -> List[int]:
        # Build an adjacency list representation of the tree
        adj_list = defaultdict(list)
        for u, v in edges:
            adj_list[u].append(v)
            adj_list[v].append(u)

        # Initialize the result array
        n = len(cost)
        coin = [0] * n

        # Helper function to calculate the maximum product of cost values assigned to 3 distinct nodes in the subtree of node i
        def max_product(node):
            if len(adj_list[node]) < 3:
                return 1
            max_product_value = float('-inf')
            for neighbor in adj_list[node]:
                product = max_product(neighbor)
                if product > max_product_value:
                    max_product_value = product
            return max_product_value

        # Fill the result array using the helper function
        for i in range(n):
            coin[i] = max_product(i)

        return coin

from typing import List

class Solution:
    def minEatingSpeed(self, piles: List[int], h: int) -> int:
        left, right = 1, max(piles)
        while left < right:
            mid = (left + right) // 2
            if sum((pile - 1) // mid + 1 for pile in piles) > h:
                left = mid + 1
            else:
                right = mid
        return left

class Solution:
    def minimumPartition(self, s: str, k: int) -> int:
        if k < 9:
            max_digit = max(s)
            if int(max_digit) > k:
                return -1
            return len(s)

        partitions = 0
        current_value = 0

        for char in s:
            digit = int(char)
            if current_value * 10 + digit > k:
                partitions += 1
                current_value = digit
            else:
                current_value = current_value * 10 + digit

        if current_value > 0:
            partitions += 1

        return partitions

