class Solution:
    def subsets(self, nums: List[int]) -> List[List[int]]:
        result = []
        for i in range(1 << len(nums)):
            subset = []
            for j in range(len(nums)):
                if (i >> j) & 1:
                    subset.append(nums[j])
            result.append(subset)
        return result

class Solution:
    def countLargestGroup(self, n: int) -> int:
        # Initialize variables to keep track of the largest group size and its count
        largest_group_size = 0
        count = 0

        # Iterate through each number from 1 to n
        for i in range(1, n + 1):
            # Calculate the sum of the digits of the current number
            digit_sum = sum(int(digit) for digit in str(i))

            # Check if the current digit sum is greater than the largest group size found so far
            if digit_sum > largest_group_size:
                largest_group_size = digit_sum
                count = 1  # Reset count for the new group
            elif digit_sum == largest_group_size:
                count += 1  # Increment count for the same group size

        return count

class Solution:
    def isValid(self, code: str) -> bool:
        # Initialize stack for opening tags
        stack = []
        # Initialize current tag name
        current_tag = ''
        # Initialize flag for cdata mode
        cdata_mode = False

        for char in code:
            # Handle cdata mode
            if char == '<' and not cdata_mode:
                # Check if there's a mismatched closing tag
                if stack and stack[-1] != '/':
                    return False
                # Parse cdata content
                if stack and stack[-1] == '/' and char == '>':
                    cdata_mode = False
                else:
                    cdata_mode = True
                continue

            # Check if we're inside a cdata section
            if cdata_mode:
                continue

            # Check if character is a letter
            if char.isalpha():
                # Append to current tag name
                current_tag += char
            elif char.isdigit() and int(char) <= 9:
                # Append digit to current tag name
                current_tag += char
            elif char == '>' and len(current_tag) > 0:
                # Close the tag if it's valid
                if stack and stack[-1] == current_tag[0]:
                    stack.pop()
                    current_tag = ''
                else:
                    return False
            else:
                # Invalid character found
                return False

        # Check if all tags were properly closed
        return not stack

