class Solution:
    def topKFrequent(self, words: List[str], k: int) -> List[str]:
        word_count = Counter(words)
        return [word for word, count in word_count.most_common(k)]

class Solution:
    def isOneEditDistance(self, s: str, t: str) -> bool:
        # Check if the lengths of the strings are different
        if len(s) != len(t):
            return False

        # Initialize counters for characters at each position
        diff_count = 0

        # Iterate through the strings
        for i in range(len(s)):
            # If characters at the current positions differ
            if s[i] != t[i]:
                # Increment the difference counter
                diff_count += 1

                # If there are more than two differences, return False
                if diff_count > 2:
                    return False

        # If no differences were found, return True
        return True

class Solution:
    def differByOne(self, dict: List[str]) -> bool:
        # Create a set to store characters at each position
        char_sets = [set() for _ in range(len(dict[0]))]

        # Populate the set with characters from each string
        for word in dict:
            for i, char in enumerate(word):
                char_sets[i].add(char)

        # Check for any two positions where the sets have more than one common element
        for i in range(len(dict[0])):
            for j in range(i + 1, len(dict[0])):
                if len(char_sets[i].intersection(char_sets[j])) > 1:
                    return True

        return False

class Solution:
    def primeSubOperation(self, nums: List[int]) -> bool:
        def is_prime(n):
            if n <= 1:
                return False
            if n <= 3:
                return True
            if n % 2 == 0 or n % 3 == 0:
                return False
            i = 5
            while i * i <= n:
                if n % i == 0 or n % (i + 2) == 0:
                    return False
                i += 6
            return True

        for i in range(1, len(nums)):
            if nums[i] <= nums[i - 1]:
                current_num = nums[i - 1]
                for p in range(current_num - 1, 0, -1):
                    if is_prime(p) and nums[i] > nums[i - 1] - p:
                        nums[i] -= p
                        break
                if nums[i] <= nums[i - 1]:
                    return False
        return True

class Solution:
    def countPrefixes(self, words: List[str], s: str) -> int:
        return sum(w.startswith(s) for w in words)

class Solution:
    def canBeValid(self, s: str, locked: str) -> bool:
        balance = 0
        open_brackets = 0

        for i, char in enumerate(s):
            if locked[i] == '0':
                continue

            if char == '(':
                balance += 1
                open_brackets += 1
            else:
                balance -= 1

                if balance < 0:
                    return False

            if balance > 0 and open_brackets == 0:
                return False

        return balance == 0

from collections import defaultdict, deque

class Solution:
    def networkBecomesIdle(self, edges: List[List[int]], patience: List[int]) -> int:
        n = len(patience)
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        dist = [-1] * n
        q = deque([0])
        dist[0] = 0

        while q:
            node = q.popleft()
            for neighbor in graph[node]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[node] + 1
                    q.append(neighbor)

        max_time = 0
        for i in range(1, n):
            round_trip_time = dist[i] * 2
            if round_trip_time % patience[i] == 0:
                max_time = max(max_time, round_trip_time + round_trip_time // patience[i] - 1)
            else:
                max_time = max(max_time, round_trip_time + round_trip_time // patience[i])

        return max_time + 1

from typing import List

class Solution:
    def longestCycle(self, edges: List[int]) -> int:
        n = len(edges)
        visited = [-1] * n
        max_cycle_length = -1

        for i in range(n):
            if visited[i] != -1:
                continue

            current_length = 0
            node = i
            while node != -1 and visited[node] == -1:
                visited[node] = current_length
                current_length += 1
                node = edges[node]

            if node != -1 and visited[node] >= 0:
                max_cycle_length = max(max_cycle_length, current_length - visited[node])

        return max_cycle_length

class Solution:
    def maxDistance(self, nums1: List[int], nums2: List[int]) -> int:
        res = 0
        left, right = 0, len(nums2)-1

        while left < len(nums1) and right >= 0:
            if nums1[left] > nums2[right]:
                left += 1
            else:
                res = max(res, right - left)
                right -= 1

        return res

class Solution:
    def isStrictlyPalindromic(self, n: int) -> bool:
        def is_palindrome(s):
            return s == s[::-1]

        for base in range(2, n):
            num_str = ""
            while n > 0:
                num_str = str(n % base) + num_str
                n //= base
            if not is_palindrome(num_str):
                return False
        return True

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def trimBST(self, root: Optional[TreeNode], low: int, high: int) -> Optional[TreeNode]:
        if not root: 
            return None

        # If current node's value is less than low, prune it
        if root.val < low: 
            return self.trimBST(root.right, low, high)

        # If current node's value is greater than high, prune it
        if root.val > high: 
            return self.trimBST(root.left, low, high)

        # Recursively trim the left and right subtrees
        root.left = self.trimBST(root.left, low, high)
        root.right = self.trimBST(root.right, low, high)

        return root

class Solution:
    def groupThePeople(self, groupSizes: List[int]) -> List[List[int]]:
        groups = {}
        result = []

        for i, size in enumerate(groupSizes):
            if size not in groups:
                groups[size] = []
            groups[size].append(i)

            if len(groups[size]) == size:
                result.append(groups[size])
                groups[size] = []

        return result

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def maxAncestorDiff(self, root: Optional[TreeNode]) -> int:
        def dfs(node, min_val, max_val):
            if not node:
                return max_val - min_val
            min_val = min(min_val, node.val)
            max_val = max(max_val, node.val)
            left_diff = dfs(node.left, min_val, max_val)
            right_diff = dfs(node.right, min_val, max_val)
            return max(left_diff, right_diff)

        return dfs(root, root.val, root.val)

from typing import List

class Solution:
    def countSubMultisets(self, nums: List[int], l: int, r: int) -> int:
        MOD = 10**9 + 7
        max_sum = sum(nums)
        if max_sum < l:
            return 0

        # Count occurrences of each number
        count = {}
        for num in nums:
            if num != 0:
                count[num] = count.get(num, 0) + 1

        # Initialize DP table
        dp = [0] * (max_sum + 1)
        dp[0] = 1

        # Process each unique number
        for num, freq in count.items():
            new_dp = dp[:]
            for j in range(num, max_sum + 1):
                for k in range(1, freq + 1):
                    if j - num * k >= 0:
                        new_dp[j] = (new_dp[j] + dp[j - num * k]) % MOD
                    else:
                        break
            dp = new_dp

        # Sum up the counts of valid sums
        result = sum(dp[l:r+1]) % MOD
        return result

class Solution:
    def triangleType(self, nums: List[int]) -> str:
        # Check if the sides can form an equilateral triangle
        if nums[0] == nums[1] == nums[2]:
            return "equilateral"
        # Check if the sides can form an isosceles triangle
        elif nums[0] == nums[1] or nums[1] == nums[2] or nums[0] == nums[2]:
            return "isosceles"
        # If none of the above conditions are met, it's a scalene triangle
        else:
            return "scalene"

from typing import List

class Solution:
    def findMinMoves(self, machines: List[int]) -> int:
        total_dresses = sum(machines)
        if total_dresses % len(machines):
            return -1

        avg_dresses = total_dresses // len(machines)
        min_moves = 0

        for i, dress in enumerate(machines):
            diff = dress - avg_dresses
            min_moves += max(diff, abs(diff))

        return min_moves

class Solution:
    def minimumPerimeter(self, neededApples: int) -> int:
        n = 0
        total_apples = 0
        while total_apples < neededApples:
            n += 1
            total_apples += 12 * n * (n + 1)
        return 8 * n

class Solution:
    def maxScore(self, nums: List[int], x: int) -> int:
        even_max = odd_max = float('-inf')
        if nums[0] % 2 == 0:
            even_max = nums[0]
        else:
            odd_max = nums[0]

        for num in nums[1:]:
            if num % 2 == 0:
                even_max = max(even_max + num, odd_max + num - x)
            else:
                odd_max = max(odd_max + num, even_max + num - x)

        return even_max if even_max != float('-inf') else odd_max

from typing import List

class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
        m, n = len(strs), len(strs[0])

        @lru_cache(None)
        def dp(prev):
            j = prev + 1
            while j < n and all(strs[i][j] >= strs[i][prev] for i in range(m)):
                j += 1
            if j == n:
                return 0

            keep = 1 + dp(j)
            skip = dp(prev + 1)

            return min(keep, skip)

        return dp(-1)

class Solution:
    def isPossibleDivide(self, nums: List[int], k: int) -> bool:
        nums.sort()
        for i in range(len(nums)):
            if nums[i] != nums[i-1]+1:
                return False
        return len(set(nums)) == k

class Solution:
    def minInteger(self, num: str, k: int) -> str:
        from collections import deque

        # Create a list of deques for each digit '0' to '9'
        digit_indices = [deque() for _ in range(10)]
        for i, d in enumerate(num):
            digit_indices[int(d)].append(i)

        result = []
        used = [False] * len(num)

        while k > 0 and any(digit_indices):
            for d in range(10):
                if digit_indices[d]:
                    idx = digit_indices[d][0]
                    # Check if we can move this digit to the front with the remaining k swaps
                    if idx <= k:
                        result.append(str(d))
                        used[idx] = True
                        digit_indices[d].popleft()
                        k -= idx
                        break
            else:
                # If no digit can be moved, decrement k and try again
                k -= 1

        # Append the remaining digits in their original order
        for i in range(len(num)):
            if not used[i]:
                result.append(num[i])

        return ''.join(result)

class Solution:
    def minimumArrayLength(self, nums: List[int]) -> int:
        # Find the GCD of all numbers in the list
        gcd_value = functools.reduce(math.gcd, nums)

        # Count the occurrences of the GCD in the list
        count = nums.count(gcd_value)

        # The minimum length of the array is 1 if the GCD appears more than once,
        # otherwise it's 1 if the GCD appears exactly once, and 0 if the GCD doesn't appear at all.
        return min(1, count // 2 + count % 2)

class Solution:
    def getHint(self, secret: str, guess: str) -> str:
        bulls = 0
        cows = 0

        # Count bulls
        for i in range(len(secret)):
            if secret[i] == guess[i]:
                bulls += 1

        # Count cows
        for i in range(len(secret)):
            if secret[i] != guess[i] and secret.count(secret[i]) == 1:
                cows += 1

        return f"{bulls}A{cows}B"

class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        count = {}
        for num in nums:
            if num in count:
                count[num] += 1
            else:
                count[num] = 1

        for key, value in count.items():
            if value > len(nums) // 2:
                return key

class Solution:
    def amountPainted(self, paint: List[List[int]]) -> List[int]:
        max_end = max(day[1] for day in paint)
        painted = [0] * (max_end + 1)
        worklog = []

        for start, end in paint:
            new_area = 0
            for i in range(start, end):
                if painted[i] == 0:
                    painted[i] = 1
                    new_area += 1
            worklog.append(new_area)

        return worklog

class Solution:
    def canCross(self, stones: List[int]) -> bool:
        # Create a set to store visited positions
        visited = set()
        # Initialize the first stone as visited
        visited.add(0)
        # Iterate through the stones
        for i in range(1, len(stones)):
            # Check if the current stone is already visited
            if stones[i] in visited:
                continue
            # Check all possible jumps from the current stone
            for j in range(i - 1, -1, -1):
                if stones[j] + 1 == stones[i]:
                    visited.add(stones[i])
                elif stones[j] + 2 == stones[i]:
                    visited.add(stones[i])
                elif stones[j] + 3 == stones[i]:
                    visited.add(stones[i])
        # Return True if all stones are visited, otherwise False
        return len(visited) == len(stones)

