import itertools

class Solution:
    def maximumRows(self, matrix: List[List[int]], numSelect: int) -> int:
        m, n = len(matrix), len(matrix[0])
        max_covered_rows = 0

        # Generate all combinations of columns to select
        for cols in itertools.combinations(range(n), numSelect):
            covered_rows = 0
            # Check how many rows are covered by the selected columns
            for row in range(m):
                if all(matrix[row][col] == 0 for col in cols):
                    covered_rows += 1
            max_covered_rows = max(max_covered_rows, covered_rows)

        return max_covered_rows

from collections import deque

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        m, n = len(grid), len(grid[0])
        dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        # Function to check if a cell is valid
        def isValid(x, y):
            return 0 <= x < m and 0 <= y < n

        # Function to find the shortest path from (x, y) to food
        def findPath(x, y):
            visited = [[False for _ in range(n)] for _ in range(m)]
            queue = deque([(x, y)])
            visited[x][y] = True

            while queue:
                cx, cy = queue.popleft()

                if grid[cx][cy] == 'F':
                    return True

                for dx, dy in dirs:
                    nx, ny = cx + dx, cy + dy

                    if not isValid(nx, ny) or grid[nx][ny] == '#' or visited[nx][ny]:
                        continue

                    visited[nx][ny] = True
                    queue.append((nx, ny))

            return False

        # Find the positions of Cat, Mouse, and Food
        cat_pos, mouse_pos, food_pos = None, None, None
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 'C':
                    cat_pos = (i, j)
                elif grid[i][j] == 'M':
                    mouse_pos = (i, j)
                elif grid[i][j] == 'F':
                    food_pos = (i, j)

        # Check if Cat can reach food before Mouse
        if findPath(cat_pos[0], cat_pos[1]):
            return False

        # Check if Mouse can reach food within 1000 turns
        for _ in range(1000):
            # Move Cat
            cat_next_pos = None
            for dx, dy in dirs:
                nx, ny = cat_pos[0] + dx * catJump, cat_pos[1] + dy * catJump
                if isValid(nx, ny) and grid[nx][ny] != '#':
                    cat_next_pos = (nx, ny)
                    break

            if cat_next_pos is None:
                return False

            # Move Mouse
            mouse_next_pos = None
            for dx, dy in dirs:
                nx, ny = mouse_pos[0] + dx * mouseJump, mouse_pos[1] + dy * mouseJump
                if isValid(nx, ny) and grid[nx][ny] != '#':
                    mouse_next_pos = (nx, ny)
                    break

            if mouse_next_pos is None:
                return False

            # Check if Mouse can capture Cat
            if mouse_next_pos == cat_pos:
                return False

            # Check if Mouse can reach food
            if findPath(mouse_next_pos[0], mouse_next_pos[1]):
                return True

            # Update positions
            cat_pos = cat_next_pos
            mouse_pos = mouse_next_pos

        return False

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def isUnivalTree(self, root: Optional[TreeNode]) -> bool:
        if not root:
            return True

        stack = [root]
        target_value = root.val

        while stack:
            node = stack.pop()
            if node.val != target_value:
                return False
            if node.left:
                stack.append(node.left)
            if node.right:
                stack.append(node.right)

        return True

class Solution:
    def gameResult(self, head: Optional[ListNode]) -> str:
        odd_count = 0
        even_count = 0

        current = head
        while current:
            if current.val % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

            current = current.next

        if odd_count > even_count:
            return "Odd"
        elif even_count > odd_count:
            return "Even"
        else:
            return "Tie"

class Solution:
    def findLength(self, nums1: List[int], nums2: List[int]) -> int:
        # Initialize a counter for the length of the longest common subarray
        length = 0

        # Use nested loops to iterate through each element of nums1 and nums2
        for i in range(len(nums1)):
            for j in range(len(nums2)):
                # If the elements at the current positions match, increment the length counter
                if nums1[i] == nums2[j]:
                    length += 1

        # Return the length of the longest common subarray
        return length

