from typing import List

class Solution:
    def isNStraightHand(self, hand: List[int], groupSize: int) -> bool:
        # If the total number of cards is not divisible by groupSize, return False
        if len(hand) % groupSize != 0:
            return False

        # Count the frequency of each card
        count = Counter(hand)

        # Sort the unique card values
        sorted_cards = sorted(count.keys())

        # Try to form groups
        for card in sorted_cards:
            if count[card] > 0:
                # Decrease the count of the current card
                count[card] -= 1
                # Check for consecutive cards in the group
                for i in range(1, groupSize):
                    if count[card + i] == 0:
                        return False
                    count[card + i] -= 1

        return True

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        def max_digit(n):
            return max(int(digit) for digit in str(n))

        max_digit_to_sum = {}

        for num in nums:
            digit = max_digit(num)
            if digit not in max_digit_to_sum:
                max_digit_to_sum[digit] = []
            max_digit_to_sum[digit].append(num)

        max_sum = -1

        for digit in max_digit_to_sum:
            if len(max_digit_to_sum[digit]) >= 2:
                max_sum = max(max_sum, sum(max_digit_to_sum[digit]))

        return max_sum

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        # If there's only one number, it's trivially traversable
        if len(nums) == 1:
            return True

        # If the smallest number is 1, it's impossible to traverse to any other number
        if min(nums) == 1:
            return False

        # Initialize the prime factorization map
        prime_factors = defaultdict(set)

        # Compute prime factors for each number
        for num in nums:
            i = 2
            while i * i <= num:
                if num % i == 0:
                    prime_factors[i].add(num)
                    while num % i == 0:
                        num //= i
                i += 1
            if num > 1:
                prime_factors[num].add(num)

        # Find the maximum prime factor value
        max_prime_factor = max(prime_factors.keys())

        # Create a graph based on prime factors
        graph = defaultdict(list)
        for num in nums:
            for prime in prime_factors[num]:
                graph[prime].append(num)

        # Check if the graph is connected
        visited = set()
        stack = [nums[0]]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        stack.append(neighbor)

        # If all numbers are connected, return True
        return len(visited) == len(nums)

class Solution:
    def maximumBooks(self, books: List[int]) -> int:
