class Solution:
    def relativeSortArray(self, arr1: List[int], arr2: List[int]) -> List[int]:
        # Create a dictionary to count occurrences of each element in arr2
        count = {}
        for num in arr2:
            if num in count:
                count[num] += 1
            else:
                count[num] = 1

        # Create a list to store elements from arr1
        result = []

        # Iterate through arr1 and append elements from arr2 in their original order
        for num in arr1:
            if num in count:
                result.append(num)
            else:
                result.append(arr2[count[num]])

        return result

