class Solution:
    def kEmptySlots(self, bulbs: List[int], k: int) -> int:
        n = len(bulbs)
        days = [0] * (n + 1)

        for i in range(n):
            day = i + 1
            days[bulbs[i]] = day

            left = bulbs[i] - k - 1
            right = bulbs[i] + k + 1

            while left > 0 and days[left] < day:
                left -= 1

            while right <= n and days[right] < day:
                right += 1

            if left > 0 and days[left] == day:
                return day

            if right <= n and days[right] == day:
                return day

        return -1

