# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def longestConsecutive(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0

        self.max_length = 0

        def dfs(node):
            if not node:
                return 0, 0

            inc = dec = 1

            if node.left:
                left_inc, left_dec = dfs(node.left)
                if node.val == node.left.val + 1:
                    dec += left_dec
                elif node.val == node.left.val - 1:
                    inc += left_inc

            if node.right:
                right_inc, right_dec = dfs(node.right)
                if node.val == node.right.val + 1:
                    dec = max(dec, 1 + right_dec)
                elif node.val == node.right.val - 1:
                    inc = max(inc, 1 + right_inc)

            self.max_length = max(self.max_length, inc + dec - 1)
            return inc, dec

        dfs(root)
        return self.max_length

class Solution:
    def maxIncreasingGroups(self, usageLimits: List[int]) -> int:
        usageLimits.sort(reverse=True)
        total_used = 0
        groups = 0

        for limit in usageLimits:
            if total_used + limit > groups:
                groups += 1
                total_used = groups
            else:
                total_used += limit

        return groups

class Solution:
