        count = 0

        for i in range(m):
            for j in range(n):
                if picture[i][j] == 'B':
                    # Check if the current position is the first occurrence of 'B'
                    if i == 0 or picture[i-1][j] != 'B':
                        # Check if the current position is the last occurrence of 'B'
                        if j == n-1 or picture[i][j+1] != 'B':
                            count += 1

        return count

class Solution:
    def minDeletion(self, nums: List[int]) -> int:
        n = len(nums)
        deletions = 0

        for i in range(0, n, 2):
            if i + 1 < n and nums[i] == nums[i + 1]:
                deletions += 1

        # If the length of the resulting array is odd, we need to delete one more element
        if (n - deletions) % 2 != 0:
            deletions += 1

        return deletions

class Solution:
    def canReorderDoubled(self, arr: List[int]) -> bool:
        # Sort the array in ascending order
        arr.sort()

        # Check if the length of the array is odd
        if len(arr) % 2 != 0:
            return False

        # Create a dictionary to count occurrences of each number
        num_count = {}

        # Count occurrences of each number in the array
        for num in arr:
            num_count[num] = num_count.get(num, 0) + 1

        # Create a list to store the doubled numbers
        doubled_numbers = []

        # Collect all doubled numbers from the array
        for num in arr:
            if num % 2 == 0:
                doubled_numbers.append(num)

        # Check if there are enough doubled numbers to form a pair for every other number
        for num in doubled_numbers:
            if num not in num_count or num_count[num] == 0:
                return False

            # If the number of times the doubled number is present is greater than half of the number
            if num_count[num] > num // 2:
                return False

            # Decrease the count of the doubled number
            num_count[num] -= 1

        return True

class Solution:
