from collections import defaultdict

class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        graph = defaultdict(list)
        indegree = {recipe: 0 for recipe in recipes}

        # Build the graph and calculate the indegree of each recipe
        for recipe, ingredients_list in zip(recipes, ingredients):
            for ingredient in ingredients_list:
                graph[ingredient].append(recipe)
                indegree[recipe] += 1

        # Topological sort to find all recipes that can be made
        queue = deque([supply for supply in supplies if supply in indegree])
        result = []

        while queue:
            current_recipe = queue.popleft()
            result.append(current_recipe)

            for neighbor in graph[current_recipe]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    queue.append(neighbor)

        return result

class Solution:
    def getSmallestString(self, s: str) -> str:
        s = list(s)
        n = len(s)

        for i in range(n):
            # Check if the current digit is even
            if int(s[i]) % 2 == 0:
                # Look for the smallest even digit to the right
                for j in range(i + 1, n):
                    if int(s[j]) % 2 == 0 and s[j] < s[i]:
                        # Swap the digits
                        s[i], s[j] = s[j], s[i]
                        break
            else:
                # Look for the smallest odd digit to the right
                for j in range(i + 1, n):
                    if int(s[j]) % 2 != 0 and s[j] < s[i]:
                        # Swap the digits
                        s[i], s[j] = s[j], s[i]
                        break

        return ''.join(s)

from collections import defaultdict

class Solution:
    def rootCount(self, edges: List[List[int]], guesses: List[List[int]], k: int) -> int:
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def dfs(node, parent):
            count = 0
            if (node, parent) in guesses:
                count += 1

            for child in graph[node]:
                if child != parent:
                    count += dfs(child, node)

            return count

        total_nodes = len(graph)
        result = 0

        for i in range(total_nodes):
            count = dfs(i, -1)
            if count >= k:
                result += 1

        return result

class Solution:
    def hardestWorker(self, n: int, logs: List[List[int]]) -> int:
        max_time = 0
        hardest_id = -1
        for id, time in logs:
            if time > max_time:
                max_time = time
                hardest_id = id
        return hardest_id

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        n = len(s)
        dp = [False] * (n + 1)
        dp[0] = True

        for i in range(1, n + 1):
            for word in wordDict:
                if i >= len(word):
                    dp[i] |= dp[i - len(word)]

        return dp[-1]

