class Solution:
    def minimumPushes(self, word: str) -> int:
        freq = Counter(word)
        sorted_freq = sorted(freq.items(), key=lambda x: x[1], reverse=True)
        result = 0

        for i, (letter, count) in enumerate(sorted_freq):
            if i < 8:
                result += count * 1
            elif i < 16:
                result += count * 2
            elif i < 24:
                result += count * 3
