class Solution:
    def checkPalindromeFormation(self, a: str, b: str) -> bool:
        # Check if a is a palindrome
        if a != a[::-1]:
            return False

        # Check if b is a palindrome
        if b != b[::-1]:
            return False

        # Concatenate a and b
        concatenated = a + b

        # Check if the concatenated string is a palindrome
        return concatenated == concatenated[::-1]

