class Solution:
    def possiblyEquals(self, s1: str, s2: str) -> bool:
        # Split s1 into a list of substrings
        substrings1 = s1.split()

        # Split s2 into a list of substrings
        substrings2 = s2.split()

        # Check if the lengths of the substrings are equal
        if len(substrings1) != len(substrings2):
            return False

        # Check if the substrings are equal after replacing each with its length
        for i in range(len(substrings1)):
            if substrings1[i] != str(len(substrings1[i])):
                return False

        # Concatenate the substrings
        return ''.join(substrings1) == ''.join(substrings2)

