import heapq

class Solution:
    def topKFrequent(self, words: List[str], k: int) -> List[str]:
        # Count the frequency of each word
        count = {}
        for word in words:
            count[word] = count.get(word, 0) + 1

        # Use a heap to keep track of the top k elements
        # The heap will store tuples of (-frequency, word)
        # We use negative frequency because heapq is a min-heap by default
        heap = []
        for word, freq in count.items():
            heapq.heappush(heap, (-freq, word))
            if len(heap) > k:
                heapq.heappop(heap)

        # Extract the words from the heap and sort them
        result = []
        while heap:
            result.append(heapq.heappop(heap)[1])
        result.sort()

        # Since we popped from the heap, the result is in reverse order
        return result[::-1]

