from collections import defaultdict

class Solution:
    def verticalOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []

        # Use a dictionary to store nodes grouped by their x-coordinate
        col_map = defaultdict(list)
        queue = [(root, 0)]  # Queue to perform BFS

        while queue:
            node, col = queue.pop(0)

            # Add the node's value to the list at the corresponding column
            col_map[col].append(node.val)

            # Enqueue the left child with decremented column index
            if node.left:
                queue.append((node.left, col - 1))

            # Enqueue the right child with incremented column index
            if node.right:
                queue.append((node.right, col + 1))

        # Convert the dictionary into a list of lists based on sorted columns
        return [col_map[col] for col in sorted(col_map)]

