class Solution:
    def maximumSubtreeSize(self, edges: List[List[int]], colors: List[int]) -> int:
        from collections import defaultdict

        # Build the adjacency list for the tree
        tree = defaultdict(list)
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        def dfs(node, parent):
            max_size = 1
            same_color_size = 1
            all_same_color = True

            for neighbor in tree[node]:
                if neighbor == parent:
                    continue

                child_size, child_same_color_size, child_all_same_color = dfs(neighbor, node)

                if not child_all_same_color or colors[neighbor] != colors[node]:
                    all_same_color = False

                max_size = max(max_size, child_size)

                if all_same_color and colors[neighbor] == colors[node]:
                    same_color_size += child_same_color_size

            if all_same_color:
                max_size = same_color_size

            return max_size, same_color_size, all_same_color

        return dfs(0, -1)[0]

class Solution:
    def findKDistantIndices(self, nums: List[int], key: int, k: int) -> List[int]:
        res = []
        for i in range(len(nums)):
            if nums[i] == key:
                res.extend(range(max(0,i-k), min(i+k+1,len(nums))))
        return sorted(res)

