from functools import lru_cache

class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        @lru_cache(None)
        def dfs(mask):
            if mask == (1 << len(nums)) - 1:
                return 1

            count = 0
            for i in range(len(nums)):
                if mask & (1 << i) == 0:
                    continue
                    for j in range(i + 1, len(nums)):
                        if mask & (1 << j) == 0:
                            continue
                            if nums[j] % nums[i] == 0 or nums[i] % nums[j] == 0:
                                new_mask = mask | (1 << i) | (1 << j)
                                count += dfs(new_mask)

            return count

        return dfs(0) % (10**9 + 7)

from typing import List

class Solution:
    def countHighestScoreNodes(self, parents: List[int]) -> int:
        n = len(parents)
        children = [[] for _ in range(n)]

        # Build the tree
        for i in range(1, n):
            children[parents[i]].append(i)

        # Calculate the size of each subtree
        size = [1] * n

        def dfs(node):
            for child in children[node]:
                size[node] += dfs(child)
            return size[node]

        dfs(0)

        max_score = 0
        count = 0

        for i in range(n):
            score = 1
            # Multiply the sizes of the subtrees formed by removing this node
            for child in children[i]:
                score *= size[child]
            # Multiply by the size of the remaining part of the tree
            if i != 0:
                score *= (n - size[i])

            if score > max_score:
                max_score = score
                count = 1
            elif score == max_score:
                count += 1

        return count

from typing import List

class Solution:
    def numberOfPairs(self, points: List[List[int]]) -> int:
        count = 0
        n = len(points)

        for i in range(n):
            for j in range(i + 1, n):
                xi, yi = points[i]
                xj, yj = points[j]

                if xi < xj and yi > yj:
                    # Check if there are any points in the rectangle formed by (xi, yi) and (xj, yj)
                    valid = True
                    for k in range(n):
                        if k != i and k != j:
                            xk, yk = points[k]
                            if xi <= xk <= xj and yi >= yk >= yj:
                                valid = False
                                break
                    if valid:
                        count += 1

        return count

