import heapq

class Solution:
    def maxProbability(self, n: int, edges: List[List[int]], succProb: List[float], start_node: int, end_node: int) -> float:
        # Create an adjacency list for the graph
        graph = [[] for _ in range(n)]
        for i, (a, b) in enumerate(edges):
            graph[a].append((b, succProb[i]))
            graph[b].append((a, succProb[i]))

        # Max-heap to store the current max probability to reach each node
        max_heap = [(-1.0, start_node)]  # We use negative probabilities because heapq is a min-heap by default
        visited = [False] * n

        while max_heap:
            prob, node = heapq.heappop(max_heap)
            prob = -prob  # Convert back to positive

            if visited[node]:
                continue

            if node == end_node:
                return prob

            visited[node] = True

            for neighbor, edge_prob in graph[node]:
                if not visited[neighbor]:
                    new_prob = prob * edge_prob
                    heapq.heappush(max_heap, (-new_prob, neighbor))

        return 0.0

class Solution:
    def minChanges(self, n: int, k: int) -> int:
        if n == k:
            return 0

        # Convert numbers to binary strings
        bin_n = bin(n)[2:]
        bin_k = bin(k)[2:]

        # Pad the shorter binary string with leading zeros
        max_len = max(len(bin_n), len(bin_k))
        bin_n = bin_n.zfill(max_len)
        bin_k = bin_k.zfill(max_len)

        changes = 0
        for i in range(max_len):
            if bin_n[i] == '1' and bin_k[i] == '0':
                changes += 1

        # Check if it's possible to make n equal to k
        if changes > 0 and bin_n.count('1') < changes:
            return -1

        return changes

class Solution:
    def hasValidPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

        def is_valid(x, y):
            return 0 <= x < m and 0 <= y < n

        def dfs(i, j):
            if i == m - 1 and j == n - 1:
                return True
            for dx, dy in directions:
                nx, ny = i + dx, j + dy
                if is_valid(nx, ny) and grid[nx][ny] == 1:
                    if dfs(nx, ny):
                        return True
            return False

        return dfs(0, 0)

class Solution:
    def averageOfSubtree(self, root: TreeNode) -> int:
        res = 0

        def dfs(node):
            if not node:
                return 0, 0

            left_sum, left_count = dfs(node.left)
            right_sum, right_count = dfs(node.right)

            total_sum = node.val + left_sum + right_sum
            total_count = 1 + left_count + right_count

            if total_sum // total_count == node.val:
                nonlocal res
                res += 1

            return total_sum, total_count

        dfs(root)
        return res

import re

class Solution:
    def isValid(self, code: str) -> bool:
        # Check if the code starts and ends with a valid tag
        if not re.match(r'^<([A-Z]{1,9})>[^<]*</\\\\1>$', code):
            return False

        stack = []
        i = 0
        while i < len(code):
            if code[i] == '<':
                if i + 1 < len(code):
                    if code[i+1] == '/':
                        # End tag
                        j = code.find('>', i)
                        if j == -1:
                            return False
                        tag_name = code[i+2:j]
                        if not stack or stack[-1] != tag_name:
                            return False
                        stack.pop()
                        i = j + 1
                    elif code[i+1] == '!':
                        # CDATA section
                        if not stack:
                            return False
                        if code[i:i+9] != '<![CDATA[':
                            return False
                        j = code.find(']]>', i)
                        if j == -1:
                            return False
                        i = j + 1
                    else:
                        # Start tag
                        j = code.find('>', i)
                        if j == -1:
                            return False
                        tag_name = code[i+1:j]
                        if not (1 <= len(tag_name) <= 9 and tag_name.isupper()):
                            return False
                        stack.append(tag_name)
                        i = j + 1
                else:
                    return False
            else:
                i += 1

        return not stack

class Solution:
    def bestRotation(self, nums: List[int]) -> int:
        n = len(nums)
        ans = n
        for i in range(n):
            # Calculate the new index after rotating by i positions
            new_index = (i + n - 1) % n
            # Check if the current element is greater than its index
            if nums[new_index] <= i:
                ans = min(ans, new_index)
        return ans

class Solution:
    def reformat(self, s: str) -> str:
        # Count occurrences of each character
        char_count = {}
        for char in s:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

        # Initialize result string
        result = []

        # Check if there are enough characters to form a valid permutation
        if len(s) % 2 != 0:
            return ""

        # Separate characters based on their counts
        odd_count = 0
        for count in char_count.values():
            if count % 2 == 1:
                odd_count += 1
                if odd_count > 1:
                    return ""

        # Fill the result string with characters
        for char in s:
            if char.isalpha():
                result.append(char)
            elif char.isdigit():
                if odd_count == 1:
                    result.append(char)
                else:
                    return ""

        return "".join(result)

from collections import Counter

class Solution:
    def sortFeatures(self, features: List[str], responses: List[str]) -> List[str]:
        # Count the occurrences of each feature in responses
        feature_counts = Counter()
        for response in responses:
            for feature in response.split():
                feature_counts[feature] += 1

        # Sort features based on popularity and original index
        return sorted(features, key=lambda x: (-feature_counts[x], features.index(x)))

class Solution:
    def videoStitching(self, clips: List[List[int]], time: int) -> int:
        # Sort clips by their starting time
        clips.sort()
        n = len(clips)
        if clips[0][0] != 0:
            return -1

        # Initialize variables
        end = clips[0][1]
        max_end = end
        count = 1

        i = 1
        while i < n:
            if clips[i][0] > end:
                return -1

            while i < n and clips[i][0] <= end:
                max_end = max(max_end, clips[i][1])
                i += 1

            if end == max_end:
                return -1

            end = max_end
            count += 1

            if end >= time:
                break

        return count if end >= time else -1

from typing import List

class Solution:
    def hasValidPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        directions = {
            1: [(0, -1), (0, 1)],
            2: [(-1, 0), (1, 0)],
            3: [(0, -1), (1, 0)],
            4: [(0, 1), (1, 0)],
            5: [(0, -1), (-1, 0)],
            6: [(0, 1), (-1, 0)]
        }
        reverse_directions = {
            (0, -1): {1, 3, 5},
            (0, 1): {1, 4, 6},
            (-1, 0): {2, 3, 4},
            (1, 0): {2, 5, 6}
        }

        visited = set()
        stack = [(0, 0)]

        while stack:
            x, y = stack.pop()
            if (x, y) == (m - 1, n - 1):
                return True
            if (x, y) in visited:
                continue
            visited.add((x, y))

            for dx, dy in directions[grid[x][y]]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] in reverse_directions[(dx, dy)]:
                    stack.append((nx, ny))

        return False

class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        increasing = decreasing = 0

        for i in range(1, len(nums)):
            if nums[i] > nums[i - 1]:
                increasing += 1
            elif nums[i] < nums[i - 1]:
                decreasing += 1

        return max(increasing, decreasing)

import re

class Solution:
    def myAtoi(self, s: str) -> int:
        # Remove leading whitespaces
        s = s.lstrip()

        # Check for empty string after stripping
        if not s:
            return 0

        # Determine the sign based on the first character
        sign = 1
        if s[0] == '-':
            sign = -1
            s = s[1:]
        elif s[0] == '+':
            s = s[1:]

        # Extract the numeric part using regular expression
        match = re.search(r'^\\\\d+', s)
        if not match:
            return 0

        # Convert the extracted numeric part to an integer
        num_str = match.group(0)
        try:
            num = int(num_str)
        except ValueError:
            # Handle cases where the number exceeds the 32-bit limit
            if sign == 1:
                return 2**31 - 1
            else:
                return -2**31

        # Apply the determined sign
        return num * sign

class Solution:
    def evenProduct(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        left = 0
        right = 0

        while right < n:
            if nums[right] % 2 == 0:
                ans += right - left + 1
            while left < right and nums[left] % 2 != 0:
                left += 1
            right += 1

        return ans

