class Solution:
    def removeInterval(self, intervals: List[List[int]], toBeRemoved: List[int]) -> List[List[int]]:
        res = []
        for i in range(len(intervals)):
            start, end = intervals[i]
            # If the current interval overlaps with toBeRemoved, split it into two parts
            if start < toBeRemoved[1] and end > toBeRemoved[0]:
                if start == toBeRemoved[0]: res.append([start, toBeRemoved[1]])
                else: res.append([start, toBeRemoved[0]])
                if end == toBeRemoved[1]: res.append([toBeRemoved[1], end])
                else: res.append([toBeRemoved[1], end])
            elif start >= toBeRemoved[1] or end <= toBeRemoved[0]: 
                res.append([start, end])
        return res

class Solution:
    def nextGreaterElement(self, nums1: List[int], nums2: List[int]) -> List[int]:
        stack = []
        ans = [-1] * len(nums1)

        for i in range(len(nums2)):
            while stack and nums2[stack[-1]] < nums2[i]:
                ans[stack.pop()] = nums2[i]

            stack.append(i)

        return ans

class Solution:
    def minSubarray(self, nums: List[int], p: int) -> int:
        total_sum = sum(nums)
        target = total_sum % p

        if target == 0:
            return 0

        prefix_sums = {0: -1}
        current_sum = 0
        min_length = float('inf')

        for i, num in enumerate(nums):
            current_sum = (current_sum + num) % p
            required_sum = (current_sum - target + p) % p

            if required_sum in prefix_sums:
                min_length = min(min_length, i - prefix_sums[required_sum])

            prefix_sums[current_sum] = i

        return min_length if min_length != float('inf') else -1

class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        n = len(nums)
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    if nums[i] < nums[j] and nums[k] < nums[j]:
                        return min(nums[i] + nums[j] + nums[k], nums[i] + nums[k] + nums[j])
        return -1

from bisect import bisect_left

class Solution:
    def longestObstacleCourseAtEachPosition(self, obstacles: List[int]) -> List[int]:
        result = []
        dp = []  # Store the minimum ending value of subsequence up to i

        for obstacle in obstacles:
            index = bisect_left(dp, obstacle)
            if index == len(dp):
                dp.append(obstacle)
            else:
                dp[index] = obstacle

            result.append(index + 1)

        return result

class Solution:
    def customSortString(self, order: str, s: str) -> str:
        # Create a dictionary to map characters in order to their positions
        char_map = {char: index for index, char in enumerate(order)}

        # Sort the string based on the positions in the order dictionary
        sorted_string = ''.join(sorted(s, key=lambda x: char_map[x]))

        return sorted_string

class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        mod = 10**9 + 7
        result = 0

        # Iterate through each bit position from n-1 to 0
        for i in range(n):
            # Check if the ith bit of a is different from the ith bit of b
            if (a >> i) & 1 != (b >> i) & 1:
                # Set the ith bit of result to 1
                result |= (1 << i)

        # Calculate the final result using the formula (result ^ a) * (result ^ b)
        return ((result ^ a) * (result ^ b)) % mod

class Solution:
    def tree2str(self, root: Optional[TreeNode]) -> str:
        if not root:
            return ""

        left_str = f"({self.tree2str(root.left)})" if root.left else ""
        right_str = f"({self.tree2str(root.right)})" if root.right else ""

        # Ensure the right parenthesis comes after the left parenthesis if it exists
        if left_str and right_str:
            return f"{root.val}{left_str}{right_str}"
        elif left_str:
            return f"{root.val}{left_str}"
        else:
            return f"{root.val}{right_str}"

