import math

class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        # Check if the starting point is inside the rectangle
        if not (0 <= circles[0][0] - circles[0][2] <= xCorner <= circles[0][0] + circles[0][2] and 0 <= circles[0][1] - circles[0][2] <= yCorner <= circles[0][1] + circles[0][2]):
            return False

        # Check if the ending point is inside the rectangle
        if not (0 <= circles[-1][0] - circles[-1][2] <= xCorner <= circles[-1][0] + circles[-1][2] and 0 <= circles[-1][1] - circles[-1][2] <= yCorner <= circles[-1][1] + circles[-1][2]):
            return False

        # Check if there is a path from the bottom left corner to the top right corner
        for i in range(len(circles)):
            if self.is_path_blocked(xCorner, yCorner, circles[i]):
                return False

        return True

    def is_path_blocked(self, xEnd, yEnd, circle):
        # Calculate the distance between the end point and the center of the circle
        dist = math.sqrt((xEnd - circle[0])**2 + (yEnd - circle[1])**2)

        # If the distance is less than or equal to the radius of the circle, then the path is blocked
        return dist <= circle[2]

