class Solution:
    def minimumSum(self, n: int, k: int) -> int:
        return k * (k + 1) // 2 - (k - 1) * ((k - 1) + 1) // 2 + n - (k - 1)

class Solution:
    def isPowerOfFour(self, n: int) -> bool:
        # A number is a power of four if it has exactly one bit set to 1
        # and that bit must be at an even position (i.e., 0-indexed)
        return n > 0 and n & (n - 1) == 0 and n.bit_length() % 2 == 0

class Solution:
    def maximumEvenSplit(self, finalSum: int) -> List[int]:
        if finalSum % 2 != 0:
            return []

        result = []
        current_sum = 0
        i = 2

        while current_sum < finalSum:
            next_even = i + 2
            if current_sum + next_even > finalSum:
                result.append(finalSum - current_sum)
                break
            result.append(i)
            current_sum += i
            i += 2

        return result

class Solution:
    def largestPerimeter(self, nums: List[int]) -> int:
        nums.sort()
        for i in range(len(nums)-2):
            if nums[i] + nums[i+1] > nums[i+2]:
                return nums[i] + nums[i+1] + nums[i+2]
        return -1

from collections import deque

class Solution:
    def minimumLevel(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0

        queue = deque([(root, 1)])
        min_sum_level = float('inf')
        min_sum = float('inf')

        while queue:
            node, level = queue.popleft()

            if level < min_sum_level or (level == min_sum_level and node.val < min_sum):
                min_sum_level = level
                min_sum = node.val

            if node.left:
                queue.append((node.left, level + 1))
            if node.right:
                queue.append((node.right, level + 1))

        return min_sum_level

class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        if k == 0 or not prices:
            return 0

        n = len(prices)
        if k >= n // 2:
            # If k is large enough, it's equivalent to unlimited transactions
            return sum(max(prices[i] - prices[i-1], 0) for i in range(1, n))

        dp = [[0] * 2 for _ in range(k + 1)]
        for i in range(1, k + 1):
            max_diff = float('-inf')
            for j in range(1, n):
                max_diff = max(max_diff, dp[i - 1][0] - prices[j - 1])
                dp[i][1] = max(dp[i][1], max_diff + prices[j - 1])
            dp[i][0] = max(dp[i][0], dp[i][1])

        return dp[k][0]

class Solution:
    def countSubIslands(self, grid1: List[List[int]], grid2: List[List[int]]) -> int:
        def dfs(i, j):
            if i < 0 or i >= len(grid2) or j < 0 or j >= len(grid2[0]) or grid2[i][j] == 0:
                return True
            if grid1[i][j] == 0:
                return False

            grid2[i][j] = 0
            return dfs(i-1, j) and dfs(i+1, j) and dfs(i, j-1) and dfs(i, j+1)

        count = 0
        for i in range(len(grid2)):
            for j in range(len(grid2[0])):
                if grid2[i][j] == 1 and dfs(i, j):
                    count += 1

        return count

class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        max_length = 0
        current_length = 0

        for i in range(1, len(nums)):
            if (i == 1 and nums[i] != nums[i-1] + 1) or (nums[i] - nums[i-1] == (i+1) % 2):
                current_length += 1
                max_length = max(max_length, current_length)
            else:
                current_length = 1

        return max_length if max_length > 0 else -1

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
