class Solution:
    def findLatestTime(self, s: str) -> str:
        s = list(s)
        if s[0] == '?':
            s[0] = '1' if s[1] in {'?', '0', '1'} else '0'
        if s[1] == '?':
            s[1] = '9' if s[0] == '0' else '1'
        if s[3] == '?':
            s[3] = '5'
        if s[4] == '?':
            s[4] = '9'
        return ''.join(s)

class Solution:
    def smallestSubsequence(self, s: str, k: int, letter: str, repetition: int) -> str:
        stack = []
        count = s.count(letter)
        for i, char in enumerate(s):
            while stack and stack[-1] > char and count >= repetition + len(stack) - 1 - i:
                if stack[-1] == letter:
                    repetition -= 1
                stack.pop()
            stack.append(char)
            if char == letter:
                count -= 1
        return ''.join(stack[:k])

class Solution:
    def amountPainted(self, paint: List[List[int]]) -> List[int]:
        intervals = []
        result = []

        for start, end in paint:
            overlap = 0
            for i, (s, e) in enumerate(intervals):
                if s <= start <= e or s <= end <= e or start <= s <= end:
                    overlap += min(e, end) - max(s, start)
                    intervals[i] = (max(s, start), min(e, end))
            if overlap == 0:
                intervals.append((start, end))
            result.append(end - start - overlap)

        return result

from typing import List

class Solution:
    def handleQuery(self, nums1: List[int], nums2: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums1)
        flip_count = [0] * (n + 1)
        total_sum = sum(nums2)
        ones_count = sum(nums1)
        result = []

        for query in queries:
            if query[0] == 1:
                l, r = query[1], query[2]
                flip_count[l] += 1
                if r + 1 < n:
                    flip_count[r + 1] -= 1

            elif query[0] == 2:
                p = query[1]
                total_sum += ones_count * p

            elif query[0] == 3:
                result.append(total_sum)

        current_flips = 0
        current_ones = 0
        for i in range(n):
            current_flips += flip_count[i]
            if current_flips % 2 == 1:
                current_ones += 1 - nums1[i]
            else:
                current_ones += nums1[i]
            nums1[i] = 1 if current_flips % 2 == 1 else nums1[i]

        return result

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def isSubtree(self, root: Optional[TreeNode], subRoot: Optional[TreeNode]) -> bool:
        # Check if subRoot is empty, then it's a subtree of root
        if not subRoot:
            return True

        # If root is empty but subRoot is not, then subRoot is not a subtree of root
        if not root:
            return False

        # Check if the current nodes match, if they do, check the subtrees recursively
        if root.val == subRoot.val:
            return self.isSubtree(root.left, subRoot.left) and self.isSubtree(root.right, subRoot.right)

        # Recursively check if the left subtree is a subtree of the current root
        return self.isSubtree(root.left, subRoot)

        # Recursively check if the right subtree is a subtree of the current root
        return self.isSubtree(root.right, subRoot)

class Solution:
    def minimumArea(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        min_area = float('inf')
        for i in range(rows):
            for j in range(cols):
                # Check if the current cell is 1
                if grid[i][j] == 1:
                    # Try to find the smallest rectangle
                    left, right, top, bottom = i, i, j, j
                    while left > 0 and grid[left - 1][j] == 0:
                        left -= 1
                    while right < rows - 1 and grid[right + 1][j] == 0:
                        right += 1
                    while top > 0 and grid[i][top - 1] == 0:
                        top -= 1
                    while bottom < cols - 1 and grid[i][bottom + 1] == 0:
                        bottom += 1
                    # Calculate the area of the rectangle
                    area = (right - left + 1) * (bottom - top + 1)
                    # Update the minimum area if the current rectangle has smaller area
                    if area < min_area:
                        min_area = area
        return min_area

from typing import *
class Solution:
    def vowelStrings(self, words: List[str], queries: List[List[int]]) -> List[int]:
        vowels = set('aeiou')
        prefix_count = [0] * len(words)
        for i in range(len(words)):
            if words[i][0] in vowels and words[i][-1] in vowels:
                prefix_count[i] += 1
            if i > 0:
                prefix_count[i] += prefix_count[i-1]
        result = []
        for l, r in queries:
            count = prefix_count[r] - (prefix_count[l-1] if l > 0 else 0)
            result.append(count)
        return result

class Solution:
    def maxProduct(self, root: Optional[TreeNode]) -> int:
        self.total_sum = 0
        self.max_product = 0

        def dfs(node):
            if not node:
                return 0

            left_sum = dfs(node.left)
            right_sum = dfs(node.right)

            self.total_sum += node.val
            self.max_product = max(self.max_product, left_sum * (self.total_sum - left_sum), right_sum * (self.total_sum - right_sum))

            return node.val + left_sum + right_sum

        dfs(root)
        return self.max_product % (10**9 + 7)

from typing import List

class Solution:
    def findMissingAndRepeatedValues(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        total_numbers = set(range(1, n*n + 1))
        seen = set()
        repeated = None

        for row in grid:
            for num in row:
                if num in seen:
                    repeated = num
                else:
                    seen.add(num)

        missing = total_numbers - seen
        return [repeated, list(missing)[0]]

