class Solution:
    def equalSubstring(self, s: str, t: str, maxCost: int) -> int:
        res = 0
        i, j = 0, 0
        cost = 0

        while i < len(s) and j < len(t):
            if abs(ord(s[i]) - ord(t[j])) > maxCost:
                cost -= abs(ord(s[i]) - ord(t[j]))
                i += 1
            else:
                res = max(res, j - i + 1)
                j += 1

        return res

class Solution:
    def maxSideLength(self, mat: List[List[int]], threshold: int) -> int:
        m, n = len(mat), len(mat[0])
        for i in range(m):
            for j in range(n):
                if mat[i][j] > threshold:
                    break
                if i + 1 < m and j + 1 < n and abs(mat[i+1][j] - mat[i][j+1]) + abs(mat[i][j+1] - mat[i+1][j+1]) <= threshold:
                    return 2
        return 0

class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
        # Initialize variables
        ans = 0
        stack = initialBoxes.copy()
        visited = set(initialBoxes)

        while stack:
            box = stack.pop(0)
            if status[box]:
                ans += candies[box]
                for key in keys[box]:
                    status[key] = 1
                for contained in containedBoxes[box]:
                    if contained not in visited:
                        stack.append(contained)
                        visited.add(contained)

        return ans

class Solution:
    def validPalindrome(self, s: str) -> bool:
        # Remove characters from the string if they appear more than once
        while any(s[i] == s[-i-1] for i in range(len(s)//2)):
            s = s[:-1]
        # Check if the resulting string is a palindrome
        return s == s[::-1]

class Solution:
    def numberOfWeakCharacters(self, properties: List[List[int]]) -> int:
        # Sort the properties based on the sum of attack and defense
        sorted_properties = sorted(properties, key=lambda x: x[0] + x[1])

        # Initialize a counter for weak characters
        weak_count = 0

        # Iterate through the sorted properties
        for prop in sorted_properties:
            # Check if the current character is weak
            if prop[1] < prop[0]:
                weak_count += 1

        return weak_count

class Solution:
    def minimumScore(self, s: str, t: str) -> int:
        m, n = len(s), len(t)
        dp = [[0] * (n+1) for _ in range(m+1)]

        # Initialize the DP table
        for i in range(1, m+1):
            for j in range(1, n+1):
                if s[i-1] == t[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])

        return m - dp[m][n]

class Solution:
    def maxAbsValExpr(self, arr1: List[int], arr2: List[int]) -> int:
        n = len(arr1)
        result = 0

        # Helper function to calculate the maximum absolute value expression
        def max_expr(a, b):
            return max(
                a[n-1] + b[n-1],
                a[0] + b[0],
                a[n-1] - b[0],
                a[0] - b[n-1]
            )

        # Calculate the maximum value for each component separately
        max1 = max_expr([arr1[i] + i for i in range(n)], [arr2[i] + i for i in range(n)])
        max2 = max_expr([arr1[i] + i for i in range(n)], [arr2[i] - i for i in range(n)])
        max3 = max_expr([arr1[i] - i for i in range(n)], [arr2[i] + i for i in range(n)])
        max4 = max_expr([arr1[i] - i for i in range(n)], [arr2[i] - i for i in range(n)])

        # Return the maximum of all components
        return max(max1, max2, max3, max4)

class Solution:
