from collections import defaultdict

class Solution:
    def largestPathValue(self, colors: str, edges: List[List[int]]) -> int:
        n = len(colors)
        adj_list = defaultdict(list)
        in_degree = [0] * n

        # Build adjacency list and in-degree count
        for u, v in edges:
            adj_list[u].append(v)
            in_degree[v] += 1

        # Topological sort using Kahn's algorithm
        queue = deque([i for i in range(n) if in_degree[i] == 0])
        visited = set()
        max_colors = [[0] * 26 for _ in range(n)]

        while queue:
            node = queue.popleft()
            visited.add(node)

            for neighbor in adj_list[node]:
                max_colors[neighbor][ord(colors[neighbor]) - ord('a')] += 1

                for j in range(26):
                    max_colors[neighbor][j] = max(max_colors[neighbor][j], max_colors[node][j])

                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        if len(visited) != n:
            return -1

        return max(max_colors[i][-1] for i in range(n))

class Solution:
    def minSwaps(self, grid: List[List[int]]) -> int:
        n = len(grid)
        # Count the number of trailing zeros for each row
        count_zeros = [sum(row[i:] == [0] * (n - i) for i in range(n)) for row in grid]
        swaps = 0

        # Try to place each row in its correct position
        for i in range(n):
            target_zeros = n - i - 1
            j = i
            while j < n and count_zeros[j] < target_zeros:
                j += 1
            if j == n:
                return -1
            # Swap the current row with the first row with enough trailing zeros
            for k in range(j, i, -1):
                grid[k], grid[k-1] = grid[k-1], grid[k]
                swaps += 1

        return swaps

# Definition for a binary tree node.
