#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def twoSumBSTs(self, root1: Optional[TreeNode], root2: Optional[TreeNode], target: int) -> bool:
        def inorder_traversal(node, vals):
            if node:
                inorder_traversal(node.left, vals)
                vals.append(node.val)
                inorder_traversal(node.right, vals)

        def find_target_in_bst(node, target):
            if not node:
                return False
            if node.val == target:
                return True
            elif node.val < target:
                return find_target_in_bst(node.right, target)
            else:
                return find_target_in_bst(node.left, target)

        # Get all values from the first BST
        vals1 = []
        inorder_traversal(root1, vals1)

        # For each value in the first BST, check if the complement exists in the second BST
        for val in vals1:
            complement = target - val
            if find_target_in_bst(root2, complement):
                return True

        return False

class Solution:
    def shiftingLetters(self, s: str, shifts: List[List[int]]) -> str:
        for i in range(len(shifts)):
            # Calculate the new index after shifting the string
            new_index = (ord(s[i]) - ord('a') + shifts[i][2]) % 26 + ord('a')
            # Update the string with the new index
            s = s[:i] + chr(new_index) + s[i+1:]
        return s

