class Solution:
    def minimumDeletions(self, word: str, k: int) -> int:
        char_count = Counter(word)
        min_deletions = float("inf")

        for count in char_count.values():
            max_freq = count + k
            deletions = sum(max_freq > c for c in char_count.values())
            min_deletions = min(min_deletions, deletions)

        return min_deletions

class Solution:
    def myPow(self, x: float, n: int) -> float:
        if n == 0:
            return 1
        if n < 0:
            x = 1 / x
            n = -n
        result = 1
        while n:
            if n % 2:
                result *= x
            x *= x
            n //= 2
        return result

from collections import deque

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        rows, cols = len(grid), len(grid[0])
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        # Initialize a queue for BFS with distance and remaining obstacles
        queue = deque([(0, 0, k)])
        visited = set((0, 0, k))

        while queue:
            x, y, obs_left = queue.popleft()

            if x == rows - 1 and y == cols - 1:
                return obs_left

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 <= nx < rows and 0 <= ny < cols:
                    new_obs_left = obs_left

                    if grid[nx][ny]:
                        new_obs_left -= 1

                    if new_obs_left >= 0 and (nx, ny, new_obs_left) not in visited:
                        visited.add((nx, ny, new_obs_left))
                        queue.append((nx, ny, new_obs_left))

        return -1

