class Solution:
    def stoneGameIX(self, stones: List[int]) -> bool:
        count = [0] * 3
        for stone in stones:
            count[stone % 3] += 1

        # If there are no stones with value % 3 == 0, Alice wins
        if count[0] == 0:
            return count[1] > 0 and count[2] > 0

        # If the difference between count[1] and count[2] is less than 3, Bob wins
        return abs(count[1] - count[2]) > 2

class Solution:
    def captureForts(self, forts: List[int]) -> int:
        ans = 0
        left = None
        right = None

        for i in range(len(forts)):
            if forts[i] != 0:
                if left is not None:
                    ans = max(ans, abs(i-left-1))
                left = i
            elif forts[i] == -1 and left is not None:
                right = i
                left = None

        return ans

