        n = len(matrix)

        # Check rows
        for i in range(n):
            if sorted(set(matrix[i])) != list(range(1, n + 1)):
                return False

        # Check columns
        for j in range(n):
            if sorted([matrix[i][j] for i in range(n)]) != list(range(1, n + 1)):
                return False

        return True

