class Solution:
    def minCostSetTime(self, startAt: int, moveCost: int, pushCost: int, targetSeconds: int) -> int:
        def calculate_cost(digits, start):
            cost = 0
            current_digit = str(start)
            for digit in digits:
                if digit != current_digit:
                    cost += moveCost
                    current_digit = digit
                cost += pushCost
            return cost

        minutes, seconds = divmod(targetSeconds, 60)
        options = []

        if minutes < 100:
            options.append(f"{minutes:02}{seconds:02}")

        if seconds < 40 and minutes > 0:
            options.append(f"{minutes - 1:02}{seconds + 60:02}")

        min_cost = float('inf')
        for option in options:
            cost = calculate_cost(option, startAt)
            min_cost = min(min_cost, cost)

        return min_cost

class Solution:
    def minimumCoins(self, prices: List[int]) -> int:
        n = len(prices)
        dp = [float('inf')] * (n+1)
        dp[0] = 0

        for i in range(1, n+1):
            for j in range(i):
                if j == 0 or i - j > j:
                    dp[i] = min(dp[i], dp[j] + prices[i-j-1])

        return dp[n]

