class Solution:
    def longestConsecutive(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0

        max_length = 1
        stack = [(root, 1)]

        while stack:
            node, current_length = stack.pop()

            # Check left child
            if node.left:
                if node.left.val == node.val + 1:
                    stack.append((node.left, current_length + 1))
                    max_length = max(max_length, current_length + 1)
                else:
                    stack.append((node.left, 1))

            # Check right child
            if node.right:
                if node.right.val == node.val + 1:
                    stack.append((node.right, current_length + 1))
                    max_length = max(max_length, current_length + 1)
                else:
                    stack.append((node.right, 1))

        return max_length

