class Solution:
    def oddString(self, words: List[str]) -> str:
        def get_difference_array(word):
            return [ord(word[j+1]) - ord(word[j]) for j in range(len(word) - 1)]

        diff_arrays = [get_difference_array(word) for word in words]

        # Find the odd one out
        for i in range(1, len(diff_arrays) - 1):
            if diff_arrays[i] != diff_arrays[i - 1] and diff_arrays[i] != diff_arrays[i + 1]:
                return words[i]

        # If the first or last is the odd one out
        if diff_arrays[0] != diff_arrays[1]:
            return words[0]
        return words[-1]

from typing import List

class Solution:
    def kthSmallestSubarraySum(self, nums: List[int], k: int) -> int:
        def countSubarraysWithSumLessThanOrEqualTo(target):
            count = 0
            start = 0
            current_sum = 0
            for end in range(len(nums)):
                current_sum += nums[end]
                while current_sum > target:
                    current_sum -= nums[start]
                    start += 1
                count += end - start + 1
            return count

        left, right = min(nums), sum(nums)
        while left < right:
            mid = (left + right) // 2
            if countSubarraysWithSumLessThanOrEqualTo(mid) >= k:
                right = mid
            else:
                left = mid + 1
        return left

