class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        # Initialize two variables to keep track of the longest subsequence ending with even and odd sums
        even_end = odd_end = 0

        for num in nums:
            if num % 2 == 0:
                # If the current number is even, it can extend the subsequence ending with odd sums
                even_end, odd_end = odd_end + 1, max(odd_end, 1)
            else:
                # If the current number is odd, it can extend the subsequence ending with even sums
                odd_end, even_end = even_end + 1, max(even_end, 1)

        # Return the maximum length of the valid subsequence found
        return max(even_end, odd_end)

class Solution:
    def validIPAddress(self, queryIP: str) -> str:
        # Check for IPv4
        if queryIP.count('.') == 3:
            parts = queryIP.split('.')
            for part in parts:
                if not part.isdigit() or int(part) < 0 or int(part) > 255 or (part[0] == '0' and len(part) != 1):
                    return "Neither"
            return "IPv4"
        # Check for IPv6
        elif queryIP.count(':') == 7:
            parts = queryIP.split(':')
            for part in parts:
                if not part.isalnum() or len(part) > 4:
                    return "Neither"
            return "IPv6"
        else:
            return "Neither"

class Solution:
    def maximumScore(self, nums: List[int], k: int) -> int:
        n = len(nums)
        left = right = k
        max_score = nums[k]
        current_min = nums[k]

        while left > 0 or right < n - 1:
            if (left > 0 and nums[left - 1] >= nums[right + 1]):
                left -= 1
            else:
                right += 1

            current_min = min(current_min, nums[left], nums[right])
            max_score = max(max_score, current_min * (right - left + 1))

        return max_score

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])
        queue = deque([(mat, 0)])
        visited = set()
        while queue:
            current_matrix, steps = queue.popleft()
            for i in range(m):
                for j in range(n):
                    if current_matrix[i][j]:
                        new_matrix = [row[:] for row in current_matrix]
                        new_matrix[i][j] = 0
                        for dx, dy in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
                            nx, ny = i + dx, j + dy
                            if 0 <= nx < m and 0 <= ny < n:
                                new_matrix[nx][ny] = 1
                        if tuple(map(tuple, new_matrix)) not in visited:
                            visited.add(tuple(map(tuple, new_matrix)))
                            if all(sum(row) == 0 for row in new_matrix):
                                return steps + 1
                            queue.append((new_matrix, steps + 1))
        return -1

