class Solution:
    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        def simulate(players, round):
            winners = []
            i, j = 0, len(players) - 1
            while i < j:
                if players[i] == firstPlayer or players[j] == secondPlayer:
                    winners.append(firstPlayer)
                elif players[i] == secondPlayer or players[j] == firstPlayer:
                    winners.append(secondPlayer)
                else:
                    winners.append(max(players[i], players[j]))
                i += 1
                j -= 1
            if i == j:
                winners.append(players[i])
            winners.sort()
            return winners

        def dfs(players, round):
            nonlocal earliest, latest
            if len(players) == 1:
                return
            if firstPlayer in players and secondPlayer in players:
                earliest = min(earliest, round)
                latest = max(latest, round)
                return
            winners = simulate(players, round)
            dfs(winners, round + 1)

        earliest, latest = float('inf'), float('-inf')
        players = list(range(1, n + 1))
        dfs(players, 1)
        return [earliest, latest]

