def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        n = len(s)
        total_substrings = n * (n + 1) // 2
        non_dominant_count = 0

        zero_count = 0
        one_count = 0

        for char in s:
            if char == '0':
                zero_count += 1
            else:
                one_count += 1

            if one_count < zero_count * zero_count:
                non_dominant_count += 1

        return total_substrings - non_dominant_count

class Solution:
    def getMinimumDifference(self, root: Optional[TreeNode]) -> int:
        self.prev = None
        self.min_diff = float('inf')

        def inorder(node):
            if not node:
                return

            inorder(node.left)

            if self.prev is not None:
                self.min_diff = min(self.min_diff, node.val - self.prev.val)

            self.prev = node

            inorder(node.right)

        inorder(root)
        return self.min_diff

