class Solution:
    def maxSpending(self, values: List[List[int]]) -> int:
        pq = []
        for row in values:
            for val in row:
                heapq.heappush(pq, val)

        ans = 0
        while pq:
            ans += heapq.heappop(pq) * (len(values) * len(values[0]) - len(pq))

        return ans

