        for i, num in enumerate(nums):
            for j in range(3):
                dp[i + 1][(j + num) % 3] = max(dp[i][j], dp[i][j] + num)

        return dp[-1][0]

from heapq import heappush, heappop

class Solution:
    def kthSmallest(self, mat: List[List[int]], k: int) -> int:
        if not mat or not mat[0]:
            return 0

        m, n = len(mat), len(mat[0])
        heap = [(sum(row[0] for row in mat), tuple(0 for _ in range(m)))]
        visited = set()

        while heap:
            total, indices = heappop(heap)
            if k == 1:
                return total

            for i in range(m):
                new_indices = list(indices)
                new_indices[i] += 1
                if new_indices[i] < n:
                    new_total = total - mat[i][indices[i]] + mat[i][new_indices[i]]
                    new_state = tuple(new_indices)
                    if new_state not in visited:
                        visited.add(new_state)
                        heappush(heap, (new_total, new_state))

            k -= 1

