class Solution:
    def findAndReplacePattern(self, words: List[str], pattern: str) -> List[str]:
        def match(word):
            if len(word) != len(pattern):
                return False

            char_to_pattern = {}
            pattern_to_char = {}

            for w, p in zip(word, pattern):
                if w in char_to_pattern and char_to_pattern[w] != p:
                    return False
                if p in pattern_to_char and pattern_to_char[p] != w:
                    return False

                char_to_pattern[w] = p
                pattern_to_char[p] = w

            return True

        return [word for word in words if match(word)]

