        left, right = 0, max(candies)
        result = 0

        while left <= right:
            mid = (left + right) // 2
            if sum(x // mid for x in candies) >= k:
                result = mid
                left = mid + 1
            else:
                right = mid - 1

        return result

class Solution:
    def encode(self, s: str) -> str:
        n = len(s)
        dp = [[None] * n for _ in range(n)]

        for length in range(1, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                dp[i][j] = s[i:j+1]

                # Try to find a repeating substring
                for k in range(i, j):
                    if dp[i][k] == dp[k+1][j]:
                        new_s = str(k-i+1) + '[' + dp[i][k] + ']'
                        if len(new_s) < len(dp[i][j]):
                            dp[i][j] = new_s

                # Check if the current substring can be further compressed
                for r in range(1, length // 2 + 1):
                    if length % r == 0 and s[i:i+r] * (length // r) == s[i:j+1]:
                        new_s = str(length // r) + '[' + s[i:i+r] + ']'
                        if len(new_s) < len(dp[i][j]):
                            dp[i][j] = new_s

        return dp[0][n-1]

