from collections import defaultdict

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        graph = defaultdict(list)
        for i, j, k in zip(original, changed, cost):
            graph[i].append((j, k))

        @lru_cache(None)
        def dfs(start, end):
            if start > len(source) - 1 or end > len(target) - 1:
                return float('inf')

            if source[start] == target[end]:
                return dfs(start + 1, end + 1)

            min_cost = float('inf')
            for neighbor, weight in graph[source[start]]:
                if neighbor == target[end]:
                    min_cost = min(min_cost, weight + dfs(start + 1, end + 1))
                elif dfs(start + 1, neighbor) + weight < min_cost:
                    min_cost = dfs(start + 1, neighbor) + weight

            return min_cost

        result = dfs(0, 0)
        return result if result != float('inf') else -1

class Solution:
    def numSubarraysWithSum(self, nums: List[int], goal: int) -> int:
        if not nums:
            return 0

        count = 0
        current_sum = 0

        for num in nums:
            current_sum += num

            # If current_sum equals goal, increment count
            if current_sum == goal:
                count += 1

            # If current_sum exceeds goal, reset it to zero
            elif current_sum > goal:
                current_sum = 0

        return count

