class Solution:
    def jobScheduling(self, startTime: List[int], endTime: List[int], profit: List[int]) -> int:
        # Combine the start times, end times, and profits into a single list of jobs
        jobs = sorted(zip(startTime, endTime, profit), key=lambda x: x[1])

        # Create an array to store the maximum profit up to each job
        dp = [0] * len(jobs)

        # Initialize the first job's profit
        dp[0] = jobs[0][2]

        # Fill the dp array
        for i in range(1, len(jobs)):
            # Find the last job that doesn't overlap with the current job
            j = self.findLastNonOverlappingJob(jobs, i)

            # If there is no overlapping job, consider only the current job's profit
            if j == -1:
                dp[i] = max(dp[i-1], jobs[i][2])
            else:
                # Otherwise, consider the maximum profit including the current job
                dp[i] = max(dp[i-1], dp[j] + jobs[i][2])

        # The last element of dp contains the maximum profit
        return dp[-1]

    def findLastNonOverlappingJob(self, jobs, index):
        # Binary search to find the last job that doesn't overlap with the job at 'index'
        low, high = 0, index - 1

        while low <= high:
            mid = (low + high) // 2
            if jobs[mid][1] <= jobs[index][0]:
                if jobs[mid+1][1] <= jobs[index][0]:
                    low = mid + 1
                else:
                    return mid
            else:
                high = mid - 1

        return -1

