        sumA = sum(aliceSizes)
        sumB = sum(bobSizes)
        diff = (sumB - sumA) // 2

        setB = set(bobSizes)

        for size in aliceSizes:
            if size + diff in setB:
                return [size, size + diff]

class Solution:
    def movesToChessboard(self, board: List[List[int]]) -> int:
        n = len(board)

        # Check if it's possible to form a valid chessboard
        def is_valid(chessboard):
            for i in range(n):
                for j in range(n):
                    if chessboard[i][j] != chessboard[0][0] ^ (i % 2 == j % 2):
                        return False
            return True

        # Count the number of 1s in each row and column
        row_counts = [sum(row) for row in board]
        col_counts = [sum(col) for col in zip(*board)]

        # Check if the counts are valid for a chessboard
        if not all(count == n // 2 + n % 2 for count in row_counts) or not all(count == n // 2 + n % 2 for count in col_counts):
            return -1

        # Calculate the number of moves needed to make the first row and column match the target pattern
        def calculate_moves(row, col):
            moves = 0
            for i in range(n):
                if row[i] != (i % 2 == 0):
                    moves += 1
                if col[i] != (i % 2 == 0):
                    moves += 1
            return moves // 2

        # Find the minimum number of moves needed
        moves = float('inf')
        for i in range(2):
            target_row = [i % 2] * n
            target_col = [i % 2] * n
            moves = min(moves, calculate_moves(board[0], target_col))
            moves = min(moves, calculate_moves(target_row, board[0]))
            board = list(zip(*board))

        return moves if moves != float('inf') else -1

