class Solution:
    def countPairsOfConnectableServers(self, edges: List[List[int]], signalSpeed: int) -> List[int]:
        from collections import defaultdict

        # Build the graph
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        def dfs(node, parent, distance):
            count = 0
            for neighbor, weight in graph[node]:
                if neighbor == parent:
                    continue
                new_distance = distance + weight
                if new_distance % signalSpeed == 0:
                    count += 1
                count += dfs(neighbor, node, new_distance)
            return count

        n = len(graph)
        result = [0] * n

        for root in range(n):
            total_pairs = 0
            for neighbor, weight in graph[root]:
                if weight % signalSpeed == 0:
                    total_pairs += 1
                total_pairs += dfs(neighbor, root, weight)

            # Calculate the number of pairs
            for neighbor, weight in graph[root]:
                if weight % signalSpeed == 0:
                    pairs = dfs(neighbor, root, weight)
                    result[root] += pairs * (total_pairs - pairs)
                else:
                    pairs = dfs(neighbor, root, weight)
                    if pairs % signalSpeed == 0:
                        result[root] += pairs * (total_pairs - pairs)

        return result

class Solution:
    def reverseBits(self, n: int) -> int:
        # Initialize the result variable to store the reversed bits
        res = 0

        # Iterate over each bit of the input number
        for i in range(32):
            # Shift the bits to the right by 1 position and add the least significant bit
            res = (res << 1) | (n & 1)

        # Return the reversed bits
        return res

class Solution:
    def numberOfCleanRooms(self, room: List[List[int]]) -> int:
        m, n = len(room), len(room[0])
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        seen = set()
        stack = [(0, 0)]

        while stack:
            x, y = stack.pop()
            seen.add((x, y))
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in seen and room[nx][ny] == 0:
                    stack.append((nx, ny))

        return len(seen)

