class Solution:
    def maxDistance(self, grid: List[List[int]]) -> int:
        n = len(grid)
        queue = []
        visited = set()

        # Collect all land cells into the queue
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    queue.append((i, j))
                    visited.add((i, j))

        # Directions for moving up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        distance = -1

        while queue:
            level_size = len(queue)
            distance += 1

            for _ in range(level_size):
                x, y = queue.pop(0)

                for dx, dy in directions:
                    nx, ny = x + dx, y + dy

                    if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append((nx, ny))

        return distance

class Solution:
    def canMakeSquare(self, grid: List[List[str]]) -> bool:
        # Count the number of 'W's in the grid
        white_count = sum(1 for row in grid for col in row if col == 'W')

        # If there are fewer than 2 'W's, it's impossible to make a 2x2 square
        if white_count < 2:
            return False

        # Try to make the smallest 2x2 square
        for i in range(0, 3):
            for j in range(0, 3):
                if i != j and grid[i][j] == 'W':
                    # Try to make a smaller 2x2 square
                    for k in range(i, i + 2):
                        for l in range(j, j + 2):
                            if k != l and grid[k][l] == 'W':
                                # If all cells in the 2x2 square are 'W', return True
                                return True
        return False

class Solution:
    def largestValues(self, root: Optional[TreeNode]) -> List[int]:
        if not root:
            return []

        queue = deque([root])
        result = []

        while queue:
            current_max = float('-inf')
            level_size = len(queue)

            for _ in range(level_size):
                node = queue.popleft()
                current_max = max(current_max, node.val)

                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

            result.append(current_max)

        return result

class Solution:
    def removeKdigits(self, num: str, k: int) -> str:
        stack = []
        for digit in num:
            while stack and stack[-1] > digit and k > 0:
                stack.pop()
                k -= 1
            stack.append(digit)
        # Remove trailing zeros
        while stack and stack[-1] == '0':
            stack.pop()
        # Return the result if stack is empty, otherwise convert it to string
        return ''.join(stack) if stack else '0'

