from math import factorial
from typing import List

class Solution:
    def getProbability(self, balls: List[int]) -> float:
        total_balls = sum(balls)
        half_balls = total_balls // 2
        k = len(balls)

        def comb(n, k):
            return factorial(n) // (factorial(k) * factorial(n - k))

        def dfs(i, left, right, left_colors, right_colors, total_permutations):
            if i == k:
                if left == right and left_colors == right_colors:
                    return total_permutations
                return 0

            result = 0
            for j in range(0, balls[i] + 1):
                if left + j > half_balls or right + (balls[i] - j) > half_balls:
                    continue
                result += dfs(i + 1, left + j, right + (balls[i] - j), 
                              left_colors + (j > 0), right_colors + ((balls[i] - j) > 0),
                              total_permutations * comb(balls[i], j))
            return result

        total_ways = comb(total_balls, half_balls)
        valid_ways = dfs(0, 0, 0, 0, 0, 1)

        return valid_ways / total_ways

from typing import List
import heapq

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        # Create a graph representation
        graph = {}
        for i in range(len(original)):
            u, v, c = original[i], changed[i], cost[i]
            if u not in graph:
                graph[u] = {}
            if v not in graph[u]:
                graph[u][v] = float('inf')
            graph[u][v] = min(graph[u][v], c)

        # Function to find the shortest path from src to all other nodes using Dijkstra's algorithm
        def dijkstra(graph, src):
            dist = {node: float('inf') for node in graph}
            dist[src] = 0
            priority_queue = [(0, src)]

            while priority_queue:
                current_dist, current_node = heapq.heappop(priority_queue)

                if current_dist > dist[current_node]:
                    continue

                for neighbor, weight in graph[current_node].items():
                    distance = current_dist + weight

                    if distance < dist[neighbor]:
                        dist[neighbor] = distance
                        heapq.heappush(priority_queue, (distance, neighbor))

            return dist

        # Precompute shortest paths between all pairs of characters
        all_pairs_shortest_paths = {}
        for char in graph:
            all_pairs_shortest_paths[char] = dijkstra(graph, char)

        # Calculate the total minimum cost to convert source to target
        total_cost = 0
        for s, t in zip(source, target):
            if s != t:
                if t not in all_pairs_shortest_paths[s] or all_pairs_shortest_paths[s][t] == float('inf'):
                    return -1
                total_cost += all_pairs_shortest_paths[s][t]

        return total_cost

