class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        if len(nums) == 1:
            return True

        def find(x):
            while x in uf:
                while uf[x] in uf:
                    uf[x] = uf[uf[x]]
                x = uf[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return False
            uf[px] = py
            return True

        uf = {}
        for n in nums:
            if n == 1:
                return False
            for d in range(2, int(n**0.5) + 1):
                if n % d == 0:
                    union(n, d)
                    union(n, n // d)

        return len({find(n) for n in nums}) == 1

