class Solution:
    def removeOnes(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        if not m or not n:
            return 0

        # Find rows and columns with all ones
        rows_with_all_ones = [i for i in range(m) if all(grid[i])]
        cols_with_all_ones = [j for j in range(n) if all(grid[i][j] for i in range(m))]

        # If there are no rows or columns with all ones, return 0
        if not rows_with_all_ones and not cols_with_all_ones:
            return 0

        # Count the number of operations required to remove all ones
        count = 0
        for r in rows_with_all_ones:
            grid[r] = [0] * n
        for c in cols_with_all_ones:
            for i in range(m):
                grid[i][c] = 0

        return count + 1

