class Solution:
    def maximumsSplicedArray(self, nums1: List[int], nums2: List[int]) -> int:
        def max_sum_by_swapping(nums1, nums2):
            max_diff = current_diff = 0
            for i in range(len(nums1)):
                current_diff = max(nums2[i] - nums1[i], current_diff + nums2[i] - nums1[i])
                max_diff = max(max_diff, current_diff)
            return sum(nums1) + max_diff

        return max(max_sum_by_swapping(nums1, nums2), max_sum_by_swapping(nums2, nums1))

class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        if len(s) != len(t):
            return False

        # Count the occurrences of each digit in s and t
        count_s = [0] * 10
        count_t = [0] * 10
        for char in s:
            count_s[int(char)] += 1
        for char in t:
            count_t[int(char)] += 1

        # If the counts don't match, transformation is impossible
        if count_s != count_t:
            return False

        # Check if we can transform s to t
        position = [0] * 10  # To keep track of the next position of each digit in s
        for i in range(len(s)):
            digit_s = int(s[i])
            digit_t = int(t[i])

            # Check if digit_t has appeared before in s
            if position[digit_t] > position[digit_s]:
                return False

            # Increment the position for the current digit in s
            position[digit_s] += 1

            # Ensure that all smaller digits have not been used up more times than in t
            for d in range(digit_t):
                if position[d] > count_t[d]:
                    return False

        return True

