class Solution:
    def furthestBuilding(self, heights: List[int], bricks: int, ladders: int) -> int:
        n = len(heights)
        max_heap = []

        for i in range(n - 1):
            climb = heights[i + 1] - heights[i]
            if climb > 0:
                heapq.heappush(max_heap, -climb)
                if len(max_heap) > ladders:
                    bricks += heapq.heappop(max_heap)
                if bricks < 0:
                    return i

        return n - 1

class Solution:
    def getLongestSubsequence(self, words: List[str], groups: List[int]) -> List[str]:
        max_length = 0
        longest_subsequence = []

        # Iterate through all possible starting points
        for start in range(len(words)):
            current_length = 1
            current_subsequence = [words[start]]

            # Try to extend the subsequence
            for i in range(start + 1, len(words)):
                if groups[i] != groups[i - 1]:
                    current_length += 1
                    current_subsequence.append(words[i])
                else:
                    break

            # Update the longest subsequence if necessary
            if current_length > max_length:
                max_length = current_length
                longest_subsequence = current_subsequence

        return longest_subsequence

class Solution:
    def isCircularSentence(self, sentence: str) -> bool:
        # Split the sentence into words
        words = sentence.split()

        # Check if the first word is the same as the last word
        if words[0] != words[-1]:
            return False

        # Check if the last word is the same as the first word
        if words[-1] != words[0]:
            return False

        # Check if the sentence is circular
        for i in range(len(words)):
            if words[i] != words[(i + 1) % len(words)]:
                return False

        return True

class Solution:
    def minDominoRotations(self, tops: List[int], bottoms: List[int]) -> int:
        n = len(tops)
        target = tops[0]

        # Check if target can be used for the first column
        count_top = sum(1 for i in range(n) if tops[i] == target)
        count_bottom = sum(1 for i in range(n) if bottoms[i] == target)

        if count_top + count_bottom >= n:
            return min(count_top, count_bottom)

        # Check if target can be used for the second column
        target = bottoms[0]
        count_top = sum(1 for i in range(n) if tops[i] == target)
        count_bottom = sum(1 for i in range(n) if bottoms[i] == target)

        if count_top + count_bottom >= n:
            return min(count_top, count_bottom)

        return -1

class Solution:
    def longestBeautifulSubstring(self, word: str) -> int:
        max_length = 0
        current_length = 0
        has_all_vowels = False

        for i in range(len(word)):
            if word[i] == 'a':
                if i > 0 and word[i-1] != 'a':
                    current_length = 1
                else:
                    current_length += 1
            elif word[i] == 'e':
                if i > 0 and word[i-1] != 'e' and word[i-1] != 'a':
                    current_length = 1
                else:
                    current_length += 1
                has_all_vowels = True
            elif word[i] == 'i':
                if i > 0 and word[i-1] != 'i' and word[i-1] != 'e':
                    current_length = 1
                else:
                    current_length += 1
                has_all_vowels = True
            elif word[i] == 'o':
                if i > 0 and word[i-1] != 'o' and word[i-1] != 'i':
                    current_length = 1
                else:
                    current_length += 1
                has_all_vowels = True
            elif word[i] == 'u':
                if i > 0 and word[i-1] != 'u' and word[i-1] != 'o':
                    current_length = 1
                else:
                    current_length += 1
                has_all_vowels = True

                if has_all_vowels:
                    max_length = max(max_length, current_length)

        return max_length

class Solution:
    def subArrayRanges(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        max_val = min_val = nums[0]
        total_sum = 0

        for i in range(1, n):
            max_val = max(nums[i], max_val)
            min_val = min(nums[i], min_val)
            total_sum += max_val - min_val

        return total_sum

