class Solution:
    def minimumXORSum(self, nums1: List[int], nums2: List[int]) -> int:
        self.nums1 = nums1
        self.nums2 = nums2
        self.dp = [[-1 for _ in range(1 << len(nums1))] for _ in range(len(nums1))]
        return self.helper(0, 0)

    def helper(self, index, mask):
        if index == len(self.nums1):
            return 0

        if self.dp[index][mask] != -1:
            return self.dp[index][mask]

        res = float('inf')
        for i in range(len(self.nums2)):
            if not (mask & (1 << i)):
                res = min(res, self.nums1[index] ^ self.nums2[i] + self.helper(index + 1, mask | (1 << i)))

        self.dp[index][mask] = res
        return res

class Solution:
    def nextClosestTime(self, time: str) -> str:
        digits = set(time.replace(":", ""))
        hour, minute = map(int, time.split(":"))

        while True:
            # Increment the minute
            if minute == 59:
                hour += 1
                minute = 0
            else:
                minute += 1

            # Wrap around hour if it reaches 24
            if hour == 24:
                hour = 0

            # Check if the new time can be formed using the given digits
            if all(x in digits for x in f"{hour}{minute}"):
                return f"{hour:02}:{minute:02}"

