class Solution:
    def maximumScoreAfterOperations(self, edges: List[List[int]], values: List[int]) -> int:
        n = len(values)
        graph = [[] for _ in range(n)]

        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def dfs(node, parent):
            if len(graph[node]) == 1 and node != 0:
                return values[node]

            min_val = float('inf')
            for neighbor in graph[node]:
                if neighbor != parent:
                    min_val = min(min_val, dfs(neighbor, node))

            return min(min_val, values[node])

        total_sum = sum(values)
        min_value_to_keep = dfs(0, -1)

        return total_sum - min_value_to_keep

