class Solution:
    def minimizeTheDifference(self, mat: List[List[int]], target: int) -> int:
        m, n = len(mat), len(mat[0])
        dp = [set() for _ in range(m + 1)]
        dp[0].add(0)

        for i in range(m):
            new_dp = set()
            for num in dp[i]:
                for val in mat[i]:
                    new_sum = num + val
                    if new_sum > target:
                        break
                    new_dp.add(new_sum)
            dp[i + 1] = new_dp

        min_diff = float('inf')
        for num in dp[m]:
            min_diff = min(min_diff, abs(target - num))

        return min_diff

