        return ''.join(result)

class Solution:
    def countSteppingNumbers(self, low: int, high: int) -> List[int]:
        result = []

        def dfs(num):
            if num >= low and num <= high:
                result.append(num)
            if num > high:
                return
            last_digit = num % 10
            if last_digit == 0:
                dfs(num * 10 + 1)
            elif last_digit == 9:
                dfs(num * 10 + 8)
            else:
                dfs(num * 10 + last_digit - 1)
                dfs(num * 10 + last_digit + 1)

        for i in range(1, 10):
            dfs(i)

        return sorted(result)

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        # Recursive approach
        return self.compare(root, root)

    def compare(self, left, right):
        if not left and not right:
            return True
        if not left or not right:
            return False
        if left.val != right.val:
            return False

        # Recursively compare left and right subtrees
        return self.compare(left.left, right.right) and self.compare(left.right, right.left)

from collections import deque

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x <= y:
            return y - x

        queue = deque([(x, 0)])
        visited = set([x])

        while queue:
            current_x, operations = queue.popleft()

            if current_x == y:
                return operations

            # Possible operations
            next_operations = [
                (current_x // 11, operations + 1 + (current_x % 11)),
                (current_x // 5, operations + 1 + (current_x % 5)),
                (current_x - 1, operations + 1),
                (current_x + 1, operations + 1)
            ]

            for next_x, next_ops in next_operations:
                if next_x not in visited and next_x > 0:
                    visited.add(next_x)
                    queue.append((next_x, next_ops))

