class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        if m == 1 and n == 1:
            return 0

        # Directions for moving up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Queue for BFS: (row, col, remaining k, steps)
        queue = deque([(0, 0, k, 0)])

        # Set to keep track of visited states: (row, col, remaining k)
        visited = set((0, 0, k))

        while queue:
            row, col, remaining_k, steps = queue.popleft()

            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc

                if 0 <= new_row < m and 0 <= new_col < n:
                    new_remaining_k = remaining_k - grid[new_row][new_col]

                    if new_remaining_k >= 0 and (new_row, new_col, new_remaining_k) not in visited:
                        if new_row == m - 1 and new_col == n - 1:
                            return steps + 1

                        visited.add((new_row, new_col, new_remaining_k))
                        queue.append((new_row, new_col, new_remaining_k, steps + 1))

        return -1

class Solution:
    def numBusesToDestination(self, routes: List[List[int]], source: int, target: int) -> int:
        if source == target:
            return 0

        # Build a graph where each node represents a bus stop and edges represent routes connecting them
        graph = defaultdict(list)
        for i, route in enumerate(routes):
            for stop in route:
                graph[stop].append(i)

        # BFS to find the shortest path from source to target
        queue = deque([(source, 0)])
        visited = set()

        while queue:
            stop, steps = queue.popleft()

            if stop == target:
                return steps

            if stop in visited:
                continue

            visited.add(stop)

            for bus in graph[stop]:
                if bus not in visited:
                    for next_stop in routes[bus]:
                        queue.append((next_stop, steps + 1))

        return -1

