class Solution:
    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        if m == 1 and n == 1:
            return False

        # Check if we can reach the bottom-right corner without flipping any cell
        def canReachBottomRight():
            stack = [(0, 0)]
            visited = set()
            while stack:
                i, j = stack.pop()
                if i == m - 1 and j == n - 1:
                    return True
                visited.add((i, j))
                for dx, dy in [(1, 0), (0, 1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1 and (ni, nj) not in visited:
                        stack.append((ni, nj))
            return False

        # Check if we can reach the top-left corner without flipping any cell
        def canReachTopLeft():
            stack = [(m - 1, n - 1)]
            visited = set()
            while stack:
                i, j = stack.pop()
                if i == 0 and j == 0:
                    return True
                visited.add((i, j))
                for dx, dy in [(-1, 0), (0, -1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1 and (ni, nj) not in visited:
                        stack.append((ni, nj))
            return False

        # Check if we can reach the bottom-left corner from the top-left corner
        def canReachFromTopLeftToBottomRight():
            stack = [(0, 0)]
            visited = set()
            while stack:
                i, j = stack.pop()
                if i == m - 1 and j == n - 1:
                    return True
                visited.add((i, j))
                for dx, dy in [(-1, 0), (0, -1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1 and (ni, nj) not in visited:
                        stack.append((ni, nj))
            return False

        # Check if we can reach the top-right corner from the bottom-right corner
        def canReachFromBottomRightToTopLeft():
            stack = [(m - 1, n - 1)]
            visited = set()
            while stack:
                i, j = stack.pop()
                if i == 0 and j == n - 1:
                    return True
                visited.add((i, j))
                for dx, dy in [(1, 0), (0, -1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1 and (ni, nj) not in visited:
                        stack.append((ni, nj))
            return False

        # If we can reach both corners without flipping any cell, then we can't disconnect the matrix
        if canReachBottomRight() and canReachTopLeft():
            return False

        # If we can reach both corners from each other, then we can't disconnect the matrix
        if canReachFromTopLeftToBottomRight() and canReachFromBottomRightToTopLeft():
            return False

        # Otherwise, we can disconnect the matrix
        return True

