class Solution:
    def waysToMakeFair(self, nums: List[int]) -> int:
        n = len(nums)
        prefix_even = [0] * (n + 1)
        prefix_odd = [0] * (n + 1)

        for i in range(n):
            if i % 2 == 0:
                prefix_even[i + 1] = prefix_even[i] + nums[i]
            else:
                prefix_odd[i + 1] = prefix_odd[i] + nums[i]

        ans = 0
        for i in range(n):
            left_even = prefix_even[i]
            right_even = prefix_even[n] - left_even - nums[i]
            left_odd = prefix_odd[i]
            right_odd = prefix_odd[n] - left_odd - nums[i]

            if left_even == right_odd and left_odd == right_even:
                ans += 1

        return ans

class Solution:
    def maxValueAfterReverse(self, nums: List[int]) -> int:
        n = len(nums)
        base_value = sum(abs(nums[i] - nums[i + 1]) for i in range(n - 1))

        # Calculate the potential gain by reversing a subarray
        max_gain = 0

        # Check the gain by reversing a subarray that includes the first or last element
        for i in range(1, n):
            max_gain = max(max_gain, abs(nums[0] - nums[i]) - abs(nums[i] - nums[i - 1]))
            max_gain = max(max_gain, abs(nums[n - 1] - nums[i - 1]) - abs(nums[i] - nums[i - 1]))

        # Check the gain by reversing a subarray that does not include the first or last element
        for i in range(1, n - 1):
            for j in range(i + 1, n):
                if (nums[i - 1] - nums[i]) * (nums[j] - nums[j - 1]) > 0:
                    max_gain = max(max_gain, abs(nums[i - 1] - nums[j]) - abs(nums[i] - nums[j - 1]))

        return base_value + max_gain

class Solution:
    def minCostToEqualizeArray(self, nums: List[int], cost1: int, cost2: int) -> int:
        # Count the frequency of each number
        count = Counter(nums)

        # Calculate the total cost if we increase each number by 1
        total_cost_increase = sum(cost1 * freq for freq in count.values())

        # Calculate the total cost if we increase two numbers by 1
        total_cost_double_increase = 0
        for num, freq in count.items():
            for other_num in range(num + 1, max(nums) + 1):
                if other_num not in count:
                    continue
                total_cost_double_increase += cost2 * freq * count[other_num]

        # The minimum cost is the smaller of the two options
        return min(total_cost_increase, total_cost_double_increase) % (10**9 + 7)

class Solution:
    def hasValidPath(self, grid: List[List[str]]) -> bool:
        def dfs(x, y):
            if x < 0 or y < 0 or x >= len(grid) or y >= len(grid[0]) or grid[x][y] != '(':
                return False
            if x == len(grid) - 1 and y == len(grid[0]) - 1:
                return True
            return dfs(x + 1, y) or dfs(x, y + 1)

        return dfs(0, 0)

