class Solution:
    def canMakeSquare(self, grid: List[List[str]]) -> bool:
        def check_square(x, y):
            return grid[x][y] == grid[x+1][y] == grid[x][y+1] == grid[x+1][y+1]

        for i in range(2):
            for j in range(2):
                if check_square(i, j):
                    return True
                grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1] = \\\\
                        grid[i+1][j+1], grid[i][j+1], grid[i+1][j], grid[i][j]
                if check_square(i, j):
                    return True
                grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1] = \\\\
                        grid[i][j+1], grid[i+1][j+1], grid[i][j], grid[i+1][j]
        return False

class Solution:
    def maxPrice(self, items: List[List[int]], capacity: int) -> float:
        items.sort(key=lambda x: x[0]/x[1], reverse=True)
        res = 0
        for p, w in items:
            if w <= capacity:
                res += p
                capacity -= w
            else:
                break
        return res if capacity == 0 else -1

