    def splitString(self, s: str) -> bool:
        n = len(s)
        for i in range(1, n):
            num1 = int(s[:i])
            if num1 == 0:
                continue
            for j in range(i+1, n):
                num2 = int(s[i:j])
                if num2 == 0:
                    continue
                if num1 - num2 != 1:
                    break
                else:
                    if j == n-1:
                        return True
        return False

