class Solution:
    def convertArray(self, nums: List[int]) -> int:
        def min_operations_to_sorted(arr):
            lis = []
            cost = 0
            for num in arr:
                pos = bisect.bisect_right(lis, num)
                if pos == len(lis):
                    lis.append(num)
                else:
                    cost += lis[pos] - num
                    lis[pos] = num
            return cost

        return min(min_operations_to_sorted(nums), min_operations_to_sorted(reversed(nums)))

