class Solution:
    def maximumANDSum(self, nums: List[int], numSlots: int) -> int:
        # Initialize the DP table
        dp = [[0] * (1 << numSlots) for _ in range(numSlots + 1)]

        # Helper function to calculate the maximum AND sum
        def helper(nums, i, mask):
            if i == len(nums):
                return 0
            if dp[i][mask] != 0:
                return dp[i][mask]

            max_sum = float('-inf')
            for j in range(1, numSlots + 1):
                if not (mask & (1 << (j - 1))):
                    new_mask = mask | (1 << (j - 1))
                    max_sum = max(max_sum, nums[i] & j + helper(nums, i + 1, new_mask))

            dp[i][mask] = max_sum
            return dp[i][mask]

        return helper(nums, 0, 0)

import heapq

class Solution:
    def swimInWater(self, grid: List[List[int]]) -> int:
        n = len(grid)
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        visited = set()
        min_heap = [(grid[0][0], 0, 0)]  # (elevation, row, col)
        result = grid[0][0]

        while min_heap:
            elevation, row, col = heapq.heappop(min_heap)
            result = max(result, elevation)

            if row == n - 1 and col == n - 1:
                return result

            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < n and 0 <= new_col < n and (new_row, new_col) not in visited:
                    visited.add((new_row, new_col))
                    heapq.heappush(min_heap, (grid[new_row][new_col], new_row, new_col))

        return -1

