class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        def parse(s):
            if not s:
                return set()
            if s[0] != '{':
                i = 0
                while i < len(s) and s[i] not in ',{':
                    i += 1
                return {s[:i]} | parse(s[i:])

            stack = []
            i = 1
            while i < len(s):
                if s[i] == '{':
                    stack.append(i)
                elif s[i] == '}':
                    if not stack:
                        break
                    stack.pop()
                i += 1

            if not stack:
                return parse(s[1:i]) | parse(s[i+1:])

            j = i
            while j < len(s):
                if s[j] == ',' and not stack:
                    break
                if s[j] == '{':
                    stack.append(j)
                elif s[j] == '}':
                    stack.pop()
                j += 1

            return parse(s[1:i]) | (parse(s[i+1:j]) * parse(s[j+1:]))

        def multiply(a, b):
            return {x + y for x in a for y in b}

        result = parse(expression)
        return sorted(result)

