class Solution:
    def minimumTime(self, hens: List[int], grains: List[int]) -> int:
        # Sort both lists
        hens.sort()
        grains.sort()

        # Initialize variables
        start, end = min(hens), max(grains)
        ans = float('inf')

        # Binary search for the minimum time
        while start <= end:
            mid = (start + end) // 2
            if self.canEatAllGrains(hens, grains, mid):
                ans = mid
                end = mid - 1
            else:
                start = mid + 1

        return ans

    def canEatAllGrains(self, hens, grains, target_time):
        # Count the number of grains that can be eaten in the given time
        count = sum(1 for grain in grains if grain <= target_time)
        return count >= len(hens)

