class Solution:
    def minSwap(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        dp = [[0]*2 for _ in range(n)]

        # Initialize base case
        dp[0][0] = 0 if nums1[0] > nums2[0] else 1
        dp[0][1] = 1 if nums1[0] > nums2[0] else 0

        # Fill DP table
        for i in range(1, n):
            if nums1[i] > nums2[i]:
                dp[i][0] = min(dp[i-1][0], dp[i-1][1]) + 1
                dp[i][1] = min(dp[i-1][0], dp[i-1][1])
            else:
                dp[i][0] = dp[i-1][0]
                dp[i][1] = dp[i-1][1] + 1

        return min(dp[-1])

