class Solution:
    def goodSubsetofBinaryMatrix(self, grid: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        # Dictionary to store the first occurrence of each binary pattern
        pattern_index = {}

        for i in range(m):
            # Convert the row to a tuple to use as a dictionary key
            pattern = tuple(grid[i])
            # Check if this pattern has been seen before
            if pattern in pattern_index:
                # If found, we have at least two rows with the same pattern
                # This subset is guaranteed to be good
                return [pattern_index[pattern], i]
            else:
                # Store the index of the first occurrence of this pattern
                pattern_index[pattern] = i

        # Check all pairs of rows to find a good subset
        for i in range(m):
            for j in range(i + 1, m):
                # Check if the sum of each column is at most 1 (half of 2)
                if all(grid[i][k] + grid[j][k] <= 1 for k in range(n)):
                    return [i, j]

        # If no good subset is found, return an empty list
        return []

# Definition for singly-linked list.
# class ListNode:
#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def mergeNodes(self, head: Optional[ListNode]) -> Optional[ListNode]:
        dummy = ListNode(0)
        current = dummy
        sum_val = 0

        while head:
            if head.val == 0:
                if sum_val > 0:
                    current.next = ListNode(sum_val)
                    current = current.next
                    sum_val = 0
            else:
                sum_val += head.val
            head = head.next

        return dummy.next

