class Solution:
    def minimumTotalCost(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        freq = Counter()
        same = []

        # Count the frequency of elements that are the same in both arrays
        for i in range(n):
            if nums1[i] == nums2[i]:
                freq[nums1[i]] += 1
                same.append(i)

        # Find the most frequent element that appears in the same positions
        max_freq = freq.most_common(1)[0][1]
        max_element = freq.most_common(1)[0][0]

        # If the most frequent element appears more than half the time, we need additional swaps
        if max_freq > n // 2:
            extra_swaps_needed = max_freq - (n // 2)
            total_cost = sum(same)

            # Try to find additional indices to swap
            for i in range(n):
                if nums1[i] != nums2[i] and nums1[i] != max_element and nums2[i] != max_element:
                    total_cost += i
                    extra_swaps_needed -= 1
                    if extra_swaps_needed == 0:
                        break

            # If we couldn't find enough additional swaps, return -1
            if extra_swaps_needed > 0:
                return -1

            return total_cost

        # If no element appears more than half the time, we can just swap all same elements
        return sum(same)

class Solution:
    def isStrictlyPalindromic(self, n: int) -> bool:
        # Convert the number to a string
        num_str = str(n)
        # Iterate through each base from 2 to n-2
        for base in range(2, n-1):
            # Convert the number to the current base
            base_num = int(num_str, base)
            # Check if the string representation of the number in the current base is palindromic
            if str(base_num)[::-1] != num_str:
                return False
        return True

