class Solution:
    def lemonadeChange(self, bills: List[int]) -> bool:
        # Initialize the amount of money and the number of coins used
        amount = 0
        coins = 0

        # Iterate through each bill in the list
        for bill in bills:
            # Check if the current bill is $5
            if bill == 5:
                # If the amount of money is greater than or equal to $5, add $5 to the amount
                if amount >= 5:
                    amount -= 5
                else:
                    # If not enough money, return False
                    return False
            # Check if the current bill is $10
            elif bill == 10:
                # If the amount of money is greater than or equal to $10, subtract $10 from the amount
                if amount >= 10:
                    amount -= 10
                else:
                    # If not enough money, return False
                    return False
            # Check if the current bill is $20
            elif bill == 20:
                # If the amount of money is greater than or equal to $20, subtract $20 from the amount
                if amount >= 20:
                    amount -= 20
                else:
                    # If not enough money, return False
                    return False
            # If none of the above conditions are met, return False
            else:
                # If more than one bill of the same value is found, return False
                return False

        # If all bills were paid correctly, return True
        return True

class Solution:
    def minimumOneBitOperations(self, n: int) -> int:
        # Initialize the result to 0
        res = 0

        # Iterate through each bit of n
        while n > 0:
            # If the current bit is 1, increment the result by 2
            if n % 2 == 1:
                res += 2
            # Right shift n by 1 bit
            n >>= 1

        return res

class Solution:
    def sumRemoteness(self, grid: List[List[int]]) -> int:
        n = len(grid)
        remotes = [[0] * n for _ in range(n)]
        queue = deque()

        # Add all blocked cells to the queue
        for i in range(n):
            for j in range(n):
                if grid[i][j] == -1:
                    queue.append((i, j))

        # Process each cell in the queue
        while queue:
            i, j = queue.popleft()
            for x, y in [(i+1, j), (i-1, j), (i, j+1), (i, j-1)]:
                if 0 <= x < n and 0 <= y < n and grid[x][y] == 0:
                    remotes[x][y] += grid[i][j]
                    queue.append((x, y))

        # Sum up all values in the remotes matrix
        return sum(sum(row) for row in remotes)

