        if not root:
            return TreeNode(val)
        if root.val < val:
            root.right = self.insertIntoBST(root.right, val)
        else:
            root.left = self.insertIntoBST(root.left, val)
        return root

from typing import List
from collections import deque

class Solution:
    def minimumSeconds(self, land: List[List[str]]) -> int:
        n, m = len(land), len(land[0])
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        # Find the starting point 'S' and all flooded cells '*'
        start = None
        floods = deque()
        for i in range(n):
            for j in range(m):
                if land[i][j] == 'S':
                    start = (i, j)
                elif land[i][j] == '*':
                    floods.append((i, j))

        # Initialize the queue for BFS
        queue = deque([(start[0], start[1], 0)])
        visited = set([start])

        # Perform BFS
        while queue:
            x, y, time = queue.popleft()

            # Check if we reached the destination
            if land[x][y] == 'D':
                return time

            # Explore neighbors
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and land[nx][ny] != 'X':
                    # Check if the cell will be flooded at the next second
                    if any(abs(nx - fx) + abs(ny - fy) == 1 for fx, fy in floods):
                        continue
                    queue.append((nx, ny, time + 1))
                    visited.add((nx, ny))

        return -1

from typing import List

class Solution:
    def numSimilarGroups(self, strs: List[str]) -> int:
        def is_similar(s1, s2):
            diff = [i for i in range(len(s1)) if s1[i] != s2[i]]
            return len(diff) == 2 and s1[diff[0]] == s2[diff[1]] and s1[diff[1]] == s2[diff[0]]

        def dfs(node, visited):
            stack = [node]
            while stack:
                current = stack.pop()
                if current not in visited:
                    visited.add(current)
                    for neighbor in graph[current]:
                        if neighbor not in visited:
                            stack.append(neighbor)

        n = len(strs)
        graph = {i: [] for i in range(n)}

        for i in range(n):
            for j in range(i + 1, n):
                if is_similar(strs[i], strs[j]):
                    graph[i].append(j)
                    graph[j].append(i)

        visited = set()
        groups = 0

        for i in range(n):
            if i not in visited:
                dfs(i, visited)
                groups += 1

        return groups

