class Solution:
    def trimMean(self, arr: List[int]) -> float:
        sorted_arr = sorted(arr)
        n = len(sorted_arr)
        left_index = int(0.05 * n)
        right_index = int(0.95 * n)
        trimmed_arr = sorted_arr[left_index:right_index]
        return sum(trimmed_arr) / len(trimmed_arr)

class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        left, right = 1, max(arr)
        while left < right:
            mid = (left + right) // 2
            if sum(i if i <= mid else mid for i in arr) >= target:
                right = mid
            else:
                left = mid + 1
        return left

class Solution:
    def catchMaximumAmountofPeople(self, team: List[int], dist: int) -> int:
        n = len(team)
        res = 0
        for i in range(n):
            # Check if the person at index i is not "it"
            if team[i] != 0:
                # Calculate the range of people that can catch them
                start = max(0, i - dist)
                end = min(n - 1, i + dist)
                # Update the result with the maximum number of people that can catch them
                res = max(res, end - start + 1)
        return res

class Solution:
    def countCompleteComponents(self, n: int, edges: List[List[int]]) -> int:
        graph = {i: set() for i in range(n)}
        for u, v in edges:
            graph[u].add(v)
            graph[v].add(u)

        visited = set()
        count = 0

        def dfs(node):
            stack = [node]
            component = set()
            while stack:
                node = stack.pop()
                if node not in visited:
                    visited.add(node)
                    component.add(node)
                    for neighbor in graph[node]:
                        stack.append(neighbor)
            return component

        for i in range(n):
            if i not in visited:
                component = dfs(i)
                if len(component) == len(graph[i]) + 1:
                    count += 1

        return count

