class Solution:
    def canReach(self, s: str, minJump: int, maxJump: int) -> bool:
        n = len(s)
        dp = [False] * n
        dp[0] = True

        for i in range(n):
            if not dp[i]:
                continue

            for j in range(max(0, i - maxJump), min(n, i + minJump + 1)):
                if s[j] == '0':
                    dp[j] = True

        return dp[-1]

class Solution:
    def sortArrayByParityII(self, nums: List[int]) -> List[int]:
        e, o = [], []
        for num in nums:
            if num % 2 == 0:
                e.append(num)
            else:
                o.append(num)
        result = []
        for i in range(len(e)):
            result.extend([e[i], o[i]])
        return result

