class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        if len(nums) <= 2:
            return True

        for i in range(1, len(nums)):
            if nums[i-1] + nums[i] >= m:
                return self.canSplitArray(nums[:i], m) and self.canSplitArray(nums[i:], m)

        return False

