class Solution:
    def survivedRobotsHealths(self, positions: List[int], healths: List[int], directions: str) -> List[int]:
        robots = sorted(zip(positions, healths, directions, range(len(positions))), key=lambda x: x[0])
        stack = []

        for pos, health, dir, idx in robots:
            if dir == 'R':
                stack.append((health, idx))
            else:
                while stack and health > 0:
                    top_health, top_idx = stack[-1]
                    if top_health < health:
                        stack.pop()
                        health -= 1
                    elif top_health == health:
                        stack.pop()
                        health = 0
                    else:
                        stack[-1] = (top_health - 1, top_idx)
                        health = 0

        result = [0] * len(positions)
        for health, idx in stack:
            result[idx] = health

        return [h for h in result if h > 0]

