class Solution:
    def maxIntersectionCount(self, y: List[int]) -> int:
        events = defaultdict(int)

        for i in range(1, len(y)):
            if y[i] > y[i - 1]:
                events[y[i - 1]] += 1
                events[y[i]] -= 1
            else:
                events[y[i]] += 1
                events[y[i - 1]] -= 1

        current_intersections = 0
        max_intersections = 0

        for _, change in sorted(events.items()):
            current_intersections += change
            max_intersections = max(max_intersections, current_intersections)

        return max_intersections

class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        if sum(colsum) != upper + lower:
            return []

        result = [[0, 0] for _ in range(len(colsum))]

        for i, c in enumerate(colsum):
            if c == 2:
                result[i][0] = 1
                result[i][1] = 1
                upper -= 1
                lower -= 1
            elif c == 1:
                if upper > lower:
                    result[i][0] = 1
                    upper -= 1
                else:
                    result[i][1] = 1
                    lower -= 1

        if upper != 0 or lower != 0:
            return []

        return result

class Solution:
    def countSpecialSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        MOD = 10**9 + 7

        dp = [[0] * 3 for _ in range(n + 1)]
        dp[0][0] = 1  # Base case: there's one way to have an empty sequence

        for i in range(1, n + 1):
            if nums[i - 1] == 0:
                dp[i][0] = (dp[i][0] + dp[i - 1][1]) % MOD
            elif nums[i - 1] == 1:
                dp[i][0] = (dp[i][0] + dp[i - 1][2]) % MOD
            elif nums[i - 1] == 2:
                dp[i][0] = (dp[i][0] + dp[i - 1][0]) % MOD

        for i in range(1, n + 1):
            if nums[i - 1] == 0:
                dp[i][1] = (dp[i][1] + dp[i - 1][0]) % MOD
            elif nums[i - 1] == 1:
                dp[i][1] = (dp[i][1] + dp[i - 1][2]) % MOD
            elif nums[i - 1] == 2:
                dp[i][1] = (dp[i][1] + dp[i - 1][1]) % MOD

        for i in range(1, n + 1):
            if nums[i - 1] == 0:
                dp[i][2] = (dp[i][2] + dp[i - 1][1]) % MOD
            elif nums[i - 1] == 1:
                dp[i][2] = (dp[i][2] + dp[i - 1][0]) % MOD
            elif nums[i - 1] == 2:
                dp[i][2] = (dp[i][2] + dp[i - 1][2]) % MOD

        return sum(dp[n]) % MOD

class Solution:
    def numberOfGoodSubarraySplits(self, nums: List[int]) -> int:
        n = len(nums)
        cnt = Counter(nums)
        ans = 0
        for k, v in cnt.items():
            if v == 1:
                ans += 1
                continue
            if cnt[k - 1] == 1:
                ans += v
                continue
            if cnt[k - 2] == 1:
                ans += v
                continue
            ans = 0
            break
        return ans % (10 ** 9 + 7)

class Solution:
    def isValid(self, code: str) -> bool:
        stack = []
        i, n = 0, len(code)

        while i < n:
            if code[i] == '<':
                if i == n - 1:
                    return False
                if code[i + 1] == '/':  # End tag
                    j = code.find('>', i)
                    if j == -1:
                        return False
                    tag_name = code[i + 2:j]
                    if not stack or stack.pop() != tag_name:
                        return False
                    if not stack and j != n - 1:
                        return False
                    i = j + 1
                elif code[i + 1] == '!':  # CDATA
                    if not stack:
                        return False
                    cdata_start = code.find('[CDATA[', i)
                    if cdata_start != i + 2:
                        return False
                    cdata_end = code.find(']]>', cdata_start)
                    if cdata_end == -1:
                        return False
                    i = cdata_end + 3
                else:  # Start tag
                    j = code.find('>', i)
                    if j == -1:
                        return False
                    tag_name = code[i + 1:j]
                    if not (1 <= len(tag_name) <= 9) or not all(c.isupper() for c in tag_name):
                        return False
                    stack.append(tag_name)
                    i = j + 1
            else:
                i += 1

        return not stack

