class Solution:
    def stoneGameVI(self, aliceValues: List[int], bobValues: List[int]) -> int:
        # Sort the indices of stones based on the sum of their values
        indices = sorted(range(len(aliceValues)), key=lambda i: aliceValues[i] + bobValues[i])

        total_points = 0
        for i in range(0, len(indices), 2):
            total_points += aliceValues[indices[i]]

        for i in range(1, len(indices), 2):
            total_points -= bobValues[indices[i]]

        if total_points > 0:
            return 1
        elif total_points < 0:
            return -1
        else:
            return 0

class Solution:
    def primePalindrome(self, n: int) -> int:
        def is_prime(num):
            if num < 2:
                return False
            if num == 2:
                return True
            if num % 2 == 0:
                return False
            for i in range(3, int(num**0.5) + 1, 2):
                if num % i == 0:
                    return False
            return True

        def is_palindrome(num):
            return str(num) == str(num)[::-1]

        if n <= 2:
            return 2

        while True:
            if n % 2 == 0:
                n += 1
                continue
            if is_palindrome(n) and is_prime(n):
                return n
            n += 2

            # Skip even length numbers except 2
            if 10**7 < n < 10**8:
                n = 10**8
            elif 10**5 < n < 10**6:
                n = 10**6
            elif 10**3 < n < 10**4:
                n = 10**4
            elif 10 < n < 100:
                n = 100

