class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        max1, max2 = nums1[-1], nums2[-1]

        # Check if it's impossible to satisfy the conditions
        for i in range(n - 1):
            if nums1[i] > max1 and nums2[i] > max1:
                return -1
            if nums1[i] > max2 and nums2[i] > max2:
                return -1

        # Calculate the minimum operations needed
        swap_count1 = 0
        swap_count2 = 1

        for i in range(n - 1):
            if nums1[i] > max1 or nums2[i] > max1:
                swap_count1 += 1
            if nums1[i] > max2 or nums2[i] > max2:
                swap_count2 += 1

        return min(swap_count1, swap_count2)

