class Solution:
    def garbageCollection(self, garbage: List[str], travel: List[int]) -> int:
        # Calculate the time taken to collect all garbage
        collection_time = sum(len(g) for g in garbage)

        # Calculate the travel time for each type of garbage truck
        last_seen = {char: i for i, house in enumerate(garbage) for char in house}

        travel_time = 0
        prefix_sum = [0] + list(accumulate(travel))

        for char in 'MPG':
            if char in last_seen:
                travel_time += prefix_sum[last_seen[char]]

        return collection_time + travel_time

class Solution:
    def numberOfSpecialChars(self, word: str) -> int:
        seen_lower = set()
        seen_upper = set()
        special_count = 0

        for char in word:
            if char.islower():
                seen_lower.add(char)
            else:
                lower_char = char.lower()
                if lower_char in seen_lower and lower_char not in seen_upper:
                    special_count += 1
                    seen_upper.add(lower_char)

        return special_count

class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        n = len(grid)
        if n < 4:
            return n * n

        # Create a 2D list to represent the grid
        grid = [[char for char in row] for row in grid]

        # Initialize the visited set
        visited = set()

        # Iterate over each cell in the grid
        for i in range(n):
            for j in range(n):
                # If the current cell is a '/'
                    if grid[i][j] == '/':
                        # Check the top-left cell
                        if (i > 0 and grid[i - 1][j] == ' ') or (i > 0 and grid[i - 1][j] == '/') or (i > 0 and grid[i - 1][j] == '\\\\\\\\'):
                            continue
                        # Check the top-right cell
                        if (i < n - 1 and grid[i + 1][j] == ' ') or (i < n - 1 and grid[i + 1][j] == '/') or (i < n - 1 and grid[i + 1][j] == '\\\\\\\\'):
                            continue
                        # Check the bottom-left cell
                        if (j > 0 and grid[i][j - 1] == ' ') or (j > 0 and grid[i][j - 1] == '/') or (j > 0 and grid[i][j - 1] == '\\\\\\\\'):
                            continue
                        # Check the bottom-right cell
                        if (j < n - 1 and grid[i][j + 1] == ' ') or (j < n - 1 and grid[i][j + 1] == '/') or (j < n - 1 and grid[i][j + 1] == '\\\\\\\\'):
                            continue
                        # Mark the cell as visited
                        visited.add((i, j))

                        # Explore all possible directions
                        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
                        for dx, dy in directions:
                            nx, ny = i + dx, j + dy
                            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                                visited.add((nx, ny))

        # Return the number of regions
        return len(visited)

