class Solution:
    def check(self, nums: List[int]) -> bool:
        n = len(nums)
        if n < 2:
            return True

        # Find the pivot point where the array is rotated
        pivot = -1
        for i in range(1, n):
            if nums[i] < nums[i-1]:
                pivot = i
                break

        # If there's no pivot, the array is already sorted
        if pivot == -1:
            return True

        # Check if the array is sorted before and after the pivot
        return nums[:pivot] == sorted(nums[:pivot]) and nums[pivot:] == sorted(nums[pivot:])

