class Solution:
    def isBipartite(self, graph: List[List[int]]) -> bool:
        n = len(graph)
        color = [0] * n  # Initialize color array to keep track of the color of each node

        for i in range(n):
            if color[i] != 0:
                continue  # Skip already colored nodes

            queue = collections.deque([i])  # Use a queue to perform BFS
            while queue:
                node = queue.popleft()
                color[node] = 1  # Mark the current node as visited
                for neighbor in graph[node]:
                    if color[neighbor] == 0:
                        queue.append(neighbor)  # Add unvisited neighbor to the queue
                        color[neighbor] = 2 - color[node]  # Change color of the neighbor

        return all(color[i] == color[j] for i in range(n) for j in range(n) if color[i] == color[j])

