from collections import defaultdict, deque

class Solution:
    def collectTheCoins(self, coins: List[int], edges: List[List[int]]) -> int:
        n = len(coins)
        graph = defaultdict(list)

        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # First pass: remove leaves without coins
        queue = deque([i for i in range(n) if len(graph[i]) == 1 and coins[i] == 0])
        while queue:
            leaf = queue.popleft()
            for neighbor in graph[leaf]:
                graph[neighbor].remove(leaf)
                if len(graph[neighbor]) == 1 and coins[neighbor] == 0:
                    queue.append(neighbor)
            del graph[leaf]

        # Second pass: remove leaves again (up to 2 levels deep)
        for _ in range(2):
            queue = deque([i for i in graph if len(graph[i]) == 1])
            while queue:
                leaf = queue.popleft()
                for neighbor in graph[leaf]:
                    graph[neighbor].remove(leaf)
                del graph[leaf]

        # The remaining graph is the part we need to traverse
        return max(0, 2 * (len(graph) - 1))

class Solution:
    def maximumOddBinaryNumber(self, s: str) -> str:
        # Convert the input string to a list of characters
        bits = list(s)

        # Find the index of the first '1'
        i = bits.index('1')

        # If there is no '1', return the entire string as is
        if i == -1:
            return ''.join(bits)

        # Create a new list to store the bits with '1' at the end
        result = bits[:]

        # Reverse the list to ensure the first '1' is at the end
        result.reverse()

        # Add '1's to the start of the list until the first '1' is at the end
        while i > 0:
            result.insert(0, '1')
            i -= 1

        # Join the list into a string and return it
        return ''.join(result)

