class Solution:
    def isConvex(self, points: List[List[int]]) -> bool:
        # Check if the polygon is convex
        if len(points) < 3:
            return True

        # Create a list of points for comparison
        points = [points[0], points[1], points[-1]]

        # Check if the polygon is convex by comparing each pair of consecutive points
        for i in range(len(points) - 2):
            if (points[i][1] - points[i + 1][1]) * (points[i + 1][0] - points[i][0]) > (points[i + 1][1] - points[i][1]) * (points[i][0] - points[i + 2][0]):
                return False

        return True

from functools import lru_cache

class Solution:
    @lru_cache(None)
    def countTexts(self, pressedKeys: str) -> int:
        if len(pressedKeys) == 0:
            return 1

        # Count the frequency of each digit
        freq = {}
        for char in pressedKeys:
            if char in freq:
                freq[char] += 1
            else:
                freq[char] = 1

        MOD = 10**9 + 7

        # Calculate the number of ways to form strings of length 1 to n
        dp = [0] * (len(pressedKeys) + 1)
        dp[0] = 1

        for i in range(1, len(pressedKeys) + 1):
            # Single character
            dp[i] = dp[i-1]

            # Two characters
            if i >= 2 and pressedKeys[i-1] == pressedKeys[i-2]:
                dp[i] = (dp[i] + dp[i-2]) % MOD

            # Three characters
            if i >= 3 and (pressedKeys[i-1] == pressedKeys[i-2] == pressedKeys[i-3] or pressedKeys[i-1] == '7' or pressedKeys[i-1] == '9'):
                dp[i] = (dp[i] + dp[i-3]) % MOD

            # Four characters
            if i >= 4 and (pressedKeys[i-1] == pressedKeys[i-2] == pressedKeys[i-3] == pressedKeys[i-4] or pressedKeys[i-1] == '7' or pressedKeys[i-1] == '9'):
                dp[i] = (dp[i] + dp[i-4]) % MOD

        return dp[len(pressedKeys)]

