class Solution:
    def isAlienSorted(self, words: List[str], order: str) -> bool:
        # Create a mapping from each character to its index in the order
        char_to_index = {char: i for i, char in enumerate(order)}

        # Iterate through each pair of consecutive words
        for i in range(len(words) - 1):
            word1 = words[i]
            word2 = words[i + 1]

            # Compare the characters of the two words
            for j in range(min(len(word1), len(word2))):
                if word1[j] != word2[j]:
                    # If the characters at the current position differ,
                    # check if the character in the first word comes before the character in the second word
                    if char_to_index[word1[j]] < char_to_index[word2[j]]:
                        break
                    else:
                        # If the character in the first word does not come before the character in the second word,
                        # return False
                        return False

            # If we reach the end of one word but not the other,
            # check if the longer word is lexicographically smaller
            if len(word1) > len(word2):
                return False

        # If all words are sorted lexicographically, return True
        return True

class Solution:
    def lengthOfLongestSubstringKDistinct(self, s: str, k: int) -> int:
        # Initialize a dictionary to store character counts and their indices
        char_count = {}
        max_length = 0
        left = 0

        for right, char in enumerate(s):
            # If the character count exceeds k, remove characters from the left until it's less than k
            while len(char_count) > k:
                char_count[s[left]] = char_count.pop(s[left])
                left += 1

            # Update the maximum length found so far
            max_length = max(max_length, right - left + 1)

        return max_length

class Solution:
    def minimumTime(self, nums1: List[int], nums2: List[int], x: int) -> int:
        n = len(nums1)
        total = sum(nums1) + sum(nums2) * n
        if total <= x:
            return n

        dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(i + 1):
                dp[i][j] = min(dp[i][j], dp[i - 1][j])
                dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + i * nums2[i - 1] + nums1[i - 1])

        for j in range(n + 1):
            if dp[n][j] <= x:
                return j

        return -1

class Solution:
    def kConcatenationMaxSum(self, arr: List[int], k: int) -> int:
        n = len(arr)
        total_sum = sum(arr)
        max_sum = max(0, total_sum)
        max_single = max(max(arr), -min(arr))

        if k == 1:
            return max_single

        # Calculate max sum for k = 2
        max_sum_2 = max_sum + total_sum * (k - 2)

        # If max sum for k = 2 is negative, return max single element
        if max_sum_2 < 0:
            return max_single

        # Calculate max sum for k > 2
        max_sum_k = max(max_sum, max_sum_2, max_sum + total_sum * (k - 1))

        return max_sum_k % (10**9 + 7)

