class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        max_sum = float('-inf')
        left = 0
        for right in range(len(nums)):
            while left < right and abs(nums[right] - nums[left]) != k:
                left += 1
            if abs(nums[right] - nums[left]) == k:
                max_sum = max(max_sum, nums[right])
        return max_sum

