class Solution:
    def sumEvenGrandparent(self, root: Optional[TreeNode]) -> int:
        self.res = 0

        def dfs(node, parent, grandparent):
            if not node:
                return

            if grandparent and grandparent.val % 2 == 0:
                self.res += node.val

            dfs(node.left, node, parent)
            dfs(node.right, node, parent)

        dfs(root, None, None)
        return self.res

