class Solution:
    def countGoodNumbers(self, n: int) -> int:
        MOD = 10**9 + 7

        # Helper function to calculate (base^exponent) % MOD using recursion
        def power(base, exponent):
            if exponent == 0:
                return 1
            elif exponent % 2 == 0:
                half_power = power(base, exponent // 2)
                return (half_power * half_power) % MOD
            else:
                return (base * power(base, exponent - 1)) % MOD

        # Calculate the number of good digit strings
        if n % 2 == 0:
            return (power(5, n // 2) * power(4, n // 2)) % MOD
        else:
            return (power(5, (n - 1) // 2) * power(4, (n + 1) // 2)) % MOD

class Solution:
    def isValidSudoku(self, board: List[List[str]]) -> bool:
        # Check rows
        for i in range(9):
            row = set(board[i])
            if len(row) != 9 or len(set(row)) != 9:
                return False

        # Check columns
        for j in range(9):
            col = set()
            for i in range(9):
                col.add(board[i][j])
            if len(col) != 9 or len(set(col)) != 9:
                return False

        # Check 3x3 sub-boxes
        for i in range(0, 9, 3):
            for j in range(0, 9, 3):
                sub_box = set()
                for k in range(i, i+3):
                    for l in range(j, j+3):
                        sub_box.add(board[k][l])
                if len(sub_box) != 9 or len(set(sub_box)) != 9:
                    return False

        return True

