import itertools

class Solution:
    def minimumTimeRequired(self, jobs: List[int], k: int) -> int:
        def canFinish(jobs, k, limit):
            groups = [0] * k
            for job in jobs:
                placed = False
                for i in range(k):
                    if groups[i] + job <= limit:
                        groups[i] += job
                        placed = True
                        break
                if not placed:
                    return False
            return True

        jobs.sort(reverse=True)
        left, right = max(jobs), sum(jobs)
        while left < right:
            mid = (left + right) // 2
            if canFinish(jobs, k, mid):
                right = mid
            else:
                left = mid + 1
        return left

from collections import defaultdict

class Solution:
    def rootCount(self, edges: List[List[int]], guesses: List[List[int]], k: int) -> int:
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        guess_set = set((u, v) for u, v in guesses)

        def dfs(node, parent):
            count = 0
            for neighbor in graph[node]:
                if neighbor == parent:
                    continue
                if (node, neighbor) in guess_set:
                    count += 1
                count += dfs(neighbor, node)
            return count

        initial_count = dfs(0, -1)

        def count_valid_roots(node, parent, current_count):
            nonlocal valid_roots
            if current_count >= k:
                valid_roots += 1
            for neighbor in graph[node]:
                if neighbor == parent:
                    continue
                next_count = current_count + (-(1 if (parent, neighbor) in guess_set else 0)) + ((1 if (node, neighbor) in guess_set else 0))
                count_valid_roots(neighbor, node, next_count)

        valid_roots = 0
        count_valid_roots(0, -1, initial_count)

        return valid_roots

class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        # Create a list of tuples where each tuple contains the count of set bits and the corresponding number
        bit_count_pairs = [(bin(num).count('1'), num) for num in nums]

        # Sort the list based on the count of set bits
        bit_count_pairs.sort()

        # Check if the sorted list is equal to the original list
        return bit_count_pairs == sorted(nums)

