class Solution:
    def findRestaurant(self, list1: List[str], list2: List[str]) -> List[str]:
        # Create a dictionary to store the indices of list1
        index_map = {restaurant: i for i, restaurant in enumerate(list1)}

        # Initialize variables to track the minimum index sum and the result list
        min_index_sum = float('inf')
        result = []

        # Iterate through list2 to find common restaurants
        for j, restaurant in enumerate(list2):
            if restaurant in index_map:
                index_sum = index_map[restaurant] + j
                if index_sum < min_index_sum:
                    min_index_sum = index_sum
                    result = [restaurant]
                elif index_sum == min_index_sum:
                    result.append(restaurant)

        return result

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        flips = 0

        # Check rows
        for i in range(m):
            row = grid[i]
            for j in range(n // 2):
                if row[j] != row[n - 1 - j]:
                    flips += 1
                    row[n - 1 - j] = row[j]

        # Check columns
        for j in range(n):
            col_sum = sum(grid[i][j] for i in range(m))
            if col_sum % 2 != 0:
                flips += 1
                for i in range(m):
                    grid[i][j] = 1 - grid[i][j]

        # Ensure total number of 1's is divisible by 4
        total_ones = sum(sum(row) for row in grid)
        if total_ones % 4 != 0:
            flips += 4 - (total_ones % 4)

        return flips

