                min_len = min(min_len, j - i)
            j += 1

        return min_len

import heapq

class Solution:
    def minimumVisitedCells(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        if grid[0][0] >= n - 1 and grid[0][0] >= m - 1:
            return 2

        right = [collections.deque() for _ in range(n)]
        down = [collections.deque() for _ in range(m)]

        heap = [(2, 0, 0)]
        visited = set()

        while heap:
            steps, i, j = heapq.heappop(heap)

            if (i, j) in visited:
                continue

            visited.add((i, j))

            if i == m - 1 and j == n - 1:
                return steps

            for k in range(j + 1, min(n, j + grid[i][j] + 1)):
                if (i, k) not in visited:
                    heapq.heappush(heap, (steps + 1, i, k))
                    right[k].append((i, k))

            for k in range(i + 1, min(m, i + grid[i][j] + 1)):
                if (k, j) not in visited:
                    heapq.heappush(heap, (steps + 1, k, j))
                    down[k].append((k, j))

        return -1

