class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        dp = defaultdict(int)
        for num in nums:
            remainder = num % k
            if remainder not in dp:
                dp[remainder] = 1
            else:
                dp[(remainder + k) % k] = max(dp[(remainder + k) % k], dp[remainder] + 1)
        return max(dp.values())

