        res = set()
        for num in nums1:
            if num in nums2 or num in nums3:
                res.add(num)
        for num in nums2:
            if num in nums1 or num in nums3:
                res.add(num)
        for num in nums3:
            if num in nums1 or num in nums2:
                res.add(num)
        return list(res)

