class Solution:
    def camelMatch(self, queries: List[str], pattern: str) -> List[bool]:
        def matches(query, pattern):
            p_index = 0
            for char in query:
                if p_index < len(pattern) and char == pattern[p_index]:
                    p_index += 1
                elif char.isupper():
                    return False
            return p_index == len(pattern)

        return [matches(query, pattern) for query in queries]

