        return ''.join(stack)

class Solution:
    def leftmostBuildingQueries(self, heights: List[int], queries: List[List[int]]) -> List[int]:
        n = len(heights)
        stack = []
        res = [-1] * len(queries)

        for i in range(n):
            while stack and heights[stack[-1]] <= heights[i]:
                stack.pop()

            if stack and heights[stack[-1]] > heights[i]:
                res[queries[i][0]] = stack[-1]

            stack.append(i)

        return res

