class Solution:
    def sumOfFlooredPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        max_num = max(nums)
        count = [0] * (max_num + 1)

        # Count the occurrences of each number
        for num in nums:
            count[num] += 1

        # Accumulate counts
        for i in range(1, max_num + 1):
            count[i] += count[i - 1]

        result = 0
        for num in nums:
            for multiple in range(num, max_num + 1, num):
                end = min(multiple + num - 1, max_num)
                result += (count[end] - count[multiple - 1])
                result %= MOD

        return result

class Solution:
    def lengthOfLIS(self, nums: List[int], k: int) -> int:
        # Initialize a list to store the length of LIS ending at each index
        lis = [1] * len(nums)

        # Iterate through the array starting from the second element
        for i in range(1, len(nums)):
            # Find the maximum length of LIS ending at the previous index
            for j in range(i):
                if nums[j] < nums[i]:
                    # If the current element is greater than the previous element and the difference between the two elements is less than or equal to k, update the LIS length
                    lis[i] = max(lis[i], lis[j] + 1)

        # Return the maximum length of LIS found
        return max(lis)

class Solution:
    def countPyramids(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        ans = 0

        # Count pyramids
        for r in range(1, m):
            for c in range(1, n - 1):
                if grid[r][c]:
                    grid[r][c] = min(grid[r-1][c-1], grid[r-1][c], grid[r-1][c+1]) + 1
                    ans += grid[r][c] - 1

        # Count inverse pyramids
        for r in range(m - 2, -1, -1):
            for c in range(1, n - 1):
                if grid[r][c]:
                    grid[r][c] = min(grid[r+1][c-1], grid[r+1][c], grid[r+1][c+1]) + 1
                    ans += grid[r][c] - 1

        return ans

