class Solution:
    def largestEvenSum(self, nums: List[int], k: int) -> int:
        # Sort the array in descending order
        nums.sort(reverse=True)

        # Initialize the sum of the largest k elements
        max_sum = sum(nums[:k])

        # Check if the sum is already even
        if max_sum % 2 == 0:
            return max_sum

        # Try to replace the smallest odd number with the largest even number
        for i in range(k):
            if nums[i] % 2 != 0:
                for j in range(i+1, k):
                    if nums[j] % 2 == 0:
                        # Replace the smallest odd number with the largest even number
                        max_sum -= nums[i]
                        max_sum += nums[j]
                        break
                else:
                    # If no even number is found, return -1
                    return -1

        return max_sum

class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        # Create a dictionary to store the frequency of characters in s1
        char_count = {}
        for char in s1:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

        # Initialize a counter for the current window
        window_count = {}
        for i in range(len(s1)):
            char = s2[i]
            if char in window_count:
                window_count[char] += 1
            else:
                window_count[char] = 1

        # Check if the current window has the same frequency as s1
        if window_count == char_count:
            return True

        # Slide the window across s2
        for i in range(len(s1), len(s2)):
            # Add the new character to the window
            char = s2[i]
            if char in window_count:
                window_count[char] += 1
            else:
                window_count[char] = 1

            # Remove the character that is no longer in the window
            char_to_remove = s2[i - len(s1)]
            if char_to_remove in window_count:
                window_count[char_to_remove] -= 1
            else:
                window_count[char_to_remove] = 0

            # Check if the current window has the same frequency as s1
            if window_count == char_count:
                return True

        return False

class Solution:
    def maxA(self, n: int) -> int:
        if n <= 6:
            return n

        dp = [i for i in range(n + 1)]
        for i in range(7, n + 1):
            dp[i] = 2 * dp[i - 3]

        return dp[n]

class Solution:
    def calculateMinimumHP(self, dungeon: List[List[int]]) -> int:
        m = len(dungeon)
        n = len(dungeon[0])
        dp = [[float('inf')] * n for _ in range(m)]
        dp[0][0] = max(1, dungeon[0][0])
        for i in range(1, m):
            dp[i][0] = max(dp[i-1][0], dp[i][0])
        for j in range(1, n):
            dp[0][j] = max(dp[0][j-1], dp[0][j])
        for i in range(1, m):
            for j in range(1, n):
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) - dungeon[i][j]
        return max(1, dp[m-1][n-1])

class Solution:
    def findGoodStrings(self, n: int, s1: str, s2: str, evil: str) -> int:
