        dp = [[0] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 1

        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if s1[i - 1] <= s2[j - 1] and s1[i - 1] >= s2[j]:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD

        return dp[n][n]

