        max_len = 0
        left = 0
        for right in range(len(nums)):
            while right - left + 1 > k:
                if nums[left] != nums[right]:
                    max_len = max(max_len, right - left + 1)
                left += 1
        return nums[left:right+1]

class Solution:
    def numberOfPatterns(self, m: int, n: int) -> int:
        def dfs(visited, i, remain):
            if remain == 0:
                return 1
            visited[i] = True
            total = 0
            for j in range(1, 10):
                if not visited[j]:
                    mid = (i + j) // 2
                    if (i % 3 != j % 3 and i // 3 != j // 3) or visited[mid]:
                        total += dfs(visited[:], j, remain - 1)
            visited[i] = False
            return total

        total_patterns = 0
        for length in range(m, n + 1):
            total_patterns += dfs([False] * 10, 1, length - 1) * 4  # Patterns starting with 1, 3, 7, 9
            total_patterns += dfs([False] * 10, 2, length - 1) * 4  # Patterns starting with 2, 4, 6, 8
            total_patterns += dfs([False] * 10, 5, length - 1)      # Patterns starting with 5
        return total_patterns

