class Solution:
    def maximumValueSum(self, nums: List[int], k: int, edges: List[List[int]]) -> int:
        total_sum = 0
        odd_xor_diff = float('inf')
        xor_count = 0

        for num in nums:
            xor_value = num ^ k
            if xor_value > num:
                total_sum += xor_value
                if (xor_value - num) % 2 == 1:
                    xor_count += 1
            else:
                total_sum += num
                if (num - xor_value) % 2 == 1:
                    odd_xor_diff = min(odd_xor_diff, abs(num - xor_value))

        if xor_count % 2 == 1:
            total_sum -= odd_xor_diff

        return total_sum

