class Solution:
    def countSubstrings(self, s: str, t: str) -> int:
        n, m = len(s), len(t)
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        ans = 0

        # Initialize the first row
        for i in range(m + 1):
            if s[0] == t[i - 1]:
                dp[0][i] = 1

        # Fill the DP table
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if s[i - 1] == t[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = dp[i - 1][j]

        # Calculate the total number of valid substrings
        for i in range(n + 1):
            for j in range(m + 1):
                ans += dp[i][j]

        return ans

