        return list((count1 & count2).elements())

class Solution:
    def minCostSetTime(self, startAt: int, moveCost: int, pushCost: int, targetSeconds: int) -> int:
        def calculate_cost(digits, startAt):
            cost = 0
            current_digit = str(startAt)
            for digit in digits:
                if digit != current_digit:
                    cost += moveCost
                    current_digit = digit
                cost += pushCost
            return cost

        def get_times(targetSeconds):
            times = []
            if targetSeconds < 100:
                times.append(f"{targetSeconds:02d}")
            if targetSeconds >= 60:
                minutes = targetSeconds // 60
                seconds = targetSeconds % 60
                if minutes < 100:
                    times.append(f"{minutes}{seconds:02d}")
            return times

        times = get_times(targetSeconds)
        min_cost = float('inf')
        for time in times:
            cost = calculate_cost(time, startAt)
            min_cost = min(min_cost, cost)
        return min_cost

class Solution:
    def uniqueLetterString(self, s: str) -> int:
        n = len(s)
        # Create a list of indices for each character
        char_indices = [i for i in range(n)]
        # Create a dictionary to store the count of each character
        char_count = {}
        # Create a dictionary to store the sum of unique characters for each substring
        unique_sum = {}

        # Iterate through the characters and update the counts and sums
        for i in range(n):
            char = s[i]
            if char in char_count:
                char_count[char] += 1
                unique_sum[char] += char_count[char]
            else:
                char_count[char] = 1
                unique_sum[char] = char_count[char]

        # Calculate the total sum of unique characters for all substrings
        total_unique_sum = 0
        for substring in unique_sum:
            total_unique_sum += unique_sum[substring]

        return total_unique_sum

