class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        prefix_sum = {0: -1}
        current_sum = 0

        for i, num in enumerate(nums):
            current_sum += num
            if current_sum - target in prefix_sum:
                return i - prefix_sum[current_sum - target]
            prefix_sum[current_sum] = i

        return -1

class Solution:
    def smallestValue(self, n: int) -> int:
        while True:
            factors = []
            divisor = 2
            while divisor * divisor <= n:
                if n % divisor == 0:
                    factors.append(divisor)
                    while n % divisor == 0:
                        n //= divisor
                divisor += 1
            if n > 1:
                factors.append(n)

            next_value = sum(factors)
            if next_value == n:
                return n
            else:
                n = next_value

class Solution:
    def waysToMakeFair(self, nums: List[int]) -> int:
        odd_sum, even_sum = 0, 0
        for i in range(len(nums)):
            if i % 2 == 0:
                even_sum += nums[i]
            else:
                odd_sum += nums[i]
            if odd_sum == even_sum:
                return 1
        return 0

