class Solution:
    def maxEqualFreq(self, nums: List[int]) -> int:
        freq = Counter()
        count = defaultdict(int)
        max_length = 0

        for i, num in enumerate(nums):
            # Update frequency of the current number
            freq[num] += 1
            # Update count of frequencies
            count[freq[num]] += 1
            if freq[num] > 1:
                count[freq[num] - 1] -= 1

            # Check for valid conditions
            if len(count) == 1:
                key = next(iter(count))
                if key == 1 or count[key] == 1:
                    max_length = i + 1
            elif len(count) == 2:
                keys = sorted(count.keys())
                if (keys[0] == 1 and count[keys[0]] == 1) or (keys[1] - keys[0] == 1 and count[keys[1]] == 1):
                    max_length = i + 1

        return max_length

