        # Create a mapping from characters to their indices
        char_to_index = {char: i for i, char in enumerate(order)}

        # Sort words based on the indices in the order
        sorted_words = sorted(words, key=lambda x: word_to_index[x])

        # Check if the sorted words are equal to the original words
        return sorted_words == words

