class Solution:
    def houseOfCards(self, n: int) -> int:
        dp = [0] * (n + 1)
        dp[0] = 1

        for i in range(1, n + 1):
            # If we place a triangle on the current row
            dp[i] += dp[i - 2]

            # If we place a horizontal card above the current row
            for j in range(i - 2, 0, -1):
                dp[i] += dp[j - 1]

        return dp[n]

class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        # Helper function to check if a substring is in the word
        def is_substring(sub):
            return sub in word

        # Directions for moving in the grid
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        # Check each cell in the board
        for i in range(len(board)):
            for j in range(len(board[0])):
                if board[i][j] == word[0]:
                    # Start the DFS from the current cell
                    if self.dfs(board, i, j, word, directions):
                        return True

        return False

    def dfs(self, board, i, j, word, directions):
        # If we have reached the end of the word, return True
        if len(word) == 0:
            return True

        # Try all possible moves in the current direction
        for dx, dy in directions:
            new_i, new_j = i + dx, j + dy
            # Check if the new position is within bounds and if the character is the same as the current character
            if 0 <= new_i < len(board) and 0 <= new_j < len(board[0]) and board[new_i][new_j] == word[0]:
                # Recursively call the DFS function on the new position
                if self.dfs(board, new_i, new_j, word[1:], directions):
                    return True

        # If no valid move leads to the end of the word, return False
        return False

