class Solution:
    def countVisitedNodes(self, edges: List[int]) -> List[int]:
        n = len(edges)
        visited = [False] * n
        result = [0] * n

        for i in range(n):
            if visited[i]:
                continue

            current_node = i
            cycle_length = 0
            path = []

            while not visited[current_node]:
                visited[current_node] = True
                path.append(current_node)
                current_node = edges[current_node]
                cycle_length += 1

            # If we encounter a node in the cycle again, it means we have found a cycle.
            if current_node in path:
                cycle_start = path.index(current_node)
                cycle_length -= cycle_start

                for node in path[cycle_start:]:
                    result[node] = cycle_length

            else:
                # For nodes not in the cycle, the length of the path is the number of unique nodes visited.
                result[i] = cycle_length + len(path) - cycle_start

        return result

# Definition for singly-linked list.
# class ListNode:
#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        if not lists:
            return None

        # Merge two sorted lists
        def merge(l1, l2):
            dummy = tail = ListNode()
            while l1 and l2:
                if l1.val < l2.val:
                    tail.next = l1
                    l1 = l1.next
                else:
                    tail.next = l2
                    l2 = l2.next
                tail = tail.next
            tail.next = l1 or l2
            return dummy.next

        # Merge k sorted lists using divide-and-conquer
        def mergeK(lists):
            if len(lists) == 1:
                return lists[0]
            mid = len(lists) // 2
            left = mergeK(lists[:mid])
            right = mergeK(lists[mid:])
            return merge(left, right)

        return mergeK(lists)

