# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def createBinaryTree(self, descriptions: List[List[int]]) -> Optional[TreeNode]:
        nodes = {}
        parents = set()
        children = set()

        for parent_val, child_val, is_left in descriptions:
            if parent_val not in nodes:
                nodes[parent_val] = TreeNode(parent_val)
            if child_val not in nodes:
                nodes[child_val] = TreeNode(child_val)

            if is_left:
                nodes[parent_val].left = nodes[child_val]
            else:
                nodes[parent_val].right = nodes[child_val]

            parents.add(parent_val)
            children.add(child_val)

        root_val = (parents - children).pop()
        return nodes[root_val]

class Solution:
    def printTree(self, root: Optional[TreeNode]) -> List[List[str]]:
        if not root:
            return []

        def get_height(node):
            if not node:
                return 0
            return max(get_height(node.left), get_height(node.right)) + 1

        height = get_height(root)
        width = 2**height - 1

        matrix = [["" for _ in range(width)] for _ in range(height)]

        def fill_matrix(node, r, c):
            if not node:
                return
            matrix[r][c] = str(node.val)
            fill_matrix(node.left, r + 1, c - 2**(height - r - 1))
            fill_matrix(node.right, r + 1, c + 2**(height - r - 1))

        fill_matrix(root, 0, width // 2)

        return matrix

