class Solution:
    def canSeePersonsCount(self, heights: List[int]) -> List[int]:
        n = len(heights)
        answer = [0] * n
        stack = []

        for i in range(n):
            while stack and heights[stack[-1]] < heights[i]:
                answer[stack.pop()] += 1
            if stack:
                answer[stack[-1]] += 1
            stack.append(i)

        return answer

class Solution:
    def surfaceArea(self, grid: List[List[int]]) -> int:
        if not grid:
            return 0

        n = len(grid)
        surface_area = 0

        for i in range(n):
            for j in range(n):
                if grid[i][j] > 0:
                    surface_area += 2 + 4 * grid[i][j]

                    # Check adjacent cells
                    if i > 0:
                        surface_area -= min(grid[i-1][j], grid[i][j]) * 2
                    if j > 0:
                        surface_area -= min(grid[i][j-1], grid[i][j]) * 2

        return surface_area

class Solution:
    def breakPalindrome(self, palindrome: str) -> str:
        # Convert the palindrome string to a list of characters
        chars = list(palindrome)

        # Check if the string is already a palindrome
        if chars == chars[::-1]:
            return ""

        # Find the first non-palindromic character
        for i in range(len(chars)):
            if chars[i] != chars[-i-1]:
                # Swap the character with the next one
                chars[i], chars[-i-1] = chars[-i-1], chars[i]
                # Sort the list to ensure the smallest character comes first
                chars.sort()
                # Join the list back into a string
                return ''.join(chars)

        # If no non-palindromic character is found, return an empty string
        return ""

