class Solution:
    def numberOfBoomerangs(self, points: List[List[int]]) -> int:
        ans = 0
        for i in range(len(points)):
            dist_dict = defaultdict(int)
            for j in range(len(points)):
                if i != j:
                    x1, y1 = points[i]
                    x2, y2 = points[j]
                    d = (x1 - x2)**2 + (y1 - y2)**2
                    dist_dict[d] += 1
            for val in dist_dict.values():
                ans += val * (val - 1)
        return ans

