class Solution:
    def maximumProcessableQueries(self, nums: List[int], queries: List[int]) -> int:
        n = len(nums)
        m = len(queries)

        # Create prefix and suffix max arrays
        prefix_max = [0] * (n + 1)
        suffix_max = [0] * (n + 1)

        for i in range(n):
            prefix_max[i + 1] = max(prefix_max[i], nums[i])

        for i in range(n - 1, -1, -1):
            suffix_max[i] = max(suffix_max[i + 1], nums[i])

        # Binary search to find the first query that cannot be processed
        left, right = 0, m
        while left < right:
            mid = (left + right + 1) // 2
            if prefix_max[mid] >= queries[mid - 1] and suffix_max[n - mid + 1] >= queries[mid - 1]:
                left = mid
            else:
                right = mid - 1

        return left

