class Solution:
    def sumGame(self, num: str) -> bool:
        n = len(num)
        left_sum = 0
        left_count = 0
        right_sum = 0
        right_count = 0

        # Calculate the sum and count of '?' on both halves
        for i in range(n // 2):
            if num[i] == '?':
                left_count += 1
            else:
                left_sum += int(num[i])

        for i in range(n // 2, n):
            if num[i] == '?':
                right_count += 1
            else:
                right_sum += int(num[i])

        # Determine the total number of '?' to be filled
        total_ones = left_count + right_count

        # Calculate the difference in the sums of the two halves
        sum_diff = abs(left_sum - right_sum)

        # If the total number of '?' is odd, Bob can always win by filling the last '?' with a value that makes the sums equal
        if total_ones % 2 == 1:
            return True

        # If the total number of '?' is even and the difference in sums is odd, Bob can always win by filling the last '?' to balance the sums
        if sum_diff % 2 == 1:
            return True

        # If the total number of '?' is even and the difference in sums is even, Alice can win if she can fill the '?' in such a way that the sums remain unequal
        if sum_diff % 2 == 0:
            return False

