class Solution:
    def binarySearchableNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Find the maximum value to the left of each index
        max_left = [float('-inf')] * n
        for i in range(1, n):
            max_left[i] = max(max_left[i-1], nums[i-1])

        # Find the minimum value to the right of each index
        min_right = [float('inf')] * n
        for i in range(n-2, -1, -1):
            min_right[i] = min(min_right[i+1], nums[i+1])

        # Count the numbers that are guaranteed to be found
        count = 0
        for i in range(n):
            if max_left[i] < nums[i] < min_right[i]:
                count += 1

        return count

class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        # Initialize the maximum score to the first element of the first row
        max_score = grid[0][0]

        # Iterate through each row in the grid
        for i in range(1, len(grid)):
            # Update the maximum score if the current row's score is greater
            max_score = max(max_score, grid[i][0] - grid[i - 1][0])

        # Iterate through each column in the grid
        for j in range(1, len(grid[0])):
            # Update the maximum score if the current column's score is greater
            max_score = max(max_score, grid[0][j] - grid[0][j - 1])

        return max_score

