class Solution:
    def minOperations(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return 0

        # Check if it's possible to reduce all numbers to 1
        if not all(num > 1 for num in nums):
            return -1

        # Reduce the array to its GCD
        current_gcd = nums[0]
        for num in nums[1:]:
            current_gcd = gcd(current_gcd, num)
            if current_gcd == 1:
                break

        # If GCD is still greater than 1, it's impossible to reduce all numbers to 1
        if current_gcd > 1:
            return -1

        # Count the number of operations needed
        operations = 0
        for num in nums:
            operations += num - 1

        return operations

class Solution:
    def groupStrings(self, strings: List[str]) -> List[List[str]]:
        # Dictionary to store the list of strings with the same shifting pattern
        groups = defaultdict(list)

        for s in strings:
            # Calculate the difference between each consecutive character in the string
            diff = [ord(s[j]) - ord(s[j-1]) for j in range(1, len(s))]

            # Group the strings based on their difference vector
            groups[tuple(diff)].append(s)

        return list(groups.values())

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 10**9 + 7
        R, C = len(pizza), len(pizza[0])

        # Function to count apples in a sub-pizza
        def count_apples(r, c):
            count = 0
            for i in range(r, R):
                for j in range(c, C):
                    if pizza[i][j] == 'A':
                        count += 1
            return count

        # Initialize dp table
        dp = [[[0] * (k + 1) for _ in range(C)] for _ in range(R)]

        # Fill dp table from bottom-right to top-left
        for r in range(R - 1, -1, -1):
            for c in range(C - 1, -1, -1):
                if count_apples(r, c) > 0:
                    dp[r][c][1] = 1

        # Fill dp table for multiple pieces
        for i in range(2, k + 1):
            for r in range(R):
                for c in range(C):
                    if count_apples(r, c) > 0:
                        for nr in range(r + 1, R):
                            if count_apples(r, c) - count_apples(nr, c) > 0:
                                dp[r][c][i] = (dp[r][c][i] + dp[nr][c][i - 1]) % MOD
                        for nc in range(c + 1, C):
                            if count_apples(r, c) - count_apples(r, nc) > 0:
                                dp[r][c][i] = (dp[r][c][i] + dp[r][nc][i - 1]) % MOD

        return dp[0][0][k]

