import bisect

class Solution:
    def maximumTastiness(self, price: List[int], k: int) -> int:
        price.sort()
        left, right = 0, price[-1] - price[0]

        while left < right:
            mid = (left + right) // 2
            if self.can_form_baskets(price, k, mid):
                left = mid + 1
            else:
                right = mid

        return left - 1

    def can_form_baskets(self, price, k, target):
        prev_price = price[0]
        count = 1

        for i in range(1, len(price)):
            if price[i] - prev_price >= target:
                count += 1
                prev_price = price[i]

        return count >= k

