class Solution:
    def sequentialDigits(self, low: int, high: int) -> List[int]:
        result = []
        for start in range(1, 10):
            num = 0
            for next_digit in range(start, 10):
                num = num * 10 + next_digit
                if low <= num <= high:
                    result.append(num)
        return sorted(result)

class Solution:
    def maxBoxesInWarehouse(self, boxes: List[int], warehouse: List[int]) -> int:
        boxes.sort()
        warehouse.sort(reverse=True)
        boxes_idx = 0
        warehouse_idx = len(warehouse) - 1

        res = 0
        while boxes_idx < len(boxes) and warehouse_idx >= 0:
            if boxes[boxes_idx] <= warehouse[warehouse_idx]:
                boxes_idx += 1
                warehouse_idx -= 1
                res += 1
            else:
                break

        return res

