import heapq

class Solution:
    def maximumMinimumPath(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        heap = [(grid[0][0], 0, 0)]
        visited = set()
        while heap:
            val, i, j = heapq.heappop(heap)
            if (i, j) == (m-1, n-1):
                return val
            visited.add((i, j))
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + dx, j + dy
                if 0 <= ni < m and 0 <= nj < n and (ni, nj) not in visited:
                    heapq.heappush(heap, (min(val, grid[ni][nj]), ni, nj))

class Solution:
    def maxPoints(self, points: List[List[int]]) -> int:
        m, n = len(points), len(points[0])
        dp = [[0] * n for _ in range(m)]

        # Initialize the first row
        for i in range(n):
            dp[0][i] = points[0][i]

        # Fill the DP table
        for i in range(1, m):
            for j in range(n):
                # Add points from the current row
                dp[i][j] = points[i][j] + max(dp[i-1][k] for k in range(j))

                # Subtract points from the previous row
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-1]) - abs(points[i][j] - points[i-1][j-1])

        return max(dp[-1])

class Solution:
    def maximumSetSize(self, nums1: List[int], nums2: List[int]) -> int:
        # Remove n/2 elements from nums1 and n/2 elements from nums2
        nums1 = list(set(nums1))[:len(nums1)//2]
        nums2 = list(set(nums2))[:len(nums2)//2]

        # Insert the remaining elements of nums1 and nums2 into a set s
        s = set(nums1 + nums2)

        return len(s)

