class Solution:
    def diffWaysToCompute(self, expression: str) -> List[int]:
        def compute(left, right, op):
            if op == '+':
                return left + right
            elif op == '-':
                return left - right
            else:
                return left * right

        def dfs(expression):
            if len(expression) == 1:
                return [int(expression)]

            res = []
            for i in range(len(expression)):
                if expression[i] in ['+', '-', '*']:
                    left = dfs(expression[:i])
                    right = dfs(expression[i+1:])
                    for l in left:
                        for r in right:
                            res.append(compute(l, r, expression[i]))
            return res

        return dfs(expression)

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        from collections import defaultdict
        from typing import List

        def backtrack(start):
            if start == len(s):
                return [""]
            if start in memo:
                return memo[start]

            results = []
            for word in wordDict:
                if s.startswith(word, start):
                    suffixes = backtrack(start + len(word))
                    for suffix in suffixes:
                        results.append((word + " " + suffix).strip())

            memo[start] = results
            return results

        memo = defaultdict(list)
        return backtrack(0)

class Solution:
    def shortestDistance(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        visited = set()
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        def dfs(i, j):
            if (i, j) in visited:
                return 0
            visited.add((i, j))
            min_distance = float('inf')
            for dx, dy in directions:
                nx, ny = i + dx, j + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0:
                    min_distance = min(min_distance, dfs(nx, ny) + 1)
            return min_distance

        total_distance = float('inf')
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0:
                    total_distance = min(total_distance, dfs(i, j))

        if total_distance == float('inf'):
            return -1
        else:
            return total_distance

class Solution:
