        n = len(s)
        flip = 0
        for i in range(1, n):
            if s[i-1] == s[i]:
                continue
            elif s[i-1] == '0':
                if i > 1 and s[i-2] == '1':
                    flip += 1
            else:
                if i > 1 and s[i-2] == '0':
                    flip += 1
                if i > 1 and s[i-2] == '1':
                    flip += 1
        return flip

