class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        # Step 1: Build the graph
        graph = collections.defaultdict(dict)
        for o, c, co in zip(original, changed, cost):
            if c not in graph[o]:
                graph[o][c] = co
            else:
                graph[o][c] = min(graph[o][c], co)

        # Step 2: Floyd-Warshall algorithm to find shortest paths between all pairs of nodes
        nodes = set(original).union(set(changed))
        dist = {node: {node: 0 for node in nodes} for node in nodes}

        for u in graph:
            for v in graph[u]:
                dist[u][v] = graph[u][v]

        for k in nodes:
            for i in nodes:
                for j in nodes:
                    if i in dist and k in dist[i] and j in dist[k]:
                        if j not in dist[i] or dist[i][j] > dist[i][k] + dist[k][j]:
                            dist[i][j] = dist[i][k] + dist[k][j]

        # Step 3: Dynamic programming to find the minimum cost to convert source to target
        n = len(source)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(i):
                sub_s = source[j:i]
                sub_t = target[j:i]
                if sub_s == sub_t:
                    dp[i] = min(dp[i], dp[j])
                elif sub_s in dist and sub_t in dist[sub_s]:
                    dp[i] = min(dp[i], dp[j] + dist[sub_s][sub_t])

        return dp[n] if dp[n] != float('inf') else -1

