class Solution:
    def largestVariance(self, s: str) -> int:
        if len(s) < 2:
            return 0

        # Count the frequency of each character
        char_count = Counter(s)

        max_variance = 0

        # Iterate over all pairs of unique characters
        for i in char_count:
            for j in char_count:
                if i == j:
                    continue

                # Initialize variables to keep track of the current count of characters and the maximum variance found
                cur_count_i = 0
                cur_count_j = 0
                max_variance_i = float('-inf')
                max_variance_j = float('-inf')

                # Process each character in the string
                for c in s:
                    if c == i:
                        cur_count_i += 1
                        max_variance_i = max(max_variance_i, cur_count_i - cur_count_j)
                    elif c == j:
                        cur_count_j += 1
                        max_variance_j = max(max_variance_j, cur_count_j - cur_count_i)

                    # Ensure that the count of j is always greater than or equal to the count of i
                    if cur_count_j > cur_count_i:
                        cur_count_i, cur_count_j = cur_count_j, cur_count_i

                # Update the maximum variance
                max_variance = max(max_variance, max_variance_i, max_variance_j)

        return max_variance

