class Solution:
    def threeSumMulti(self, arr: List[int], target: int) -> int:
        count = Counter(arr)
        result = 0

        for i, c1 in count.items():
            for j, c2 in count.items():
                if i == j == target - i * 2:
                    result += c1 * (c1 - 1) * (c1 - 2) // 6
                elif i == j != target - i * 2:
                    result += c1 * c2 * count[target - i * 2]
                elif i != j == target - i * 2:
                    result += c1 * count[target - i * 2] * (count[target - i * 2] - 1) // 2
                else:
                    result += c1 * c2 * count[target - i * 2]

        return result % (10**9 + 7)

