class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        n = len(nums)
        # Create a frequency map to count the occurrences of each power of 2
        freq = {}
        for num in nums:
            if num in freq:
                freq[num] += 1
            else:
                freq[num] = 1

        # Find the maximum power of 2 less than or equal to target
        max_power = 0
        for num in freq:
            if num <= target:
                max_power = max(max_power, num)

        # Check if the maximum power of 2 is greater than or equal to target
        if max_power < target:
            return -1

        # Calculate the number of operations needed to make the target sum
        operations = 0
        current_sum = 0

        for num in nums:
            if num > 1:
                # Remove the current power of 2 and add two occurrences of it
                current_sum -= num
                current_sum //= 2
                operations += 1

        return operations

