class Solution:
    def maxLength(self, ribbons: List[int], k: int) -> int:
        low, high = 1, max(ribbons)
        while low < high:
            mid = (low + high) // 2
            count = sum([ribbon // mid for ribbon in ribbons])
            if count >= k:
                low = mid + 1
            else:
                high = mid
        return low - 1

