class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        n = len(nums)
        total_sum = sum(nums)
        if n < m:
            return False

        # Check if there's at least one way to split the array into n arrays
        for i in range(n):
            if i > 0 and nums[i-1] >= m:
                continue
            if i < n-1 and nums[i+1] >= m:
                continue

            # Check if the sum of the remaining part is greater than or equal to m
            remaining_sum = total_sum - nums[i]
            if remaining_sum >= m:
                return True

        return False

