class Solution:
    def findSecondMinimumValue(self, root: Optional[TreeNode]) -> int:
        def dfs(node, min_val):
            if not node:
                return float('inf')
            if node.val > min_val:
                return node.val
            return min(dfs(node.left, min_val), dfs(node.right, min_val))

        result = dfs(root, root.val)
        return result if result != float('inf') else -1

class Solution:
    def minimumJumps(self, forbidden: List[int], a: int, b: int, x: int) -> int:
        # Initialize the number of jumps and the list of forbidden positions
        jumps = 0
        forbidden_positions = set(forbidden)

        # Iterate through the forbidden positions to mark visited positions
        for pos in forbidden_positions:
            if pos < 0:
                continue
            if pos + a > x:
                break
            if pos - b < 0:
                break

        # If the bug cannot reach x, return -1
        if pos != x:
            return -1

        # If the bug can reach x, calculate the minimum number of jumps
        while True:
            jumps += 1
            # Check if the bug has reached x
            if pos == x:
                break
            # Check if the bug can jump forward
            if pos + a > x:
                break
            # Check if the bug can jump backward
            if pos - b < 0:
                break

            # Move to the next forbidden position
            pos += a if pos + a > x else 1
            pos -= b if pos - b < 0 else 1

        return jumps

