class Solution:
    def replaceWords(self, dictionary: List[str], sentence: str) -> str:
        # Create a dictionary to map each root to its corresponding words
        root_to_words = {root: words for root, words in enumerate(dictionary)}

        # Split the sentence into words
        words = sentence.split()

        # Replace each word with its corresponding root if it exists
        result = []
        for word in words:
            if word in root_to_words:
                result.append(root_to_words[word])
            else:
                result.append(word)

        # Join the result words back into a sentence
        return ' '.join(result)

class Solution:
    def isThereAPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        dp = [[[False] * (n + 1) for _ in range(m + 1)] for _ in range(2)]
        dp[0][0][0] = True

        for i in range(m):
            for j in range(n):
                for k in range(2):
                    if grid[i][j]:
                        dp[(k + 1) % 2][i + 1][j] |= dp[k % 2][i][j]
                        dp[(k + 1) % 2][i][j + 1] |= dp[k % 2][i][j]
                    else:
                        dp[(k + 1) % 2][i + 1][j] |= dp[k % 2][i][j]
                        dp[(k + 1) % 2][i][j + 1] |= dp[k % 2][i][j]

        return dp[(m + n) % 2][m][n]

