        # Iterate through the list of words
        for i in range(len(wordsDict)):
            # Check if both words are present in the current index
            if wordsDict[i] == word1 or wordsDict[i] == word2:
                # Calculate the distance between the current word and the other word
                distance = abs(i - wordsDict.index(word1)) + abs(i - wordsDict.index(word2))

