class Solution:
    def minCost(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            count = [0] * n
            unique_count = 0
            trimmed_length = 0

            for j in range(i, 0, -1):
                if count[nums[j - 1]] == 0:
                    unique_count += 1
                count[nums[j - 1]] += 1

                if count[nums[j - 1]] == 2:
                    trimmed_length += 2
                elif count[nums[j - 1]] > 2:
