class Solution:
    def findOriginalArray(self, changed: List[int]) -> List[int]:
        # Create a dictionary to count occurrences of each number
        count = {}
        for num in changed:
            if num in count:
                count[num] += 1
            else:
                count[num] = 1

        # Check if the length of the original array is odd
        if len(changed) % 2 != 0:
            return []

        # Create a list to store the original array
        original = []

        # Iterate over the keys of the count dictionary
        for num in count.keys():
            # Check if the number of times it appears is even
            if count[num] % 2 == 0:
                # Append the number to the original array
                original.append(num)
                # Decrease the count by half
                count[num] //= 2

        return original

class Solution:
    def dominantIndex(self, nums: List[int]) -> int:
        if len(nums) < 2:
            return -1

        # Find the maximum value and its index
        max_value = max(nums)
        max_index = nums.index(max_value)

        # Check if the maximum value is at least twice as large as every other number
        for i in range(len(nums)):
            if i != max_index and nums[i] < 2 * max_value:
                return -1

        return max_index

