class Solution:
    def canMakePalindromeQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s)
        half_n = n // 2

        # Prefix sum of character counts for the first half
        prefix_count_first_half = [Counter() for _ in range(half_n + 1)]
        for i in range(half_n):
            prefix_count_first_half[i + 1] = prefix_count_first_half[i] + Counter(s[i])

        # Suffix sum of character counts for the second half
        suffix_count_second_half = [Counter() for _ in range(half_n + 1)]
        for i in range(half_n - 1, -1, -1):
            suffix_count_second_half[half_n - 1 - i] = suffix_count_second_half[half_n - 2 - i] + Counter(s[n - 1 - i])

        def can_form_palindrome(a, b, c, d):
            # Check if the characters outside the rearrangeable parts match
            for i in range(a):
                if s[i] != s[n - 1 - i]:
                    return False
            for i in range(b + 1, half_n):
                if s[i] != s[n - 1 - i]:
                    return False

            # Check if the characters inside the rearrangeable parts can be rearranged to form a palindrome
            left_counter = prefix_count_first_half[b + 1] - prefix_count_first_half[a]
            right_counter = suffix_count_second_half[c - half_n] - suffix_count_second_half[d - half_n + 1]

            # Combine the counts from both halves
            combined_counter = left_counter + right_counter

            # Count the number of mismatches
            mismatch_count = 0
            for i in range(a, b + 1):
                if s[i] != s[n - 1 - i]:
                    mismatch_count += 1

            # Check if the mismatches can be resolved by rearranging
            for char in combined_counter:
                if combined_counter[char] % 2 != 0:
                    mismatch_count -= 1

            return mismatch_count <= 0

        result = []
        for a, b, c, d in queries:
            result.append(can_form_palindrome(a, b, c, d))

        return result

class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        import math

        # Function to check if a point is inside a circle
        def is_inside_circle(x, y, circle):
            return math.sqrt((x - circle[0])**2 + (y - circle[1])**2) <= circle[2]

        # Check if the path from (0, 0) to (xCorner, yCorner) intersects with any circle
        for circle in circles:
            if is_inside_circle(xCorner, 0, circle) or is_inside_circle(0, yCorner, circle):
                return False

        # Check if there is a valid path from (0, 0) to (xCorner, yCorner)
        def dfs(x, y):
            if x == xCorner and y == yCorner:
                return True

            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx <= xCorner and 0 <= ny <= yCorner:
                    if not is_inside_circle(nx, ny, circle) and dfs(nx, ny):
                        return True

            return False

        return dfs(0, 0)

from typing import List

class Solution:
    def pacificAtlantic(self, heights: List[List[int]]) -> List[List[int]]:
        if not heights or not heights[0]:
            return []

        m, n = len(heights), len(heights[0])
        pacific_reachable = set()
        atlantic_reachable = set()

        def dfs(r, c, reachable):
            reachable.add((r, c))
            for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in reachable and heights[nr][nc] >= heights[r][c]:
                    dfs(nr, nc, reachable)

        for i in range(m):
            dfs(i, 0, pacific_reachable)
            dfs(i, n - 1, atlantic_reachable)

        for j in range(n):
            dfs(0, j, pacific_reachable)
            dfs(m - 1, j, atlantic_reachable)

        return list(pacific_reachable & atlantic_reachable)

class Solution:
    def maximumCostSubstring(self, s: str, chars: str, vals: List[int]) -> int:
        char_values = {char: val for char, val in zip(chars, vals)}
        max_cost = float('-inf')
        current_cost = 0

        for char in s:
            if char in char_values:
                current_cost += char_values[char]
            else:
                current_cost += ord(char) -ord('a') + 1

            max_cost = max(max_cost, current_cost)

            if current_cost < 0:
                current_cost = 0

        return max_cost

from collections import deque

class Solution:
    def shortestPathAllKeys(self, grid: List[str]) -> int:
        m, n = len(grid), len(grid[0])
        start_x, start_y = 0, 0
        key_count = 0

        # Find the start position and count the number of keys
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '@':
                    start_x, start_y = i, j
                elif grid[i][j].islower():
                    key_count += 1

        # Directions for moving in the grid
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        # BFS initialization
        queue = deque([(start_x, start_y, 0)])  # (x, y, state)
        visited = set()
        visited.add((start_x, start_y, 0))

        steps = 0

        while queue:
            for _ in range(len(queue)):
                x, y, state = queue.popleft()

                # Check if all keys are collected
                if state == (1 << key_count) - 1:
                    return steps

                # Explore neighbors
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != '#':
                        if grid[nx][ny].isupper():
                            # Check if we have the key for this lock
                            key = ord(grid[nx][ny].lower()) - ord('a')
                            if not (state & (1 << key)):
                                continue
                        elif grid[nx][ny].islower():
                            # Pick up the key
                            key = ord(grid[nx][ny]) - ord('a')
                            new_state = state | (1 << key)
                            if (nx, ny, new_state) not in visited:
                                visited.add((nx, ny, new_state))
                                queue.append((nx, ny, new_state))
                        else:
                            # Empty cell or start point
                            if (nx, ny, state) not in visited:
                                visited.add((nx, ny, state))
                                queue.append((nx, ny, state))
            steps += 1

        return -1

from typing import List

class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        def isInsideCircle(x, y, cx, cy, r):
            return (x - cx) ** 2 + (y - cy) ** 2 <= r ** 2

        def isPathClear(x1, y1, x2, y2):
            dx = x2 - x1
            dy = y2 - y1
            for t in range(1001):
                x = x1 + t * dx / 1000
                y = y1 + t * dy / 1000
                if any(isInsideCircle(x, y, cx, cy, r) for cx, cy, r in circles):
                    return False
            return True

        # Check the four main segments of the rectangle
        if isPathClear(0, 0, xCorner, 0) and isPathClear(xCorner, 0, xCorner, yCorner) and isPathClear(xCorner, yCorner, 0, yCorner):
            return True
        if isPathClear(0, 0, 0, yCorner) and isPathClear(0, yCorner, xCorner, yCorner) and isPathClear(xCorner, yCorner, xCorner, 0):
            return True

        # Check the diagonal paths
        if isPathClear(0, 0, xCorner, yCorner):
            return True
        if isPathClear(0, yCorner, xCorner, 0):
            return True

        return False

class Solution:
    def findContestMatch(self, n: int) -> str:
        def helper(arr):
            if len(arr) == 1:
                return arr[0]
            mid = len(arr) // 2
            left = helper(arr[:mid])
            right = helper(arr[mid:])
            return f"({left},{right})"

        return helper(list(range(1, n + 1)))

class Solution:
    def kthGrammar(self, n: int, k: int) -> int:
        if n == 1:
            return 0

        # Calculate the position of k in the nth row
        position = (k - 1) // 2

        # Determine the value of the k-th symbol in the nth row
        if position % 2 == 0:
            return 0  # 00
        else:
            return 1  # 01

