class Solution:
    def largestPalindromic(self, num: str) -> str:
        counter = Counter(num)
        odd_count = sum(1 for c in counter if counter[c] % 2 == 1)
        mid = ''
        largest = ''
        for c in sorted(counter.keys(), reverse=True):
            if c == '0' and not mid:
                continue
            if counter[c] % 2 == 1:
                if odd_count > 1:
                    odd_count -= 1
                else:
                    mid = c
            largest += c * (counter[c] // 2)
        return largest + mid + largest[::-1]

from collections import defaultdict

class Solution:
    def checkWays(self, pairs: List[List[int]]) -> int:
        # Build graph using adjacency list
        adj = defaultdict(list)
        for u, v in pairs:
            adj[u].append(v)
            adj[v].append(u)

        # Count degree of each node
        degree = defaultdict(int)
        for u in adj:
            degree[u] = len(adj[u])

        # Check if every node has even degree
        if any(d % 2 != 0 for d in degree.values()):
            return 0

        # Find the root node
        root = None
        for u in degree:
            if degree[u] == 1:
                root = u
                break

        # If no root is found, return 0
        if root is None:
            return 0

        # Perform DFS to count the number of connected components
        visited = set()
        stack = [root]
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            stack.extend(adj[node])

        # If more than one component, return 0
        if len(visited) != len(adj):
            return 0

        # Check if the graph is a tree
        if len(pairs) != len(set(tuple(sorted(pair)) for pair in pairs)):
            return 0

        # Check if the graph is a binary tree
        for u in adj:
            if len(adj[u]) != 1 and len(adj[u]) != 2:
                return 0

        # Check if the graph is a binary tree with a single root
        if len(adj[root]) != 1:
            return 0

        # Return 2 if the graph is a binary tree with a single root and two children
        return 2

from collections import Counter
from functools import lru_cache

class Solution:
    def minStickers(self, stickers: List[str], target: str) -> int:
        @lru_cache(None)
        def dfs(target):
            if not target:
                return 0
            target_count = Counter(target)
            res = float('inf')
            for sticker in stickers:
                if sticker[0] not in target_count:
                    continue
                remaining = []
                sticker_count = Counter(sticker)
                for char, count in target_count.items():
                    if char in sticker_count:
                        remaining.append((char, max(0, count - sticker_count[char])))
                    else:
                        remaining.append((char, count))
                new_target = ''.join(char * count for char, count in remaining)
                res = min(res, 1 + dfs(new_target))
            return res if res != float('inf') else -1

        return dfs(tuple(target))

