class Solution:
    def maxProduct(self, root: Optional[TreeNode]) -> int:
        def calculate_sum(node):
            if not node:
                return 0
            return node.val + calculate_sum(node.left) + calculate_sum(node.right)

        def find_max_product(node):
            if not node:
                return 0
            left_sum = calculate_sum(node.left)
            right_sum = calculate_sum(node.right)
            nonlocal max_product, total_sum
            max_product = max(max_product, left_sum * (total_sum - left_sum), right_sum * (total_sum - right_sum))
            find_max_product(node.left)
            find_max_product(node.right)

        total_sum = calculate_sum(root)
        max_product = 0
        find_max_product(root)
        return max_product % (10**9 + 7)

class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        remainder_counts = [0, 0, 0]
        for num in nums:
            remainder_counts[num % 3] += 1

        if remainder_counts[0] == len(nums):
            return 0

        # If there's at least one number divisible by 3, we can skip it
        if remainder_counts[0] > 0:
            remainder_counts[0] -= 1

        # Calculate the minimum operations needed to make the rest divisible by 3
        ops = 0
        for i in range(1, 3):
            if remainder_counts[i] > 0:
                if remainder_counts[(i + 1) % 3] > 0:
                    # If there are enough numbers to make the remainder different
                    ops += min(remainder_counts[i], remainder_counts[(i + 1) % 3])
                else:
                    # If not, we need to use the remaining numbers to make the remainder different
                    ops += remainder_counts[i]

        return ops

