class Solution:
    def strongPasswordChecker(self, password: str) -> int:
        # Check the length of the password
        if len(password) < 6 or len(password) > 20:
            return 0

        # Count the number of lowercase letters, uppercase letters, and digits
        lowercase_count = sum(1 for char in password if char.islower())
        uppercase_count = sum(1 for char in password if char.isupper())
        digit_count = sum(1 for char in password if char.isdigit())

        # Check if there are at least one of each type of character
        if lowercase_count == 0 or uppercase_count == 0 or digit_count == 0:
            return 0

        # Count the number of consecutive repeating characters
        repeat_count = 0
        for i in range(len(password) - 1):
            if password[i] == password[i + 1]:
                repeat_count += 1
            else:
                if repeat_count >= 3:
                    return repeat_count + 1
                repeat_count = 0

        # If there are no consecutive repeating characters, return 0
        return 0

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [1] * n

        for i in range(1, n):
            for j in range(i - 1, -1, -1):
                if nums[j] < nums[i]:
                    dp[i] = max(dp[i], dp[j] + 1)

        return max(dp)

