class Solution:
    def canDistribute(self, nums: List[int], quantity: List[int]) -> bool:
        count = Counter(nums)
        counts = sorted(count.values(), reverse=True)
        q = sorted(quantity, reverse=True)

        @lru_cache(None)
        def dfs(i, j):
            if i == len(q):
                return True
            if j == len(counts):
                return False

            for k in range(min(q[i], counts[j]), 0, -1):
                if counts[j] >= k and dfs(i + 1, j + 1):
                    return True
            return False

        return dfs(0, 0)

class Solution:
    def maxNonOverlapping(self, nums: List[int], target: int) -> int:
        prefix_sum = 0
        seen_sums = {0: -1}
        count = 0

        for i, num in enumerate(nums):
            prefix_sum += num
            if prefix_sum - target in seen_sums:
                if seen_sums[prefix_sum - target] >= i - 1:
                    continue
                count += 1
                seen_sums.clear()
                seen_sums[prefix_sum] = i
            else:
                seen_sums[prefix_sum] = i

        return count

class Solution:
    def stoneGameVIII(self, stones: List[int]) -> int:
        prefix_sum = [stones[0]]
        for i in range(1, len(stones)):
            prefix_sum.append(prefix_sum[-1] + stones[i])

        dp = [0] * len(stones)
        dp[-1] = prefix_sum[-1]

        for i in range(len(stones) - 2, -1, -1):
            dp[i] = max(dp[i+1], prefix_sum[i] - dp[i+1])

        return dp[0]

