class Solution:
    def maximumNumber(self, num: str, change: List[int]) -> str:
        num_list = list(num)
        changed = False

        for i in range(len(num_list)):
            digit = int(num_list[i])
            if change[digit] > digit:
                changed = True
            elif change[digit] < digit:
                if changed:
                    break
            num_list[i] = str(change[digit])

        return ''.join(num_list)

class Solution:
    def minimizeXor(self, num1: int, num2: int) -> int:
        # Count the number of set bits in num2
        set_bits_num2 = num2.bit_count()

        # Create a copy of num1 to manipulate
        x = num1

        # If the number of set bits in num1 is greater than in num2, we need to remove some set bits
        if set_bits_num2 < x.bit_count():
            # Remove set bits from the least significant positions
            for _ in range(x.bit_count() - set_bits_num2):
                x &= x - 1
        elif set_bits_num2 > x.bit_count():
            # Add set bits to the least significant positions
            for _ in range(set_bits_num2 - x.bit_count()):
                x |= x + 1

        return x

