class Solution:
    def exclusiveTime(self, n: int, logs: List[str]) -> List[int]:
        res = [0] * n
        st = []
        last_time = 0

        for log in logs:
            func_id, action, timestamp = log.split(':')
            func_id, timestamp = int(func_id), int(timestamp)

            if action == 'start':
                if st:
                    prev_func_id, prev_timestamp = st[-1]
                    res[prev_func_id] += timestamp - prev_timestamp
                st.append((func_id, timestamp))
            else:
                _, prev_timestamp = st.pop()
                res[func_id] += timestamp - prev_timestamp + 1
                if st:
                    next_func_id, _ = st[-1]
                    st[-1] = (next_func_id, timestamp + 1)

        return res

