class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        count = Counter(nums)
        max_length = 1

        for num in sorted(count):
            if num == 1:
                if count[num] % 2 == 0:
                    max_length = max(max_length, count[num] - 1)
                else:
                    max_length = max(max_length, count[num])
            elif count[num] >= 2:
                next_num = num * num
                length = 2
                while count[next_num] >= 2:
                    length += 2
                    next_num *= next_num
                max_length = max(max_length, length)

        return max_length

class Solution:
    def tictactoe(self, moves: List[List[int]]) -> str:
        # Initialize the board
        board = [[' ' for _ in range(3)] for _ in range(3)]

        # Fill the board with moves
        for i, move in enumerate(moves):
            row, col = move
            if i % 2 == 0:
                board[row][col] = 'X'
            else:
                board[row][col] = 'O'

        # Check rows, columns and diagonals for a win
        for i in range(3):
            if board[i][0] == board[i][1] == board[i][2] != ' ':
                return 'A' if board[i][0] == 'X' else 'B'
            if board[0][i] == board[1][i] == board[2][i] != ' ':
                return 'A' if board[0][i] == 'X' else 'B'

        if board[0][0] == board[1][1] == board[2][2] != ' ':
            return 'A' if board[0][0] == 'X' else 'B'
        if board[0][2] == board[1][1] == board[2][0] != ' ':
            return 'A' if board[0][2] == 'X' else 'B'

        # Check if the game is pending or a draw
        if len(moves) < 9:
            return "Pending"
        else:
            return "Draw"

class Solution:
    def minTaps(self, n: int, ranges: List[int]) -> int:
        intervals = []
        for i, r in enumerate(ranges):
            if r > 0:
                intervals.append((max(0, i - r), min(n, i + r)))

        # Sort intervals by their start time
        intervals.sort()

        end = 0
        taps = 0

        for start, end_interval in intervals:
            if end >= end_interval:
                continue
            if end < start:
                return -1

            end = end_interval
            taps += 1

        if end < n:
            return -1

        return taps

class Solution:
    def monotoneIncreasingDigits(self, n: int) -> int:
        s = list(str(n))
        i = 1
        while i < len(s) and s[i] >= s[i - 1]:
            i += 1
        while i > 0 and s[i] < s[i - 1]:
            s[i - 1] = str(int(s[i - 1]) - 1)
            i -= 1
        for j in range(i + 1, len(s)):
            s[j] = '9'
        return int(''.join(s))

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def hasPathSum(self, root: Optional[TreeNode], targetSum: int) -> bool:
        if not root:
            return False

        # Check if we're at a leaf node
        if not root.left and not root.right:
            return root.val == targetSum

        # Recur for left and right subtrees
        return self.hasPathSum(root.left, targetSum - root.val) or self.hasPathSum(root.right, targetSum - root.val)

