from typing import List

class Solution:
    def canDistribute(self, nums: List[int], quantity: List[int]) -> bool:
        # Count the frequency of each number in nums
        freq = list(Counter(nums).values())
        freq.sort(reverse=True)

        # Precompute the powerset of quantity
        n = len(quantity)
        powerset = []
        for i in range(1 << n):
            subset = []
            for j in range(n):
                if i & (1 << j):
                    subset.append(quantity[j])
            powerset.append(subset)

        # Check if we can satisfy the subset using the current frequency
        def can_satisfy(subset, freq):
            freq_copy = freq[:]
            for q in subset:
                placed = False
                for i in range(len(freq_copy)):
                    if freq_copy[i] >= q:
                        freq_copy[i] -= q
                        placed = True
                        break
                if not placed:
                    return False
            return True

        # Try to satisfy each subset of quantity
        for i in range(1, 1 << n):
            subset = powerset[i]
            if not can_satisfy(subset, freq):
                return False

        return True

class Solution:
    def minNumberOfFrogs(self, croakOfFrogs: str) -> int:
        # Initialize counters for each type of frog
        count_croak = 0
        count_rake = 0
        count_oak = 0
        count_ape = 0

        # Iterate through each character in the string
        for char in croakOfFrogs:
            # Increment the counter for each type of frog
            if char == 'c':
                count_croak += 1
            elif char == 'r':
                count_rake += 1
            elif char == 'o':
                count_oak += 1
            elif char == 'a':
                count_ape += 1

            # If the total count of any frog exceeds 5, return -1
            if count_croak + count_rake + count_oak + count_ape > 5:
                return -1

        # Return the minimum number of frogs
        return min(count_croak, count_rake, count_oak, count_ape)

from typing import List
import bisect

class Solution:
    def maxTaskAssign(self, tasks: List[int], workers: List[int], pills: int, strength: int) -> int:
        tasks.sort()
        workers.sort()

        def can_complete(k):
            remaining_workers = workers[-k:]
            remaining_pills = pills
            for i in range(k-1, -1, -1):
                if remaining_workers[-1] >= tasks[i]:
                    remaining_workers.pop()
                elif remaining_pills > 0 and remaining_workers[0] + strength >= tasks[i]:
                    remaining_pills -= 1
                    remaining_workers.pop(bisect.bisect_left(remaining_workers, tasks[i] - strength))
                else:
                    return False
            return True

        left, right = 0, min(len(tasks), len(workers))
        while left < right:
            mid = (left + right + 1) // 2
            if can_complete(mid):
                left = mid
            else:
                right = mid - 1
        return left

from collections import defaultdict
class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        graph = defaultdict(list)
        for u,v in connections:
            graph[u].append(v)
            graph[v].append(u)
        visited = set()
        ans = 0

        def dfs(node):
            nonlocal ans
            if node in visited: return
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    ans += 1
                    dfs(neighbor)

        dfs(0)
        return ans

