class Solution:
    def findRestaurant(self, list1: List[str], list2: List[str]) -> List[str]:
        # Create a dictionary to count occurrences of each word in list1
        word_count1 = {}
        for word in list1:
            if word in word_count1:
                word_count1[word] += 1
            else:
                word_count1[word] = 1

        # Create a dictionary to count occurrences of each word in list2
        word_count2 = {}
        for word in list2:
            if word in word_count2:
                word_count2[word] += 1
            else:
                word_count2[word] = 1

        # Find the common words with the least index sum
        min_sum = float('inf')
        result = []
        for word in word_count1:
            if word in word_count2:
                sum1 = word_count1[word]
                sum2 = word_count2[word]
                if sum1 + sum2 < min_sum:
                    min_sum = sum1 + sum2
                    result = [word]
                elif sum1 + sum2 == min_sum:
                    result.append(word)

        return result

from collections import Counter
from typing import List

class Solution:
    def maxScoreWords(self, words: List[str], letters: List[str], score: List[int]) -> int:
        def word_score(word, score_map):
            return sum(score_map[char] for char in word)

        def can_form(word, letter_count):
            word_count = Counter(word)
            for char, count in word_count.items():
                if letter_count[char] < count:
                    return False
            return True

        def update_letter_count(letter_count, word, add=True):
            for char in word:
                if add:
                    letter_count[char] += 1
                else:
                    letter_count[char] -= 1

        def backtrack(index, current_score, letter_count):
            if index == len(words):
                return current_score

            max_score = current_score
            for i in range(index, len(words)):
                if can_form(words[i], letter_count):
                    update_letter_count(letter_count, words[i], add=False)
                    max_score = max(max_score, backtrack(i + 1, current_score + word_score(words[i], score_map), letter_count))
                    update_letter_count(letter_count, words[i], add=True)

            return max_score

        letter_count = Counter(letters)
        score_map = {chr(i + ord('a')): score[i] for i in range(26)}

        return backtrack(0, 0, letter_count)

class Solution:
    def largestDivisibleSubset(self, nums: List[int]) -> List[int]:
        if not nums:
            return []

        nums.sort()
        n = len(nums)
        dp = [1] * n
        prev_index = [-1] * n

        max_index = 0
        for i in range(1, n):
            for j in range(i):
                if nums[i] % nums[j] == 0 and dp[i] < dp[j] + 1:
                    dp[i] = dp[j] + 1
                    prev_index[i] = j
            if dp[i] > dp[max_index]:
                max_index = i

        result = []
        while max_index != -1:
            result.append(nums[max_index])
            max_index = prev_index[max_index]

        return result[::-1]

