class Solution:
    def hasPath(self, maze: List[List[int]], start: List[int], destination: List[int]) -> bool:
        m, n = len(maze), len(maze[0])
        visited = set()

        def dfs(x, y):
            if (x, y) in visited:
                return False
            if [x, y] == destination:
                return True
            visited.add((x, y))

            # Roll left
            r = y
            while r >= 0 and maze[x][r] == 0:
                r -= 1
            if dfs(x, r + 1):
                return True

            # Roll right
            r = y
            while r < n and maze[x][r] == 0:
                r += 1
            if dfs(x, r - 1):
                return True

            # Roll up
            r = x
            while r >= 0 and maze[r][y] == 0:
                r -= 1
            if dfs(r + 1, y):
                return True

            # Roll down
            r = x
            while r < m and maze[r][y] == 0:
                r += 1
            if dfs(r - 1, y):
                return True

            return False

        return dfs(start[0], start[1])

class Solution:
    def findMaximumXOR(self, nums: List[int]) -> int:
        # Create a Trie node class
        class Node:
            def __init__(self):
                self.children = {}

        # Initialize the root node
        root = Node()

        # Insert each number into the Trie
        for num in nums:
            current_node = root
            for bit in range(31, -1, -1):  # Iterate from the most significant bit to the least significant bit
                if (num >> bit) & 1:
                    if '1' not in current_node.children:
                        current_node.children['1'] = Node()
                    current_node = current_node.children['1']
                else:
                    if '0' not in current_node.children:
                        current_node.children['0'] = Node()
                    current_node = current_node.children['0']

        # Find the maximum XOR value
        max_xor = 0
        for num in nums:
            current_node = root
            xor_value = 0
            for bit in range(31, -1, -1):  # Iterate from the most significant bit to the least significant bit
                if (num >> bit) & 1:
                    if '0' in current_node.children:
                        xor_value |= (1 << bit)
                        current_node = current_node.children['0']
                    else:
                        current_node = current_node.children['1']
                else:
                    if '1' in current_node.children:
                        xor_value |= (1 << bit)
                        current_node = current_node.children['1']
                    else:
                        current_node = current_node.children['0']
            max_xor = max(max_xor, xor_value)

        return max_xor

class Solution:
    def removeKdigits(self, num: str, k: int) -> str:
        stack = []
        for digit in num:
            while k > 0 and stack and stack[-1] > digit:
                stack.pop()
                k -= 1
            stack.append(digit)

        # If there are still digits to remove, remove them from the end
        while k > 0:
            stack.pop()
            k -= 1

        # Join the stack to form the number and remove leading zeros
        result = ''.join(stack).lstrip('0')

        # If the result is empty, return '0'
        return result if result else '0'

from typing import List

class Solution:
    def numsSameConsecDiff(self, n: int, k: int) -> List[int]:
        if n == 1:
            return list(range(10))

        result = []

        def backtrack(current_number, remaining_length):
            if remaining_length == 0:
                result.append(current_number)
                return

            last_digit = current_number % 10
            next_digits = set()

            if last_digit + k < 10:
                next_digits.add(last_digit + k)
            if last_digit - k >= 0:
                next_digits.add(last_digit - k)

            for next_digit in next_digits:
                backtrack(current_number * 10 + next_digit, remaining_length - 1)

        for first_digit in range(1, 10):
            backtrack(first_digit, n - 1)

        return result

