class Solution:
    def numberOfPairs(self, points: List[List[int]]) -> int:
        count = 0
        n = len(points)

        for i in range(n):
            for j in range(n):
                if points[i][0] < points[j][0] and points[i][1] > points[j][1]:
                    valid = True
                    for k in range(n):
                        if k != i and k != j:
                            if points[i][0] <= points[k][0] <= points[j][0] and points[j][1] <= points[k][1] <= points[i][1]:
                                valid = False
                                break
                    if valid:
                        count += 1

        return count

class Solution:
    def areConnected(self, n: int, threshold: int, queries: List[List[int]]) -> List[bool]:
        if threshold == 0:
            return [True] * len(queries)

        parent = list(range(n + 1))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY

        for i in range(threshold + 1, n + 1):
            for j in range(2 * i, n + 1, i):
                union(i, j)

        return [find(a) == find(b) for a, b in queries]

class Solution:
    def longestConsecutive(self, root: Optional[TreeNode]) -> int:
        res = 0

        def dfs(node):
            nonlocal res
            if not node:
                return 0

            left_inc = dfs(node.left)
            right_dec = dfs(node.right)

            inc = dec = 1
            if node.left and node.left.val == node.val + 1:
                inc += left_inc
            if node.right and node.right.val == node.val + 1:
                inc += right_inc
            if node.left and node.left.val == node.val - 1:
                dec += left_dec
            if node.right and node.right.val == node.val - 1:
                dec += right_dec

            res = max(res, inc, dec)

            return max(inc, dec)

        dfs(root)
        return res

class Solution:
    def smallestGoodBase(self, n: str) -> str:
        n = int(n)
        for m in range(2, 61):
            k = int(n ** (1.0 / m))
            if k < 2:
                continue
            if sum(k ** i for i in range(m + 1)) == n:
                return str(k)
        return str(n - 1)

class Solution:
    def minFlipsMonoIncr(self, s: str) -> int:
        n = len(s)
        dp0 = 0  # Number of flips needed if the current character is '0'
        dp1 = 0  # Number of flips needed if the current character is '1'

        for i in range(n):
            if s[i] == '0':
                # If the current character is '0', we can either keep it as '0' or change it to '1'
                # If we keep it as '0', dp0 remains the same
                # If we change it to '1', dp0 becomes dp1 + 1
                dp0 = min(dp0, dp1)
                dp1 += 1
            else:
                # If the current character is '1', we can only keep it as '1'
                # Changing it to '0' would increase the number of flips
                dp0 += 1

        # The final result is the minimum number of flips needed to make the entire string monotone increasing
        return min(dp0, dp1)

class Solution:
    def abbreviateProduct(self, left: int, right: int) -> str:
        product = 1
        for i in range(left, right + 1):
            product *= i

        # Count trailing zeros
        C = 0
        while product % 10 == 0:
            product //= 10
            C += 1

        # Convert product to string to check length
        product_str = str(product)
        d = len(product_str)

        if d > 10:
            return f"{product_str[:5]}...{product_str[-5:]}e{C}"
        else:
            return f"{product_str}e{C}"

