    def isPreorder(self, nodes: List[List[int]]) -> bool:
        stack = []
        for node in nodes:
            while stack and stack[-1][1] < node[0]:
                stack.pop()
            stack.append(node)
        return len(stack) == 1 and stack[0][0] == 0

class Solution:
    def buildTree(self, inorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
        if not inorder or not postorder:
            return None

        root = TreeNode(postorder[-1])
        root_index = inorder.index(root.val)

        root.left = self.buildTree(inorder[:root_index], postorder[:root_index])
        root.right = self.buildTree(inorder[root_index+1:], postorder[root_index:])

        return root

from collections import Counter

class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        even_count = Counter(nums[::2])
        odd_count = Counter(nums[1::2])

        most_common_even = even_count.most_common(2)
        most_common_odd = odd_count.most_common(2)

        total_operations = float('inf')

        for e1, e1_freq in most_common_even:
            for o1, o1_freq in most_common_odd:
                if e1 != o1:
                    operations = (n // 2 - e1_freq) + (n // 2 - o1_freq)
                    total_operations = min(total_operations, operations)

        if total_operations == float('inf'):
            total_operations = min((n // 2 - most_common_even[0][1]), (n // 2 - most_common_odd[0][1]))

        return total_operations

class Solution:
    def convertArray(self, nums: List[int]) -> int:
        n = len(nums)
        ans = float('inf')

        # Helper function to calculate the cost of making the array non-decreasing
        def non_decreasing_cost():
            cost = 0
            for i in range(1, n):
                if nums[i] < nums[i - 1]:
                    cost += nums[i - 1] - nums[i]
                    nums[i] = nums[i - 1]
            return cost

        # Helper function to calculate the cost of making the array non-increasing
        def non_increasing_cost():
            cost = 0
            for i in range(1, n):
                if nums[i] > nums[i - 1]:
                    cost += nums[i] - nums[i - 1]
                    nums[i] = nums[i - 1]
            return cost

        # Try both non-decreasing and non-increasing conversions
        ans = min(non_decreasing_cost(), non_increasing_cost())

        return ans

