class Solution:
    def countPairs(self, root: Optional[TreeNode], distance: int) -> int:
        self.count = 0

        def dfs(node):
            if not node:
                return []

            if not node.left and not node.right:
                return [1]

            left = dfs(node.left)
            right = dfs(node.right)

            for l in left:
                for r in right:
                    if l + r <= distance:
                        self.count += 1

            return [x + 1 for x in left + right]

        dfs(root)
        return self.count

class Solution:
    def longestSubsequence(self, s: str, k: int) -> int:
        zeros = s.count('0')
        ones = []
        count = 0
        for i, char in enumerate(s):
            if char == '1':
                ones.append(i)
                count += 1
                if int(''.join(['1' if j < len(ones) else '0' for j in range(len(ones))]), 2) > k:
                    count -= 1
                    ones.pop()
        return count + zeros

class Solution:
    def canJump(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True

        # Initialize the maximum jump length
        max_jump = nums[0]

        # Iterate through the array starting from the second element
        for i in range(1, n):
            # Update the maximum jump length if the current position can be reached
            max_jump = max(max_jump, i + nums[i])

        # Check if the last position can be reached
        return max_jump >= n - 1

class Solution:
    def waysToBuyPensPencils(self, total: int, cost1: int, cost2: int) -> int:
        if cost1 > total or cost2 > total:
            return 1

        count = 0
        for i in range(total // cost1 + 1):
            count += (total - i * cost1) // cost2 + 1
        return count

