class Solution:
    def minChanges(self, nums: List[int], k: int) -> int:
        n = len(nums)
        groups = [[] for _ in range(k)]
        group_sizes = [0] * k
        max_freqs = [0] * k

        for i in range(n):
            groups[nums[i] % k].append(nums[i])
            group_sizes[nums[i] % k] += 1

        total_changes = n // 2
        for i in range(k):
            freq = {}
            for num in groups[i]:
                freq[num] = freq.get(num, 0) + 1
            max_freqs[i] = max(freq.values())
            total_changes = min(total_changes, n // 2 - max_freqs[i])

        return total_changes

class Solution:
    def minOperations(self, initial: str, target: str) -> int:
        # Find the longest common subsequence (LCS) between initial and target
        m, n = len(initial), len(target)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if initial[i - 1] == target[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        lcs_length = dp[m][n]

        # Minimum operations required is the sum of characters to be added and removed
        return (m - lcs_length) + (n - lcs_length)

