class Solution:
    def maxDiff(self, num: int) -> int:
        num_str = str(num)
        a = num
        b = num

        # Find the first non-'9' digit to maximize 'a'
        for i, digit in enumerate(num_str):
            if digit != '9':
                a = int(num_str.replace(digit, '9'))
                break

        # Find the first non-'1' digit to maximize 'b'
        for i, digit in enumerate(num_str):
            if digit != '1' and (i == 0 or digit != num_str[0]):
                b = int(num_str.replace(digit, '1'))
                break

        # If 'a' is already the maximum, return 0
        if a == num:
            return 0

        return a - b

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # Generate all possible topping combinations
        def generate_combinations(topping_costs, max_toppings):
            combinations = set()
            for i in range(2 ** len(topping_costs)):
                combination = []
                for j in range(len(topping_costs)):
                    if (i >> j) & 1:
                        combination.append(topping_costs[j])
                combinations.add(sum(combination))
            return combinations

        topping_combinations = generate_combinations(toppingCosts, 2)
        min_diff = float('inf')
        closest_cost = float('inf')

        for base in baseCosts:
            for combo in topping_combinations:
                total_cost = base + combo
                diff = abs(total_cost - target)
                if diff < min_diff or (diff == min_diff and total_cost < closest_cost):
                    min_diff = diff
                    closest_cost = total_cost

        return closest_cost

class Solution:
    def findErrorNums(self, nums: List[int]) -> List[int]:
        # Initialize two lists to store the result
        res = [0] * 2

        # Iterate through each number in the input list
        for num in nums:
            # Calculate the index of the number if it's not already present
            index = abs(num) - 1

            # If the number is already present at its index, mark it as negative
            if nums[index] < 0:
                res[0] = abs(nums[index])
                break

            # Otherwise, swap the number with the number at its index
            else:
                nums[index] *= -1

        # Calculate the first missing positive number
        for i in range(len(nums)):
            if nums[i] > 0:
                res[1] = i + 1

        return res

