class Solution:
    def toHex(self, num: int) -> str:
        if num == 0:
            return "0"

        # Handle negative numbers using two's complement
        if num < 0:
            num += 2**32

        hex_chars = "0123456789abcdef"
        hex_string = ""

        while num > 0:
            remainder = num % 16
            hex_string = hex_chars[remainder] + hex_string
            num //= 16

        return hex_string

class Solution:
    def equalDigitFrequency(self, s: str) -> int:
        count = Counter(s)
        n = len(s)
        res = 0

        for i in range(n):
            for j in range(i+1, n+1):
                sub = s[i:j]
                freq = Counter(sub)

                if all(freq[k] == count[k] for k in freq):
                    res += 1

        return res

