class Solution:
    def bagOfTokensScore(self, tokens: List[int], power: int) -> int:
        tokens.sort()
        max_score = 0
        power -= sum(tokens)
        for token in tokens:
            if power >= token:
                max_score += 1
                power -= token
            else:
                break
        return max_score

