class Solution:
    def largestMultipleOfThree(self, digits: List[int]) -> str:
        # Count the frequency of each digit
        count = [0] * 10
        for digit in digits:
            count[digit] += 1

        # Calculate the sum of all digits
        total_sum = sum(digits)

        # Helper function to remove the smallest number of digits to make the sum divisible by 3
        def remove_digits_to_make_divisible_by_three(sum_mod):
            for i in range(10):
                if count[i] > 0 and (i % 3 == sum_mod):
                    count[i] -= 1
                    return True
            for i in range(10):
                if count[i] > 1 and (i % 3 == sum_mod):
                    count[i] -= 2
                    return True
            return False

        # Reduce the sum modulo 3 to 0
        while total_sum % 3 != 0:
            if not remove_digits_to_make_divisible_by_three(total_sum % 3):
                return ""
            total_sum = sum(digit * cnt for digit, cnt in enumerate(count))

        # Construct the largest number
        result = []
        for digit in range(9, -1, -1):
            result.append(str(digit) * count[digit])

        # Handle the case where the result is ["0", "0", ...]
        return ''.join(result).lstrip('0') or '0'

class Solution:
    def numberToWords(self, num: int) -> str:
        if num == 0:
            return "Zero"

        def one(num):
            switcher = {
                1: 'One', 2: 'Two', 3: 'Three', 4: 'Four', 5: 'Five',
                6: 'Six', 7: 'Seven', 8: 'Eight', 9: 'Nine'
            }
            return switcher.get(num)

        def two_less_20(num):
            switcher = {
                10: 'Ten', 11: 'Eleven', 12: 'Twelve', 13: 'Thirteen', 14: 'Fourteen',
                15: 'Fifteen', 16: 'Sixteen', 17: 'Seventeen', 18: 'Eighteen', 19: 'Nineteen'
            }
            return switcher.get(num)

        def ten(num):
            switcher = {
                2: 'Twenty', 3: 'Thirty', 4: 'Forty', 5: 'Fifty',
                6: 'Sixty', 7: 'Seventy', 8: 'Eighty', 9: 'Ninety'
            }
            return switcher.get(num)

        def two(num):
            if not num:
                return ''
            elif num < 10:
                return one(num)
            elif num < 20:
                return two_less_20(num)
            else:
                tenner = num // 10
                rest = num - tenner * 10
                return ten(tenner) + ('' if not rest else ' ' + one(rest))

        def three(num):
            hundred = num // 100
            rest = num - hundred * 100
            if hundred and rest:
                return one(hundred) + ' Hundred ' + two(rest)
            elif not hundred and rest:
                return two(rest)
            elif hundred and not rest:
                return one(hundred) + ' Hundred'

        billion = num // 1000000000
        million = (num - billion * 1000000000) // 1000000
        thousand = (num - billion * 1000000000 - million * 1000000) // 1000
        remainder = num - billion * 1000000000 - million * 1000000 - thousand * 1000

        result = ''
        if billion:
            result += three(billion) + ' Billion'
        if million:
            result += ' ' if result else ''
            result += three(million) + ' Million'
        if thousand:
            result += ' ' if result else ''
            result += three(thousand) + ' Thousand'
        if remainder:
            result += ' ' if result else ''
            result += three(remainder)

        return result

class Solution:
    def numberOfWeeks(self, milestones: List[int]) -> int:
        return sum(milestones)

class Solution:
    def numberToWords(self, num: int) -> str:
        if num == 0:
            return "Zero"

        below_20 = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"]
        tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]

        def helper(n):
            if n < 20:
                return below_20[n]
            elif n < 100:
                return tens[n // 10] + (" " + helper(n % 10) if n % 10 != 0 else "")
            elif n < 1000:
                return below_20[n // 100] + " Hundred" + (" " + helper(n % 100) if n % 100 != 0 else "")
            else:
                for i, billion in enumerate(["Billion", "Million", "Thousand"]):
                    if n >= billion:
                        return helper(n // billion) + " " + billion + (" " + helper(n % billion) if n % billion != 0 else "")

        return helper(num)

class Solution:
    def averageOfLevels(self, root: Optional[TreeNode]) -> List[float]:
        queue = deque([root])
        result = []
        while queue:
            level_sum = 0
            level_count = len(queue)
            for _ in range(level_count):
                node = queue.popleft()
                level_sum += node.val
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            result.append(level_sum / level_count)
        return result

class Solution:
    def distinctEchoSubstrings(self, text: str) -> int:
        n = len(text)
        seen = set()
        for i in range(n):
            for j in range(i+1, n//2+1):
                if text[i:i+j] == text[i+j:i+2*j]:
                    seen.add(text[i:i+j])
        return len(seen)

class Solution:
    def fixedPoint(self, arr: List[int]) -> int:
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == mid:
                return mid
            elif arr[mid] < mid:
                left = mid + 1
            else:
                right = mid - 1
        return -1

class Solution:
    def countTriplets(self, nums: List[int]) -> int:
        count = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                for k in range(j + 1, len(nums)):
                    if nums[i] & nums[j] & nums[k] == 0:
                        count += 1
        return count

