class Solution:
    def splitMessage(self, message: str, limit: int) -> List[str]:
        n = len(message)
        if limit <= 5:
            return []

        def fits(b):
            if b == 1:
                return limit >= 3 + 1 + 1
            elif b < 10:
                return limit >= 3 + 2 + 1 + 1
            elif b < 100:
                return limit >= 3 + 3 + 1 + 1
            else:
                return limit >= 3 + 4 + 1 + 1

        if not fits(1):
            return []

        for b in range(1, 1001):
            if fits(b):
                parts = []
                idx = 0
                for i in range(1, b + 1):
                    start = idx
                    end = min(idx + limit - 3 - len(str(b)) - len(str(i)), n)
                    parts.append(message[start:end] + '<' + str(i) + '/' + str(b) + '>')
                    idx = end
                if idx == n:
                    return parts

        return []

class Solution:
    def partitionString(self, s: str) -> int:
        seen = set()
        count = 0

        for char in s:
            if char not in seen:
                seen.add(char)
            else:
                seen.clear()
                count += 1

        return count + 1  # Adding 1 because the last substring must be counted separately

