class Solution:
    def twoSumBSTs(self, root1: Optional[TreeNode], root2: Optional[TreeNode], target: int) -> bool:
        stack = []
        while root1 or root2:
            if root1:
                stack.append(root1)
                root1 = root1.left
            if root2:
                stack.append(root2)
                root2 = root2.right
            node = stack.pop()
            if node.val + target == 0:
                return True
            elif node.val + target < 0:
                root1 = node.right
            else:
                root2 = node.left
        return False

