class Solution:
    def splitPainting(self, segments: List[List[int]]) -> List[List[int]]:
        max_end = max(end for _, end, _ in segments)
        changes = [0] * (max_end + 1)

        for start, end, color in segments:
            changes[start] += color
            changes[end] -= color

        current_color_sum = 0
        result = []
        for i in range(1, max_end):
            current_color_sum += changes[i]
            if current_color_sum > 0:
                if not result or result[-1][1] != i:
                    result.append([i, i + 1, current_color_sum])
                else:
                    result[-1][1] = i + 1

        return result

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        n = len(nums)
        # Sort the array in ascending order
        nums.sort()
        # Initialize variables to store the maximum XOR and the corresponding indices
        max_xor = float('-inf')
        max_pair = (-1, -1)
        # Iterate through the array to find the maximum XOR and its corresponding indices
        for i in range(n):
            for j in range(i + 1, n):
                if abs(nums[i] - nums[j]) <= min(nums[i], nums[j]):
                    xor = nums[i] ^ nums[j]
                    if xor > max_xor:
                        max_xor = xor
                        max_pair = (nums[i], nums[j])
        return max_xor

class Solution:
    def largestVariance(self, s: str) -> int:
        max_variance = 0
        unique_chars = set(s)

        for x in unique_chars:
            for y in unique_chars:
                if x == y:
                    continue

                variance = 0
                has_y = False
                for char in s:
                    if char == x:
                        variance += 1
                    elif char == y:
                        variance -= 1
                        has_y = True

                    if variance < 0:
                        variance = 0
                        has_y = False

                    if has_y:
                        max_variance = max(max_variance, variance)

        return max_variance

class Solution:
    def getDescentPeriods(self, prices: List[int]) -> int:
        if len(prices) == 1:
            return 1

        count = 1
        for i in range(1, len(prices)):
            if prices[i-1] == prices[i]-1:
                count += 1
            else:
                count = 1

        return sum(count for count in counts)

class Solution:
    def minTransfers(self, transactions: List[List[int]]) -> int:
        # Count the net balance for each person
        balances = [0]
        for i in range(12):
            balances.append(balances[-1])
            for j in range(len(transactions)):
                if transactions[j][0] == i:
                    balances[-1] -= transactions[j][2]
                elif transactions[j][1] == i:
                    balances[-1] += transactions[j][2]

        # Sort the balances in descending order
        balances.sort(reverse=True)

        # Helper function to perform DFS
        def dfs(start, current_transfers):
            if start >= len(balances):
                return current_transfers

            # Skip the current transaction
            result = dfs(start + 1, current_transfers)

            # Try to transfer the current balance to the next person
            for i in range(start + 1, len(balances)):
                if balances[i] > 0 and balances[start] < 0:
                    balances[i] -= balances[start]
                    result = min(result, dfs(i + 1, current_transfers + 1))
                    balances[i] += balances[start]

            return result

        # Start the DFS from the first person
        return dfs(0, 0)

class Solution:
    def hasTrailingZeros(self, nums: List[int]) -> bool:
