class Solution:
    def kBigIndices(self, nums: List[int], k: int) -> int:
        count = 0
        n = len(nums)

        # Count the number of indices where there are at least k different elements
        for i in range(n):
            count += sum(1 for j in range(i + 1, n) if len(set(nums[j:i+1])) >= k)

        return count

class Solution:
    def xorAllNums(self, nums1: List[int], nums2: List[int]) -> int:
        # If the length of nums1 is even, then the XOR of all elements in nums1 will cancel out.
        # Similarly, if the length of nums2 is even, then the XOR of all elements in nums2 will cancel out.
        # If both lengths are odd, then the XOR of all elements in nums1 will XOR with the XOR of all elements in nums2.
        return reduce(xor, nums1) if len(nums2) % 2 else reduce(xor, nums2) if len(nums1) % 2 else reduce(xor, nums1) ^ reduce(xor, nums2)

from typing import List

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:
        INF = float('inf')
        dp = [[[INF] * (n + 1) for _ in range(target + 1)] for _ in range(m)]

        for i in range(n):
            dp[0][1][i+1] = cost[0][i] if houses[0] == 0 else INF

        for i in range(1, m):
            for t in range(1, min(i + 2, target + 1)):
                for c in range(1, n + 1):
                    if houses[i] != 0 and houses[i] != c:
                        continue
                    dp[i][t][c] = min(dp[i-1][t-1][c] if houses[i-1] != c else INF, dp[i-1][t][c])
                    if houses[i-1] == c:
                        dp[i][t][c] += cost[i][c-1]
                    elif houses[i-1] != 0:
                        dp[i][t][c] += min(cost[i][j-1] for j in range(1, n + 1))

        ans = min(dp[m-1][target][c] for c in range(1, n + 1))
        return ans if ans < INF else -1

