import heapq

class Solution:
    def leftmostBuildingQueries(self, heights: List[int], queries: List[List[int]]) -> List[int]:
        n = len(heights)
        m = len(queries)
        ans = [-1] * m
        pending = [[] for _ in range(n)]

        for qi, (a, b) in enumerate(queries):
            if a > b:
                a, b = b, a
            if a == b or heights[a] < heights[b]:
                ans[qi] = b
            else:
                pending[b].append((heights[a], qi))

        max_heap = []
        for i in range(n-1, -1, -1):
            while max_heap and -max_heap[0][0] < heights[i]:
                _, qi = heapq.heappop(max_heap)
                ans[qi] = i
            for h, qi in pending[i]:
                if ans[qi] == -1:
                    heapq.heappush(max_heap, (-h, qi))

        return ans

