class Solution:
    def mostPoints(self, questions: List[List[int]]) -> int:
        n = len(questions)
        dp = [0] * (n+1)
        for i in range(n-1, -1, -1):
            if i + questions[i][1] + 1 < n:
                dp[i] = max(dp[i], dp[i + questions[i][1] + 1] + questions[i][0])
            else:
                dp[i] = dp[i] + questions[i][0]
        return dp[0]

