class Solution:
    def isCousins(self, root: Optional[TreeNode], x: int, y: int) -> bool:
        def find_node(node, target, parent, depth):
            if not node:
                return None, None
            if node.val == target:
                return parent, depth
            left_parent, left_depth = find_node(node.left, target, node, depth + 1)
            if left_parent:
                return left_parent, left_depth
            return find_node(node.right, target, node, depth + 1)

        parent_x, depth_x = find_node(root, x, None, 0)
        parent_y, depth_y = find_node(root, y, None, 0)

        return depth_x == depth_y and parent_x != parent_y

