class Solution:
    def catchMaximumAmountofPeople(self, team: List[int], dist: int) -> int:
        n = len(team)
        caught = 0
        i, j = 0, 0

        while i < n and j < n:
            if team[i] == 0:
                # Find the first '1' within the range [i - dist, i + dist]
                while j < n and (team[j] == 0 or j < i - dist or j > i + dist):
                    j += 1
                if j < n and team[j] == 1 and i - dist <= j <= i + dist:
                    caught += 1
                    j += 1
                i += 1
            else:
                i += 1

        return caught

