class Solution:
    def minCost(self, basket1: List[int], basket2: List[int]) -> int:
        count = Counter(basket1) + Counter(basket2)
        target = {fruit: cnt // 2 for fruit, cnt in count.items() if cnt % 2 == 0}

        if len(target) * 2 != len(basket1):
            return -1

        excess1 = sorted([fruit for fruit in basket1 if target[fruit] > 0 and (count[fruit] - target[fruit] * 2) % 2 == 1])
        excess2 = sorted([fruit for fruit in basket2 if target[fruit] > 0 and (count[fruit] - target[fruit] * 2) % 2 == 1], reverse=True)

        min_fruit = min(count.keys())
        swaps = [(min(excess1[i], excess2[i]), min_fruit * 2) for i in range(len(excess1))]

        return sum(min(swap) for swap in swaps)

class Solution:
    def makeSmallestPalindrome(self, s: str) -> str:
        # Find the first non-palindromic character
        for i in range(len(s)):
            if s[i] != s[-i-1]:
                # Replace the non-palindromic character with the smallest character
                s[i], s[-i-1] = s[-i-1], s[i]
                break

        return s

class Solution:
    def makeAntiPalindrome(self, s: str) -> str:
        from collections import Counter

        n = len(s)
        count = Counter(s)
        chars = sorted(count.items())

        # If the most frequent character appears more than half the length of the string, it's impossible
        if chars[-1][1] > n // 2:
            return "-1"

        result = [''] * n
        index = 0

        # Fill the first half of the result array
        for char, freq in chars:
            for _ in range(min(freq, (n + 1) // 2 - index)):
                result[index] = char
                index += 1

        # Fill the second half of the result array
        index = n - 1
        for char, freq in reversed(chars):
            for _ in range(min(freq, n // 2 - (n - 1 - index))):
                result[index] = char
                index -= 1

        # Ensure the result is an anti-palindrome
        for i in range(n // 2):
            if result[i] == result[n - i - 1]:
                # Find a character to swap
                for j in range(n):
                    if j != i and j != n - i - 1 and result[j] != result[n - i - 1]:
                        result[j], result[n - i - 1] = result[n - i - 1], result[j]
                        break

        return ''.join(result)

class Solution:
    def findRedundantDirectedConnection(self, edges: List[List[int]]) -> List[int]:
        n = len(edges)
        parent = [0] * (n + 1)
        candidate1 = candidate2 = -1

        # Step 1: Check for a node with two parents
        for u, v in edges:
            if parent[v] != 0:
                candidate1 = [parent[v], v]
                candidate2 = [u, v]
                # Remove the second edge temporarily
                edges.remove([u, v])
            else:
                parent[v] = u

        # Step 2: Check for cycles using union-find
        uf = UnionFind(n + 1)
        for u, v in edges:
            if not uf.union(u, v):
                if candidate1 == -1:
                    return [u, v]
                else:
                    return candidate1
        return candidate2

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX == rootY:
            return False
        self.parent[rootY] = rootX
        return True

