class Solution:
    def maxPotholes(self, road: str, budget: int) -> int:
        n = len(road)
        i = 0
        count = 0

        while i < n:
            if road[i] == 'x':
                j = i
                while j < n and road[j] == 'x':
                    j += 1
                count += j - i
                i = j
            else:
                i += 1

        return min(count, budget)

