class Solution:
    def getSkyline(self, buildings: List[List[int]]) -> List[List[int]]:
        events = []
        for left, right, height in buildings:
            events.append((left, -height, right))
            events.append((right, 0, 0))
        events.sort()

        res = [[0, 0]]
        max_heap = [(0, float('inf'))]
        for left, neg_height, right in events:
            while left >= max_heap[0][1]:
                heapq.heappop(max_heap)
            if neg_height:
                heapq.heappush(max_heap, (neg_height, right))
            if res[-1][1] != -max_heap[0][0]:
                res.append([left, -max_heap[0][0]])
        return res[1:]

class Solution:
    def parseBoolExpr(self, expression: str) -> bool:
        def evaluate(expr):
            if expr == 't':
                return True
            elif expr == 'f':
                return False
            elif expr[0] == '!':
                return not evaluate(expr[2:-1])
            else:
                operator = expr[0]
                sub_exprs = []
                balance = 0
                start = 2
                for i in range(2, len(expr) - 1):
                    if expr[i] == '(':
                        balance += 1
                    elif expr[i] == ')':
                        balance -= 1
                    elif expr[i] == ',' and balance == 0:
                        sub_exprs.append(expr[start:i])
                        start = i + 1
                sub_exprs.append(expr[start:-1])

                if operator == '&':
                    return all(evaluate(sub_expr) for sub_expr in sub_exprs)
                elif operator == '|':
                    return any(evaluate(sub_expr) for sub_expr in sub_exprs)

        return evaluate(expression)

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
from collections import defaultdict, deque

class Solution:
    def findClosestLeaf(self, root: Optional[TreeNode], k: int) -> int:
        if not root.left and not root.right:
            return root.val

        graph = defaultdict(list)

        def build_graph(node):
            if node.left:
                graph[node.val].append(node.left.val)
                graph[node.left.val].append(node.val)
                build_graph(node.left)
            if node.right:
                graph[node.val].append(node.right.val)
                graph[node.right.val].append(node.val)
                build_graph(node.right)

        build_graph(root)

        queue = deque([k])
        visited = set()

        while queue:
            current = queue.popleft()
            visited.add(current)

            if len(graph[current]) == 1 and current != root.val:
                return current

            for neighbor in graph[current]:
                if neighbor not in visited:
                    queue.append(neighbor)

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        # check if all rows are palindromic
        for i in range(len(grid)):
            if not self.is_palindrome(grid[i]):
                return len(grid) - i

        # check if all columns are palindromic
        for j in range(len(grid[0])):
            if not self.is_palindrome([row[j] for row in grid]):
                return len(grid[0]) - j

        # if both rows and columns are palindromic, return 0
        return 0

    def is_palindrome(self, arr):
        left, right = 0, len(arr) - 1
        while left < right:
            if arr[left] != arr[right]:
                return False
            left += 1
            right -= 1
        return True

