class Solution:
    def minFallingPathSum(self, matrix: List[List[int]]) -> int:
        m, n = len(matrix), len(matrix[0])

        # Initialize DP table with same size as input matrix
        dp = [[float('inf')] * n for _ in range(m)]

        # Base case: the first row's elements remain unchanged
        for j in range(n):
            dp[0][j] = matrix[0][j]

        # Fill the DP table starting from the second row
        for i in range(1, m):
            for j in range(n):
                # Calculate the minimum path sum for each cell in the current row
                if j == 0:
                    dp[i][j] = matrix[i][j] + min(dp[i-1][j], dp[i-1][j+1])
                elif j == n-1:
                    dp[i][j] = matrix[i][j] + min(dp[i-1][j-1], dp[i-1][j])
                else:
                    dp[i][j] = matrix[i][j] + min(dp[i-1][j-1], dp[i-1][j], dp[i-1][j+1])

        # The minimum falling path sum will be the smallest value in the last row of the DP table
        return min(dp[-1])

from typing import List

class Solution:
    def possibleToStamp(self, grid: List[List[int]], stampHeight: int, stampWidth: int) -> bool:
        m, n = len(grid), len(grid[0])

        # Create a prefix sum array for the grid
        prefix_sum = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                prefix_sum[i][j] = grid[i - 1][j - 1] + prefix_sum[i - 1][j] + prefix_sum[i][j - 1] - prefix_sum[i - 1][j - 1]

        # Create a grid to mark where stamps can be placed
        stampable = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(stampHeight, m + 1):
            for j in range(stampWidth, n + 1):
                if prefix_sum[i][j] - prefix_sum[i - stampHeight][j] - prefix_sum[i][j - stampWidth] + prefix_sum[i - stampHeight][j - stampWidth] == 0:
                    stampable[i - stampHeight + 1][j - stampWidth + 1] = 1

        # Create a prefix sum array for the stampable grid
        stamp_prefix_sum = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                stamp_prefix_sum[i][j] = stampable[i - 1][j - 1] + stamp_prefix_sum[i - 1][j] + stamp_prefix_sum[i][j - 1] - stamp_prefix_sum[i - 1][j - 1]

        # Check if every empty cell is covered by at least one stamp
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if grid[i - 1][j - 1] == 0:
                    if stamp_prefix_sum[min(i, m - stampHeight + 1)][min(j, n - stampWidth + 1)] - stamp_prefix_sum[min(i, m - stampHeight + 1)][j - stampWidth] - stamp_prefix_sum[i - stampHeight][min(j, n - stampWidth + 1)] + stamp_prefix_sum[i - stampHeight][j - stampWidth] == 0:
                        return False
        return True

class Solution:
    def mostFrequentEven(self, nums: List[int]) -> int:
        count = {}
        for num in nums:
            if num % 2 == 0:
                count[num] = count.get(num, 0) + 1

        max_count = 0
        result = -1

        for num, freq in count.items():
            if freq > max_count:
                max_count = freq
                result = num

        return result

class Solution:
    def nearestPalindromic(self, n: str) -> str:
        length = len(n)
        candidates = set()

        # Edge case: 10...01, 9...9
        candidates.add('1' + '0' * (length - 1) + '1')
        candidates.add('9' * (length - 1))
        if length > 1:
            candidates.add('9' * length)

        # Mirror the first half to create a palindrome
        prefix = int(n[:(length + 1) // 2])
        for i in range(prefix - 1, prefix + 2):
            if length % 2 == 0:
                candidate = str(i) + str(i)[::-1]
            else:
                candidate = str(i)[:-1] + str(i)[::-1]
            candidates.add(candidate)

        # Remove the original number if it's in the set
        num = int(n)
        candidates.discard(n)

        # Find the closest palindrome
        closest = None
        for candidate in candidates:
            candidate = int(candidate)
            if closest is None or abs(candidate - num) < abs(closest - num) or (abs(candidate - num) == abs(closest - num) and candidate < closest):
                closest = candidate

        return str(closest)

class Solution:
    def canMakeSubsequence(self, str1: str, str2: str) -> bool:
        # Initialize pointers for both strings
        i, j = 0, 0

        # Iterate through both strings
        while i < len(str1) and j < len(str2):
            # If current characters match, move both pointers
            if str1[i] == str2[j]:
                i += 1
                j += 1
            # Otherwise, move the pointer in str1
            else:
                i += 1

        # Check if all characters of str2 have been processed
        return j == len(str2)

class Solution:
    def champagneTower(self, poured: int, query_row: int, query_glass: int) -> float:
        dp = [poured] + [0] * query_row

        for row in range(1, query_row + 1):
            for col in range(row, -1, -1):
                if dp[col] > 1:
                    dp[col] = (dp[col] - 1) / 2
                    if col > 0:
                        dp[col - 1] += dp[col]

        return min(dp[query_glass], 1)

from typing import List

class Solution:
    def survivedRobotsHealths(self, positions: List[int], healths: List[int], directions: str) -> List[int]:
        n = len(positions)
        robots = sorted(range(n), key=lambda i: positions[i])
        stack = []

        for i in robots:
            if directions[i] == 'R':
                stack.append(i)
            else:
                while stack and healths[i] > 0:
                    j = stack[-1]
                    if healths[j] < healths[i]:
                        healths[i] -= 1
                        healths[stack.pop()] = 0
                    elif healths[j] > healths[i]:
                        healths[j] -= 1
                        healths[i] = 0
                        stack.pop()
                    else:
                        healths[i] = 0
                        healths[stack.pop()] = 0

        return [health for health in healths if health > 0]

