class Solution:
    def maxPointsInsideSquare(self, points: List[List[int]], s: str) -> int:
        max_points = 0
        n = len(points)

        for i in range(n):
            x1, y1 = abs(points[i][0]), abs(points[i][1])
            tag1 = s[i]
            count = 1

            for j in range(n):
                if i != j:
                    x2, y2 = abs(points[j][0]), abs(points[j][1])
                    tag2 = s[j]
                    if x2 <= x1 and y2 <= y1 and tag2 != tag1:
                        count += 1

            max_points = max(max_points, count)

        return max_points

