class Solution:
    def findMaximumElegance(self, items: List[List[int]], k: int) -> int:
        items.sort(reverse=True, key=lambda x: x[0])
        selected = []
        duplicates = []
        unique_categories = set()

        for i in range(k):
            profit, category = items[i]
            if category not in unique_categories:
                unique_categories.add(category)
                selected.append(profit)
            else:
                duplicates.append(profit)

        max_elegance = sum(selected) + len(unique_categories) ** 2

        for i in range(k, len(items)):
            if not duplicates:
                break
            if items[i][1] in unique_categories:
                continue

            unique_categories.add(items[i][1])
            sum_selected = sum(selected) - duplicates.pop() + items[i][0]
            max_elegance = max(max_elegance, sum_selected + len(unique_categories) ** 2)

        return max_elegance

class Solution:
    def validSubarraySize(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        left = [0] * n
        right = [n] * n
        stack = []

        # Fill left array
        for i in range(n):
            while stack and nums[stack[-1]] >= nums[i]:
                stack.pop()
            if stack:
                left[i] = stack[-1] + 1
            stack.append(i)

        stack = []

        # Fill right array
        for i in range(n-1, -1, -1):
            while stack and nums[stack[-1]] >= nums[i]:
                stack.pop()
            if stack:
                right[i] = stack[-1]
            stack.append(i)

        # Check for valid subarray
        for i in range(n):
            length = right[i] - left[i]
            if nums[i] > threshold // length:
                return length

        return -1

from collections import Counter

class Solution:
    def minimumDeletions(self, word: str, k: int) -> int:
        freqs = sorted(Counter(word).values())
        ans = float('inf')
        for i in range(len(freqs)):
            if freqs[i] == 0:
                continue
            max_freq = freqs[-1]
            min_freq = freqs[i]
            if min_freq + k >= max_freq:
                break
            deletions = sum(freqs[:i]) + sum(max(0, f - min_freq - k) for f in freqs[i:])
            ans = min(ans, deletions)
        return ans

