class Solution:
    def countUnivalSubtrees(self, root: Optional[TreeNode]) -> int:
        def is_unival(node):
            if not node:
                return True, 0

            left_is_unival, left_count = is_unival(node.left)
            right_is_unival, right_count = is_unival(node.right)

            if left_is_unival and right_is_unival:
                if (node.left is None or node.left.val == node.val) and (node.right is None or node.right.val == node.val):
                    return True, 1 + left_count + right_count

            return False, left_count + right_count

        _, count = is_unival(root)
        return count

