class Solution:
    def countValidWords(self, sentence: str) -> int:
        import re
        pattern = re.compile(r'^[a-z]*([a-z]-[a-z]+)?[!\\\\.,]?$')
        return sum(1 for word in sentence.split() if pattern.match(word))

