class Solution:
    def isPossibleDivide(self, nums: List[int], k: int) -> bool:
        # Count the occurrences of each number in the array
        count = Counter(nums)

        # Sort the numbers to process them in order
        sorted_nums = sorted(count.keys())

        for num in sorted_nums:
            if count[num] > 0:
                # Try to form a sequence starting from num
                for i in range(k):
                    if count[num + i] == 0:
                        return False
                    count[num + i] -= 1

        return True

