class Solution:
    def getFactors(self, n: int) -> List[List[int]]:
        if n <= 3:
            return []

        factors = []
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                factors.append([i, n // i])
                for sub_factors in self.getFactors(n // i):
                    factors.append([i] + sub_factors)

        return factors

class Solution:
    def longestAwesome(self, s: str) -> int:
        # Initialize the result and a dictionary to store the last occurrence of each bitmask
        res, d = 0, {0: -1}
        mask = 0

        for i, c in enumerate(s):
            # Update the bitmask by toggling the bit corresponding to the current digit
            mask ^= 1 << int(c)

            # Check if there exists a prefix with the same bitmask or with a bitmask that differs by exactly one bit
            for j in range(10):
                if mask ^ (1 << j) in d:
                    res = max(res, i - d[mask ^ (1 << j)])

            # Update the last occurrence of the current bitmask
            d[mask] = i

        return res

from typing import List

class Solution:
    def deleteDuplicateFolder(self, paths: List[List[str]]) -> List[List[str]]:
        from collections import defaultdict

        # Build the tree structure
        root = {}
        for path in paths:
            current = root
            for folder in path:
                if folder not in current:
                    current[folder] = {}
                current = current[folder]

        # Serialize subtrees to detect duplicates
        def serialize(node):
            if not node:
                return ""
            parts = []
            for key in sorted(node.keys()):
                parts.append(f"{key}({serialize(node[key])})")
            serialized = ",".join(parts)
            if serialized:
                subtree_count[serialized].append(node)
            return serialized

        subtree_count = defaultdict(list)
        serialize(root)

        # Mark duplicates
        def mark_duplicates(node):
            if not node:
                return
            for key in list(node.keys()):
                if len(subtree_count[serialize(node[key])]) > 1:
                    del node[key]
                else:
                    mark_duplicates(node[key])

        mark_duplicates(root)

        # Collect remaining paths
        def collect_paths(node, path):
            if not node:
                return
            for key in node.keys():
                result.append(path + [key])
                collect_paths(node[key], path + [key])

        result = []
        collect_paths(root, [])
        return result

class Solution:
    def captureForts(self, forts: List[int]) -> int:
        max_captured = 0

        for i in range(len(forts)):
            if forts[i] != 0:
                # Check if the next position is an enemy fort
                if i + 1 < len(forts) and forts[i + 1] != 0 and forts[i] * forts[i + 1] == -1:
                    # Calculate the distance between the two forts
                    distance = i + 1 - i - 1
                    # Update the maximum captured forts
                    max_captured = max(max_captured, distance)

        return max_captured

