class Solution:
    def largestSumOfAverages(self, nums: List[int], k: int) -> float:
        n = len(nums)
        prefix_sum = [0] * (n + 1)

        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        dp = [[0.0] * (k + 1) for _ in range(n + 1)]

        for i in range(1, n + 1):
            dp[i][1] = prefix_sum[i] / i

        for j in range(2, k + 1):
            for i in range(j, n + 1):
                for x in range(j - 1, i):
                    dp[i][j] = max(dp[i][j], dp[x][j - 1] + (prefix_sum[i] - prefix_sum[x]) / (i - x))

        return dp[n][k]

class Solution:
    def removeComments(self, source: List[str]) -> List[str]:
        ans = []
        i = 0
        n = len(source)
        while i < n:
            if source[i].find('//') != -1:
                j = source[i].find('//')
                if j == 0:
                    i += 1
                else:
                    source[i] = source[i][:j]
                    i += 1
            elif source[i].find('/*') != -1:
                j = source[i].find('/*')
                k = source[i].find('*/')
                if k == -1:
                    while i < n and source[i].find('*/') == -1:
                        i += 1
                    if i == n:
                        break
                    else:
                        i += 1
                else:
                    source[i] = source[i][:j] + source[i][k+2:]
                    i += 1
            else:
                ans.append(source[i])
                i += 1
        return ans

class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        min_left = float('inf')
        min_right = float('inf')
        res = float('inf')

        for i in range(1, len(nums)-1):
            if nums[i] > min_left:
                min_right = min(min_right, nums[-1]-nums[i])
                res = min(res, min_left+nums[i]+min_right)
            min_left = min(min_left, nums[i])

        return res if res != float('inf') else -1

