class Solution:
    def maxDotProduct(self, nums1: List[int], nums2: List[int]) -> int:
        n1, n2 = len(nums1), len(nums2)
        dp = [[0] * n2 for _ in range(n1)]

        # Initialize the first row
        for i in range(n1):
            dp[i][0] = nums1[i] * nums2[0]

        # Initialize the first column
        for j in range(n2):
            dp[0][j] = nums1[0] * nums2[j]

        # Fill the DP table
        for i in range(1, n1):
            for j in range(1, n2):
                dp[i][j] = max(nums1[i] * nums2[j], dp[i - 1][j], dp[i][j - 1])

        return dp[n1 - 1][n2 - 1]

class Solution:
    def maxJumps(self, arr: List[int], d: int) -> int:
        n = len(arr)
        dp = [1] * n

        for i in range(1, n):
            for j in range(i - d, i + d + 1):
                if 0 <= j < n and arr[j] > arr[i]:
                    dp[i] = max(dp[i], dp[j] + 1)

        return max(dp)

class Solution:
    def distinctSubseqII(self, s: str) -> int:
        n = len(s)
        MOD = 10**9 + 7

        # Initialize dp table with zeros
        dp = [[0] * n for _ in range(n)]

        # Base case: there's one way to have an empty subsequence
        for i in range(n):
            dp[i][i] = 1

        # Fill the dp table
        for i in range(1, n):
            for j in range(i):
                # If characters at j and i are different, add the number of subsequences ending at j plus the number of subsequences ending at i-1
                dp[i][j] = (dp[i][j] + dp[j+1][i]) % MOD

        # The number of distinct subsequences is the sum of the number of subsequences ending at each position
        return sum(dp[-1])

