class Solution:
    def maxSumAfterPartitioning(self, arr: List[int], k: int) -> int:
        n = len(arr)
        dp = [0] * (n + 1)

        for i in range(1, n + 1):
            cur_max = float('-inf')
            for j in range(i - k + 1, i + 1):
                cur_max = max(cur_max, arr[j - 1])
                dp[i] = max(dp[i], dp[j - 1] + cur_max * (i - j + 1))

        return dp[n]

