from collections import deque

class Solution:
    def shortestBridge(self, grid: List[List[int]]) -> int:
        n = len(grid)
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        first_island = deque()

        def dfs(x, y):
            grid[x][y] = 2
            first_island.append((x, y))
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 1:
                    dfs(nx, ny)

        found = False
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1 and not found:
                    dfs(i, j)
                    found = True

        steps = 0
        while first_island:
            size = len(first_island)
            for _ in range(size):
                x, y = first_island.popleft()
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < n:
                        if grid[nx][ny] == 1:
                            return steps
                        elif grid[nx][ny] == 0:
                            grid[nx][ny] = 2
                            first_island.append((nx, ny))
            steps += 1

        return steps

class Solution:
    def isNumber(self, s: str) -> bool:
        s = s.strip()
        if not s:
            return False

        point_seen = False
        e_seen = False
        num_seen = False

        for i, char in enumerate(s):
            if char.isdigit():
                num_seen = True
            elif char == '.':
                if point_seen or e_seen:
                    return False
                point_seen = True
            elif char in ('+', '-'):
                if i != 0 and s[i-1] != 'e':
                    return False
            elif char in ('e', 'E'):
                if e_seen or not num_seen:
                    return False
                e_seen = True
                num_seen = False  # Reset num_seen for the exponent part
            else:
                return False

        return num_seen

