from collections import defaultdict

class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        # Build the adjacency list representation of the graph
        graph = defaultdict(list)
        for course, prereq in prerequisites:
            graph[prereq].append(course)

        # Initialize the visited set and recursion stack
        visited = set()
        stack = []

        # Helper function to perform DFS
        def dfs(course):
            # If the course has already been visited, there's a cycle
            if course in visited:
                return False
            # Mark the course as visited and add it to the stack
            visited.add(course)
            stack.append(course)

            # Recur for all adjacent courses
            for neighbor in graph[course]:
                if not dfs(neighbor):
                    return False

            # Pop the current course from the stack
            stack.pop()
            return True

        # Perform DFS for each course
        for course in range(numCourses):
            if not dfs(course):
                return False

        return True

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not any(c in s1 for c in s2):
            return 0

        count, index = 0, 0
        memory = {}

        for i in range(n1):
            for char in s1:
                if char == s2[index]:
                    index += 1
                    if index == len(s2):
                        count += 1
                        index = 0

            if index in memory:
                break
            memory[index] = (count, i)

        if index not in memory:
            return count // n2

        prev_count, prev_index = memory[index]
        cycle_count = (n1 - prev_index - 1) // (i - prev_index)
        cycle_occurrences = count - prev_count
        remaining_count = prev_count + cycle_count * cycle_occurrences

        remaining_n1 = (n1 - prev_index - 1) % (i - prev_index)
        for j in range(remaining_n1):
            for char in s1:
                if char == s2[index]:
                    index += 1
                    if index == len(s2):
                        remaining_count += 1
                        index = 0

        return remaining_count // n2

class Solution:
    def findWords(self, board: List[List[str]], words: List[str]) -> List[str]:
        if not board or not board[0]:
            return []

        m, n = len(board), len(board[0])
        Trie = {}
        for word in words:
            node = Trie
            for char in word:
                if char not in node:
                    node[char] = {}
                node = node[char]
            node['#'] = word

        result = []
        visited = [[False] * n for _ in range(m)]

        def dfs(x, y, trie_node):
            char = board[x][y]
            if char not in trie_node:
                return

            next_node = trie_node[char]
            if '#' in next_node:
                result.append(next_node['#'])
                del next_node['#']

            visited[x][y] = True
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                    dfs(nx, ny, next_node)
            visited[x][y] = False

            if not next_node:
                del trie_node[char]

        for i in range(m):
            for j in range(n):
                dfs(i, j, Trie)

        return result

class Solution:
    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        return pairs

class Solution:
    def areSimilar(self, mat: List[List[int]], k: int) -> bool:
        n = len(mat)
        m = len(mat[0])

        for i in range(n):
            if i % 2 == 0:
                # Even-indexed row
                expected = mat[i]
                actual = mat[i][k:] + mat[i][:k]
            else:
                # Odd-indexed row
                expected = mat[i]
                actual = mat[i][-k:] + mat[i][:-k]

            if expected != actual:
                return False

        return True

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def diameterOfBinaryTree(self, root: Optional[TreeNode]) -> int:
        # Calculate the depth of the left and right subtrees
        l_depth = self.depth(root.left)
        r_depth = self.depth(root.right)

        # Calculate the diameter of the current subtree
        diameter = l_depth + r_depth

        # Return the maximum diameter found so far
        return max(diameter, l_depth + r_depth)

    def depth(self, node):
        if not node:
            return 0
        return 1 + max(self.depth(node.left), self.depth(node.right))

class Solution:
    def findTarget(self, root: Optional[TreeNode], k: int) -> bool:
        if not root:
            return False

        # Use a set to store values encountered so far
        seen = set()

        def dfs(node):
            if not node:
                return False

            # Check if the complement of the current node's value exists in the set
            if k - node.val in seen:
                return True

            # Add the current node's value to the set
            seen.add(node.val)

            # Recur on the left and right subtrees
            return dfs(node.left) or dfs(node.right)

        return dfs(root)

class Solution:
    def strongPasswordChecker(self, password: str) -> int:
        n = len(password)

        # Check for length
        if n < 6:
            return max(6 - n, 3 - sum(c.islower() or c.isupper() or c.isdigit() for c in password))
        elif n > 20:
            count = 0
            for i in range(3, n + 1):
                count += i // 3
            return count + max(n - 20, 3 - sum(c.islower() or c.isupper() or c.isdigit() for c in password))

        # Check for complexity
        lower = any(c.islower() for c in password)
        upper = any(c.isupper() for c in password)
        digit = any(c.isdigit() for c in password)
        if lower and upper and digit:
            return 0

        # Count repeating characters
        repeat_count = {}
        for i in range(n):
            if i > 0 and password[i] == password[i - 1]:
                repeat_count[password[i]] = repeat_count.get(password[i], 0) + 1
            else:
                repeat_count[password[i]] = 1

        # Calculate steps
        steps = 0
        for count in repeat_count.values():
            if count >= 3:
                steps += count // 3
                if count % 3 == 0:
                    steps -= 1

        # Insert characters to meet complexity requirements
        if not lower:
            steps += 1
        if not upper:
            steps += 1
        if not digit:
            steps += 1

        return steps

class Solution:
    def categorizeBox(self, length: int, width: int, height: int, mass: int) -> str:
