class Solution:
    def tripletCount(self, a: List[int], b: List[int], c: List[int]) -> int:
        count = 0
        for i in range(len(a)):
            for j in range(i + 1, len(b)):
                for k in range(j + 1, len(c)):
                    if (a[i] & b[j] & c[k]) % 2 == 0:
                        count += 1
        return count

class Solution:
    def isIsomorphic(self, s: str, t: str) -> bool:
        # Create a dictionary to store the mapping of characters from s to t
        char_map = {}

        # Iterate over the characters in s
        for i in range(len(s)):
            # If the character is already in the dictionary, check if the mapping is correct
            if s[i] in char_map and char_map[s[i]] != t[i]:
                return False
            # Otherwise, add the character to the dictionary with its corresponding value
            char_map[s[i]] = t[i]

        # If all characters are mapped correctly, return True
        return True

class Solution:
    def maximumNumber(self, num: str, change: List[int]) -> str:
        result = []
        i = 0
        n = len(num)
        while i < n:
            if int(num[i]) >= change[int(num[i])]:
                result.append(num[i])
                i += 1
            else:
                start = i
                while i < n and int(num[i]) < change[int(num[i])]:
                    result.append(str(change[int(num[i])]))
                    i += 1
                result.extend(num[i:])
                break
        return ''.join(result)

from math import gcd

class Solution:
    def minimumSplits(self, nums: List[int]) -> int:
        if not nums:
            return 0

        # Calculate the GCD of all numbers in the array
        total_gcd = nums[0]
        for num in nums:
            total_gcd = gcd(total_gcd, num)

        # If the total GCD is 1, it means all numbers have the same prime factorization
        if total_gcd == 1:
            return len(nums)

        # Otherwise, we need to split the array at least once to get a non-trivial subarray
        return 1

class Solution:
    def minimumOperations(self, num: str) -> int:
        # Initialize the count of digits divisible by 25
        count = 0

        # Iterate through each digit in the number
        for digit in num:
            # Check if the digit is divisible by 25
            if int(digit) % 25 == 0:
                # Increment the count
                count += 1

        # Return the count of digits divisible by 25
        return count

class Solution:
    def isReflected(self, points: List[List[int]]) -> bool:
        # Sort the points based on their x-coordinates
        points.sort(key=lambda x: x[0])

        # Find the midpoint of the sorted points
        mid_x = points[len(points) // 2][0]

        # Check if the midpoint is the same for both sets of points
        return all(x[0] == mid_x for x in points)

class Solution:
    def maxRunTime(self, n: int, batteries: List[int]) -> int:
        batteries.sort(reverse=True)
        total_time = sum(batteries)
        for battery in batteries:
            if battery > total_time // n:
                total_time -= battery - total_time // n
                n -= 1
            else:
                break
        return total_time // n

