class Solution:
    def mergeStones(self, stones: List[int], k: int) -> int:
        if len(stones) % k != 0:
            return -1

        # Calculate prefix sum array
        n = len(stones)
        pre_sum = [0] * (n + 1)
        for i in range(1, n + 1):
            pre_sum[i] = pre_sum[i-1] + stones[i-1]

        # Create a memoization table to store results
        dp = [[0] * (n + 1) for _ in range(n + 1)]

        # Fill the memoization table using dynamic programming
        for l in range(2, n + 1):
            for i in range(1, n - l + 2):
                j = i + l - 1
                min_cost = float('inf')
                for m in range(i, j, k):
                    cost = dp[i][m] + dp[m+1][j] + pre_sum[j] - pre_sum[i-1]
                    min_cost = min(min_cost, cost)
                dp[i][j] = min_cost

        return dp[1][n]

class Solution:
    def alphabetBoardPath(self, target: str) -> str:
        result = []
        x, y = 0, 0

        for char in target:
            next_x = (ord(char) - ord('a')) // 5
            next_y = (ord(char) - ord('a')) % 5

            # Move horizontally before vertically to avoid going off the board
            if next_y < y:
                result.append('L' * (y - next_y))
            if next_x < x:
                result.append('U' * (x - next_x))
            if next_x > x:
                result.append('D' * (next_x - x))
            if next_y > y:
                result.append('R' * (next_y - y))

            result.append('!')
            x, y = next_x, next_y

        return ''.join(result)

class Solution:
    def equalFrequency(self, word: str) -> bool:
        # Count the frequency of each character in the word
        char_count = Counter(word)

        # Check if the frequency of any character is odd
        if any(count % 2 != 0 for count in char_count.values()):
            return False

        # Find the smallest frequency
        min_freq = min(char_count.values())

        # Check if removing any character from the word will result in all characters having the same frequency
        for char in char_count:
            if char_count[char] == min_freq:
                # Remove the character and check if the remaining frequencies are equal
                new_char_count = char_count.copy()
                new_char_count[char] -= 1
                if all(count % 2 == 0 for count in new_char_count.values()):
                    return True

        return False

class Solution:
    def levelOrderBottom(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []

        result = []
        queue = deque([root])
        while queue:
            level = []
            for _ in range(len(queue)):
                node = queue.popleft()
                level.append(node.val)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            result.insert(0, level)
        return result

class Solution:
    def findPeakGrid(self, mat: List[List[int]]) -> List[int]:
        m, n = len(mat), len(mat[0])
        def check(i, j):
            directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and mat[ni][nj] > mat[i][j]:
                    return False
            return True

        low, high = 0, m * n - 1
        while low <= high:
            mid = (low + high) // 2
            i, j = divmod(mid, n)
            if check(i, j):
                return [i, j]
            elif mat[i][j] < mat[i + 1][j]:
                low = mid + 1
            else:
                high = mid - 1

