class Solution:
    def maxBoxesInWarehouse(self, boxes: List[int], warehouse: List[int]) -> int:
        # Sort boxes in descending order
        boxes.sort(reverse=True)
        i = j = 0

        for box in boxes:
            while j < len(warehouse) and box > warehouse[j]:
                j += 1
            if j == len(warehouse):
                break
            warehouse[j] -= box
            i += 1

        return i

