class Solution:
    def minFallingPathSum(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 1:
            return grid[0][0]

        # Initialize the first row of dp with the first row of the grid
        dp = grid[0][:]

        for i in range(1, n):
            # Find the two smallest values in the previous row
            min1, min2 = float('inf'), float('inf')
            for num in dp:
                if num < min1:
                    min2 = min1
                    min1 = num
                elif num < min2:
                    min2 = num

            # Update the current row of dp
            for j in range(n):
                if dp[j] == min1:
                    dp[j] = grid[i][j] + min2
                else:
                    dp[j] = grid[i][j] + min1

        return min(dp)

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def smallestFromLeaf(self, root: Optional[TreeNode]) -> str:
        def dfs(node, path):
            if not node:
                return
            # Prepend the current character to the path
            path = chr(97 + node.val) + path
            # If it's a leaf node, return the path
            if not node.left and not node.right:
                return path
            # Recur for left and right subtrees
            left_path = dfs(node.left, path)
            right_path = dfs(node.right, path)
            # Return the lexicographically smaller path
            if left_path and right_path:
                return min(left_path, right_path)
            return left_path or right_path

        return dfs(root, "")

