from collections import deque

class Solution:
    def sumRemoteness(self, grid: List[List[int]]) -> int:
        n = len(grid)
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        def bfs(start_i, start_j):
            queue = deque([(start_i, start_j)])
            visited.add((start_i, start_j))
            total_value = grid[start_i][start_j]
            count = 1

            while queue:
                x, y = queue.popleft()
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] != -1 and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append((nx, ny))
                        total_value += grid[nx][ny]
                        count += 1
            return total_value, count

        total_sum = 0
        visited = set()
        all_values = sum(sum(max(0, val) for val in row) for row in grid)

        for i in range(n):
            for j in range(n):
                if grid[i][j] != -1 and (i, j) not in visited:
                    component_value, component_count = bfs(i, j)
                    total_sum += (all_values - component_value) * component_count

        return total_sum

class Solution:
    def numberOfArithmeticSlices(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Initialize the dp array where dp[i] represents the number of arithmetic slices ending at index i
        dp = [0] * n

        # Iterate through the array starting from the second element
        for i in range(1, n):
            # Calculate the difference between consecutive elements
            diff = nums[i] - nums[i-1]

            # Check if the difference is equal to the previous difference
            if diff == 0:
                # If it is, increment the count of arithmetic slices ending at the current index
                dp[i] += dp[i-1]
            else:
                # Otherwise, add the count of arithmetic slices ending at the previous index plus one
                dp[i] += dp[i-1] + 1

        # Sum up all the counts to get the total number of arithmetic slices
        return sum(dp)

class Solution:
    def numberOfSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0
        max_count = 0

        for i in range(n):
            if nums[i] == nums[n-1]:
                max_count += 1
            else:
                count += max_count * (max_count + 1) // 2
                max_count = 0

        count += max_count * (max_count + 1) // 2

        return count

