import heapq

class Solution:
    def minimumDistance(self, points: List[List[int]]) -> int:
        n = len(points)
        if n < 4:
            return 0

        # Calculate the Manhattan distances between all pairs of points
        dists = []
        for i in range(n):
            for j in range(i+1, n):
                x1, y1 = points[i]
                x2, y2 = points[j]
                dists.append(abs(x1-x2) + abs(y1-y2))

        # Use a min-heap to keep track of the smallest distances
        heap = []
        for d in dists:
            heapq.heappush(heap, d)

        # Remove the largest distance from the heap
        max_dist = heapq.heappop(heap)

        # Calculate the minimum distance after removing the largest distance
        min_dist = float('inf')
        for d in dists:
            if d != max_dist:
                min_dist = min(min_dist, d)

        return min_dist

class Solution:
    def minimumSwaps(self, nums: List[int]) -> int:
        min_val = min(nums)
        max_val = max(nums)
        min_index = nums.index(min_val)
        max_index = nums.index(max_val)
        n = len(nums)
        if min_index > max_index:
            max_index -= 1
        return min_index + (n - 1 - max_index)

class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        res = []
        for c in s:
            d = ord(c) - ord('a')
            if k >= d:
                res.append('a')
                k -= d
            elif k > 0:
                res.append(chr(ord('a') + min(d, k)))
                k = 0
            else:
                res.append(c)
        return ''.join(res)

class Solution:
    def alphabetBoardPath(self, target: str) -> str:
        board = ["abcde", "fghij", "klmno", "pqrst", "uvwxy", "z"]
        pos = {char: (i, j) for i, row in enumerate(board) for j, char in enumerate(row)}

        def get_moves(x1, y1, x2, y2):
            moves = []
            if x1 > x2:
                moves.append('U' * (x1 - x2))
            if y1 < y2:
                moves.append('R' * (y2 - y1))
            if y1 > y2:
                moves.append('L' * (y1 - y2))
            if x1 < x2:
                moves.append('D' * (x2 - x1))
            return ''.join(moves)

        current_x, current_y = 0, 0
        path = []

        for char in target:
            target_x, target_y = pos[char]
            path.append(get_moves(current_x, current_y, target_x, target_y))
            path.append('!')
            current_x, current_y = target_x, target_y

        return ''.join(path)

from typing import List

class Solution:
    def maximumSetSize(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        set1 = set(nums1)
        set2 = set(nums2)
        common = set1.intersection(set2)

        unique_in_1 = min(len(set1) - len(common), n // 2)
        unique_in_2 = min(len(set2) - len(common), n // 2)

        return unique_in_1 + unique_in_2 + len(common)

class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        if sum(colsum) != upper + lower:
            return []

        result = [[0] * n for _ in range(2)]

        for i in range(n):
            if colsum[i] == 2:
                result[0][i] = 1
                result[1][i] = 1
                upper -= 1
                lower -= 1

        for i in range(n):
            if colsum[i] == 1:
                if upper > 0:
                    result[0][i] = 1
                    upper -= 1
                elif lower > 0:
                    result[1][i] = 1
                    lower -= 1

        if upper != 0 or lower != 0:
            return []

        return result

from typing import List

class Solution:
    def maxGeneticDifference(self, parents: List[int], queries: List[List[int]]) -> List[int]:
        from collections import defaultdict

        # Build the tree
        tree = defaultdict(list)
        root = -1
        for i, p in enumerate(parents):
            if p == -1:
                root = i
            else:
                tree[p].append(i)

        # Store queries by node
        node_queries = defaultdict(list)
        for node, val in queries:
            node_queries[node].append(val)

        # Trie to store genetic values
        trie = {}
        cnt = defaultdict(int)

        # Function to insert a number into the trie
        def insert(num):
            node = trie
            for i in range(18, -1, -1):
                bit = (num >> i) & 1
                if bit not in node:
                    node[bit] = {}
                node = node[bit]
                cnt[id(node)] += 1

        # Function to remove a number from the trie
        def remove(num):
            node = trie
            for i in range(18, -1, -1):
                bit = (num >> i) & 1
                node = node[bit]
                cnt[id(node)] -= 1

        # Function to query the maximum XOR with a given number
        def query(num):
            node = trie
            max_xor = 0
            for i in range(18, -1, -1):
                bit = (num >> i) & 1
                toggle_bit = 1 - bit
                if toggle_bit in node and cnt[id(node[toggle_bit])] > 0:
                    max_xor |= (1 << i)
                    node = node[toggle_bit]
                else:
                    node = node[bit]
            return max_xor

        # Result array
        result = [-1] * len(queries)

        # DFS function to traverse the tree and process queries
        def dfs(node):
            insert(node)
            for val in node_queries[node]:
                result[queries.index([node, val])] = query(val)
            for child in tree[node]:
                dfs(child)
            remove(node)

        # Start DFS from the root
        dfs(root)

        return result

class Solution:
    def minCapability(self, nums: List[int], k: int) -> int:
        l, r = 0, max(nums)
        while l < r:
            m = (l+r)//2
            if self.isRobbed(nums, m, k):
                r = m
            else:
                l = m+1
        return l

    def isRobbed(self, nums, cap, k):
        rob, not_rob = 0, 0
        for n in nums:
            if n <= cap:
                rob += 1
            else:
                not_rob += 1
            if rob >= k:
                return True
        return False

class Solution:
    def findLatestTime(self, s: str) -> str:
        # Convert the string to a list for easier manipulation
        time = list(s)

        # Handle the minutes first since they are simpler
        if time[3] == '?':
            time[3] = '5'
        if time[4] == '?':
            time[4] = '9'

        # Now handle the hours
        if time[0] == '?' and time[1] == '?':
            time[0] = '1'
            time[1] = '1'
        elif time[0] == '?':
            if time[1] <= '3':
                time[0] = '1'
            else:
                time[0] = '0'
        elif time[1] == '?':
            if time[0] == '1':
                time[1] = '9'
            else:
                time[1] = '3'

        # Join the list back into a string and return
        return ''.join(time)

class Solution:
    def maxNonOverlapping(self, nums: List[int], target: int) -> int:
        n = len(nums)
        dp = [0] * n

        for i in range(n):
            dp[i] = dp[i - 1] + nums[i]
            if dp[i] == target:
                return i

        return -1

