class Solution:
    def findRepeatedDnaSequences(self, s: str) -> List[str]:
        if len(s) < 10:
            return []

        # Initialize variables
        res = set()
        seen = defaultdict(int)

        # Iterate through the string
        for i in range(len(s) - 9):
            window = s[i:i+10]
            if window in seen:
                res.add(window)
            seen[window] += 1

