class Solution:
    def numberOfSubmatrices(self, grid: List[List[str]]) -> int:
        m, n = len(grid), len(grid[0])
        count = 0

        for i in range(m):
            x_count = [0] * n
            for j in range(i, m):
                y_count = 0
                for k in range(n):
                    if grid[j][k] == 'X':
                        x_count[k] += 1
                    elif grid[j][k] == 'Y':
