class Solution:
    def maxScoreWords(self, words: List[str], letters: List[str], score: List[int]) -> int:
        def word_score(word):
            return sum(score[ord(c) - ord('a')] for c in word)

        def can_form_word(word, available_letters):
            return all(available_letters[c] >= count for c, count in Counter(word).items())

        def backtrack(index, current_score, available_letters):
            if index == len(words):
                return current_score

            # Include the current word
            include_score = backtrack(index + 1, current_score + word_score(words[index]), available_letters - Counter(words[index]))

            # Exclude the current word
            exclude_score = backtrack(index + 1, current_score, available_letters)

            return max(include_score, exclude_score)

        available_letters = Counter(letters)
        return backtrack(0, 0, available_letters)

class Solution:
    def minimumMoves(self, arr: List[int]) -> int:
        n = len(arr)
        dp = [[float('inf')] * n for _ in range(n)]

        # Every single element is a palindrome of length 1
        for i in range(n):
            dp[i][i] = 1

        # Fill the DP table
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if arr[i] == arr[j]:
                    dp[i][j] = dp[i + 1][j - 1]
                else:
                    for k in range(i, j):
                        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

        return dp[0][n - 1]

