class Solution:
    def countSpecialNumbers(self, n: int) -> int:
        def count_with_limit(limit, used):
            if limit == 0:
                return 1
            res = 0
            digit = limit % 10
            for i in range(0, digit):
                if used & (1 << i) == 0:
                    res += perm(10 - len(bin(used)[2:]) + 1, len(str(limit)) - 1)
            if used & (1 << digit) == 0:
                res += count_with_limit(limit // 10, used | (1 << digit))
            return res

        def perm(m, n):
            if n == 0:
                return 1
            return m * perm(m - 1, n - 1)

        def count_without_limit(digits):
            if digits == 1:
                return 9
            return 9 * perm(9, digits - 1)

        num_str = str(n)
        length = len(num_str)
        total = sum(count_without_limit(i) for i in range(1, length))

        used = 0
        for i, char in enumerate(num_str):
            digit = int(char)
            for j in range(0 if i else 1, digit):
                if used & (1 << j) == 0:
                    total += perm(10 - len(bin(used)[2:]) + 1, length - i - 1)
            if used & (1 << digit) != 0:
                break
            used |= (1 << digit)
        else:
            total += 1

        return total

