class Solution:
    def countRectangles(self, rectangles: List[List[int]], points: List[List[int]]) -> List[int]:
        heights = [[] for _ in range(101)]
        for l, h in rectangles:
            heights[h].append(l)
        for ls in heights:
            ls.sort()

        result = []
        for x, y in points:
            count = 0
            for h in range(y, 101):
                idx = bisect_left(heights[h], x - 0.1)
                count += len(heights[h]) - idx
            result.append(count)

        return result

