            if flowerbed[i] == 0:
                if i > 0 and flowerbed[i - 1] == 0:
                    continue
                if i < len(flowerbed) - 1 and flowerbed[i + 1] == 0:
                    continue

                count += 1

                if count >= n:
                    return True

