class Solution:
    def canConvert(self, str1: str, str2: str) -> bool:
        if str1 == str2:
            return True

        # If the lengths are different, they cannot be converted
        if len(str1) != len(str2):
            return False

        # Create a dictionary to store the count of each character in str1
        char_count = {}
        for char in str1:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

        # Check if there are more than two characters with the same count
        max_count = max(char_count.values())
        if max_count > 2:
            return False

        # Check if the difference between the counts of any two characters is greater than 1
        for count1, count2 in zip(sorted(list(char_count.values()), reverse=True), sorted(list(char_count.values()), reverse=True)[1:]):
            if count1 - count2 > 1:
                return False

        return True

