class Solution:
    def generateMatrix(self, n: int) -> List[List[int]]:
        if n == 1:
            return [[1]]

        result = []
        left, right = 0, n - 1
        top, bottom = 0, n - 1

        while left <= right and top <= bottom:
            # Fill the top row
            for i in range(top, bottom + 1):
                result.append([i])

            # Move to the right
            for i in range(bottom, top - 1, -1):
                result.append([i])

            # Move down
            for i in range(right, left - 1, -1):
                result.append([i])

            # Move to the left
            for i in range(left, right + 1):
                result.append([i])

            # Move to the top
            top += 1
            right -= 1
            bottom -= 1

        return result

