class Solution:
    def longestDiverseString(self, a: int, b: int, c: int) -> str:
        from heapq import heappush, heappop, heapify

        # Max heap to store the counts of characters
        max_heap = []
        if a > 0:
            heappush(max_heap, (-a, 'a'))
        if b > 0:
            heappush(max_heap, (-b, 'b'))
        if c > 0:
            heappush(max_heap, (-c, 'c'))

        result = []
        while len(max_heap) >= 2:
            # Get the two most frequent characters
            first_count, first_char = heappop(max_heap)
            second_count, second_char = heappop(max_heap)

            # Append up to 2 of the first character
            append_count = min(-first_count, 2)
            result.append(first_char * append_count)
            first_count += append_count

            # Append one of the second character
            result.append(second_char)
            second_count += 1

            # Push the characters back if they still have remaining counts
            if first_count < 0:
                heappush(max_heap, (first_count, first_char))
            if second_count < 0:
                heappush(max_heap, (second_count, second_char))

        # If there's one character left in the heap, append up to 2 of it
        if max_heap:
            count, char = max_heap[0]
            result.append(char * min(-count, 2))

        return ''.join(result)

# Definition for a binary tree node.
