class Solution:
    def minimumOperations(self, root: Optional[TreeNode]) -> int:
        from collections import deque

        def dfs(node):
            if not node:
                return []

            queue = deque([node])
            levels = []

            while queue:
                level = []
                size = len(queue)

                for _ in range(size):
                    node = queue.popleft()
                    level.append(node.val)

                    if node.left:
                        queue.append(node.left)
                    if node.right:
                        queue.append(node.right)

                levels.append(level)

            return levels

        levels = dfs(root)
        swaps = 0

        for level in levels:
            sorted_level = sorted(level)
            pos = {val: i for i, val in enumerate(sorted_level)}

            for i in range(len(level)):
                if level[i] != sorted_level[i]:
                    swaps += 1
                    level[i], level[pos[level[i]]] = level[pos[level[i]]], level[i]

        return swaps

