class Solution:
    def splitLoopedString(self, strs: List[str]) -> str:
        # Reverse each string if the reversed string is lexicographically larger
        for i in range(len(strs)):
            strs[i] = max(strs[i], strs[i][::-1])

        # Concatenate all strings
        total = ''.join(strs)
        result = ''

        # Try each string as a potential starting point
        for i in range(len(strs)):
            # Consider both the original and reversed version of the current string
            for rev in [False, True]:
                current = strs[i][::-1] if rev else strs[i]
                # Try every possible cut point in the current string
                for j in range(len(current)):
                    # Form the new string by concatenating the part after the cut, the rest of the strings, and the part before the cut
                    candidate = current[j:] + total[len(current):] + current[:j]
                    result = max(result, candidate)

        return result

class Solution:
    def compressedString(self, word: str) -> str:
        if len(word) == 0:
            return ""

        comp = ""
        count = 1

        for i in range(1, len(word)):
            if word[i] == word[i-1]:
                count += 1
            else:
                comp += str(count)
                comp += word[i-1]
                count = 1

        # Append the last group
        comp += str(count)
        comp += word[-1]

        return comp

class Solution:
    def canReach(self, s: str, minJump: int, maxJump: int) -> bool:
        n = len(s)
        dp = [False] * n

        # Initialize the dp array
        dp[0] = True

        # Iterate through the string
        for i in range(1, n):
            # Check if the current index is reachable
            if dp[i - minJump] and s[i] == '0':
                # Update the dp array for the next index
                dp[i] = True

        return dp[n - 1]

class Solution:
    def countPalindromicSubsequences(self, s: str) -> int:
        mod = 10**9 + 7
        n = len(s)
        dp = [[0] * (n+1) for _ in range(n+1)]
        dp[0][0] = 1

        for i in range(1, n+1):
            for j in range(1, n+1):
                if s[i-1] == s[j-1]:
                    dp[i][j] = (dp[i-1][j-1] + dp[i-1][j]) % mod
                else:
                    dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % mod

        return dp[n][n]

