class Solution:
    def knightProbability(self, n: int, k: int, row: int, column: int) -> float:
        if k == 0:
            return 1

        directions = [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]

        @lru_cache(None)
        def dfs(x, y, steps):
            if steps == k:
                return 1

            prob = 0
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n:
                    prob += dfs(nx, ny, steps + 1) / 8

            return prob

        return dfs(row, column, 0)

