class Solution:
    def permuteUnique(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        ans = []
        n = len(nums)

        def dfs(path):
            if len(path) == n:
                ans.append(path[:])
                return

            for i in range(len(nums)):
                if i > 0 and nums[i] == nums[i - 1]:
                    continue

                path.append(nums[i])
                dfs(path)
                path.pop()

        dfs([])
        return ans

