class Solution:
    def canChange(self, start: str, target: str) -> bool:
        l, r = 0, 0
        while l < len(start):
            if start[l] != '_':
                break
            l += 1

        while r < len(target):
            if target[r] != '_':
                break
            r += 1

        if l > r:
            return False

        i, j = l, r
        while i < len(start) and j < len(target):
            if start[i] != target[j]:
                return False

            if start[i] == 'L':
                if i < j:
                    return False
            elif start[i] == 'R':
                if i > j:
                    return False

            i += 1
            j += 1

        if i < len(start) or j < len(target):
            return False

        return True

from heapq import heappush, heappop

class Solution:
    def minMeetingRooms(self, intervals: List[List[int]]) -> int:
        # Sort the intervals based on their start times
        intervals.sort(key=lambda x: x[0])

        # Initialize a heap to keep track of the end times of active meetings
        min_heap = []

        for interval in intervals:
            # If there is an active meeting starting at or before this interval's start time,
            # we can reuse the same room for this interval
            if min_heap and interval[0] >= min_heap[0]:
                heappop(min_heap)

            # Add the end time of this interval to the heap
            heappush(min_heap, interval[1])

        # The size of the heap represents the number of active meetings, which is the minimum number of rooms needed
        return len(min_heap)

