class Solution:
    def minimumOperationsToWriteY(self, grid: List[List[int]]) -> int:
        n = len(grid)
        y_cells = set()
        non_y_cells = set()

        # Identify Y cells
        for i in range(n):
            for j in range(n):
                if (i == j and i <= n // 2) or (i < n // 2 and j == n - 1 - i) or (i >= n // 2 and j == n // 2):
                    y_cells.add((i, j))
                else:
                    non_y_cells.add((i, j))

        # Count occurrences of each value in Y cells and non-Y cells
        y_count = [0] * 3
        non_y_count = [0] * 3

        for i, j in y_cells:
            y_count[grid[i][j]] += 1

        for i, j in non_y_cells:
            non_y_count[grid[i][j]] += 1

        # Calculate the minimum operations needed
        min_operations = float('inf')

        for y_val in range(3):
            for non_y_val in range(3):
                if y_val != non_y_val:
                    operations = (len(y_cells) - y_count[y_val]) + (len(non_y_cells) - non_y_count[non_y_val])
                    min_operations = min(min_operations, operations)

        return min_operations

