class Solution:
    def maxSumBST(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0

        def helper(node):
            nonlocal res
            if not node:
                return float('inf'), float('-inf'), 0

            lmin, lmax, ls = helper(node.left)
            rmin, rmax, rs = helper(node.right)

            if lmax >= node.val or rmin <= node.val:
                return float('-inf'), float('inf'), 0

            sm = node.val + ls + rs
            res = max(res, sm)
            return min(lmin, node.val), max(rmax, node.val), sm

        res = 0
        helper(root)
        return res

