class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        if len(s1) != len(s2):
            return False

        # Base case: if lengths are different, they cannot be scrambled
        if len(s1) == 1:
            return s1 == s2

        # Check if the two strings are already equal
        if s1 == s2:
            return True

        # Check if any permutation of s1 is equal to s2
        for i in range(1, len(s1)):
            if self.isScramble(s1[:i], s2[:i]) and self.isScramble(s1[i:], s2[i:]) or \\\\
               self.isScramble(s1[:i], s2[-i:]) and self.isScramble(s1[i:], s2[:-i]):
                return True

        return False

class Solution:
    def sumOfBeauties(self, nums: List[int]) -> int:
        n = len(nums)
        min_left = [float('inf')] * n
        max_right = [float('-inf')] * n

        # Fill min_left array
        for i in range(1, n):
            min_left[i] = min(min_left[i-1], nums[i-1])

        # Fill max_right array
        for i in range(n-2, -1, -1):
            max_right[i] = max(max_right[i+1], nums[i+1])

        result = 0
        for i in range(1, n-1):
            if min_left[i] < nums[i] < max_right[i]:
                result += 2
            elif nums[i-1] < nums[i] < nums[i+1]:
                result += 1

        return result

from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 10**9 + 7
        rows, cols = len(pizza), len(pizza[0])

        # Precompute the number of apples in the submatrix starting from (r, c)
        apple_count = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in range(rows - 1, -1, -1):
            for c in range(cols - 1, -1, -1):
                apple_count[r][c] = (pizza[r][c] == 'A') + apple_count[r + 1][c] + apple_count[r][c + 1] - apple_count[r + 1][c + 1]

        # dp[r][c][k] := number of ways to cut the submatrix starting from (r, c) into k pieces
        dp = [[[0] * (k + 1) for _ in range(cols)] for _ in range(rows)]

        # Base case: if k == 1, we need to check if there's at least one apple in the submatrix
        for r in range(rows):
            for c in range(cols):
                dp[r][c][1] = 1 if apple_count[r][c] > 0 else 0

        # Fill the dp table
        for r in range(rows):
            for c in range(cols):
                for p in range(2, k + 1):
                    # Try making a horizontal cut
                    for cut_r in range(r + 1, rows):
                        if apple_count[r][c] > apple_count[cut_r][c]:
                            dp[r][c][p] = (dp[r][c][p] + dp[cut_r][c][p - 1]) % MOD

                    # Try making a vertical cut
                    for cut_c in range(c + 1, cols):
                        if apple_count[r][c] > apple_count[r][cut_c]:
                            dp[r][c][p] = (dp[r][c][p] + dp[r][cut_c][p - 1]) % MOD

        return dp[0][0][k]

