class Solution:
    def findWinningPlayer(self, skills: List[int], k: int) -> int:
        queue = list(range(len(skills)))
        win_count = 0

        while True:
            if skills[queue[0]] > skills[queue[1]]:
                winner, loser = queue[0], queue[1]
                win_count += 1
            else:
                winner, loser = queue[1], queue[0]
                win_count = 1

            if win_count == k:
                return winner

            queue = [winner] + queue[2:] + [loser]

class Solution:
    def minLengthAfterRemovals(self, nums: List[int]) -> int:
        n = len(nums)
        # Create a frequency map to count occurrences of each number
        freq_map = {}
        for num in nums:
            if num in freq_map:
                freq_map[num] += 1
            else:
                freq_map[num] = 1

        # Count the number of elements that appear exactly once
        unique_elements = sum(1 for count in freq_map.values() if count == 1)

        # Calculate the minimum length of the array after removing elements
        return n - unique_elements

