import math

class Solution:
    def maxPoints(self, points: List[List[int]]) -> int:
        if not points:
            return 0

        n = len(points)
        if n < 3:
            return n

        max_points_on_line = 1

        for i in range(n):
            slope_count = defaultdict(int)
            duplicates = 1

            for j in range(i + 1, n):
                if points[i] == points[j]:
                    duplicates += 1
                else:
                    dx = points[j][0] - points[i][0]
                    dy = points[j][1] - points[i][1]

                    # Calculate the greatest common divisor to simplify the slope
                    gcd = math.gcd(dx, dy)
                    slope = (dx // gcd, dy // gcd)

                    slope_count[slope] += 1

            current_max = duplicates
            for count in slope_count.values():
                current_max = max(current_max, count + duplicates)

            max_points_on_line = max(max_points_on_line, current_max)

        return max_points_on_line

