        return int(max_num) - int(min_num)

from typing import List

class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7

        # Function to calculate the number of ways to transform s into t in exactly k operations
        def count_ways(s, t, k):
            n = len(s)
            if n != len(t):
                return 0

            # Create a list to store the number of ways to transform each suffix of s to t
            dp = [0] * (n + 1)

            # Initialize the first suffix
            dp[0] = 1

            # Iterate through each suffix of s
            for i in range(1, n + 1):
                # Calculate the number of ways to transform the current suffix to t
                for j in range(1, min(i + 1, len(t))):
                    if s[i - j] == t[j]:
                        dp[i] += dp[i - j]
                        dp[i] %= MOD

            return dp[n]

        # Calculate the number of ways to transform s into t in exactly k operations
        return count_ways(s, t, k)

