class Solution:
    def wordsAbbreviation(self, words: List[str]) -> List[str]:
        def abbreviate(word, prefix_len):
            n = len(word)
            if prefix_len >= n - 3:
                return word
            return word[:prefix_len] + str(n - prefix_len - 1) + word[-1]

        def min_abbr(words, prefix_len):
            abbr_dict = defaultdict(list)
            for i, word in enumerate(words):
                abbr = abbreviate(word, prefix_len)
                abbr_dict[abbr].append((word, i))

            result = [''] * len(words)
            for abbr, group in abbr_dict.items():
                if len(group) == 1:
                    word, index = group[0]
                    result[index] = abbr
                else:
                    sub_result = min_abbr([word for word, _ in group], prefix_len + 1)
                    for (word, index), sub_abbr in zip(group, sub_result):
                        result[index] = sub_abbr
            return result

        return min_abbr(words, 1)

class Solution:
    def passThePillow(self, n: int, time: int) -> int:
        # Determine if the direction is forward or backward
        if time % (n - 1) == 0:
            return n - time // (n - 1)
        else:
            # Calculate the current position based on the time
            return time % (n - 1) + 1

class Solution:
    def constrainedSubsetSum(self, nums: List[int], k: int) -> int:
        # Initialize variables to keep track of the maximum sum of a valid subsequence
        max_sum = float('-inf')
        current_sum = 0

        # Iterate through each element in the array
        for num in nums:
            # Update the current sum by adding the current number to it
            current_sum += num

            # If the current sum is greater than the maximum sum found so far, update the maximum sum
            if current_sum > max_sum:
                max_sum = current_sum

            # If the current sum minus the last element in the subsequence is less than or equal to k, remove the last element
            if current_sum - nums[-1] <= k:
                current_sum -= nums[-1]

        return max_sum

