class Solution:
    def maxRepOpt1(self, text: str) -> int:
        from collections import defaultdict

        # Count the frequency of each character
        freq = defaultdict(int)
        for char in text:
            freq[char] += 1

        # Group the same characters together
        groups = []
        count = 1
        for i in range(1, len(text)):
            if text[i] == text[i - 1]:
                count += 1
            else:
                groups.append((text[i - 1], count))
                count = 1
        groups.append((text[-1], count))

        max_length = 0

        # Check each group
        for i in range(len(groups)):
            char, count = groups[i]

            # If there is more than one group of this character, we can extend the current group
            if freq[char] > count:
                max_length = max(max_length, count + 1)

            # Try to merge with the next group if there is only one character between them
            if i + 2 < len(groups) and groups[i + 1][1] == 1 and groups[i + 2][0] == char:
                total_count = count + groups[i + 2][1]
                if freq[char] > total_count:
                    total_count += 1
                max_length = max(max_length, total_count)

        return max_length

from typing import List

class Solution:
    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        def dp(l, r, n):
            if l > r:
                l, r = r, l
            if (l, r, n) in memo:
                return memo[(l, r, n)]
            if l + r == n + 1:
                return (1, 1)
            early = float('inf')
            late = float('-inf')
            for i in range(1, (n // 2) + 1):
                for j in range(i + 1, (n // 2) + 2):
                    if (i <= l < j and r >= n - j + 1) or (i <= r < j and l >= n - j + 1):
                        e, l_ = dp(max(i, n - r + 1), min(j - 1, n - l + 1), n // 2 + n % 2)
                        early = min(early, e + 1)
                        late = max(late, l_ + 1)
            memo[(l, r, n)] = (early, late)
            return memo[(l, r, n)]

        memo = {}
        return list(dp(firstPlayer, secondPlayer, n))

