class Solution:
    def maxRunTime(self, n: int, batteries: List[int]) -> int:
        total_time = sum(batteries)
        batteries.sort()
        while len(batteries) > n:
            total_time -= batteries.pop()
            if total_time < sum(batteries):
                break
        return total_time // n

