class Solution:
    def twoSumBSTs(self, root1: Optional[TreeNode], root2: Optional[TreeNode], target: int) -> bool:
        def dfs(node, s):
            if not node:
                return False
            if (target - node.val) in s:
                return True
            s.add(node.val)
            return dfs(node.left, s) or dfs(node.right, s)

        s = set()
        return dfs(root1, s) and dfs(root2, s)

class Solution:
    def clumsy(self, n: int) -> int:
        if n == 0:
            return 1

        # Initialize the result with the first number
        result = n

        # Loop through the numbers from n down to 1
        for i in range(n-1, 0, -1):
            # Perform the operation based on the current number
            if i % 4 == 0:
                # Multiply
                result *= i
            elif i % 4 == 1:
                # Divide
                result /= i
            elif i % 4 == 2:
                # Add
                result += i
            else:
                # Subtract
                result -= i

        return result

class Solution:
    def stoneGameIII(self, stoneValue: List[int]) -> str:
        n = len(stoneValue)
        dp = [[-1 for _ in range(4)] for _ in range(n)]

        def dfs(i, turn):
            if i == n:
                return 0

            if dp[i][turn] != -1:
                return dp[i][turn]

            res = float('-inf')
            for j in range(3):
                if i + j >= n:
                    break
                res = max(res, stoneValue[i] + dfs(i+j+1, not turn))

            dp[i][turn] = res
            return res

        total = sum(stoneValue)
        if dfs(0, True) > total // 2:
            return "Alice"
        elif dfs(0, True) < total // 2:
            return "Bob"
        else:
            return "Tie"

from typing import List

class Solution:
    def minDays(self, grid: List[List[int]]) -> int:
        def dfs(x, y):
            if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == 0:
                return
            grid[x][y] = 0
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                dfs(x + dx, y + dy)

        def count_islands():
            count = 0
            for i in range(len(grid)):
                for j in range(len(grid[0])):
                    if grid[i][j] == 1:
                        count += 1
                        dfs(i, j)
            return count

        # Check initial state
        if count_islands() != 1:
            return 0

        # Try removing each land cell one by one
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    grid[i][j] = 0
                    if count_islands() != 1:
                        return 1
                    grid[i][j] = 1

        return 2

class Solution:
    def stoneGameIX(self, stones: List[int]) -> bool:
        s = sum(stones)
        if s % 3 == 0:
            return False
        elif s % 3 == 1:
            return len([x for x in stones if x % 3 == 1]) % 2 != 0
        else:
            return len([x for x in stones if x % 3 == 2]) % 2 != 0

