class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)
        word = [''] * n
        current_char = 'a'

        # Assign characters to the word array
        for i in range(n):
            if word[i] == '':
                if current_char > 'z':
                    return ""
                word[i] = current_char
                current_char = chr(ord(current_char) + 1)

        # Validate and fill the lcp matrix
        for i in range(n):
            for j in range(i, n):
                if lcp[i][j] != lcp[j][i]:
                    return ""
                if i == j:
                    if lcp[i][j] != n - i:
                        return ""
                else:
                    if word[i] == word[j]:
                        expected = 1 + lcp[i + 1][j + 1] if i + 1 < n and j + 1 < n else 1
                        if lcp[i][j] != expected:
                            return ""
                    else:
                        if lcp[i][j] != 0:
                            return ""

        return ''.join(word)

class Solution:
    def canConstruct(self, s: str, k: int) -> bool:
        # Initialize two pointers, one at the start and one at the end of the string
        left, right = 0, len(s) - 1

        # Count the number of odd occurrences of each character
        odd_count = Counter(s)

        # Iterate through the string, moving the pointers towards the center
        while left < right:
            # If the count of a character is odd, decrement the pointer for that character
            if odd_count[s[left]] % 2 == 1:
                odd_count[s[left]] -= 1
            else:
                # If the count of a character is even, increment the pointer for that character
                odd_count[s[right]] += 1

            # Move the pointers towards the center
            left += 1
            right -= 1

        # If all characters have been used up, return True
        return odd_count == Counter()

class Solution:
    def reformatNumber(self, number: str) -> str:
