        number = number.replace(" ", "").replace("-", "")

        # Group the digits into blocks of length 3
        blocks = []
        for i in range(0, len(number), 3):
            blocks.append(number[i:i+3])

        # Join the blocks with dashes
        return "-".join(blocks)

