class Solution:
    def minDominoRotations(self, tops: List[int], bottoms: List[int]) -> int:
        count = Counter(tops)
        for num in set(tops):
            if count[num] >= len(tops) - count[num]:
                return len(tops) - count[num]
        count = Counter(bottoms)
        for num in set(bottoms):
            if count[num] >= len(tops) - count[num]:
                return len(tops) - count[num]
        return -1

