class Solution:
    def findKOr(self, nums: List[int], k: int) -> int:
        res = 0
        for i in range(31):
            cnt = sum((n >> i) & 1 for n in nums)
            if cnt >= k:
                res |= (1 << i)
        return res

class Solution:
    def minCapability(self, nums: List[int], k: int) -> int:
        def canRob(houseCapability):
            count, lastRobbed = 0, -2
            for i in range(len(nums)):
                if i - lastRobbed > 1 and nums[i] <= houseCapability:
                    count += 1
                    lastRobbed = i
            return count >= k

        left, right = min(nums), max(nums)
        while left < right:
            mid = (left + right) // 2
            if canRob(mid):
                right = mid
            else:
                left = mid + 1
        return left

class Solution:
    def closestToTarget(self, arr: List[int], target: int) -> int:
        res = float('inf')
        for i in range(len(arr)):
            temp = arr[i]
            for j in range(i + 1, len(arr)):
                temp += arr[j]
                if abs(temp - target) < res:
                    res = abs(temp - target)
        return res

