class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        if len(bloomDay) < m*k:
            return -1

        left, right = min(bloomDay), max(bloomDay)

        while left < right:
            mid = (left + right)//2

            cnt = 0
            for i in range(len(bloomDay)):
                if bloomDay[i] > mid:
                    cnt = 0
                else:
                    cnt += 1
                    if cnt == k:
                        cnt = 0
                        m -= 1

            if m == 0:
                right = mid
            else:
                left = mid+1

        return left

