class Solution:
    def numMovesStones(self, a: int, b: int, c: int) -> List[int]:
        # Sort the positions of the stones
        stones = sorted([a, b, c])
        x, y, z = stones

        # Calculate the minimum number of moves
        if z - x == 2:
            min_moves = 0
        elif z - x == 3:
            min_moves = 1
        else:
            min_moves = 2

        # Calculate the maximum number of moves
        max_moves = z - x - 2

        return [min_moves, max_moves]

class Solution:
    def knightDialer(self, n: int) -> int:
        MOD = 10**9 + 7

        # Define the possible moves of the knight
        moves = [
            (2, 1), (2, -1), (-2, 1), (-2, -1),
            (1, 2), (1, -2), (-1, 2), (-1, -2)
        ]

        # Initialize the dp array
        dp = [[0] * 10 for _ in range(n)]

        # Base case: there's exactly one way to start from each digit
        for i in range(10):
            dp[0][i] = 1

        # Fill the dp array
        for i in range(1, n):
            for j in range(10):
                for dx, dy in moves:
                    new_x, new_y = j + dx, j + dy
                    if 0 <= new_x < 10 and 0 <= new_y < 10:
                        dp[i][j] = (dp[i][j] + dp[i-1][new_x]) % MOD

        # Sum up all the ways to reach the end state
        result = sum(dp[n-1]) % MOD

        return result

class Solution:
    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        parent = list(range(len(nums)))
        size = [1]*len(nums)

        def find(x):
            if x != parent[x]:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x,y):
            px,py = find(x),find(y)
            if px!=py:
                if size[px]>size[py]:
                    parent[py]=px
                    size[px]+=size[py]
                else:
                    parent[px]=py
                    size[py]+=size[px]

        total = sum(nums)
        if total % len(nums) != 0:
            return 0

        target = total // len(nums)

        def dfs(node,cur_sum):
            nonlocal ans
            cur_sum += nums[node]
            if cur_sum > target:
                return False
            if cur_sum == target:
                ans+=1
                return True

            for nxt in range(len(edges)):
                if edges[nxt][0]==node or edges[nxt][1]==node:
                    continue
                if dfs(edges[nxt][0],cur_sum):
                    return True
                if dfs(edges[nxt][1],cur_sum):
                    return True

            return False

        ans=0
        for i in range(len(nums)):
            if not dfs(i,0):
                break

        return ans

class Solution:
    def numberOfChild(self, n: int, k: int) -> int:
        return (k + n - 1) % n if k < 2 * (n - 1) else 2 * (n - 1) - (k % (2 * (n - 1)))

class Solution:
    def placeWordInCrossword(self, board: List[List[str]], word: str) -> bool:
        m, n = len(board), len(board[0])
        for i in range(m):
            for j in range(n):
                if board[i][j] == ' ':
                    # Try placing the word horizontally
                    for k in range(len(word)):
                        if board[i][k] != '#' and word[k] == board[i][j+k]:
                            continue
                        else:
                            break
                    else:
                        continue
                    # Try placing the word vertically
                    for k in range(len(word)):
                        if board[k][j] != '#' and word[k] == board[i+k][j]:
                            continue
                        else:
                            break
                    else:
                        continue
                    return True
        return False

class Solution:
    def longestRepeating(self, s: str, queryCharacters: str, queryIndices: List[int]) -> List[int]:
        n = len(s)
        intervals = [[i, i] for i in range(n)]
        ans = []

        def merge(intervals):
            merged = []
            for interval in sorted(intervals):
                if not merged or merged[-1][1] + 1 < interval[0]:
                    merged.append(interval)
                else:
                    merged[-1][1] = max(merged[-1][1], interval[1])
            return merged

        for char, idx in zip(queryCharacters, queryIndices):
            left, right = idx, idx
            while left > 0 and s[left - 1] == char:
                left -= 1
            while right < n - 1 and s[right + 1] == char:
                right += 1

            for i in range(left, right + 1):
                intervals[i][0] = left
                intervals[i][1] = right

            intervals = merge(intervals)
            ans.append(max(interval[1] - interval[0] + 1 for interval in intervals))

        return ans

# Definition for a binary tree node.
