class Solution:
    def sumNumbers(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0

        def dfs(node, current_sum):
            current_sum = current_sum * 10 + node.val
            if not node.left and not node.right:
                return current_sum

            left_sum = dfs(node.left, current_sum) if node.left else 0
            right_sum = dfs(node.right, current_sum) if node.right else 0

            return left_sum + right_sum

        return dfs(root, 0)

class Solution:
    def minimumMoves(self, nums: List[int], k: int, maxChanges: int) -> int:
        l, r = 0, len(nums)
        while l < r:
            m = (l + r) // 2
            # Check if it's possible to pick k ones in m steps
            if self.canPickKOnes(nums, k, m, maxChanges):
                r = m
            else:
                l = m + 1

        return l

    def canPickKOnes(self, nums, k, m, maxChanges):
        left, right = 0, m
        changes = 0

        while right < len(nums):
            if nums[right] == 0:
                changes += 1
            if changes > maxChanges:
                return False

            if right - left + 1 >= k:
                left += 1

            right += 1

        return True

from typing import List

class Solution:
    def closestNode(self, n: int, edges: List[List[int]], query: List[List[int]]) -> List[int]:
        from collections import defaultdict, deque

        # Build the graph
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def bfs(start):
            queue = deque([start])
            visited = {start: 0}
            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited[neighbor] = visited[node] + 1
                        queue.append(neighbor)
            return visited

        def find_closest_node(start, end, node):
            start_to_all = bfs(start)
            end_to_all = bfs(end)
            node_to_all = bfs(node)

            min_distance = float('inf')
            closest_node = -1

            for i in range(n):
                if i in start_to_all and i in end_to_all and i in node_to_all:
                    distance = max(start_to_all[i], end_to_all[i], node_to_all[i])
                    if distance < min_distance:
                        min_distance = distance
                        closest_node = i

            return closest_node

        result = []
        for start, end, node in query:
            result.append(find_closest_node(start, end, node))

        return result

