class Solution:
    def kthSmallest(self, mat: List[List[int]], k: int) -> int:
        def kSmallestPairs(arr1, arr2, k):
            return list(merge(arr1, arr2))[:k]

        result = mat[0][:k]
        for row in mat[1:]:
            result = kSmallestPairs([a + b for a in result for b in row], [], k)

        return result[k-1]

class Solution:
    def minimumKeypresses(self, s: str) -> int:
        freq = [0] * 26
        for char in s:
            freq[ord(char) - ord('a')] += 1

        freq.sort(reverse=True)

        total_presses = 0
        for i in range(26):
            if i < 9:
                total_presses += freq[i]
            elif i < 18:
                total_presses += 2 * freq[i]
            else:
                total_presses += 3 * freq[i]

        return total_presses

