class Solution:
    def minSpeedOnTime(self, dist: List[int], hour: float) -> int:
        def can_reach_on_time(speed):
            total_time = sum((d + speed - 1) // speed for d in dist[:-1])
            total_time += dist[-1] / speed
            return total_time <= hour

        left, right = 1, max(max(dist), math.ceil(sum(dist) / hour))
        while left < right:
            mid = (left + right) // 2
            if can_reach_on_time(mid):
                right = mid
            else:
                left = mid + 1
        return left if can_reach_on_time(left) else -1

