class UnionFind:
    def __init__(self):
        self.parent = {}

    def find(self, x):
        if x not in self.parent:
            self.parent[x] = x
        elif self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            self.parent[rootX] = rootY

class Solution:
    def accountsMerge(self, accounts: List[List[str]]) -> List[List[str]]:
        uf = UnionFind()
        email_to_name = {}

        for acc in accounts:
            name = acc[0]
            for i in range(1, len(acc)):
                email = acc[i]
                if email not in email_to_name:
                    email_to_name[email] = name
                uf.union(acc[1], email)

        merged_accounts = defaultdict(list)
        for email in email_to_name:
            root = uf.find(email)
            merged_accounts[root].append(email)

        result = []
        for name, emails in merged_accounts.items():
            result.append([email_to_name[name]] + sorted(emails))

        return result

class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        if not preorder or not inorder:
            return None

        root_val = preorder[0]
        root = TreeNode(root_val)

        index = inorder.index(root_val)

        root.left = self.buildTree(preorder[1:index+1], inorder[:index])
        root.right = self.buildTree(preorder[index+1:], inorder[index+1:])

        return root

class Solution:
    def minCharacters(self, a: str, b: str) -> int:
        # Count the frequency of each character in both strings
        count_a = {}
        for char in a:
            if char in count_a:
                count_a[char] += 1
            else:
                count_a[char] = 1

        count_b = {}
        for char in b:
            if char in count_b:
                count_b[char] += 1
            else:
                count_b[char] = 1

        # Count the minimum number of changes needed
        changes = 0

        # Count the characters that are in both strings but not in the other string
        common_chars = set(count_a.keys()) & set(count_b.keys())
        for char in common_chars:
            if count_a[char] > count_b[char]:
                changes += count_a[char] - count_b[char]

        # Count the characters that are in one string but not in the other string
        unique_chars = set(count_a.keys()) | set(count_b.keys())
        for char in unique_chars:
            if count_a[char] < count_b[char]:
                changes += count_b[char] - count_a[char]

        return changes

class Solution:
    def nextClosestTime(self, time: str) -> str:
        digits = set(time)
        hour, minute = map(int, time.split(':'))

        while True:
            minute += 1
            if minute == 60:
                minute = 0
                hour += 1
                if hour == 24:
                    hour = 0

            new_time = f"{hour:02d}:{minute:02d}"
            if all(digit in digits for digit in new_time):
                return new_time

class Solution:
    def maxDiff(self, num: int) -> int:
        num_str = str(num)

        # Find the first digit that is not 9 to maximize the number
        for i, c in enumerate(num_str):
            if c != '9':
                max_num = int(num_str.replace(c, '9'))
                break
        else:
            max_num = num

        # Find the first digit that is not 1 to minimize the number
        for i, c in enumerate(num_str):
            if c != '1':
                if i == 0:
                    min_num = int(num_str.replace(c, '1'))
                else:
                    min_num = int(num_str.replace(c, '0'))
                break
        else:
            min_num = num

        return max_num - min_num

