class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        if not digits:
            return []

        phone_map = {
            '2': 'abc',
            '3': 'def',
            '4': 'ghi',
            '5': 'jkl',
            '6': 'mno',
            '7': 'pqrs',
            '8': 'tuv',
            '9': 'wxyz'
        }

        result = []
        self.backtrack(digits, "", result, phone_map)
        return result

    def backtrack(self, digits: str, current: str, result: List[str], phone_map: dict):
        if len(current) == len(digits):
            result.append(current)
            return

        for char in phone_map[digits[len(current)]]:
            self.backtrack(digits, current + char, result, phone_map)

