class Solution:
    def maxHappyGroups(self, batchSize: int, groups: List[int]) -> int:
        count = Counter([g % batchSize for g in groups])
        ans = count[0]
        count[0] = 0

        for i in range(1, (batchSize + 1) // 2):
            ans += min(count[i], count[batchSize - i])
            count[i] = 0
            count[batchSize - i] = 0

        return ans + sum(v // 2 for v in count.values())

