class Solution:
    def maxHeight(self, cuboids: List[List[int]]) -> int:
        # Sort each cuboid's dimensions
        for cuboid in cuboids:
            cuboid.sort()

        # Sort cuboids based on their smallest dimension
        cuboids.sort(key=lambda x: (x[0], x[1]))

        n = len(cuboids)
        dp = [cuboid[-1] for cuboid in cuboids]

        for i in range(1, n):
            for j in range(i):
                if cuboids[j][1] <= cuboids[i][1] and cuboids[j][2] <= cuboids[i][2]:
                    dp[i] = max(dp[i], dp[j] + cuboids[i][-1])

        return max(dp)

