class Solution:
    def maximumLengthOfRanges(self, nums: List[int]) -> List[int]:
        stack = []
        ans = [1]*len(nums)
        for i in range(len(nums)):
            while stack and nums[stack[-1]] < nums[i]:
                idx = stack.pop()
                left = stack[-1]+1 if stack else -1
                ans[idx] = i-left+1
            stack.append(i)
        return ans

