class Solution:
    def getLongestSubsequence(self, words: List[str], groups: List[int]) -> List[str]:
        # Find the longest alternating subsequence using dynamic programming
        n = len(words)
        dp = [[0] * 2 for _ in range(n)]

        # Base case: single word has no subsequences
        for i in range(n):
            dp[i][groups[i]] = 1

        # Fill the DP table
        for i in range(1, n):
            for j in range(i):
                if groups[i] != groups[j]:
                    dp[i][groups[i]] = max(dp[i][groups[i]], dp[j][groups[i]])
                    dp[i][groups[j]] = max(dp[i][groups[j]], dp[j][groups[i]])

        # Find the maximum length of alternating subsequences
        max_len = max(max(row) for row in dp)

        # Collect the words that form the longest alternating subsequences
        result = []
        for i in range(n):
            if dp[i][groups[i]] == max_len:
                result.append(words[i])

        return result

class Solution:
    def findStrobogrammatic(self, n: int) -> List[str]:
        if n == 1:
            return ["0", "1", "8"]

        # Initialize the list to store the result
        result = []

        # Iterate over each digit from 1 to n-1
        for i in range(1, n):
            # Generate all possible strobogrammatic numbers of length i-1
            for j in range(10):
                # Construct the current strobogrammatic number
                current = self.helper(i-1, j)
                # Append it to the result list
                result.append(current)

        return result

    # Helper function to generate all possible strobogrammatic numbers of a given length
    def helper(self, length, num):
        if length == 0:
            return [num]

        # If the last digit is 0, append '0' to the result
        if num % 10 == 0:
            return self.helper(length - 1, num * 10)

        # If the last digit is 1, append '1' to the result
        if num % 10 == 1:
            return self.helper(length - 1, num * 10 + 1)

        # If the last digit is 8, append '8' to the result
        if num % 10 == 8:
            return self.helper(length - 1, num * 10 + 8)

        # If the last digit is 6, append '9' to the result
        if num % 10 == 6:
            return self.helper(length - 1, num * 10 + 9)

        # Otherwise, append the two possible strobogrammatic numbers
        return self.helper(length - 1, num * 10) + self.helper(length - 1, num * 10 + 1)

class Solution:
    def numSplits(self, s: str) -> int:
        left_count = [0] * 26
        right_count = [0] * 26
        left_unique = 0
        right_unique = 0

        for char in s:
            index = ord(char) - ord('a')
            if right_count[index] == 0:
                right_unique += 1
            right_count[index] += 1

        good_splits = 0

        for char in s:
            index = ord(char) - ord('a')

            # Move character from right to left
            right_count[index] -= 1
            if right_count[index] == 0:
                right_unique -= 1

            if left_count[index] == 0:
                left_unique += 1
            left_count[index] += 1

            if left_unique == right_unique:
                good_splits += 1

        return good_splits

class Solution:
    def rangeSumBST(self, root: Optional[TreeNode], low: int, high: int) -> int:
        if not root:
            return 0

        current_sum = 0
        if low <= root.val <= high:
            current_sum += root.val

        if root.val > low:
            current_sum += self.rangeSumBST(root.left, low, high)

        if root.val < high:
            current_sum += self.rangeSumBST(root.right, low, high)

        return current_sum

class Solution:
    def minimumLength(self, s: str) -> int:
        n = len(s)
        for i in range(n):
            # find the longest prefix and suffix that are equal to the current character
            for j in range(i, n - 1):
                if s[i] == s[j]:
                    # check if there is no overlap between the prefix and suffix
                    if j - i + 1 < n - i:
                        return j - i + 1
        return n

class Solution:
    def findDiagonalOrder(self, mat: List[List[int]]) -> List[int]:
        result = []
        for i in range(len(mat)):
            for j in range(len(mat[0])):
                result.append(mat[i][j])

        # Separate even and odd diagonals
        even_diagonals = []
        odd_diagonals = []
        for i in range(len(result)):
            if i % 2 == 0:
                even_diagonals.append(result[i])
            else:
                odd_diagonals.append(result[i])

        # Reverse the odd diagonals
        odd_diagonals.reverse()

        # Combine even and reversed odd diagonals
        result = even_diagonals + odd_diagonals

        return result

class Solution:
    def countNegatives(self, grid: List[List[int]]) -> int:
        count = 0
        for row in grid:
            # Use binary search to find the first negative element in each row
            left, right = 0, len(row) - 1
            while left <= right:
                mid = (left + right) // 2
                if row[mid] < 0:
                    right = mid - 1
                else:
                    left = mid + 1
            count += len(row) - left
        return count

class Solution:
    def isNumber(self, s: str) -> bool:
        # Check if the string is empty
        if not s:
            return False

        # Check for negative sign at the start
        if s[0] == '-':
            s = s[1:]

        # Check for positive sign at the end
        if s[-1] == '+':
            s = s[:-1]

        # Split the string into parts based on the dot
        parts = s.split('.')

        # Check if there are exactly two parts
        if len(parts) != 2:
            return False

        # Split each part further into digits
        num_parts = parts[0].split('.')
        den_parts = parts[1].split('.')

        # Check if both parts are valid integers
        if not all(map(lambda x: x.isdigit(), num_parts)) or not all(map(lambda x: x.isdigit(), den_parts)):
            return False

        # Check if the decimal part contains a dot
        if len(den_parts) > 1:
            return False

        # Check if the exponent is valid
        try:
            float(den_parts[1])
        except ValueError:
            return False

        return True

class Solution:
    def minimumOperations(self, num: str) -> int:
        n = len(num)
        min_operations = n

        # Check for numbers ending in 00, 25, 50, 75
        for target in ['00', '25', '50', '75']:
            found_first = False
            count = 0
            for i in range(n-1, -1, -1):
                if num[i] == target[-1]:
                    if found_first:
                        break
                    else:
                        found_first = True
                else:
                    count += 1
            if found_first:
                min_operations = min(min_operations, count)

        # If there's at least one '0', we can always make a number ending in '00'
        if '0' in num:
            min_operations = min(min_operations, n - 1)

        return min_operations

