class Solution:
    def kLengthApart(self, nums: List[int], k: int) -> bool:
        # Initialize a counter for the number of consecutive 1's
        consecutive_ones = 0

        # Iterate through the array
        for i in range(len(nums)):
            # Check if the current element is a 1
            if nums[i] == 1:
                # Increment the counter if it's the first 1 encountered
                consecutive_ones += 1
                # If there are more than k consecutive 1's, return False
                if consecutive_ones > k:
                    return False

        # If no consecutive 1's are found, return True
        return True

