class Solution:
    def findBlackPixel(self, picture: List[List[str]], target: int) -> int:
        if not picture or not picture[0]:
            return 0

        m, n = len(picture), len(picture[0])
        row_count = [0] * m
        col_count = [0] * n
        row_pattern = {}

        # Count black pixels in each row and column, and record row patterns
        for i in range(m):
            for j in range(n):
                if picture[i][j] == 'B':
                    row_count[i] += 1
                    col_count[j] += 1
                    if i not in row_pattern:
                        row_pattern[i] = []
                    row_pattern[i].append(j)

        count = 0
        for i in range(m):
            if row_count[i] != target:
                continue
            for j in row_pattern[i]:
                if col_count[j] != target:
                    continue
                # Check if all rows with a black pixel at column j are the same as row i
                valid = True
                for k in range(m):
                    if picture[k][j] == 'B' and picture[k] != picture[i]:
                        valid = False
                        break
                if valid:
                    count += 1

        return count

