class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        count = defaultdict(int)
        current_sum = 0
        max_sum = 0

        for i in range(len(nums)):
            if i < k:
                current_sum += nums[i]
                count[nums[i]] += 1
            else:
                current_sum += nums[i]
                count[nums[i]] += 1
                count[nums[i - k]] -= 1

                if count[nums[i - k]] == 0:
                    del count[nums[i - k]]

            if len(count) == k:
                max_sum = max(max_sum, current_sum)

        return max_sum

