class Solution:
    def longestAlternatingSubarray(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        max_length = 0

        for i in range(n):
            if nums[i] > threshold:
                continue

            current_length = 1
            if i > 0 and nums[i-1] % 2 == nums[i] % 2:
                continue

            j = i + 1
            while j < n and nums[j] <= threshold and nums[j] % 2 != nums[j-1] % 2:
                current_length += 1
                j += 1

            max_length = max(max_length, current_length)

        return max_length

class Solution:
    def longestBeautifulSubstring(self, word: str) -> int:
        vowels = 'aeiou'
        max_length = 0

        for i in range(len(word)):
            # Check if the current character is a vowel
            if word[i] in vowels:
                # Check if the next character is a vowel and the previous one is not
                if i + 1 < len(word) and word[i + 1] in vowels and word[i - 1] not in vowels:
                    # Update the maximum length if the current substring is longer
                    max_length = max(max_length, i - i + 1)

        return max_length

from typing import List

class Solution:
    def getMaxFunctionValue(self, receiver: List[int], k: int) -> int:
        n = len(receiver)
        max_score = 0

        # Precompute the 2^j-th next player for each player using dynamic programming
        next_player = [[0] * 64 for _ in range(n)]

        for i in range(n):
            next_player[i][0] = receiver[i]

        for j in range(1, 64):
            for i in range(n):
                next_player[i][j] = next_player[next_player[i][j-1]][j-1]

        # Calculate the maximum score
        for start in range(n):
            current = start
            score = start
            pos = k

            for j in range(64):
                if pos & (1 << j):
                    score += next_player[current][j]
                    current = next_player[current][j]

            max_score = max(max_score, score)

        return max_score

