        count = 0

        for i in range(n):
            is_alternating = True
            for j in range(k):
                if colors[(i + j) % n] != (j % 2):
                    is_alternating = False
                    break
            if is_alternating:
                count += 1

        return count

class Solution:
    def numWays(self, s: str) -> int:
        count_ones = s.count('1')
        if count_ones % 3 != 0:
            return 0

        mod = 10**9 + 7
        count_ones_per_part = count_ones // 3
        count_zeros = s.count('0')
        left_count = 0

        result = 0
        for i in range(len(s)):
            if s[i] == '0':
                left_count += 1
            else:
                if left_count == count_ones_per_part - 1:
                    result = (result + count_zeros - left_count) % mod
                elif left_count == count_ones_per_part:
                    result = (result + 1) % mod

        return result

from collections import defaultdict

class Solution:
    def minimumDistance(self, word: str) -> int:
        self.d = defaultdict(lambda: defaultdict(int))
        for i in range(5):
            for j in range(5):
                self.d[i][j] = abs(i-2) + abs(j-2)
        return self.helper(word, 0, 0, {})

    def helper(self, word, cur_i, cur_j, memo):
        if cur_i == len(word):
            return 0

        if (cur_i, cur_j) in memo:
            return memo[(cur_i, cur_j)]

        res = float('inf')
        for i in range(5):
            for j in range(5):
                res = min(res, self.d[cur_i][i] + self.d[cur_j][j] + self.helper(word, cur_i+1, j, memo))

        memo[(cur_i, cur_j)] = res
        return res

class Solution:
    def minimumChairs(self, s: str) -> int:
        chairs = 0
        free_chairs = 0

        for event in s:
            if event == 'E':
                chairs += 1
                free_chairs += chairs
            else:
                chairs -= 1
                free_chairs -= 1

        return free_chairs

