class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        MOD = 10**9 + 7

        for i in range(n-1, -1, -1):
            bit = 1 << i
            if (a & bit) == 0 and (b & bit) == 0:
                a |= bit
            elif (a & bit) and (b & bit):
                if a > b:
                    b |= bit
                else:
                    a |= bit
            elif (a & bit) and not (b & bit):
                if a - bit > b + bit:
                    a ^= bit
                    b |= bit
            elif not (a & bit) and (b & bit):
                if b - bit > a + bit:
                    b ^= bit
                    a |= bit

        return (a * b) % MOD

class Solution:
    def smallestSubarrays(self, nums: List[int]) -> List[int]:
        n = len(nums)
        ans = [1] * n
        max_or = nums[0]
        bit_mask = [0] * 32

        for i in range(n):
            # Update the maximum OR value up to index i
            max_or |= nums[i]

            # Determine the bit mask for the current index
            for j in range(32):
                if nums[i] & (1 << j):
                    bit_mask[j] = max(bit_mask[j], i + 1)

        for i in range(n - 1, -1, -1):
            # Find the minimum length subarray ending at i with the maximum OR
            for j in range(32):
                if bit_mask[j] > i + 1:
                    ans[i] = max(ans[i], bit_mask[j] - i)

        return ans

