class Solution:
    @lru_cache(None)
    def strangePrinter(self, s: str) -> int:
        n = len(s)
        if n == 1:
            return 1

        min_turns = float('inf')
        for i in range(1, n):
            if s[i] != s[0]:
                min_turns = min(min_turns, self.strangePrinter(s[:i]) + self.strangePrinter(s[i:]))
            else:
                min_turns = min(min_turns, self.strangePrinter(s[:i-1]) + self.strangePrinter(s[i:]))

        return min_turns

class Solution:
    def maximumLength(self, s: str) -> int:
        n = len(s)
        max_length = 0
        found = False

        for i in range(n):
            for j in range(i + 1, n + 1):
                substring = s[i:j]
                if len(set(substring)) == 1:
                    if s.count(substring) >= 3:
                        max_length = max(max_length, len(substring))
                        found = True

        return max_length if found else -1

class Solution:
    def shortestCompletingWord(self, licensePlate: str, words: List[str]) -> str:
        # Remove non-alphanumeric characters and convert to lowercase
        licensePlate = ''.join(char.lower() for char in licensePlate if char.isalnum())

        # Split the license plate into individual letters
        letters = list(licensePlate)

        # Create a dictionary to count occurrences of each letter
        letter_count = {}

        # Count occurrences of each letter in the license plate
        for char in letters:
            if char in letter_count:
                letter_count[char] += 1
            else:
                letter_count[char] = 1

        # Find the minimum length of the completed word
        min_length = float('inf')
        best_word = None

        # Iterate over each word in the list
        for word in words:
            # Convert the word to lowercase and split into individual letters
            word_letters = list(word.lower())

            # Count occurrences of each letter in the word
            word_letter_count = {}
            for char in word_letters:
                if char in word_letter_count:
                    word_letter_count[char] += 1
                else:
                    word_letter_count[char] = 1

            # Calculate the difference between the counts and the original letter count
            difference = sum(word_letter_count.values()) - sum(letter_count.values())

            # Update the best word if this word has a smaller difference
            if difference < min_length:
                min_length = difference
                best_word = word

        # Return the shortest completing word
        return best_word

