class Solution:
    def collectTheCoins(self, coins: List[int], edges: List[List[int]]) -> int:
        # Build adjacency list
        adj_list = defaultdict(list)
        for u, v in edges:
            adj_list[u].append(v)
            adj_list[v].append(u)

        # Depth-first search to count leaves and their values
        @lru_cache(None)
        def dfs(node):
            if len(adj_list[node]) == 1:
                return coins[node], 0
            left_val, left_count = dfs(adj_list[node][0])
            right_val, right_count = dfs(adj_list[node][1])
            total_coins = left_val + right_val
            total_edges = left_count + right_count
            if total_coins >= 2:
                return 0, total_edges
            else:
                return max(left_val, right_val), total_edges

        # Calculate the minimum number of edges needed
        _, min_edges = dfs(0)
        return min_edges

