class Solution:
    def calculate(self, s: str) -> int:
        def precedence(op):
            if op in ('+', '-'):
                return 1
            if op in ('*', '/'):
                return 2
            return 0

        def apply_operator(operators, values):
            operator = operators.pop()
            right = values.pop()
            left = values.pop()
            if operator == '+':
                values.append(left + right)
            elif operator == '-':
                values.append(left - right)
            elif operator == '*':
                values.append(left * right)
            elif operator == '/':
                values.append(int(left / right))

        def greater_precedence(op1, op2):
            return precedence(op1) > precedence(op2)

        operators = []
        values = []
        i = 0
        while i < len(s):
            if s[i] == ' ':
                i += 1
                continue
            if s[i] == '(':
                operators.append(s[i])
            elif s[i].isdigit():
                val = 0
                while i < len(s) and s[i].isdigit():
                    val = (val * 10) + int(s[i])
                    i += 1
                values.append(val)
                i -= 1
            elif s[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # pop '('
            else:
                while (operators and operators[-1] != '(' and
                       greater_precedence(operators[-1], s[i])):
                    apply_operator(operators, values)
                operators.append(s[i])
            i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def findDistance(self, root: Optional[TreeNode], p: int, q: int) -> int:
        def lca(root, p, q):
            if not root:
                return None
            if root.val == p or root.val == q:
                return root
            left = lca(root.left, p, q)
            right = lca(root.right, p, q)
            if left and right:
                return root
            return left if left else right

        def depth(root, target, d):
            if not root:
                return -1
            if root.val == target:
                return d
            left = depth(root.left, target, d + 1)
            if left != -1:
                return left
            return depth(root.right, target, d + 1)

        if p == q:
            return 0

        common_ancestor = lca(root, p, q)
        dist_p = depth(common_ancestor, p, 0)
        dist_q = depth(common_ancestor, q, 0)

        return dist_p + dist_q

class Solution:
    def tictactoe(self, moves: List[List[int]]) -> str:
        board = [[' ' for _ in range(3)] for _ in range(3)]
        for i, move in enumerate(moves):
            row, col = move
            if i % 2 == 0:
                board[row][col] = 'X'
            else:
                board[row][col] = 'O'

            # Check rows
            if all(board[row][j] == 'X' for j in range(3)) or all(board[row][j] == 'O' for j in range(3)):
                return 'X' if i % 2 == 0 else 'O'

            # Check columns
            if all(board[j][col] == 'X' for j in range(3)) or all(board[j][col] == 'O' for j in range(3)):
                return 'X' if i % 2 == 0 else 'O'

            # Check diagonals
            if board[0][0] == board[1][1] == board[2][2] == 'X' or board[0][2] == board[1][1] == board[2][0] == 'X':
                return 'X'
            elif board[0][0] == board[1][1] == board[2][2] == 'O' or board[0][2] == board[1][1] == board[2][0] == 'O':
                return 'O'

        # Check draw
        if len(moves) == 9:
            return 'Draw'
        else:
            return 'Pending'

