class Solution:
    def countCompleteComponents(self, n: int, edges: List[List[int]]) -> int:
        def find(x):
            while x != parent[x]:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY
                size[rootY] += size[rootX]
                neighbors[rootY].update(neighbors[rootX])
                neighbors[rootX].clear()

        parent = list(range(n))
        size = [1] * n
        neighbors = [set() for _ in range(n)]

        for u, v in edges:
            union(u, v)
            neighbors[find(u)].add(v)

        complete_components = 0
        for i in range(n):
            if i == find(i) and size[i] * (size[i] - 1) // 2 == len(neighbors[i]):
                complete_components += 1

        return complete_components

