                for k in range(j+1, len(nums2)):
                    if nums1[i]**2 == nums2[j]*nums2[k]:
                        count += 1
        return count

from typing import List

class Solution:
    def minimumTime(self, hens: List[int], grains: List[int]) -> int:
        hens.sort()
        grains.sort()

        def can_eat_all_grains(time):
            i, j = 0, len(grains) - 1
            while i <= j:
                if abs(hens[0] - grains[i]) > time and abs(hens[-1] - grains[j]) > time:
                    return False
                if abs(hens[0] - grains[i]) <= time:
                    i += 1
                if abs(hens[-1] - grains[j]) <= time:
                    j -= 1
            return True

        left, right = 0, max(abs(hens[0] - grains[0]), abs(hens[-1] - grains[-1]))
        while left < right:
            mid = (left + right) // 2
            if can_eat_all_grains(mid):
                right = mid
            else:
                left = mid + 1
        return left

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        if nums[0] == 0:
            nums = [1 - x for x in nums]
        count = 0
        for i in range(1, n):
            if nums[i] != nums[i-1]:
                count += 1
        if nums[-1] == 0:
            return -1
        return count // 2 + count % 2

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        # Initialize the length of the shorter string
        len1, len2 = len(word1), len(word2)

        # Create a DP table where dp[i][j] represents the minimum number of deletions needed to make word1[:i+1] and word2[:j+1] identical
        dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]

        # Fill the DP table
        for i in range(1, len1 + 1):
            for j in range(1, len2 + 1):
                if word1[i - 1] == word2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1])

        # The answer is the minimum number of deletions needed to make both words identical
        return dp[len1][len2]

class Solution:
    def largestSubarray(self, nums: List[int], k: int) -> List[int]:
        # Initialize the maximum subarray as the first 'k' elements of the array
        max_subarray = nums[:k]

        # Iterate through the remaining elements of the array starting from index 'k'
        for i in range(k, len(nums)):
            # If the current element is greater than the last element of the maximum subarray,
            # update the maximum subarray
            if nums[i] > max_subarray[-1]:
                max_subarray = nums[i-k+1:i+1]

        return max_subarray

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        dp = [0] * len(nums)
        dp[0] = nums[0]

        for i in range(1, len(nums)):
            dp[i] = max(dp[i-1], nums[i] + (i-1) * nums[i])

        return dp[-1]

