class Solution:
    def profitableSchemes(self, n: int, minProfit: int, group: List[int], profit: List[int]) -> int:
        @lru_cache(None)
        def dfs(i, total_members, current_profit):
            if i >= len(group):
                return 1 if current_profit >= minProfit else 0

            # Include the current crime
            include_count = dfs(i + 1, total_members - group[i], current_profit + profit[i])

            # Exclude the current crime
            exclude_count = dfs(i + 1, total_members, current_profit)

            return include_count + exclude_count

        return dfs(0, n, 0) % (10**9 + 7)

from math import comb

class Solution:
    def kthSmallestPath(self, destination: List[int], k: int) -> str:
        row, col = destination
        path = []

        while row > 0 and col > 0:
            # Calculate the number of paths if we go horizontally
            horizontal_paths = comb(row + col - 1, row)

            if k <= horizontal_paths:
                path.append('H')
                col -= 1
            else:
                path.append('V')
                k -= horizontal_paths
                row -= 1

        # If there are still moves left to make, they must all be in one direction
        path += ['H'] * col + ['V'] * row

        return ''.join(path)

class Solution:
    def nimGame(self, piles: List[int]) -> bool:
