class Solution:
    def search(self, nums: List[int], target: int) -> int:
        left, right = 0, len(nums) - 1

        while left <= right:
            mid = (left + right) // 2

            if nums[mid] == target:
                return mid

            # Check if the left half is sorted
            if nums[left] <= nums[mid]:
                # If target is in the left half
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:
                # If target is in the right half
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1

        return -1

class Solution:
    def numTilings(self, n: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (n+1)
        dp[0] = 1
        dp[1] = 1
        dp[2] = 2

        for i in range(3, n+1):
            dp[i] = (dp[i-1] + dp[i-2] + dp[i-3]) % MOD

        return dp[-1]

from typing import List

class Solution:
    def maximumSumOfHeights(self, heights: List[int]) -> int:
        n = len(heights)
        left = [0] * n
        right = [0] * n

        # Calculate max height for each position when going left to right
        stack = []
        for i in range(n):
            while stack and heights[i] < heights[stack[-1]]:
                stack.pop()
            if stack:
                left[i] = left[stack[-1]] + heights[i]
            else:
                left[i] = heights[i] * (i + 1)
            stack.append(i)

        # Calculate max height for each position when going right to left
        stack = []
        for i in range(n-1, -1, -1):
            while stack and heights[i] < heights[stack[-1]]:
                stack.pop()
            if stack:
                right[i] = right[stack[-1]] + heights[i]
            else:
                right[i] = heights[i] * (n - i)
            stack.append(i)

        # Find the maximum sum of heights of a mountain-shaped tower arrangement
        max_sum = 0
        for i in range(n):
            max_sum = max(max_sum, left[i] + right[i] - heights[i])

        return max_sum

