            for col in range(len(row)):
                # Check if the current cell is white
                if row[col] == 0:
                    # Calculate the sum of the cells in the jth column starting from the top row down to the ith row
                    total_sum = sum(grid[i][col] for i in range(len(grid)))
                    # Update the maximum score if the current sum is greater
                    max_score = max(max_score, total_sum)

        return max_score

