from collections import deque
class Solution:
    def closestKValues(self, root: Optional[TreeNode], target: float, k: int) -> List[int]:
        def inorder(node):
            if not node:
                return []
            return inorder(node.left) + [node.val] + inorder(node.right)

        sorted_vals = inorder(root)
        closest = deque(sorted_vals[:k])

        for val in sorted_vals[k:]:
            if abs(val - target) < abs(closest[0] - target):
                closest.popleft()
                closest.append(val)
            else:
                break

        return list(closest)

