        for i in range(1, n):
            # Check if the current number is greater than the next number
            if int(s[i]) > int(s[i-1]):
                return False
        # If all numbers are in descending order and adjacent are equal to 1
        return True

from collections import defaultdict

class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:
        graph = defaultdict(list)
        for i in range(n):
            if manager[i] != -1:
                graph[manager[i]].append(i)

        def dfs(node):
            if not graph[node]:
                return informTime[node]
            max_time = 0
            for neighbor in graph[node]:
                max_time = max(max_time, dfs(neighbor))
            return max_time + informTime[node]

        return dfs(headID)

class Solution:
    def findDuplicates(self, nums: List[int]) -> List[int]:
        result = []
        for num in nums:
            index = abs(num) - 1
            if nums[index] < 0:
                result.append(abs(num))
            else:
                nums[index] *= -1
        return result

class Solution:
    def findRedundantDirectedConnection(self, edges: List[List[int]]) -> List[int]:
        parent = list(range(len(edges) + 1))
        degree = [0] * (len(edges) + 1)
        candidate = -1

        for u, v in edges:
            degree[v] += 1
            if degree[v] == 2:
                candidate = v
            if self.find(parent, u) == v:
                return [u, v]
            self.union(parent, u, v)

        if candidate == -1:
            for u, v in reversed(edges):
                if self.find(parent, u) == v:
                    return [u, v]
        else:
            for u, v in reversed(edges):
                if v == candidate:
                    return [u, v]

    def find(self, parent, x):
        if parent[x] != x:
            parent[x] = self.find(parent, parent[x])
        return parent[x]

    def union(self, parent, x, y):
        parent[self.find(parent, x)] = self.find(parent, y)

from typing import List

class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        # Check if it's possible to mark all indices
        if len(set(changeIndices)) < n:
            return -1

        # Function to check if we can mark all indices by the given second
        def can_mark_by_second(second):
            available_operations = second
            last_occurrence = {}

            # Find the last occurrence of each index in changeIndices up to the current second
            for t in range(second):
                last_occurrence[changeIndices[t] - 1] = t

            # Try to mark indices from the end to the beginning
            for t in range(second - 1, -1, -1):
                idx = changeIndices[t] - 1
                if last_occurrence[idx] == t:
                    if available_operations > nums[idx]:
                        available_operations -= nums[idx] + 1
                    else:
                        return False
                else:
                    available_operations += 1

            return True

        # Binary search to find the earliest second
        left, right = 1, m
        while left < right:
            mid = (left + right) // 2
            if can_mark_by_second(mid):
                right = mid
            else:
                left = mid + 1

        return left if can_mark_by_second(left) else -1

class Solution:
    def isGood(self, nums: List[int]) -> bool:
        return len(set(nums)) == len(nums) + 1

from typing import List

class Solution:
    def maxNumOfSubstrings(self, s: str) -> List[str]:
        # Find the first and last occurrence of each character
        first = {c: s.index(c) for c in set(s)}
        last = {c: s.rindex(c) for c in set(s)}

        # Create intervals for each character
        intervals = []
        for c in set(s):
            start, end = first[c], last[c]
            # Expand the interval to include all characters within it
            expand_end = end
            while end > start:
                expand_end = max(expand_end, last[s[end]])
                end -= 1
            intervals.append((start, expand_end))

        # Sort intervals by end position
        intervals.sort(key=lambda x: x[1])

        # Select non-overlapping intervals
        selected = []
        end = -1
        for start, expand_end in intervals:
            if start >= end:
                selected.append(s[start:expand_end + 1])
                end = expand_end + 1

        return selected

class Solution:
    def bestClosingTime(self, customers: str) -> int:
        penalties = [0] * (len(customers) + 1)
        for i in range(1, len(penalties)):
            penalties[i] = penalties[i - 1] + (1 if customers[i - 1] == 'N' else 0)
        min_penalty = penalties[-1]
        close_hour = 0
        for i in range(len(penalties) - 2, -1, -1):
            penalties[i] += penalties[i + 1] - (1 if customers[i] == 'Y' else 0)
            if penalties[i] < min_penalty:
                min_penalty = penalties[i]
                close_hour = i
        return close_hour

class Solution:
    def maxMatrixSum(self, matrix: List[List[int]]) -> int:
        total_sum = 0
        negatives_count = 0

        for row in matrix:
            for num in row:
                if num < 0:
                    negatives_count += 1
                total_sum += abs(num)

        # If there are an even number of negative numbers, we can flip all of them
        if negatives_count % 2 == 0:
            return total_sum

        # If there are an odd number of negative numbers, we can flip all but one of them
        return total_sum - 2 * min(matrix)

class Solution:
    def validTicTacToe(self, board: List[str]) -> bool:
        # Check rows
        for row in board:
            if len(set(row)) != 3:
                return False

        # Check columns
        for col in range(3):
            if len(set([board[row][col] for row in board])) != 3:
                return False

        # Check diagonals
        if len(set([board[i][i] for i in range(3)])) != 3:
            return False
        if len(set([board[i][2-i] for i in range(3)])) != 3:
            return False

        # If all conditions are met, it's a valid game
        return True

from typing import List

class Solution:
    def rearrangeArray(self, nums: List[int]) -> List[int]:
        positives = [num for num in nums if num > 0]
        negatives = [num for num in nums if num < 0]

        result = []
        for pos, neg in zip(positives, negatives):
            result.append(pos)
            result.append(neg)

        return result

class Solution:
    def countValidWords(self, sentence: str) -> int:
        # Split the sentence into tokens using space as the delimiter
        tokens = sentence.split()

        # Initialize a counter for valid words
        valid_count = 0

        # Iterate over each token
        for token in tokens:
            # Check if the token is a valid word
            if self.is_valid_word(token):
                # Increment the counter if the token is valid
                valid_count += 1

        return valid_count

    # Helper function to check if a token is a valid word
    def is_valid_word(self, token):
        # Check if the token contains only lowercase letters, hyphens, and/or punctuation
        if not token.isalpha() and not token.isdigit() and not token.startswith('-') and not token.endswith('-'):
            return False

        # Check if there is exactly one hyphen and it is surrounded by lowercase characters
        if len(token.split('-')) == 1 and token.split('-')[0].islower() and token.split('-')[1].islower():
            return True

        # Check if there is exactly one punctuation mark
        if token.endswith(','):
            return True

        return False

class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        m, n = len(matrix), len(matrix[0])
        left, right = 0, m * n - 1

        while left <= right:
            mid = left + (right - left) // 2
            row = mid // n
            col = mid % n

            if matrix[row][col] == target:
                return True
            elif matrix[row][col] < target:
                left = mid + 1
            else:
                right = mid - 1

        return False

class Solution:
    def getFactors(self, n: int) -> List[List[int]]:
        result = []
        for i in range(2, n):
            if n % i == 0:
                result.append([i] + self.getFactors(n // i))
        return result

class Solution:
    def maximumOddBinaryNumber(self, s: str) -> str:
        # Count the number of '1's in the string
        count_ones = s.count('1')

        # If there's only one '1', it must be at the end to make the number odd
        if count_ones == 1:
            return s.replace('1', '0') + '1'

        # Place all but one '1' at the beginning, followed by all '0's, and end with one '1'
        return (count_ones - 1) * '1' + s.count('0') * '0' + '1'

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def rangeSumBST(self, root: Optional[TreeNode], low: int, high: int) -> int:
        if not root:
            return 0

        # If current node's value is greater than high, we can ignore its subtree
        if root.val > high:
            return self.rangeSumBST(root.left, low, high)

        # If current node's value is less than low, we can ignore its subtree
        elif root.val < low:
            return self.rangeSumBST(root.right, low, high)

        # Otherwise, add the current node's value to the result
        return root.val + self.rangeSumBST(root.left, low, high) + self.rangeSumBST(root.right, low, high)

from typing import List, Set, Tuple

class Solution:
    def numDistinctIslands2(self, grid: List[List[int]]) -> int:
        def dfs(r: int, c: int, island: List[Tuple[int, int]]):
            if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]) or grid[r][c] == 0:
                return
            grid[r][c] = 0
            island.append((r, c))
            dfs(r + 1, c, island)
            dfs(r - 1, c, island)
            dfs(r, c + 1, island)
            dfs(r, c - 1, island)

        def normalize(island: List[Tuple[int, int]]) -> Set[Tuple[int, int]]:
            shapes = set()
            for i in range(4):
                for flip in [False, True]:
                    new_island = [(x if not flip else -x, y) for x, y in island]
                    new_island = sorted([(x - new_island[0][0], y - new_island[0][1]) for x, y in new_island])
                    shapes.add(tuple(new_island))
                island = [(y, -x) for x, y in island]  # Rotate 90 degrees
            return min(shapes)

        islands = set()
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == 1:
                    island = []
                    dfs(r, c, island)
                    normalized_island = normalize(island)
                    islands.add(normalized_island)

        return len(islands)

class Solution:
    def checkOnesSegment(self, s: str) -> bool:
        i, j = 0, 0
        while j < len(s):
            if s[j] == '1':
                j += 1
            else:
                if i < j:
                    return False
                i = j + 1
        return True
